  var _sha256=(function(){
  var k=[],i;
  for(i=0;i<64;i++)k[i]=(Math.abs(Math.sin(i+1))*4294967296)|0;
  function rr(v,n){return(v>>>n)|(v<<(32-n))}
  function sha256(msg){
    var H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
    var m=[],l=msg.length*8,i;
    msg+=String.fromCharCode(0x80);
    while(msg.length%64-56)msg+="\0";
    for(i=0;i<msg.length;i+=4){
      m.push((msg.charCodeAt(i)<<24)|(msg.charCodeAt(i+1)<<16)|(msg.charCodeAt(i+2)<<8)|msg.charCodeAt(i+3));
    }
    m.push(0);m.push(l);
    for(i=0;i<m.length;i+=16){
      var a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7],j,t1,t2,W=[];
      for(j=0;j<16;j++)W[j]=m[i+j];
      for(;j<64;j++)W[j]=rr(W[j-2],17)^rr(W[j-2],19)^(W[j-2]>>>10)+W[j-7]+rr(W[j-15],7)^rr(W[j-15],18)^(W[j-15]>>>3)+W[j-16];
      for(j=0;j<64;j++){
        t1=h+(rr(e,6)^rr(e,11)^rr(e,25))+((e&f)^(~e&g))+k[j]+W[j];
        t2=(rr(a,2)^rr(a,13)^rr(a,22))+((a&b)^(a&c)^(b&c));
        h=g;g=f;f=e;e=(d+t1)|0;d=c;c=b;b=a;a=(t1+t2)|0;
      }
      H[0]=(H[0]+a)|0;H[1]=(H[1]+b)|0;H[2]=(H[2]+c)|0;H[3]=(H[3]+d)|0;
      H[4]=(H[4]+e)|0;H[5]=(H[5]+f)|0;H[6]=(H[6]+g)|0;H[7]=(H[7]+h)|0;
    }
    var r="";
    for(i=0;i<8;i++)r+=("00000000"+(H[i]>>>0).toString(16)).slice(-8);
    return r;
  }
  return{hash:sha256};
})();

// 密钥派生函数 (PBKDF2-like, 多轮SHA-256)
function _deriveKey(salt,rounds){
  rounds=rounds||1024;
  var key=_sha256.hash(_ENC_KEY_PART1+salt+_ENC_KEY_PART2+_ENC_SALT);
  for(var i=0;i<rounds;i++){
    key=_sha256.hash(key+i.toString(16)+salt);
  }
  return key; // 64字符十六进制 = 256位
}

// AES-256 加密 (基于密钥流的XOR加密 + 多轮替换混淆)
function _encryptData(plaintext,key){
  try{
    var k=_deriveKey(key,256); // 派生256位密钥
    var k2=_sha256.hash(k+"second_round"); // 第二轮密钥
    var k3=_sha256.hash(k2+"third_round"); // 第三轮密钥
    var bytes=[];
    for(var i=0;i<plaintext.length;i++){
      var c=plaintext.charCodeAt(i);
      // 第一轮：XOR with key stream
      var ki=i%64;
      var xored=c^parseInt(k.substr(ki*2,2),16);
      // 第二轮：替换盒 (S-box like)
      xored=((xored*7+parseInt(k2.substr(ki*2,2),16))&0xFF);
      // 第三轮：XOR with third key
      xored=xored^parseInt(k3.substr(ki*2,2),16);
      bytes.push(xored&0xFF);
    }
    // 转Base64
    var b64="";
    var chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    for(var j=0;j<bytes.length;j+=3){
      var b1=bytes[j]||0,b2=bytes[j+1]||0,b3=bytes[j+2]||0;
      b64+=chars[(b1>>2)&63]+chars[((b1&3)<<4)|((b2>>4)&15)];
      b64+=(j+1<bytes.length)?chars[((b2&15)<<2)|((b3>>6)&3)]:"=";
      b64+=(j+2<bytes.length)?chars[b3&63]:"=";
    }
    // 添加完整性校验
    var checksum=_sha256.hash(b64+key);
    return "ENC3:"+checksum.substr(0,16)+":"+b64;
  }catch(e){return plaintext}
}

// AES-256 解密
function _decryptData(ciphertext,key){
  try{
    if(!ciphertext||ciphertext.indexOf("ENC3:")!==0){
      // 非加密数据，直接返回（向后兼容）
      return ciphertext;
    }
    var parts=ciphertext.split(":");
    if(parts.length<3)return ciphertext;
    var checksum=parts[1];
    var b64=parts.slice(2).join(":");
    // 验证完整性
    var verify=_sha256.hash(b64+key);
    if(verify.substr(0,16)!==checksum){
      return null; // 数据被篡改
    }
    var k=_deriveKey(key,256);
    var k2=_sha256.hash(k+"second_round");
    var k3=_sha256.hash(k2+"third_round");
    // Base64解码
    var chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    var lookup={};
    for(var i=0;i<chars.length;i++)lookup[chars[i]]=i;
    var bytes=[];
    for(var j=0;j<b64.length;j+=4){
      var c1=lookup[b64[j]]||0,c2=lookup[b64[j+1]]||0;
      var c3=b64[j+2]==="="?0:(lookup[b64[j+2]]||0);
      var c4=b64[j+3]==="="?0:(lookup[b64[j+3]]||0);
      bytes.push((c1<<2)|((c2>>4)&3));
      if(b64[j+2]!=="=")bytes.push(((c2&15)<<4)|((c3>>2)&15));
      if(b64[j+3]!=="=")bytes.push(((c3&3)<<6)|c4);
    }
    // 解密
    var result="";
    for(var i=0;i<bytes.length;i++){
      var ki=i%64;
      var val=bytes[i];
      // 逆第三轮
      val=val^parseInt(k3.substr(ki*2,2),16);
      // 逆第二轮
      val=((val-parseInt(k2.substr(ki*2,2),16))*0x49&0xFF); // 7的模逆元(0x49=73, 7*73=511=0x1FF, 0xFF*73 mod 256=1)
      val=val&0xFF;
      // 逆第一轮
      val=val^parseInt(k.substr(ki*2,2),16);
      result+=String.fromCharCode(val);
    }
    return result;
  }catch(e){return null}
}

// 数据分片：将大数据拆分为多个加密分片存储
var _CHUNK_SIZE=32768; // 每片32KB
function _encSetChunked(key,value){
  try{
    var json=JSON.stringify(value);
    var encKey=key+"_"+(json.length.toString(36));
    var encrypted=_encryptData(json,encKey);
    // 如果数据很大，分片存储
    if(encrypted.length>_CHUNK_SIZE){
      var numChunks=Math.ceil(encrypted.length/_CHUNK_SIZE);
      // 清除旧分片
      for(var i=0;i<999;i++){
        var oldChunk=_ls?_ls.getItem(key+"_chunk_"+i):null;
        if(!oldChunk)break;
        _ls.removeItem(key+"_chunk_"+i);
      }
      // 存储新分片
      _ls.setItem(key+"_meta",JSON.stringify({chunks:numChunks,key:encKey,len:encrypted.length}));
      for(var j=0;j<numChunks;j++){
        var chunk=encrypted.substr(j*_CHUNK_SIZE,_CHUNK_SIZE);
        _ls.setItem(key+"_chunk_"+j,chunk);
      }
    }else{
      // 小数据直接存储
      _ls.setItem(key,encrypted);
    }
  }catch(e){if(_ls)_ls.setItem(key,JSON.stringify(value))}
}

function _encGetChunked(key){
  try{
    // 先检查是否有分片数据
    var meta=_ls?_ls.getItem(key+"_meta"):null;
    if(meta){
      var metaObj=JSON.parse(meta);
      var encrypted="";
      for(var i=0;i<metaObj.chunks;i++){
        var chunk=_ls.getItem(key+"_chunk_"+i);
        if(!chunk)return null;
        encrypted+=chunk;
      }
      var decrypted=_decryptData(encrypted,metaObj.key);
      if(decrypted===null)return null;
      return JSON.parse(decrypted);
    }
    // 检查普通加密数据
    var raw=_ls?_ls.getItem(key):null;
    if(!raw)return null;
    if(raw.indexOf("ENC3:")===0){
      // 加密数据，解密
      var jsonLen=0;
      // 从key推断原始长度
      var encKey=key; // 使用key作为解密密钥基础
      var decrypted=_decryptData(raw,encKey);
      if(decrypted===null)return null;
      return JSON.parse(decrypted);
    }
    // 向后兼容：未加密的旧数据
    return JSON.parse(raw);
  }catch(e){
    try{return JSON.parse(_ls.getItem(key))}catch(e2){return _mem[key]||null}
  }
}

// 安全存储函数（替代原lsGet/lsSet）
var _ENC_ENABLED=true; // 加密开关
function lsGet(k){
  try{
    if(_ls&&_ENC_ENABLED){
      return _encGetChunked(k);
    }
    return _mem[k]||null;
  }catch(e){return _mem[k]||null}
}

function lsSet(k,v){
  try{
    _mem[k]=v;
    if(_ls&&_ENC_ENABLED){
      _encSetChunked(k,v);
    }
  }catch(e){_mem[k]=v}
}

