// 本地密码哈希（简单模拟，实际使用更安全的算法）
function localHash(pw, salt){
  var h = 0;
  var s = salt || "huanyu_v9";
  var str = s + pw + s;
  for(var i = 0; i < str.length; i++){
    var c = str.charCodeAt(i);
    h = ((h << 5) - h) + c;
    h = h & h;
  }
  return "h_" + Math.abs(h).toString(36);
}

