        h+='<div style="display:flex;justify-content:flex-end;padding:0 4px 10px"><button onclick="toggleBatchMode(\'stories\')" style="background:rgba(124,92,252,.1);border:1px solid rgba(124,92,252,.2);color:#a78bfa;padding:6px 14px;border-radius:10px;font-size:12px;font-weight:600;cursor:pointer">'+(!batchMode||batchType!=="stories"?'🗑️ 批量删除':'✓ 完成')+'</button></div>';
