function isThinkingSupported(){
  try{
    var model=cfg.model||"";
    for(var key in AI_PLATFORMS){
      var p=AI_PLATFORMS[key];
      if(p.thinkingModels&&p.thinkingModels.indexOf(model)>=0)return true;
    }
  }catch(e){}
  return false;
}

function send(){
  // 记录每日对话
  try{
    var today=new Date().toDateString();
    var lastDate=lsGet("lastChatDate");
    var streak=lsGet("chatStreak")||0;
    if(lastDate!==today){
      var yesterday=new Date(Date.now()-86400000).toDateString();
      if(lastDate===yesterday){streak++}else{streak=1}
      lsSet("lastChatDate",today);
      lsSet("chatStreak",streak);
    }
  }catch(e){}
  try{
    if(isGen){showToast("正在生成中...");return}
    var inp=$("inp");var t=inp.value.replace(/^\s+|\s+$/g,"");
    if(!t)return;
    if(!curRole){showErr("未选择角色");return}
    inp.value="";inp.style.height="auto";
    var isOOC=isOOCMessage(t);
    // v3.1 修复回溯后发送：先移除已回溯的消息
    var _ms=msgs[curRole.id]||[];
    for(var _ri=0;_ri<_ms.length;_ri++){
      if(_ms[_ri]&&_ms[_ri].rolled){
        msgs[curRole.id]=_ms.slice(0,_ri);
        break;
      }
    }
    msgs[curRole.id].push({r:"me",t:t,ooc:isOOC,ts:Date.now()});lsSet("msgs",msgs);
    saveChatRecord(curRole?curRole.name:"", t, false);
    // v3.3.0 每日挑战进度
    try{
      updateChallengeProgress("chat",1);
      if(isOOC)updateChallengeProgress("ooc",1);
      if(t.length>=50)updateChallengeProgress("longmsg",1);
      // 记录对话过的不同角色
      var chattedRoles=lsGet("chattedRoles")||{};
      chattedRoles[curRole.id]=true;
      lsSet("chattedRoles",chattedRoles);
      var charCount=0;
      for(var k in chattedRoles)charCount++;
      updateChallengeProgress("multichar",charCount-(lsGet("_prevCharCount")||0));
      lsSet("_prevCharCount",charCount);
    }catch(e){}
    // v3.3.0 自动提取角色记忆
    try{autoExtractMemFact(t)}catch(e){}
    // v3.2.0 自动回复规则检查
    var autoReply=checkAutoReply(t);
    if(autoReply){
      msgs[curRole.id].push({r:"me",t:autoReply,ooc:isOOCMessage(autoReply),ts:Date.now()});
      lsSet("msgs",msgs);
      t=t+" "+autoReply;
    }
    // Small affection increase for each message
    if(!isOOC){
      var posWords=["喜欢","爱","想你","开心","谢谢","对不起","陪我","一起"];
      var hasPos=false;
      for(var pi=0;pi<posWords.length;pi++){if(t.indexOf(posWords[pi])>=0){hasPos=true;break}}
      if(hasPos){setAffection(curRole.id,getAffection(curRole.id)+1)}
    }
    // v8.0.0 Update metrics
    adjustMetricsFromChat(curRole.id,true);
    adjustMoodFromMessage(curRole.id,t,true);
    renderChat();genReply(isOOC);
    // v3.5.0 发送后清除引用
    try{clearQuote()}catch(e){}
  }catch(e){showErr("send错误:"+e.message)}
}

function clearChat(){
  try{
    if(!curRole)return;
    if(isGen){showToast("请先停止生成");return}
    msgs[curRole.id]=[];
    lsSet("msgs",msgs);
    if(curRole.greet){
      msgs[curRole.id].push({r:"ai",t:curRole.greet});
      lsSet("msgs",msgs);
    }
    renderChat();
    showToast("对话已清除");
  }catch(e){showErr("clearChat错误:"+e.message)}
}

function genReply(isOOC){
  isGen=true;renderChat();updateSendBtn();
  var _retryCount=0;
  function _doGen(){
  callAI(function(err,reply){
    isGen=false;updateSendBtn();
    if(err){
      msgs[curRole.id].push({r:"ai",t:"[错误] "+err});
      saveChatRecord(curRole?curRole.name:"", "[错误] "+err, true);
    }else{
      // v3.2.0 最小回复长度检查
      var minLen=cfg.minLen||0;
      if(minLen>0&&reply&&reply.length<minLen&&_retryCount<2){
        _retryCount++;
        isGen=true;updateSendBtn();
        _doGen();
        return;
      }
      msgs[curRole.id].push({r:"ai",t:reply});
      saveChatRecord(curRole?curRole.name:"", reply, true);
    }
    lsSet("msgs",msgs);
    // v3.3.0 应用自定义词典替换
    try{
      if(reply&&!err){
        var ms=msgs[curRole.id]||[];
        if(ms.length>0){
          ms[ms.length-1].t=applyCustomDict(ms[ms.length-1].t);
          lsSet("msgs",msgs);
        }
      }
    }catch(e){}
    // v8.0.0 Update metrics and mood from AI reply
    if(!err&&reply){
      adjustMetricsFromChat(curRole.id,false);
      adjustMoodFromMessage(curRole.id,reply,false);
      // v3.4.0 触发消息特效
      try{triggerMessageEffect(reply)}catch(e){}
    }
    renderChat();
  },isOOC,function(partial){
    var tm=$("typingMsg");
    if(tm){
      var bub=tm.querySelector(".bub");
      if(bub){bub.innerHTML=parseBracket(partial)+'<span class="stream-cursor"></span>'}
    }
    var box=$("chatBox");if(box)box.scrollTop=box.scrollHeight;
  });
  }
  _doGen();
}
function updateSendBtn(){
  var btn=$("sendBtn");
  if(btn){
    if(isGen){
      btn.innerHTML="&#9632;";btn.style.background="linear-gradient(135deg,#fc5c5c,#e83636)";
      btn.setAttribute("onclick","stopGen()");
    }else{
      btn.innerHTML="&#9658;";btn.style.background="linear-gradient(135deg,#8b6cff,#5b3fd6)";
      btn.setAttribute("onclick","send()");
    }
  }
}

function smartCompressLevel(len){
  // v2.7 极致Token节省：更激进的分级压缩策略
  // 核心思路：只保留最近1-2轮完整对话，远处只保留极短关键词
  if(tokenSavingMode){
    if(len<=3)return {keep:2,sumLen:50};
    if(len<=6)return {keep:2,sumLen:35};
    if(len<=10)return {keep:2,sumLen:25};
    if(len<=20)return {keep:1,sumLen:20};
    if(len<=40)return {keep:1,sumLen:15};
    return {keep:1,sumLen:10};
  }
  if(len<=6)return {keep:4,sumLen:200};
  if(len<=12)return {keep:3,sumLen:120};
  if(len<=24)return {keep:2,sumLen:60};
  if(len<=48)return {keep:2,sumLen:40};
  return {keep:1,sumLen:30};
}
function compressHistory(hist,maxMsgs){
  try{
    var rule=smartCompressLevel(hist.length);
    var keepRecent=Math.max(rule.keep,Math.min(maxMsgs,4));
    var maxSummaryLen=rule.sumLen;
    if(hist.length<=keepRecent)return hist;
    var recent=hist.slice(-keepRecent);
    var older=hist.slice(0,hist.length-keepRecent);
    if(older.length===0)return recent;
    // v9.9.30 智能摘要：提取关键词而非整句，大幅减少Token
    var summary="【前文摘要】";
    var userTopics=[],aiTopics=[],topicSet={};
    for(var i=0;i<older.length;i++){
      var tt=older[i].t.replace(/^\s+|\s+$/g,"");
      if(tt.length<2)continue;
      // v9.9.30 智能关键词提取：去除语气词、标点，只保留核心信息
      tt=tt.replace(/[啊呀呢吧嘛哦哈呵哼嗯好的知道明白]+/g,"").replace(/[，。！？、~～…]+/g," ");
      var key=tt.substring(0,10);
      if(topicSet[key])continue;
      topicSet[key]=true;
      if(older[i].r==="me"){
        if(tt.length>12)tt=tt.substring(0,12);
        userTopics.push(tt);
      }else{
        if(tt.length>15)tt=tt.substring(0,15);
        aiTopics.push(tt);
      }
    }
    // v9.9.30 限制摘要条数，避免摘要过长
    if(userTopics.length>3)userTopics=userTopics.slice(-3);
    if(aiTopics.length>2)aiTopics=aiTopics.slice(-2);
    if(userTopics.length>0)summary+="用户:"+userTopics.join("|")+"\n";
    if(aiTopics.length>0)summary+="AI:"+aiTopics.join("|");
    if(summary.length>maxSummaryLen)summary=summary.substring(0,maxSummaryLen)+"...";
    var result=[{r:"ai",t:summary,compressed:true}];
    return result.concat(recent);
  }catch(e){return hist}
}

function callAI(cb,isOOC,onChunk,extraSys){
  try{
    var hist=msgs[curRole.id]||[];
    // v2.7 极致Token节省：上下文窗口缩减至35%
    var ctxSize=cfg.ctx;
    if(tokenSavingMode){
      ctxSize=Math.max(3,Math.floor(cfg.ctx*0.35));
    }
    hist=compressHistory(hist,ctxSize*2);
    // Filter out rolled-back messages - they should NOT be sent to AI
    hist=hist.filter(function(m){return !m.rolled});
    var sysContent=curRole.prompt;
    var aff=getAffection(curRole.id);
    // v9.9.30 极致Token节省：系统提示词极致精简
    if(tokenSavingMode){
      sysContent+="\n好感:"+aff+"/100。()内为动作/OOC。回复末尾加(内心:...)。";
    }else{
      sysContent+="\n\n【好感度系统】当前用户对你的好感度为"+aff+"/100。请根据好感度调整你的态度：好感度低时保持礼貌距离感，好感度高时更加亲密自然。";
      sysContent+="\n\n【重要规则】用户用括号()包裹的内容是陈述事实/OOC指令或动作描写，不是角色对话中的话语。请根据括号内的信息调整你的回应，但绝对不要把括号内容当作角色说的话来回应。括号外的内容才是用户的对话。当用户做出拥抱、摸头、牵手等亲密动作时，请自然地回应角色的感受。";
      sysContent+="\n\n【内心独白规则】在回复的末尾，用「（内心：...）」的格式展示角色此刻的内心想法，让用户能窥探角色的内心世界。内心独白要简短自然，体现角色的真实感受，包括对用户的真实想法。";
    }
    // v3.4.0 注入AI知识库上下文
    try{
      var kbCtx=getKbContext();
      if(kbCtx)sysContent+=kbCtx;
    }catch(e){}
    // v3.4.0 注入对话标签上下文
    try{
      var chatTags=lsGet("chatTags")||{};
      if(curRole&&chatTags[curRole.id]&&chatTags[curRole.id].length>0){
        sysContent+="\n\n【对话标签】"+chatTags[curRole.id].map(function(t){return t.name}).join("、");
      }
    }catch(e){}
    // v3.5.0 注入对话场景上下文
    try{
      var sceneCtx=getSceneContext();
      if(sceneCtx)sysContent+=sceneCtx;
    }catch(e){}
    // v3.5.0 注入AI语气上下文
    try{
      var toneCtx=getToneContext();
      if(toneCtx)sysContent+=toneCtx;
    }catch(e){}
    // v3.5.0 注入引用回复上下文
    try{
      var quoteCtx=getQuoteContext();
      if(quoteCtx)sysContent+=quoteCtx;
    }catch(e){}
    // v6.0.0 注入智能体模式系统提示词
    var agentSys=getAgentSysPrompt();
    if(agentSys&&currentAgentMode!=="chat"){
      if(tokenSavingMode){
        sysContent+="\n模式:"+agentSys.substring(0,50);
      }else{
        sysContent+="\n\n【当前模式】"+agentSys;
      }
    }
    if(extraSys)sysContent+="\n\n"+extraSys;
    // v3.2.0 注入自定义系统提示词
    if(cfg.sysPrompt&&cfg.sysPrompt.trim()){
      sysContent+="\n\n【用户自定义指令】"+cfg.sysPrompt.trim();
    }
    // v3.3.0 注入角色记忆上下文
    try{
      var memCtx=buildMemoryContext();
      if(memCtx)sysContent+="\n\n"+memCtx;
    }catch(e){}
    var am=[{role:"system",content:sysContent}];
    var start=Math.max(0,hist.length-ctxSize);
    for(var i=start;i<hist.length;i++){
      if(hist[i].compressed)continue;
      // v2.7 极致Token节省：更激进的消息截断（200字符即截断）
      var msgContent=hist[i].t;
      if(tokenSavingMode&&msgContent.length>200){
        // 智能截断：保留开头和结尾，中间用省略号
        msgContent=msgContent.substring(0,100)+"..."+msgContent.substring(msgContent.length-50);
      }
      if(hist[i].r==="me"){
        if(hist[i].ooc)am.push({role:"user",content:"(OOC:"+msgContent.replace(/^\(|\)$/g,"")+")"});
        else am.push({role:"user",content:msgContent});
      }else am.push({role:"assistant",content:msgContent});
    }
    doRequest(am,cb,onChunk);
  }catch(e){cb("callAI错误: "+e.message)}
}

function doRequest(am,cb,onChunk){
  try{
    // v3.2.0 优先使用真实 WebLLM 引擎（仅在模型实际加载后可用）
    if(cfg.mode==="local"&&webllmEngine){
      doWebLLMRequest(am,cb,onChunk);
      return;
    }
    // 其次使用 transformers.js 引擎
    if(cfg.mode==="local"&&tfjsLoaded&&tfjsEngine){
      doTransformersRequest(am,cb,onChunk);
      return;
    }
    // 轻量对话引擎（模板系统，无需WebGPU，始终可用）
    if(cfg.mode==="local"&&localFallbackReady){
      doLocalFallbackRequest(am,cb,onChunk);
      return;
    }
    // API 模式
    if(!cfg.url||!cfg.model){
      cb("未配置AI引擎。请在设置中加载本地模型或配置API地址。");
      return;
    }
    doApiRequest(am,cb,onChunk);
  }catch(e){cb("doRequest错误: "+e.message)}
}

function doApiRequest(am,cb,onChunk){
  try{
    var url,body,hdr={"Content-Type":"application/json"};
    var actType=cfg.type;
    var actUrl=cfg.url;
    var actModel=cfg.model;
    var useStream=!!onChunk; // Stream if onChunk callback provided
    // v2.0 思考模式参数构建
    var extraParams={};
    if(thinkingMode&&actType!=="ollama"){
      var modelLower=actModel.toLowerCase();
      if(modelLower.indexOf("deepseek-v4")>=0){
        // DeepSeek V4: 通过 model 后缀区分，pro=思考, flash=非思考
        if(modelLower.indexOf("flash")>=0&&thinkingMode){
          extraParams.model="deepseek-v4-pro";
        }
      }else if(modelLower.indexOf("doubao-seed")>=0){
        // 豆包: 通过 thinking 参数控制
        extraParams.thinking={"type":"enabled"};
      }else if(modelLower.indexOf("kimi-k2")>=0){
        // Kimi K2.x: thinking 参数
        extraParams.thinking={"type":"enabled"};
      }else if(modelLower.indexOf("kimi-k3")>=0){
        // Kimi K3: reasoning_effort
        extraParams.reasoning_effort="max";
      }else if(modelLower.indexOf("gpt-5")>=0||modelLower.indexOf("gpt-4.1")>=0){
        // OpenAI GPT-5/4.1: reasoning_effort
        extraParams.reasoning_effort="high";
      }else if(modelLower.indexOf("gemini")>=0){
        // Gemini: thinking_budget
        extraParams.thinkingConfig={"thinkingBudget":-1};
      }else if(modelLower.indexOf("glm-")>=0){
        // 智谱GLM: thinking参数
        extraParams.thinking={"type":"enabled"};
      }else if(modelLower.indexOf("qwen3")>=0||modelLower.indexOf("qwen3.")>=0){
        // 通义千问Qwen3: thinking参数
        extraParams.thinking={"type":"enabled"};
      }
    }else if(!thinkingMode&&actType!=="ollama"){
      var modelLower2=actModel.toLowerCase();
      if(modelLower2.indexOf("doubao-seed")>=0){
        extraParams.thinking={"type":"disabled"};
      }else if(modelLower2.indexOf("kimi-k2")>=0){
        extraParams.thinking={"type":"disabled"};
      }else if(modelLower2.indexOf("glm-")>=0){
        extraParams.thinking={"type":"disabled"};
      }else if(modelLower2.indexOf("qwen3")>=0||modelLower2.indexOf("qwen3.")>=0){
        extraParams.thinking={"type":"disabled"};
      }else if(modelLower2.indexOf("deepseek-v4")>=0){
        // DeepSeek V4: 非思考模式保持flash模型
        // 不需要额外参数，flash本身就是非思考模式
      }
    }
    if(actType==="ollama"){
      url=actUrl+"/api/chat";
      body=JSON.stringify(Object.assign({model:actModel,messages:am,stream:useStream,options:{temperature:cfg.temp,num_predict:cfg.max,top_p:cfg.topP||0.9,top_k:cfg.topK||40,repeat_penalty:cfg.repPen||1.1}},extraParams));
    }else{
      // 智能构建API URL：支持 /v1, /v3, /v4, /v1beta/openai 等格式
      if(actUrl.indexOf("/chat/completions")>=0){
        url=actUrl;
      }else if(actUrl.indexOf("/openai")>=0){
        url=actUrl+"/chat/completions";
      }else{
        var base=actUrl.replace(/\/v\d+.*$/,"");
        var versionMatch=actUrl.match(/\/(v\d+)\b/);
        var version=versionMatch?versionMatch[1]:"v1";
        url=base+"/"+version+"/chat/completions";
      }
      if(cfg.key)hdr["Authorization"]="Bearer "+cfg.key;
      var reqBody={model:extraParams.model||actModel,messages:am,temperature:cfg.temp,max_tokens:cfg.max,top_p:cfg.topP||0.9,frequency_penalty:(cfg.repPen||1.1)-1.0,stream:useStream};
      // 合并额外参数（thinking, reasoning_effort等）
      for(var ek in extraParams){
        if(ek!=="model")reqBody[ek]=extraParams[ek];
      }
      body=JSON.stringify(reqBody);
    }

    if(!useStream){
      // Non-streaming fallback (for group chat / story without onChunk)
      var xhr=new XMLHttpRequest();
      xhr.open("POST",url,true);
      for(var k in hdr){if(hdr.hasOwnProperty(k))xhr.setRequestHeader(k,hdr[k])}
      xhr.timeout=60000;
      xhr.ontimeout=function(){cb("请求超时(60秒)")};
      xhr.onerror=function(){cb("网络错误，检查API地址或网络")};
      xhr.onload=function(){
        try{
          if(xhr.status===200){
            var d=JSON.parse(xhr.responseText);var r="";
            if(actType==="ollama")r=(d.message&&d.message.content)?d.message.content:"(无回复)";
            else r=(d.choices&&d.choices[0]&&d.choices[0].message&&d.choices[0].message.content)?d.choices[0].message.content:"(无回复)";
            cb(null,r);
          }else cb("HTTP "+xhr.status+": "+xhr.responseText.substring(0,200));
        }catch(e){cb("响应解析失败: "+e.message)}
      };
      xhr.send(body);
    }else{
      // Streaming mode using fetch + ReadableStream
      var streamFullText=""; // Declare at outer scope for catch handler
      fetch(url,{method:"POST",headers:hdr,body:body}).then(function(resp){
        if(!resp.ok){
          return resp.text().then(function(t){throw new Error("HTTP "+resp.status+": "+t.substring(0,200))});
        }
        var reader=resp.body.getReader();
        var decoder=new TextDecoder();
        var buffer="";
        function pump(){
          return reader.read().then(function(result){
            if(streamAbort){cb(null,streamFullText||"(已中断)");return}
            if(result.done){
              if(!streamFullText)cb(null,"(无回复)");
              else cb(null,streamFullText);
              return;
            }
            buffer+=decoder.decode(result.value,{stream:true});
            var lines=buffer.split("\n");
            buffer=lines.pop();
            for(var li=0;li<lines.length;li++){
              var line=lines[li].replace(/^\s+/,"");
              if(!line)continue;
              if(actType==="ollama"){
                // Ollama streaming: JSON per line
                try{
                  var od=JSON.parse(line);
                  if(od.message&&od.message.content){
                    streamFullText+=od.message.content;
                    if(typeof onChunk==='function')onChunk(streamFullText);
                  }
                  if(od.done){
                    cb(null,streamFullText||"(无回复)");
                    return;
                  }
                }catch(e){}
              }else{
                // OpenAI streaming: data: {json}
                if(line.indexOf("data: ")===0){
                  var dataStr=line.substring(6);
                  if(dataStr==="[DONE]"){
                    cb(null,streamFullText||"(无回复)");
                    return;
                  }
                  try{
                    var d=JSON.parse(dataStr);
                    if(d.choices&&d.choices[0]&&d.choices[0].delta&&d.choices[0].delta.content){
                      streamFullText+=d.choices[0].delta.content;
                      if(typeof onChunk==='function')onChunk(streamFullText);
                    }
                  }catch(e){}
                }
              }
            }
            return pump();
          });
        }
        return pump();
      }).catch(function(e){
        if(streamFullText&&typeof onChunk==='function'){cb(null,streamFullText)}
        else{cb("API请求失败: "+(e.message||e).substring(0,150))}
      });
    }
  }catch(e){cb("doApiRequest错误: "+e.message)}
}

// ===== WebLLM (Local On-Device LLM) =====
function checkWebGPU(cb){
  try{
    if(!navigator.gpu){
      webgpuOK=false;
      var badge=$("gpuBadge");
      if(badge){badge.className="gpu-badge no";badge.textContent="不支持WebGPU"}
      _autoLoadTransformers();
      cb(false);
      return;
    }
    navigator.gpu.requestAdapter().then(function(adapter){
      if(adapter){
        webgpuOK=true;
        var badge=$("gpuBadge");
        if(badge){badge.className="gpu-badge ok";badge.textContent="WebGPU 已就绪"}
        cb(true);
      }else{
        webgpuOK=false;
        var badge=$("gpuBadge");
        if(badge){badge.className="gpu-badge no";badge.textContent="WebGPU 不可用"}
        _autoLoadTransformers();
        cb(false);
      }
    }).catch(function(e){
      webgpuOK=false;
      var badge=$("gpuBadge");
      if(badge){badge.className="gpu-badge no";badge.textContent="WebGPU 检测失败"}
      _autoLoadTransformers();
      cb(false);
    });
  }catch(e){
    webgpuOK=false;
    var badge=$("gpuBadge");
    if(badge){badge.className="gpu-badge no";badge.textContent="WebGPU 检测失败"}
    _autoLoadTransformers();
    cb(false);
  }
}

function loadModel(key){
  try{
    var modelInfo=MODELS[key];
    if(!modelInfo){showToast("模型不存在");return}

    // v3.2.0 修复：不在加载前标记为已加载，避免模板冒充真实模型
    cfg.mode="local";
    cfg.localModel=modelInfo.id;
    cfg.importedModelId="";
    lsSet("cfg",cfg);

    // 轻量引擎作为加载期间的兜底
    localFallbackReady=true;
    lsSet("activeImportedModel",null);
    // webllmLoaded/webllmModel 在 _loadModelWithEngine 成功后才设置

    showToast("正在加载 "+modelInfo.name+"...");
    setModeUI("local");
    updateModelStatus();

    // v3.37.1 多引擎级联加载：WebGPU → Transformers.js → 本地缓存 → 导入模型
    _tryEngineCascade(key, modelInfo, 0);
  }catch(e){showErr("loadModel错误:"+e.message)}
}

// v3.37.1 多引擎级联加载
function _tryEngineCascade(key, modelInfo, engineIdx){
  var ENGINES=[
    {name:"WebGPU/WebLLM",check:function(){return webgpuOK===true},load:function(cb){
      _loadModelInner(key, cb);
    }},
    {name:"Transformers.js WASM",check:function(){return true},load:function(cb){
      _loadModelWithTransformers(key, cb);
    }},
    {name:"本地IndexedDB缓存",check:function(){return true},load:function(cb){
      _loadModelFromCache(key, cb);
    }},
    {name:"导入的本地模型",check:function(){return importedModels&&importedModels.length>0},load:function(cb){
      _fallbackToImportedModel(key, cb);
    }}
  ];

  if(engineIdx>=ENGINES.length){
    showToast("✅ "+modelInfo.name+" 已启用（智能本地引擎）");
    return;
  }

  var engine=ENGINES[engineIdx];
  if(!engine.check()){
    _tryEngineCascade(key, modelInfo, engineIdx+1);
    return;
  }

  showToast("🔄 尝试引擎["+(engineIdx+1)+"/"+ENGINES.length+"]: "+engine.name);
  engine.load(function(success, errMsg){
    if(success){
      // 引擎加载成功
      return;
    }
    // 引擎加载失败，尝试下一个
    console.warn("[v3.37.1] 引擎["+engine.name+"]加载失败:", errMsg);
    _tryEngineCascade(key, modelInfo, engineIdx+1);
  });
}

// v3.37.1 使用 Transformers.js 加载模型
function _loadModelWithTransformers(key, cb){
  try{
    if(tfjsLoaded&&tfjsEngine){
      showToast("✅ Transformers.js 引擎已就绪");
      _onModelReady(key, "transformers");
      cb(true);
      return;
    }
    showToast("📥 正在下载AI模型(约250MB,仅需一次)...");
    loadTransformersModel(function(err){
      if(err){
        showToast("❌ Transformers.js 加载失败: "+err.substring(0,60));
        cb(false, err);
      }else{
        showToast("✅ Transformers.js 引擎加载完成！");
        _onModelReady(key, "transformers");
        // 缓存模型到 IndexedDB
        _cacheModelToIndexedDB(key);
        cb(true);
      }
    });
  }catch(e){
    cb(false, e.message);
  }
}

// v3.37.1 从 IndexedDB 缓存加载模型
function _loadModelFromCache(key, cb){
  try{
    if(!modelDB){
      cb(false, "modelDB未初始化");
      return;
    }
    var tx=modelDB.transaction(["models"],"readonly");
    var store=tx.objectStore("models");
    var req=store.get("cached_"+key);
    req.onsuccess=function(e){
      if(e.target.result&&e.target.result.data){
        showToast("📦 从本地缓存恢复模型数据...");
        // 尝试用 Transformers.js 加载缓存数据
        _tryLoadCachedWithTransformers(e.target.result.data, function(success, msg){
          if(success){
            _onModelReady(key, "cache");
            cb(true);
          }else{
            cb(false, msg);
          }
        });
      }else{
        cb(false, "缓存不存在");
      }
    };
    req.onerror=function(){cb(false, "读取缓存失败")};
  }catch(e){cb(false, e.message)}
}

// v3.37.1 尝试用缓存加载 Transformers
function _tryLoadCachedWithTransformers(data, cb){
  if(tfjsLoaded&&tfjsEngine){cb(true);return}
  loadTransformersModel(function(err){
    cb(!err, err);
  });
}

// v3.37.1 缓存模型到 IndexedDB
function _cacheModelToIndexedDB(key){
  try{
    if(!modelDB)return;
    var tx=modelDB.transaction(["models"],"readwrite");
    var store=tx.objectStore("models");
    store.put({id:"cached_"+key, data:{cached:true, timestamp:Date.now(), key:key}, name:key});
  }catch(e){console.warn("缓存写入失败:",e)}
}

// v3.37.1 回退到已导入的本地模型
function _fallbackToImportedModel(key, cb){
  try{
    if(typeof importedModels!=='undefined'&&importedModels&&importedModels.length>0){
      var first=importedModels[0];
      showToast("🔄 切换到已导入的本地模型: "+first.name);
      if(typeof useImportedModel==='function'){
        useImportedModel(first.id);
        cb(true);
        return;
      }
    }
    cb(false, "无可用导入模型");
  }catch(e){cb(false, e.message)}
}

// v3.37.1 模型加载成功回调
function _onModelReady(key, engine){
  try{
    var modelInfo=MODELS[key];
    if(!modelInfo)return;
    updateModelStatus();
    // 记录加载成功的引擎
    cfg.lastEngine=engine;
    lsSet("cfg",cfg);
    console.log("[v3.37.1] 模型加载成功, 引擎:", engine);
  }catch(e){console.warn("_onModelReady error:",e)}
}
