function regenSvMsg(idx,e){
  try{
    if(e)e.stopPropagation();
    if(isGen){showToast("请先等待回复完成");return}
    if(!curStory||idx<0||idx>=curStory.messages.length)return;
    var m=curStory.messages[idx];
    if(m.r==="me"){showToast("只能重新生成AI回复");return}
    // 找到上一条用户消息
    var userIdx=-1;
    for(var i=idx-1;i>=0;i--){
      if(curStory.messages[i].r==="me"){userIdx=i;break}
    }
    if(userIdx<0){
      // 没有用户消息，直接删除该消息及之后的消息
      curStory.messages=curStory.messages.slice(0,idx);
      lsSet("stories",stories);
      renderStoryView();
      return;
    }
    var userText=curStory.messages[userIdx].t;
    // 删除该消息及之后的所有消息
    curStory.messages=curStory.messages.slice(0,idx);
    lsSet("stories",stories);
    renderStoryView();
    genStoryReply(userText);
    showToast("正在重新生成...");
  }catch(e){}
}
function saveGroupTemplate(){
  try{
    var grps=window._lastGrpRoles||grpRoles;
    if(!grps||grps.length<2){showErr("至少选择2个角色才能保存");return}
    var names=[];
    for(var i=0;i<grps.length;i++){var r=getRole(grps[i]);if(r)names.push(r.name)}
    var tname=names.join("+");
    if(tname.length>20)tname=tname.substring(0,20)+"...";
    var userGrps=lsGet("userGrps");if(!userGrps)userGrps=[];
    userGrps.push({name:tname,ids:grps.slice()});
    lsSet("userGrps",userGrps);
    showToast("已保存为我的群聊");
    renderHome();
  }catch(e){showErr("保存群聊错误:"+e.message)}
}

