      var ev=events[i];
      h+='<div style="padding:10px 12px;background:var(--card-bg);border-radius:10px;border:1px solid var(--card-bd);margin-bottom:8px">';
      h+='<div style="display:flex;justify-content:space-between;align-items:start">';
