function doQuickCreate(type,t){
  try{
    if(type==="role"){
      showLoading("AI正在创建角色...");
      var am=[{role:"system",content:"你是角色创建助手。用户描述角色，你返回JSON格式角色信息。返回格式：{\"name\":\"名称\",\"emoji\":\"一个emoji或简短英文\",\"cat\":\"分类(陪伴/冒险/创作/学习/实用)\",\"prompt\":\"详细角色设定\",\"greet\":\"开场白\",\"quick\":[\"快捷回复1\",\"快捷回复2\",\"快捷回复3\"]}"},{role:"user",content:t}];
      doRequest(am,function(err,reply){
        hideLoading();
        if(err){
          // v9.9.11 本地模式下用模板创建角色，不报错
          createRoleFromTemplate(t);
          return;
        }
        try{
          var jsonStr=reply.replace(/```json/g,"").replace(/```/g,"").replace(/^\s+|\s+$/g,"");
          // 尝试提取JSON对象
          var jsonMatch=jsonStr.match(/\{[\s\S]*\}/);
          if(jsonMatch)jsonStr=jsonMatch[0];
          var obj=JSON.parse(jsonStr);
          editingId=null;
          $("createTitle").textContent="创建角色";
          $("cName").value=obj.name||t.substring(0,10);
          $("cEmoji").value=obj.emoji||"🤖";
          $("cCat").value=obj.cat||"陪伴";
          $("cPrompt").value=obj.prompt||("你是一个"+t.substring(0,20)+"风格的角色，请以这个身份和用户聊天。");
          $("cGreet").value=obj.greet||("你好呀！我是"+(obj.name||t.substring(0,8))+"，很高兴认识你~");
          $("cQuick").value=(obj.quick||["你好","介绍一下自己","今天心情怎么样"]).join("\n");
          $("delBtn").style.display="none";
          var qcb=$("quickCreateBox");if(qcb)qcb.style.display="none";
          show("vCreate");
          showToast("角色已创建，点击保存");
        }catch(e2){
          createRoleFromTemplate(t);
        }
      });
    }else{
      showLoading("AI正在创建故事...");
      var am=[{role:"system",content:"你是故事创建助手。用户描述故事，你返回JSON格式故事信息。返回格式：{\"title\":\"标题\",\"type\":\"类型(奇幻冒险/悬疑推理/言情都市/科幻未来/古风仙侠/恐怖惊悚)\",\"bg\":\"背景设定\",\"open\":\"故事开场\"}"},{role:"user",content:t}];
      doRequest(am,function(err,reply){
        hideLoading();
        if(err){
          createStoryFromTemplate(t);
          return;
        }
        try{
          var jsonStr=reply.replace(/```json/g,"").replace(/```/g,"").replace(/^\s+|\s+$/g,"");
          var jsonMatch=jsonStr.match(/\{[\s\S]*\}/);
          if(jsonMatch)jsonStr=jsonMatch[0];
          var obj=JSON.parse(jsonStr);
          $("sTitle").value=obj.title||t.substring(0,15);
          $("sType").value=obj.type||"奇幻冒险";
          $("sBg").value=obj.bg||("一个关于"+t.substring(0,20)+"的故事。");
          $("sOpen").value=obj.open||("故事开始了...");
          show("vStory");
          showToast("故事已创建，选择角色后开始");
        }catch(e2){
          createStoryFromTemplate(t);
        }
      });
    }
  }catch(e){hideLoading();showErr("doQuickCreate错误:"+e.message)}
}

// ===== Template-based creation for local mode =====
function createRoleFromTemplate(desc){
  try{
    var d=String(desc||"新角色").trim();
    var name=d.substring(0,8);
    var emoji="🤖";
    var cat="陪伴";
    if(/女仆|女佣|管家/.test(d)){emoji="👩‍💼";cat="陪伴"}
    else if(/女友|恋人|老婆|爱人/.test(d)){emoji="💕";cat="陪伴"}
    else if(/男友|老公/.test(d)){emoji="💙";cat="陪伴"}
    else if(/老师|导师|教授/.test(d)){emoji="📚";cat="学习"}
    else if(/猫|喵/.test(d)){emoji="🐱";cat="陪伴"}
    else if(/狐|妖/.test(d)){emoji="🦊";cat="冒险"}
    else if(/剑|武|侠|战士/.test(d)){emoji="⚔️";cat="冒险"}
    else if(/总裁|霸道|老板/.test(d)){emoji="💼";cat="陪伴"}
    else if(/妹妹|学妹/.test(d)){emoji="🌸";cat="陪伴"}
    else if(/姐姐|学姐/.test(d)){emoji="🌺";cat="陪伴"}
    else if(/医生|护士/.test(d)){emoji="🏥";cat="实用"}
    else if(/程序员|代码|编程/.test(d)){emoji="💻";cat="实用"}
    editingId=null;
    $("createTitle").textContent="创建角色";
    $("cName").value=name;
    $("cEmoji").value=emoji;
    $("cCat").value=cat;
    $("cPrompt").value="你是一个"+d+"风格的角色。请以这个身份和用户进行自然、有趣的对话。回复要符合你的角色设定，有自己的性格特点。";
    $("cGreet").value="你好呀！我是"+name+"，很高兴认识你~今天想聊点什么？";
    $("cQuick").value="你好\n介绍一下你自己\n今天天气怎么样";
    if($("cTags"))$("cTags").value="";
    if($("cDesc"))$("cDesc").value="";
    $("delBtn").style.display="none";
    var qcb=$("quickCreateBox");if(qcb)qcb.style.display="none";
    show("vCreate");
    showToast("角色已创建，可修改后保存");
  }catch(e){showErr("createRoleFromTemplate错误:"+e.message)}
}
function createStoryFromTemplate(desc){
  try{
    var d=String(desc||"新故事").trim();
    var title=d.substring(0,12);
    var type="奇幻冒险";
    if(/悬疑|推理|侦探|破案/.test(d))type="悬疑推理";
    else if(/爱情|言情|都市|恋爱/.test(d))type="言情都市";
    else if(/科幻|未来|太空|星际/.test(d))type="科幻未来";
    else if(/古风|仙侠|武侠|修仙/.test(d))type="古风仙侠";
    else if(/恐怖|惊悚|鬼|灵异/.test(d))type="恐怖惊悚";
    $("sTitle").value=title;
    $("sType").value=type;
    $("sBg").value="一个关于"+d+"的故事。在这个世界里，充满了未知和冒险等待着主角去探索。";
    $("sOpen").value="在一个不平凡的日子里，故事的序幕缓缓拉开...";
    show("vStory");
    showToast("故事已创建，可修改后开始");
  }catch(e){showErr("createStoryFromTemplate错误:"+e.message)}
}

// ===== Save Role =====
function saveRole(){
  try{
    var r={};
    r.name=$("cName").value.replace(/^\s+|\s+$/g,"");
    if(!r.name){showErr("请输入名称");return}
    r.emoji=$("cEmoji").value.replace(/^\s+|\s+$/g,"");
    r.cat=$("cCat").value;
    r.prompt=$("cPrompt").value;
    r.greet=$("cGreet").value;
    r.quick=$("cQuick").value.split("\n").filter(function(x){return x.replace(/^\s+|\s+$/g,"").length>0});
    // v9.9.20 标签和描述
    var _tagsRaw=$("cTags")?$("cTags").value:"";
    r.tags=_tagsRaw.split(/[\s,，]+/).filter(function(s){return s.length>0 && s.length<20}).slice(0,8);
    r.desc=$("cDesc")?$("cDesc").value:"";
    if(editingId){
      r.id=editingId;
      if(isPresetRole(editingId)){
        userRoles.push(r);
        lsSet("userRoles",userRoles);
        refreshRoles();
      }else{
        for(var i=0;i<userRoles.length;i++){if(userRoles[i].id===editingId){userRoles[i]=r;break}}
        lsSet("userRoles",userRoles);
        refreshRoles();
      }
    }else{
      r.id="r"+Date.now();
      userRoles.push(r);
      lsSet("userRoles",userRoles);
      refreshRoles();
    }
    try{syncUserContentToShared();}catch(e){}
    showToast("已保存");
    go("home");
  }catch(e){showErr("saveRole错误:"+e.message)}
}
function delRole(){
  try{
    if(editingId){delRoleById(editingId)}
    go("home");
  }catch(e){showErr("delRole错误:"+e.message)}
}

