function setupInput(id,handler){try{var el=$(id);if(el){el.onkeydown=function(e){if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();handler()}};el.addEventListener("input",function(){this.style.height="auto";this.style.height=Math.min(this.scrollHeight,80)+"px"})}}catch(e){}}
function addRipple(e){
  try{
    var target=e.currentTarget||e.target;
    if(!target)return;
    var rect=target.getBoundingClientRect();
    var ripple=document.createElement("span");
    ripple.className="ripple";
    var size=Math.max(rect.width,rect.height);
    ripple.style.width=ripple.style.height=size+"px";
    ripple.style.left=(e.clientX-rect.left-size/2)+"px";
    ripple.style.top=(e.clientY-rect.top-size/2)+"px";
    target.style.position=target.style.position||"relative";
    target.style.overflow="hidden";
    target.appendChild(ripple);
    setTimeout(function(){if(ripple.parentNode)ripple.parentNode.removeChild(ripple)},600);
  }catch(e){}
}

// ===== v5.9.0 Immersive Features =====
function openCharPanel(){
  try{
    if(!curRole)return;
    var g=gradFor(0);
    $("cpAvatar").textContent=curRole.emoji||"✨";
    $("cpAvatar").style.setProperty("--c1",g[0]);
    $("cpAvatar").style.setProperty("--c2",g[1]);
    $("cpName").textContent=curRole.name;
    $("cpCat").textContent=curRole.cat||"";
    $("cpDesc").textContent=(curRole.prompt||"").substring(0,200)+"...";
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    $("cpMsgCount").textContent=active.length;
    var rounds=0;
    for(var i=0;i<active.length;i++){if(active[i].r==="me")rounds++}
    $("cpChatCount").textContent=rounds;
    // Detect mood from last AI message
    var lastAi="";
    for(var i=active.length-1;i>=0;i--){if(active[i].r==="ai"&&!active[i].compressed){lastAi=active[i].t;break}}
    var mood="😊";
    if(lastAi){
      if(lastAi.indexOf("开心")>=0||lastAi.indexOf("高兴")>=0||lastAi.indexOf("嘻")>=0)mood="😄";
      else if(lastAi.indexOf("生气")>=0||lastAi.indexOf("怒")>=0||lastAi.indexOf("哼")>=0)mood="😤";
      else if(lastAi.indexOf("哭")>=0||lastAi.indexOf("伤心")>=0||lastAi.indexOf("难过")>=0)mood="😢";
      else if(lastAi.indexOf("害羞")>=0||lastAi.indexOf("脸红")>=0)mood="😳";
      else if(lastAi.indexOf("困")>=0||lastAi.indexOf("累")>=0)mood="😴";
      else if(lastAi.indexOf("惊讶")>=0||lastAi.indexOf("震惊")>=0)mood="😱";
    }
    $("cpMood").textContent=mood;
    // v8.0.0 Various metrics
    $("cpIntimacy").textContent=getIntimacy(curRole.id);
    $("cpTrust").textContent=getTrust(curRole.id);
    $("cpDepend").textContent=getDependence(curRole.id);
    $("cpActivity").textContent=getActivity(curRole.id);
    $("charPanel").className="char-panel on";
  }catch(e){showErr("openCharPanel错误:"+e.message)}
}
