// ===== Heart Commands (心动指令) =====
function sendHeartCmd(cmd){
  try{
    if(isGen){showToast("请先等待回复完成");return}
    if(!curRole){showErr("未选择角色");return}
    var cmds={
      hug:"(我走上前，给了"+curRole.name+"一个大大的拥抱)",
      pat:"(我轻轻摸了摸"+curRole.name+"的头)",
      hold:"(我牵起了"+curRole.name+"的手)",
      kiss:"(我轻轻在"+curRole.name+"额头上亲了一下)",
      gift:"(我递给"+curRole.name+"一份精心准备的礼物)",
      confess:"(我认真地看着"+curRole.name+"的眼睛，说：我喜欢你)",
      tease:"(我凑近"+curRole.name+"的耳边，坏笑着说了一句悄悄话)",
      comfort:"(我轻轻抱住"+curRole.name+"，拍着背安慰着)",
      feed:"(我拿出一块零食，递到"+curRole.name+"嘴边)",
      sleep:"(夜深了，我依偎在"+curRole.name+"身边，渐渐睡去)",
      spar:"(我向"+curRole.name+"发起了一场友好的切磋)",
      order:"(我轻声对"+curRole.name+"下达了一个指令)",
      call:"(我拨通了"+curRole.name+"的电话)",
      date:"(我邀请"+curRole.name+"一起去约会)"
    };
    var text=cmds[cmd]||"";
    if(!text)return;
    var inp=$("inp");
    if(inp){
      inp.value=text;
      inp.focus();
    }
    // Auto-send
    send();
    // Increase affection
    increaseAffection(cmd);
  }catch(e){showErr("sendHeartCmd错误:"+e.message)}
}

// ===== v8.0.0 Enhanced Affection & Mood System =====
var RELATION_STAGES=[
  {name:"陌生",icon:"😐",min:0},
  {name:"熟悉",icon:"🙂",min:20},
  {name:"朋友",icon:"😊",min:40},
  {name:"暧昧",icon:"😳",min:60},
  {name:"恋人",icon:"🥰",min:80}
];
function getAffection(roleId){
  var aff=lsGet("aff_"+roleId);
  if(aff==null)aff=10;
  return aff;
}
function setAffection(roleId,val){
  val=Math.max(0,Math.min(100,val));
  lsSet("aff_"+roleId,val);
  updateAffectionDisplay();
}
function getAffectionStage(aff){
  for(var i=RELATION_STAGES.length-1;i>=0;i--){
    if(aff>=RELATION_STAGES[i].min)return RELATION_STAGES[i];
  }
  return RELATION_STAGES[0];
}
function getRelationStage(aff){return getAffectionStage(aff);}
function getAllAffectionData(){
  var data={};
  for(var i=0;i<roles.length;i++){
    var aff=lsGet("aff_"+roles[i].id);
    if(aff!=null)data[roles[i].id]=aff;
  }
  return data;
}
function increaseAffection(cmd){
  if(!curRole)return;
  var gains={hug:3,pat:2,hold:4,kiss:6,gift:5,confess:8,tease:3,comfort:4};
  var gain=gains[cmd]||2;
  var cur=getAffection(curRole.id);
  var oldStage=getAffectionStage(cur);
  setAffection(curRole.id,cur+gain);
  var newStage=getAffectionStage(cur+gain);
  if(newStage.name!==oldStage.name){
    showToast("💕 关系升级！"+curRole.name+"与你的关系变为「"+newStage.name+"」");
  }else if(cur+gain>=100){showToast("💕 好感度已满！"+curRole.name+"对你非常好感！")}
  else if(cur+gain>=50){showToast("💕 好感度+"+gain+"！关系越来越好~")}
  else{showToast("💕 好感度+"+gain)}
}
function updateAffectionDisplay(){
  try{
    if(!curRole)return;
    var aff=getAffection(curRole.id);
    var stage=getAffectionStage(aff);
    var sb=$("chatStatusBar");
    if(sb)sb.style.display="flex";
    var fill=$("affectionFill");
    if(fill)fill.style.width=aff+"%";
    var val=$("affectionVal");
    if(val)val.textContent=stage.icon+" "+aff;
  }catch(e){}
}

// v8.0.0 Mood system with persistent storage
function getMood(roleId){
  var m=lsGet("mood_"+roleId);
  if(m==null)m=50;
  return Math.max(0,Math.min(100,m));
}
function setMood(roleId,val){
  val=Math.max(0,Math.min(100,val));
  lsSet("mood_"+roleId,val);
}
function getAllMoodData(){
  var data={};
  for(var i=0;i<roles.length;i++){
    var m=lsGet("mood_"+roles[i].id);
    if(m!=null)data[roles[i].id]=m;
  }
  return data;
}
function adjustMoodFromMessage(roleId,text,isUser){
  var mood=getMood(roleId);
  if(isUser){
    var posWords=["喜欢","爱","想你","开心","谢谢","对不起","陪我","一起","好","棒","赞"];
    var negWords=["讨厌","滚","烦","差","坏","恨","别","走","死"];
    var hasPos=false,hasNeg=false;
    for(var i=0;i<posWords.length;i++){if(text.indexOf(posWords[i])>=0){hasPos=true;break}}
    for(var i=0;i<negWords.length;i++){if(text.indexOf(negWords[i])>=0){hasNeg=true;break}}
    if(hasPos)mood=Math.min(100,mood+3);
    if(hasNeg)mood=Math.max(0,mood-5);
  }else{
    if(text.indexOf("开心")>=0||text.indexOf("高兴")>=0||text.indexOf("哈哈")>=0)mood=Math.min(100,mood+2);
    else if(text.indexOf("生气")>=0||text.indexOf("怒")>=0)mood=Math.max(0,mood-4);
    else if(text.indexOf("哭")>=0||text.indexOf("难过")>=0)mood=Math.max(0,mood-3);
    else if(text.indexOf("喜欢")>=0||text.indexOf("爱")>=0)mood=Math.min(100,mood+5);
  }
  setMood(roleId,mood);
  return mood;
}
function updateMoodDisplay(){
  try{
    if(!curRole)return;
    var mood=getMood(curRole.id);
    var moodEmoji="😊";
    if(mood>=90)moodEmoji="😄";
    else if(mood>=75)moodEmoji="😊";
    else if(mood>=60)moodEmoji="🙂";
    else if(mood>=40)moodEmoji="😐";
    else if(mood>=25)moodEmoji="😔";
    else if(mood>=10)moodEmoji="😰";
    else moodEmoji="😢";
    var sb=$("chatStatusBar");
    if(sb)sb.style.display="flex";
    var fill=$("moodFill");
    if(fill)fill.style.width=mood+"%";
    var val=$("moodVal");
    if(val)val.textContent=moodEmoji+" "+mood;
  }catch(e){}
}

// ===== v8.0.0 Various Metrics (Intimacy, Trust, Dependence, Activity) =====
function getMetric(roleId,key){
  var v=lsGet(key+"_"+roleId);
  if(v==null){
    if(key==="act")return Math.floor(Math.random()*30)+20;
    return Math.floor(Math.random()*20)+10;
  }
  return Math.max(0,Math.min(100,v));
}
function setMetric(roleId,key,val){
  val=Math.max(0,Math.min(100,val));
  lsSet(key+"_"+roleId,val);
}
function getIntimacy(roleId){return getMetric(roleId,"intimacy")}
function setIntimacy(roleId,val){setMetric(roleId,"intimacy",val)}
function getTrust(roleId){return getMetric(roleId,"trust")}
function setTrust(roleId,val){setMetric(roleId,"trust",val)}
function getDependence(roleId){return getMetric(roleId,"depend")}
function setDependence(roleId,val){setMetric(roleId,"depend",val)}
function getActivity(roleId){return getMetric(roleId,"act")}
function setActivity(roleId,val){setMetric(roleId,"act",val)}
function adjustMetricsFromChat(roleId,isUser){
  try{
    var intimacy=getIntimacy(roleId);
    var trust=getTrust(roleId);
    var depend=getDependence(roleId);
    var activity=getActivity(roleId);
    if(isUser){
      activity=Math.min(100,activity+1);
      intimacy=Math.min(100,intimacy+0.5);
    }else{
      trust=Math.min(100,trust+0.3);
      depend=Math.min(100,depend+0.2);
    }
    setIntimacy(roleId,intimacy);
    setTrust(roleId,trust);
    setDependence(roleId,depend);
    setActivity(roleId,activity);
  }catch(e){}
}

// ===== Character Diary =====
function showDiary(){
  try{
    if(!curRole)return;
    closeCharPanel();
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled&&m.r==="ai"&&!m.compressed});
    var h="";
    if(active.length===0){
      h='<div style="text-align:center;color:#555;padding:40px 20px">暂无日记内容<br>继续对话来解锁角色的内心世界</div>';
    }else{
      // Generate diary entries from AI messages
      var entries=Math.min(active.length,8);
      for(var i=0;i<entries;i++){
        var idx=active.length-1-i;
        var m=active[idx];
        var text=m.t.replace(/（内心：[\s\S]*?）$/,"").replace(/\(内心：[\s\S]*?\)$/,"");
        var innerMatch=m.t.match(/（内心：([\s\S]*?)）$/);
        if(!innerMatch)innerMatch=m.t.match(/\(内心：([\s\S]*?)\)$/);
        var innerText=innerMatch?innerMatch[1]:"";
        var daysAgo=i;
        var timeText=i===0?"今天":(i===1?"昨天":(i+"天前"));
        var moodText="";
        if(text.indexOf("开心")>=0||text.indexOf("高兴")>=0)moodText="心情：开心 😄";
        else if(text.indexOf("生气")>=0||text.indexOf("怒")>=0)moodText="心情：生气 😤";
        else if(text.indexOf("害羞")>=0||text.indexOf("脸红")>=0)moodText="心情：害羞 😳";
        else if(text.indexOf("哭")>=0||text.indexOf("难过")>=0)moodText="心情：难过 😢";
        else moodText="心情：平静 😊";
        h+='<div class="diary-entry">';
        h+='<div class="de-time">'+timeText+'</div>';
        if(innerText){
          h+='<div class="de-text">'+esc(innerText)+'</div>';
        }else{
          h+='<div class="de-text">'+esc(text.substring(0,100)+(text.length>100?"...":""))+'</div>';
        }
        h+='<div class="de-mood">'+moodText+'</div>';
        h+='</div>';
      }
    }
    $("diaryContent").innerHTML=h;
    $("diaryPanel").className="diary-panel on";
  }catch(e){showErr("showDiary错误:"+e.message)}
}
function closeDiaryPanel(e){
  if(e&&e.target&&e.target.id!=="diaryPanel")return;
  $("diaryPanel").className="diary-panel";
}

