// v2.9.1 导出聊天记录
function exportChat(){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    if(ms.length===0){showToast("暂无聊天记录");return}
    var text="幻语AI - 与"+curRole.name+"的对话\n"+"=".repeat(30)+"\n\n";
    for(var i=0;i<ms.length;i++){
      var sender=ms[i].r==="me"?"我":curRole.name;
      text+="["+sender+"]\n"+(ms[i].t||"")+"\n\n";
    }
    if(navigator.clipboard){
      navigator.clipboard.writeText(text).then(function(){showToast("聊天记录已复制到剪贴板")});
    }else{
      var ta=document.createElement("textarea");
      ta.value=text;document.body.appendChild(ta);ta.select();
      try{document.execCommand("copy");showToast("已复制")}catch(e){}
      document.body.removeChild(ta);
    }
  }catch(e){showErr("exportChat错误:"+e.message)}
}
// v2.9 快捷发送命令
function sendQuickCmd(text){
  try{
    var inp=$("inp");
    if(inp){inp.value=text;send();}
  }catch(e){}
}
// v2.7 修复加号按钮点不开：用标志位防止document click立即关闭刚打开的菜单
document.addEventListener("click",function(e){
  try{
    if(_expandMenuJustOpened)return;
    var m=$("chatExpandMenu");
    if(m&&m.className.indexOf("on")>=0){
      var b=$("plusBtn");
      var target=e.target;
      var isPlusClick=(target===b)||(target&&target.closest&&target.closest('#plusBtn'));
      if(!isPlusClick&&!m.contains(target)){
        m.className="chat-expand-menu";
        if(b)b.className="tbtn plus";
      }
    }
  }catch(e){}
},false);
function closeExpandMenu(e){
  try{
    if(e&&e.target&&e.target.id!=="chatExpandMenu")return;
    var m=$("chatExpandMenu");
    if(m)m.className="chat-expand-menu";
    var b=$("plusBtn");
    if(b)b.className="tbtn plus";
  }catch(e){}
}
function copyLastMessage(){
  try{
    var box=$("chatBox");
    if(!box)return;
    var msgs=box.querySelectorAll(".msg-ai .msg-text");
    if(msgs.length===0){showToast("暂无AI消息可复制");return}
    var last=msgs[msgs.length-1];
    var text=last.textContent||last.innerText||"";
    if(navigator.clipboard){
      navigator.clipboard.writeText(text).then(function(){showToast("已复制到剪贴板")});
    }else{
      var ta=document.createElement("textarea");
      ta.value=text;document.body.appendChild(ta);ta.select();
      try{document.execCommand("copy");showToast("已复制")}catch(e){showErr("复制失败")}
      document.body.removeChild(ta);
    }
  }catch(e){showErr("复制失败:"+e.message)}
}

