// ===== v3.1 触摸长按检测系统（修复长按不触发问题）=====
var _longPressTimer=null;
var _longPressTriggered=false;
var _longPressStartX=0;
var _longPressStartY=0;
var _longPressMsgEl=null;
function initLongPressHandler(){
  var chatBox=$("chatBox");
  if(!chatBox)return;
  chatBox.addEventListener("touchstart",function(e){
    _longPressTriggered=false;
    if(!e.target)return;
    var msgEl=e.target.closest?e.target.closest('.msg'):null;
    if(!msgEl)return;
    var touch=e.touches[0];
    _longPressStartX=touch.clientX;
    _longPressStartY=touch.clientY;
    _longPressMsgEl=msgEl;
    _longPressTimer=setTimeout(function(){
      _longPressTriggered=true;
      if(navigator.vibrate)try{navigator.vibrate(50)}catch(e){}
      showMsgActionMenu(_longPressMsgEl);
    },500);
  },{passive:true});
  chatBox.addEventListener("touchmove",function(e){
    if(_longPressTimer&&e.touches[0]){
      var dx=Math.abs(e.touches[0].clientX-_longPressStartX);
      var dy=Math.abs(e.touches[0].clientY-_longPressStartY);
      if(dx>10||dy>10){clearTimeout(_longPressTimer);_longPressTimer=null}
    }
  },{passive:true});
  chatBox.addEventListener("touchend",function(e){
    if(_longPressTimer){clearTimeout(_longPressTimer);_longPressTimer=null}
    if(_longPressTriggered){
      _longPressTriggered=false;
      if(e.preventDefault)e.preventDefault();
      if(e.stopPropagation)e.stopPropagation();
    }
  },{passive:false});
  chatBox.addEventListener("click",function(e){
    if(_longPressTriggered){
      _longPressTriggered=false;
      if(e.preventDefault)e.preventDefault();
      if(e.stopPropagation)e.stopPropagation();
      return false;
    }
  },true);
}

