// ===== Transformers.js (WASM 本地模型推理，无需 WebGPU) =====
var tfjsEngine=null,tfjsLoaded=false,tfjsLoading=false;
var _tfjsAutoLoadStarted=false;

// v3.2.0 修复：transformers.js 是 ES Module，必须用 module script 加载
function loadTransformersJS(cb){
  try{
    if(window.transformers){cb(null);return}
    if(tfjsLoading){showToast("正在加载AI引擎...");return}
    tfjsLoading=true;

    var cdns=[
      "https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.0.2",
      "https://esm.sh/@huggingface/transformers@3.0.2",
      "https://unpkg.com/@huggingface/transformers@3.0.2",
      "https://fastly.jsdelivr.net/npm/@huggingface/transformers@3.0.2"
    ];

    function tryScript(idx){
      if(idx>=cdns.length){
        tfjsLoading=false;
        cb("Transformers.js 所有CDN加载失败");
        return;
      }
      console.log("[Transformers.js] 尝试CDN",idx+1,":",cdns[idx].substring(0,50));
      var s=document.createElement("script");
      s.type="module";
      s.textContent='import * as m from "'+cdns[idx]+'"; window.__tfjs=m; window.dispatchEvent(new Event("__tfjs_ready"));';
      var done=false;
      var timeout=setTimeout(function(){
        if(!done){done=true;tryScript(idx+1);}
      },20000);
      function onReady(){
        if(done)return;
        done=true;
        clearTimeout(timeout);
        window.transformers=window.__tfjs;
        var mod=window.__tfjs;
        try{
          mod.env.allowLocalModels=false;
          mod.env.useBrowserCache=(cfg.cacheModel!==false);
          // v3.2.0 根据用户设置选择镜像
          var mirror=cfg.mirror||"auto";
          if(mirror==="hf-mirror"||mirror==="auto"){
            mod.env.remoteHost="https://hf-mirror.com";
          }else if(mirror==="huggingface"){
            mod.env.remoteHost="https://huggingface.co";
          }else if(mirror==="modelscope"){
            mod.env.remoteHost="https://modelscope.cn";
          }else{
            mod.env.remoteHost="https://hf-mirror.com";
          }
          // WASM 单线程模式（WebView 不支持 SharedArrayBuffer）
          if(mod.env.backends&&mod.env.backends.onnx&&mod.env.backends.onnx.wasm){
            mod.env.backends.onnx.wasm.numThreads=1;
          }
        }catch(e){console.warn("env config error:",e)}
        console.log("[Transformers.js] 加载成功 from CDN",idx+1);
        tfjsLoading=false;
        cb(null);
      }
      window.addEventListener("__tfjs_ready",onReady,{once:true});
      s.onerror=function(){
        if(done)return;
        done=true;
        clearTimeout(timeout);
        console.warn("[Transformers.js] CDN",idx+1,"加载失败");
        tryScript(idx+1);
      };
      document.head.appendChild(s);
    }
    tryScript(0);
  }catch(e){cb("loadTransformersJS error: "+e.message)}
}

function loadTransformersModel(cb){
  try{
    if(tfjsLoaded&&tfjsEngine){cb(null);return}
    if(tfjsLoading){showToast("正在加载AI引擎...");return}
    tfjsLoading=true;
    var mlb=$("modelLoadBar");var mlbText=$("mlbText");var mlbTitle=$("mlbTitle");
    if(mlb)mlb.className="model-load-bar on";
    if(mlbTitle)mlbTitle.textContent="正在加载本地AI模型...";
    if(mlbText)mlbText.textContent="正在初始化推理引擎...";

    loadTransformersJS(function(err){
      if(err){
        tfjsLoading=false;
        if(mlb)mlb.className="model-load-bar";
        cb(err);return;
      }
      if(mlbText)mlbText.textContent="正在下载AI模型(约250MB,仅需一次)...";

      var pipeline=window.transformers.pipeline;
      // v3.2.0 根据量化精度设置选择模型和参数
      var quantLevel=cfg.quant||"q4";
      var quantized=(quantLevel==="q4");
      var modelId="Xenova/Qwen1.5-0.5B-Chat";
      if(quantLevel==="q8"){
        modelId="Xenova/Qwen1.5-0.5B-Chat-q8";
      }
      pipeline("text-generation",modelId,{
        quantized:quantized,
        progress_callback:function(info){
          try{
            if(info&&info.total&&info.loaded!==undefined){
              var pct=Math.round(info.loaded*100/info.total);
              if(mlbText)mlbText.textContent="下载模型中... "+pct+"%";
              var fill=$("mlbFill");
              if(fill)fill.style.width=pct+"%";
            }
          }catch(e){}
        }
      }).then(function(pipe){
        tfjsEngine=pipe;tfjsLoaded=true;tfjsLoading=false;
        if(mlb)mlb.className="model-load-bar";
        showToast("AI模型加载完成！现在可以真正离线对话了");
        updateModelStatus();
        cb(null);
      }).catch(function(e){
        tfjsLoading=false;
        if(mlb)mlb.className="model-load-bar";
        var msg=(e.message||e||"").toString();
        console.error("[Transformers.js] model load failed:",e);
        cb("模型加载失败: "+msg.substring(0,150));
      });
    });
  }catch(e){cb("loadTransformersModel error: "+e.message)}
}

function doTransformersRequest(am,cb,onChunk){
  try{
    if(!tfjsEngine||!tfjsLoaded){cb("AI模型未加载");return}
    var msgs=[];
    for(var i=0;i<am.length;i++){
      if(am[i].role==="system")msgs.push({role:"system",content:am[i].content});
      else if(am[i].role==="user")msgs.push({role:"user",content:am[i].content});
      else msgs.push({role:"assistant",content:am[i].content});
    }
    streamAbort=false;streamingText="";

    // v3.2.0 修复：使用 TextStreamer 进行流式输出
    var streamer=null;
    if(cfg.streamOut!==false){
    try{
      var TextStreamer=window.transformers.TextStreamer;
      if(TextStreamer&&tfjsEngine.tokenizer){
        streamer=new TextStreamer(tfjsEngine.tokenizer,{
          skip_prompt:true,
          callback_function:function(text){
            if(streamAbort)return;
            streamingText+=text;
            if(typeof onChunk==='function')onChunk(streamingText);
          }
        });
      }
    }catch(e){console.warn("TextStreamer init failed:",e)}
    }

    tfjsEngine(msgs,{
      max_new_tokens:cfg.max||256,
      temperature:cfg.temp||0.8,
      top_p:cfg.topP||0.9,
      top_k:cfg.topK||40,
      repetition_penalty:cfg.repPen||1.1,
      do_sample:true,
      streamer:streamer
    }).then(function(output){
      var txt="";
      if(Array.isArray(output)&&output[0]){
        var gen=output[0].generated_text;
        if(typeof gen==="string"){
          txt=gen;
        }else if(Array.isArray(gen)){
          for(var i=gen.length-1;i>=0;i--){
            if(gen[i]&&gen[i].role==="assistant"){txt=gen[i].content;break}
          }
        }
      }
      // 优先使用 streamer 收集的文本
      var finalTxt=streamingText||txt||"(无回复)";
      // 清理特殊 token
      finalTxt=String(finalTxt).replace(/<\|im_start\|>/g,"").replace(/<\|im_end\|>/g,"").replace(/<\|endoftext\|>/g,"").trim();
      cb(null,finalTxt);
    }).catch(function(e){
      if(streamingText){cb(null,streamingText);}
      else cb("AI推理错误: "+(e.message||e).toString().substring(0,100));
    });
  }catch(e){
    if(streamingText){cb(null,streamingText);}
    else cb("doTransformersRequest error: "+e.message);
  }
}

// v3.2.0: WebGPU 不可用时自动加载 WASM 模型
function _autoLoadTransformers(){
  if(_tfjsAutoLoadStarted)return;
  if(tfjsLoaded||tfjsLoading)return;
  // v3.2.0 尊重用户设置：如果关闭了自动加载，则不自动加载
  if(cfg.autoLoad===false)return;
  _tfjsAutoLoadStarted=true;
  setTimeout(function(){
    try{
      console.log("[v3.2.0] WebGPU不可用，自动加载WASM模型...");
      showToast("正在后台下载AI模型(约250MB)，完成后将自动切换为真实AI对话...");
      loadTransformersModel(function(err){
        if(err){
          console.warn("[v3.2.0] WASM模型自动加载失败:",err);
        }else{
          console.log("[v3.2.0] WASM模型加载成功，真实推理已就绪");
          showToast("AI模型加载完成！现在可以真实对话了");
        }
      });
    }catch(e){console.warn("auto-load error:",e)}
  },2000);
}

