var __cardLongPressTimer = null;
var __cardLongPressTarget = null;
function setupCardLongPress(){
  try{
    document.addEventListener("contextmenu", function(e){
      var card = e.target && e.target.closest && e.target.closest(".card-mini");
      if(!card) return;
      e.preventDefault();
      var rid = card.getAttribute("data-rid");
      if(rid){
        var allRoles = (typeof roles !== "undefined") ? roles : [];
        for(var i=0;i<allRoles.length;i++){
          if(allRoles[i] && allRoles[i].id === rid){
            showTemplatePreview(allRoles[i]);
            return;
          }
        }
      }
    }, false);
  }catch(e){console.warn("setupCardLongPress error",e)}
}
if(typeof window !== "undefined"){
  if(document.readyState === "complete") setupCardLongPress();
  else window.addEventListener("load", setupCardLongPress);
}
function doLocalFallbackRequest(am,cb,onChunk){
  try{
    var sys="",userText="";
    // v9.9.16 改造：history 装完整 [{r, t}] 序列（含 user+assistant），不仅 user
    var history=[];
    for(var i=0;i<am.length;i++){
      var m=am[i];
      if(m.role==="system"){
        sys+=m.content+"\n";
      } else if(m.role==="user"){
        userText=m.content;
        history.push({r:"me", t:m.content});
      } else if(m.role==="assistant"){
        history.push({r:"ai", t:m.content});
      }
    }
    var roleName=curRole?(curRole.name||"AI"):"AI";
    // 角色 prompt 单独传（更精确的人设）
    var rolePrompt = curRole ? (curRole.prompt||"") : "";
    var reply=generateLocalReply(roleName, sys, userText, history, rolePrompt);
    // v9.9.20 给本次消息打"本地模型"标记
    try{
      var __ms2 = msgs[curRole.id] || [];
      var __last = __ms2[__ms2.length - 1];
      if(__last && __last.r === "ai"){ __last.local = true; }
    }catch(e){}
    var chars=reply.split("");
    var idx=0;
    streamingText="";
    streamAbort=false;
    function emit(){
      if(streamAbort){if(cb)cb(null,streamingText||"(已停止)");return;}
      var chunkSize=Math.max(2,Math.floor(chars.length/15));
      var end=Math.min(idx+chunkSize,chars.length);
      var part=chars.slice(idx,end).join("");
      streamingText+=part;
      idx=end;
      if(typeof onChunk==='function')onChunk(streamingText);
      if(idx<chars.length){
        setTimeout(emit,30+Math.random()*40);
      }else{
        if(cb)cb(null,streamingText);
      }
    }
    emit();
  }catch(e){if(cb)cb("本地模型推理错误: "+e.message)}
}

