    h+='<div class="diag-item"><b>在线状态:</b> '+(navigator.onLine?'<span class="ok">✓ 在线</span>':'<span class="fail">✗ 离线</span>')+'</div>';
    h+='<div class="diag-item"><b>内存:</b> '+(navigator.deviceMemory?navigator.deviceMemory+'GB':'未知')+'</div>';
