// ===== v5.9.0 底部导航 =====
var currentTab="home";
var tabSwitchLock=false;
function switchBottomTab(tab){
  try{
    if(!tab)return;
    // v9.9.12 移除 tab===currentTab 检查，这是导致返回按钮失效的根因
    // 当用户在子页面（如 vCreate）时 currentTab 未更新，点击返回调用 go('home')
    // 会走到 switchBottomTab('home')，但 currentTab 仍是 'home'，导致直接 return 不执行任何操作
    if(tabSwitchLock){
      // v9.9.22 防卡死：如果锁超过 1 秒，强制解锁
      if(!window._tabLockTime) window._tabLockTime = Date.now();
      if(Date.now() - window._tabLockTime > 1000){
        tabSwitchLock = false;
        console.log("[v9.9.22] tabSwitchLock 超时强制解锁");
      } else {
        return;
      }
    }
    tabSwitchLock=true;
    window._tabLockTime = Date.now();
    setTimeout(function(){tabSwitchLock=false;window._tabLockTime=0},300);

    // v9.4.0 Auth check
    // v3.14.0 完全免费：移除登录和订阅检查
    // v9.9.22 进入创建前先刷新 VIP 状态
    // v3.14.0 完全免费，无需任何检查

    currentTab=tab;
    // 同步更新底部导航高亮
    var tabs=["btHome","btDiscover","btCreate","btMessages","btProfile"];
    for(var i=0;i<tabs.length;i++){
      var el=$(tabs[i]);
      if(el)el.className=el.className.replace(/\bon\b/,"").replace(/\s+/g," ").trim();
    }
    var tabMap={home:"btHome",discover:"btDiscover",create:"btCreate",messages:"btMessages",profile:"btProfile"};
    var cur=$(tabMap[tab]);
    if(cur)cur.className+=" on";

    // v9.9.26 修复首次点击白屏：先渲染内容再切换视图，避免空白闪烁
    // v2.4 彻底修复：所有视图在init时已同步预渲染，切换时仅切换CSS，零渲染
    // 安全兜底：如果预渲染失败，立即补充渲染（不再有白屏）
    var _needRender=true;
    if(tab==="home"){
      if(_preRendered.home&&!_forceReRender.home)_needRender=false;
      if(_needRender){renderHome();_preRendered.home=true;}
      show("vHome");
    }
    else if(tab==="discover"){
      if(_preRendered.discover&&!_forceReRender.discover)_needRender=false;
      if(_needRender){renderDiscover();_preRendered.discover=true;}
      show("vDiscover");
    }
    else if(tab==="create"){
      editingId=null;
      try{
        var _ct=$("createTitle");if(_ct)_ct.textContent="创建角色";
        var _cn=$("cName");if(_cn)_cn.value="";
        var _ce=$("cEmoji");if(_ce)_ce.value="";
        var _cc=$("cCat");if(_cc)_cc.value="陪伴";
        var _cp=$("cPrompt");if(_cp)_cp.value="";
        var _cg=$("cGreet");if(_cg)_cg.value="";
        var _cq=$("cQuick");if(_cq)_cq.value="";
        if($("cTags"))$("cTags").value="";
        if($("cDesc"))$("cDesc").value="";
        var _db=$("delBtn");if(_db)_db.style.display="none";
        var qcb=$("quickCreateBox");if(qcb)qcb.style.display="block";
      }catch(_e){console.warn("v9.9.22 create tab reset error:",_e);}
      show("vCreate");
    }
    else if(tab==="messages"){
      if(_preRendered.messages&&!_forceReRender.messages)_needRender=false;
      if(_needRender){renderMessages();_preRendered.messages=true;}
      show("vMessages");
    }
    else if(tab==="profile"){
      if(_preRendered.profile&&!_forceReRender.profile)_needRender=false;
      if(_needRender){renderProfile();_preRendered.profile=true;}
      show("vProfile");
    }
    // 重置强制重渲染标记
    _forceReRender={home:false,discover:false,messages:false,profile:false};
    notifyNativeHome(tab==="home");
  }catch(e){showErr("switchBottomTab错误:"+e.message);tabSwitchLock=false}
}

