function getTodayMatches(){
  var matches=[];
  var pool=PRESET_ROLES.slice(0,30);
  for(var i=pool.length-1;i>0;i--){
    var j=Math.floor(Math.random()*(i+1));
    var tmp=pool[i];pool[i]=pool[j];pool[j]=tmp;
  }
  var reasons=["你们都喜欢深夜聊天","性格互补，天生一对","兴趣相投，话题不断","缘分指数爆表","TA也在等你说话","性格相近，默契十足"];
  for(var i=0;i<3&&i<pool.length;i++){
    var r=pool[i];
    var score=Math.floor(Math.random()*30)+68;
    matches.push({
      id:r.id,
      name:r.name,
      emoji:r.emoji||"✨",
      cat:r.cat||"陪伴",
      matchScore:score,
      matchReason:reasons[Math.floor(Math.random()*reasons.length)]
    });
  }
  return matches;
}

function skipMatch(idx){
  showToast("已换一个匹配 💝");
  renderDiscover();
}

function exploreCategory(cat){
  if(cat==="all"){switchBottomTab("home");return}
  // 跳到首页并设置分类筛选
  switchBottomTab("home");
  homeTab="roles";
  subTabRoles="preset";
  roleCatFilter=cat;
  var ts=["tabRoles","tabStories","tabGroup"];
  for(var i=0;i<ts.length;i++)$(ts[i]).className="tab";
  $("tabRoles").className="tab on";
  renderHome();
}

var touchStartX=0,touchStartY=0,swipeCardEl=null;
function initSwipe(){
  var container=$("swipeContainer");
  if(!container)return;
  var cards=container.querySelectorAll(".swipe-card");
  if(cards.length===0)return;
  swipeCardEl=cards[cards.length-1];
  // 实际上第一个显示的是swipeStack[0], 对应swipeCard_0
  swipeCardEl=$("swipeCard_0");
  if(swipeCardEl){
    swipeCardEl.addEventListener("touchstart",onSwipeStart,{passive:true});
    swipeCardEl.addEventListener("touchmove",onSwipeMove,{passive:true});
    swipeCardEl.addEventListener("touchend",onSwipeEnd,{passive:true});
  }
}

function onSwipeStart(e){
  if(!e.touches[0])return;
  touchStartX=e.touches[0].clientX;
  touchStartY=e.touches[0].clientY;
}

function onSwipeMove(e){
  if(!e.touches[0]||!swipeCardEl)return;
  var dx=e.touches[0].clientX-touchStartX;
  var dy=e.touches[0].clientY-touchStartY;
  if(Math.abs(dx)>Math.abs(dy)){
    swipeCardEl.style.transform="translateX("+dx+"px) rotate("+(dx*0.05)+"deg)";
    swipeCardEl.style.opacity=Math.max(0.5,1-Math.abs(dx)/400);
  }
}

function onSwipeEnd(e){
  if(!swipeCardEl)return;
  var dx=0,dy=0;
  if(e.changedTouches&&e.changedTouches[0]){
    dx=e.changedTouches[0].clientX-touchStartX;
    dy=e.changedTouches[0].clientY-touchStartY;
  }
  if(Math.abs(dx)>Math.abs(dy)&&Math.abs(dx)>80){
    if(dx>0){swipeAction("like")}
    else{swipeAction("pass")}
  }else{
    swipeCardEl.style.transform="";
    swipeCardEl.style.opacity="";
  }
}

function swipeAction(action){
  try{
    if(!swipeCardEl)return;
    var rid=swipeCardEl.getAttribute("data-rid");
    if(action==="like"||action==="super"){
      swipeCardEl.className="swipe-card swiping-right";
      if(action==="super"){
        increaseAffectionDirect(rid,5);
        showHeartParticles();
        showToast("⭐ 超级喜欢！缘分+5");
      }else{
        increaseAffectionDirect(rid,3);
        showToast("♥ 已喜欢！缘分+3");
      }
    }else{
      swipeCardEl.className="swipe-card swiping-left";
    }
    // 下一张
    swipeIndex++;
    setTimeout(function(){
      var next=$("swipeCard_"+swipeIndex);
      if(next){
        swipeCardEl=next;
        swipeCardEl.addEventListener("touchstart",onSwipeStart,{passive:true});
        swipeCardEl.addEventListener("touchmove",onSwipeMove,{passive:true});
        swipeCardEl.addEventListener("touchend",onSwipeEnd,{passive:true});
      }else{
        // 所有卡片滑完，重新加载
        showToast("🎉 查看更多角色！");
        setTimeout(function(){renderDiscover()},500);
        swipeIndex=0;
      }
    },400);
  }catch(e){}
}

function increaseAffectionDirect(rid,amount){
  var cur=getAffection(rid);
  setAffection(rid,Math.min(100,cur+amount));
}

function showHeartParticles(){
  for(var i=0;i<5;i++){
    setTimeout(function(){
      var h=document.createElement("div");
      h.className="heart-particle";
      h.textContent="♥";
      h.style.left=(Math.random()*200+window.innerWidth/2-100)+"px";
      h.style.top="50%";
      h.style.color=["#fc5c8a","#fcb85c","#a78bfa","#5cfca8"][Math.floor(Math.random()*4)];
      document.body.appendChild(h);
      setTimeout(function(){h.remove()},1500);
    },i*100);
  }
}

