// ===== 消息列表页 =====
function renderMessages(){
  try{
    var c=$("messagesContent");if(!c)return;
    var h="";

    // 收集所有有消息的对话
    var chatList=[];
    var allRoles=PRESET_ROLES.concat(userRoles);
    for(var i=0;i<allRoles.length;i++){
      var r=allRoles[i];
      var m=msgs[r.id];
      if(m&&m.length>0){
        var lastMsg=m[m.length-1];
        var lastText=lastMsg.t||"";
        if(lastText.length>40)lastText=lastText.substring(0,40)+"...";
        var aff=getAffection(r.id);
        var stage=getRelationStage(aff);
        chatList.push({
          id:r.id,
          name:r.name,
          emoji:r.emoji||"✨",
          cat:r.cat||"",
          lastText:lastText,
          lastTime:lastMsg.time||"",
          msgCount:m.length,
          affection:aff,
          stage:stage,
          isOOC:lastMsg.ooc||false
        });
      }
    }

    // 也添加群聊历史
    var userGrps=lsGet("userGrps");if(!userGrps)userGrps=[];
    for(var gi=0;gi<userGrps.length;gi++){
      var ug=userGrps[gi];
      var gm=lsGet("grpMsgs_"+gi);
      if(gm&&gm.length>0){
        var lastG=gm[gm.length-1];
        chatList.push({
          id:"grp_"+gi,
          name:ug.name||"群聊",
          emoji:"👥",
          cat:"群聊",
          lastText:"["+lastG.r+"] "+(lastG.t||"").substring(0,30),
          lastTime:"",
          msgCount:gm.length,
          affection:0,
          stage:"",
          isGroup:true
        });
      }
    }

    // 按消息数排序
    chatList.sort(function(a,b){return b.msgCount-a.msgCount});

    if(chatList.length===0){
      h+='<div class="empty-state"><div class="es-icon">💬</div><div class="es-text">还没有对话记录</div><div class="es-hint">去发现页找到心仪的角色开始聊天吧！</div></div>';
    }else{
      // v8.0.0 batch delete button for messages
      h+='<div style="display:flex;justify-content:flex-end;padding:0 4px 10px"><button onclick="toggleBatchMode(\'messages\')" style="background:rgba(124,92,252,.1);border:1px solid rgba(124,92,252,.2);color:#a78bfa;padding:6px 14px;border-radius:10px;font-size:12px;font-weight:600;cursor:pointer">'+(!batchMode||batchType!=="messages"?'🗑️ 批量清除':'✓ 完成')+'</button></div>';
      // 关系进行中
      var activeChats=chatList.filter(function(c){return c.affection>=10});
      if(activeChats.length>0){
        h+='<div class="section-divider"><span class="sd-line"></span><span class="sd-text">💕 关系进行中 ('+activeChats.length+')</span><span class="sd-line"></span></div>';
        for(var i=0;i<activeChats.length;i++){
          h+=renderChatListItem(activeChats[i],i);
        }
      }
      // 其他对话
      var otherChats=chatList.filter(function(c){return c.affection<10});
      if(otherChats.length>0){
        h+='<div class="section-divider"><span class="sd-line"></span><span class="sd-text">💬 其他对话 ('+otherChats.length+')</span><span class="sd-line"></span></div>';
        for(var i=0;i<otherChats.length;i++){
          h+=renderChatListItem(otherChats[i],i);
        }
      }
    }

    c.innerHTML=h;
    // 隐藏消息红点
    var badge=$("msgBadge");
    if(badge)badge.style.display="none";
  }catch(e){showErr("renderMessages错误:"+e.message)}
}

function renderChatListItem(item,idx){
  var g=gradFor(item.id.charCodeAt(item.id.length-1)%10);
  var isSel=batchMode&&batchType==="messages"&&batchSelected.indexOf(item.id)>=0;
  var clickAction=batchMode&&batchType==="messages"?"toggleBatchItem('"+item.id+"')":(item.isGroup?"startGroupTemplateUser("+item.id.replace("grp_","")+")":"openChat('"+item.id+"')");
  var h='<div class="chat-list-item" style="position:relative" onclick="'+clickAction+'">';
  if(batchMode&&batchType==="messages"){
    h+='<div class="batch-checkbox '+(isSel?'on':'')+'" id="bc_'+item.id+'" style="top:50%;left:8px;margin-top:-11px;right:auto" onclick="event.stopPropagation();toggleBatchItem(\''+item.id+'\')">'+(isSel?'✓':'')+'</div>';
    h+='<div style="margin-left:30px">';
  }
  h+='<div class="cli-avatar" style="--c1:'+g[0]+';--c2:'+g[1]+'">'+esc(item.emoji);
  if(item.affection>=30)h+='<div class="cli-online"></div>';
  h+='</div>';
  h+='<div class="cli-info">';
  h+='<div class="cli-top"><div class="cli-name">'+esc(item.name);
  if(item.stage)h+=' <span style="font-size:10px;color:#fc5c8a;font-weight:600">'+esc(item.stage)+'</span>';
  h+='</div><div class="cli-time">'+esc(item.lastTime)+'</div></div>';
  var lastDisplay=esc(item.lastText);
  if(item.isOOC)lastDisplay='<span style="color:#fcb85c">( '+lastDisplay+' )</span>';
  h+='<div class="cli-last">'+lastDisplay+'</div>';
  h+='</div>';
  if(item.msgCount>0)h+='<div class="cli-badge">'+item.msgCount+'</div>';
  if(batchMode&&batchType==="messages")h+='</div>';
  h+='</div>';
  return h;
}

function clearAllBadges(){
  showToast("已全部标记为已读 ✓");
  var badge=$("msgBadge");
  if(badge)badge.style.display="none";
}

