function showChangelog(){
  try{
    if(document.getElementById('changelogOverlay'))return;
    var ov=document.createElement('div');
    ov.id='changelogOverlay';
    ov.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.78);z-index:99998;display:flex;align-items:center;justify-content:center;padding:16px;';
    var html='<div style="background:var(--card-bg,#151530);border:1px solid rgba(255,255,255,.08);border-radius:20px;padding:20px;max-width:94%;width:380px;max-height:85vh;overflow-y:auto;text-align:center;position:relative">';
    html+='<div style="font-size:18px;font-weight:bold;margin-bottom:10px">📋 更新日志</div>';
    html+='<div id="changelogBody" style="font-size:13px;color:#bbb;line-height:1.8;text-align:left">加载中...</div>';
    html+='<div style="text-align:center;margin-top:14px"><button id="changelogCloseBtn" style="padding:8px 30px;border:none;border-radius:20px;background:linear-gradient(135deg,#fbbf24,#f59e0b);color:#fff;font-size:14px">关闭</button></div>';
    html+='</div>';
    ov.innerHTML=html;
    ov.addEventListener('click',function(e){if(e.target===ov)document.body.removeChild(ov);});
    document.body.appendChild(ov);
    var cb=document.getElementById('changelogCloseBtn');
    if(cb){cb.addEventListener('click',function(){document.body.removeChild(ov);});}
    var xhr=new XMLHttpRequest();
    xhr.open('GET','https://api.github.com/repos/19923421354/huanyuai-chat/releases?per_page=5',true);
    xhr.onreadystatechange=function(){
      if(xhr.readyState===4){
        var body=document.getElementById('changelogBody');
        if(!body)return;
        if(xhr.status===200){
          try{
            var list=JSON.parse(xhr.responseText);
            if(!list||!list.length){body.innerHTML='暂无更新记录';return}
            var h='';
            for(var i=0;i<list.length;i++){
              var tag=list[i].tag_name||'';
              var date=(list[i].published_at||'').substring(0,10);
              var raw=list[i].body||'暂无说明';
              var lines=raw.split('\n');
              var show=[];
              for(var j=0;j<lines.length&&j<8;j++){if(lines[j].trim())show.push(lines[j]);}
              h+='<div style="margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid rgba(255,255,255,.06)">';
              h+='<div style="color:#fbbf24;font-weight:bold">'+esc(tag)+' <span style="color:#888;font-weight:normal;font-size:11px">'+esc(date)+'</span></div>';
              h+='<div style="color:#999;font-size:12px;margin-top:4px">'+esc(show.join('<br>'))+'</div></div>';
            }
            body.innerHTML=h;
          }catch(e){body.innerHTML='数据解析失败';}
        }else{
          body.innerHTML='网络错误，无法获取更新日志';
        }
      }
    };
    xhr.send();
  }catch(e){showErr("showChangelog错误:"+e.message)}
}

