function selectPlatform(key){
  try{
    var p=AI_PLATFORMS[key];
    if(!p)return;
    
    // 高亮选中的平台
    var cards=document.querySelectorAll(".platform-card");
    for(var i=0;i<cards.length;i++){
      cards[i].style.borderColor="rgba(124,92,252,.1)";
      cards[i].style.background="rgba(20,20,46,.6)";
    }
    event.currentTarget.style.borderColor="rgba(124,92,252,.4)";
    event.currentTarget.style.background="linear-gradient(135deg,rgba(124,92,252,.15),rgba(91,63,214,.08))";
    
    // 填充表单
    $("apiType").value=p.type;
    $("apiUrl").value=p.url;
    $("apiModel").value=p.model;
    
    // 更新 placeholder
    var keyInput=$("apiKey");
    keyInput.placeholder=p.keyPlaceholder;
    
    // 显示模型选择
    if(p.models.length>0){
      var modelInput=$("apiModel");
      // 创建下拉选择
      var existing=$("modelSelector");
      if(existing)existing.remove();
      
      var sel=document.createElement("div");
      sel.id="modelSelector";
      sel.style.cssText="margin-top:8px;display:flex;flex-wrap:wrap;gap:6px";
      for(var i=0;i<p.models.length;i++){
        var chip=document.createElement("div");
        var label=p.modelLabels?p.modelLabels[i]:"";
        // v9.9.31 更丰富的标签颜色：永久免费=绿色，免费层=青色，低成本=黄色，试用=橙色，付费=红色，旗舰=紫色
        var labelColor="#888";
        if(label==="永久免费")labelColor="#5cfca8";
        else if(label==="免费")labelColor="#5cfca8";
        else if(label==="免费层")labelColor="#00d4ff";
        else if(label==="低成本")labelColor="#ffd700";
        else if(label==="试用")labelColor="#ffa05c";
        else if(label==="付费")labelColor="#ff6b6b";
        else if(label==="旗舰")labelColor="#a78bfa";
        else if(label==="标准")labelColor="#888";
        else if(label==="小模型")labelColor="#5cfca8";
        else if(label==="大模型")labelColor="#ffa05c";
        chip.innerHTML='<span style="font-size:11px">'+p.models[i]+'</span>'+(label?'<span style="font-size:9px;margin-left:4px;padding:1px 5px;border-radius:6px;background:'+labelColor+'22;color:'+labelColor+'">'+label+'</span>':'');
        chip.style.cssText="padding:5px 12px;background:rgba(28,28,58,.6);border:1px solid rgba(124,92,252,.1);border-radius:12px;font-size:11px;color:#888;cursor:pointer;transition:all .2s;display:flex;align-items:center";
        chip.onclick=function(){
          var modelName=this.querySelector("span").textContent;
          modelInput.value=modelName;
          // 高亮
          var chips=sel.querySelectorAll("div");
          for(var c=0;c<chips.length;c++){
            chips[c].style.background="rgba(28,28,58,.6)";
            chips[c].style.color="#888";
            chips[c].style.borderColor="rgba(124,92,252,.1)";
          }
          this.style.background="linear-gradient(135deg,#8b6cff,#5b3fd6)";
          this.style.color="#fff";
          this.style.borderColor="transparent";
        };
        sel.appendChild(chip);
      }
      modelInput.parentNode.insertBefore(sel,modelInput.nextSibling);
    }
    
    showToast("✅ 已选择 "+p.name+"，请填入 API Key 后保存");
    
    // 自动保存配置
    cfg.type=p.type;
    cfg.url=p.url;
    cfg.model=p.model;
    lsSet("cfg",cfg);
    
    // 显示平台说明
    var existingDesc=$("platformDesc");
    if(existingDesc)existingDesc.remove();
    var desc=document.createElement("div");
    desc.id="platformDesc";
    desc.style.cssText="padding:12px;background:rgba(92,252,168,.06);border-radius:12px;font-size:12px;color:#5cfca8;margin-top:10px;border:1px solid rgba(92,252,168,.1)";
    desc.innerHTML="<b>"+p.name+"</b><br>"+p.desc+"<br><br>请在下方填入 API Key，然后点击保存。";
    var apiSettings=$("apiSettings");
    apiSettings.insertBefore(desc,apiSettings.firstChild);
  }catch(e){showErr("selectPlatform错误:"+e.message)}
}

