var activeDownloads={};
function getModelUrl(m){
  // 默认使用国内源 chinaUrl；切换镜像后使用 mirror/url
  if(!modelMirror && m.chinaUrl) return m.chinaUrl;
  return modelMirror?(m.mirror||m.url):m.url;
}
function getModelFilename(m){
  var url=getModelUrl(m);
  var name=m.name.replace(/\s+/g,"_").replace(/[^\w\-\.\u4e00-\u9fa5]/g,"");
  var ext=m.format==="gguf"?".gguf":(m.format==="safetensors"?".safetensors":".bin");
  return name+ext;
}
