function copyModelLink(idx){
  try{
    var m=MODEL_MARKET[idx];if(!m)return;
    var url=getModelUrl(m);
    if(navigator.clipboard&&navigator.clipboard.writeText){
      navigator.clipboard.writeText(url).then(function(){showToast("链接已复制到剪贴板");});
    }else{
      var ta=document.createElement("textarea");ta.value=url;ta.style.position="fixed";ta.style.opacity=0;document.body.appendChild(ta);ta.select();document.execCommand("copy");document.body.removeChild(ta);showToast("链接已复制到剪贴板");
    }
  }catch(e){showErr("复制链接失败:"+e.message)}
}
