function showStatus(msg){
  var el=$("importStatus");
  if(el){
    el.textContent=msg;
    el.style.display="block";
    setTimeout(function(){el.style.display="none"},5000);
  }
}

// ===== v7.0.0 加密系统 =====
function hashStr(s){
  var h=0;for(var i=0;i<s.length;i++){h=((h<<5)-h)+s.charCodeAt(i);h|=0}
  return h.toString(36);
}
function xorEncrypt(text,key){
  var r="";key=key||"huanyu2024";for(var i=0;i<text.length;i++){r+=String.fromCharCode(text.charCodeAt(i)^key.charCodeAt(i%key.length))}
  return btoa(unescape(encodeURIComponent(r)));
}
function xorDecrypt(enc,key){
  try{key=key||"huanyu2024";var r=decodeURIComponent(escape(atob(enc)));var out="";for(var i=0;i<r.length;i++){out+=String.fromCharCode(r.charCodeAt(i)^key.charCodeAt(i%key.length))}return out}
  catch(e){return ""}
}
// v7.0.0 Auth Functions
// v2.9 增强版：所有括号内容都变灰（像猫箱/星野），代表仅陈述事实，不进入对话
function parseBracket(text){
  try{
    var escText=esc(text);
    // Match Chinese full-width brackets （xxx）
    escText=escText.replace(/(（[^）]*）)/g,'<span class="paren">$1</span>');
    // Match ALL half-width brackets (xxx) - v2.9: 不再只匹配特定关键词，所有括号都变灰
    escText=escText.replace(/(\([^)]*\))/g,'<span class="paren">$1</span>');
    return escText;
  }catch(e){return esc(text)}
}
// ===== v9.0.0 本地登录/注册 =====
function switchAuthTab(tab){
  var tabs = document.querySelectorAll('.auth-tab');
  for(var i=0;i<tabs.length;i++) tabs[i].classList.remove('on');
  var el = document.querySelector('.auth-tab[data-tab="'+tab+'"]');
  if(el) el.classList.add('on');
  var forms = ['pwd','phone','email','social'];
  for(var i=0;i<forms.length;i++){
    var f = document.getElementById('authForm'+forms[i].charAt(0).toUpperCase()+forms[i].slice(1));
    if(f) f.style.display = forms[i]===tab ? 'block' : 'none';
  }
}

function doLocalLogin(){
  try{
    var u=$("loginUser").value.trim();var p=$("loginPass").value;
    if(!u||!p){showErr("请输入用户名和密码");return}
    if(isUserBlacklisted(u)){showErr("该账号已被管理员拉黑，无法登录");return}
    var users = getLocalUsers();
    if(!users[u]){showErr("用户不存在，请先注册");return}
    var hash = localHash(p, users[u].salt);
    if(hash !== users[u].hash){showErr("密码错误");return}
    authToken = genLocalToken(u);
    currentUser = {id: u, name: u,  loginMethod: 'pwd'};
    lsSet("authToken", authToken);
    lsSet("currentUser", currentUser);
    saveUserInfoToShared();
    showToast("登录成功，欢迎回来！");
    loadUserData();
    applyTheme();
    switchBottomTab("home");
  }catch(e){showErr("登录失败:"+e.message)}
}

function doLocalRegister(){
  try{
    var u=$("regUser").value.trim();var p=$("regPass").value;var p2=$("regPass2").value;
    var phone=$("regPhone")?$("regPhone").value.trim():"";
    if(!u||!p){showErr("请填写所有字段");return}
    if(u.length<2){showErr("用户名至少2个字符");return}
    if(phone && !/^1[3-9]\d{9}$/.test(phone)){showErr("请输入正确的手机号");return}
    if(p.length<4){showErr("密码至少4个字符");return}
    if(p!==p2){showErr("两次密码不一致");return}
    if(isUserBlacklisted(u)){showErr("该账号已被管理员拉黑，无法注册");return}
    var users = getLocalUsers();
    if(users[u]){showErr("用户已存在，请直接登录");return}
    var salt = Math.random().toString(36).substring(2, 10);
    var hash = localHash(p, salt);
    users[u] = {hash: hash, salt: salt, created: Date.now(),  loginMethod: 'pwd', phone: phone};
    saveLocalUsers(users);
    authToken = genLocalToken(u);
    currentUser = {id: u, name: u,  loginMethod: 'pwd', phone: phone, createdAt: Date.now()};
    lsSet("authToken", authToken);
    lsSet("currentUser", currentUser);
    saveUserInfoToShared();
    showToast("注册成功！欢迎加入幻语AI");
    applyTheme();
    switchBottomTab("home");
  }catch(e){showErr("注册失败:"+e.message)}
}

// 手机号绑定/换绑
function bindPhone(){
  try{
    if(!currentUser){showErr("请先登录");return}
    var existing = (currentUser.phone)?currentUser.phone:"";
    var input = prompt("请输入手机号" + (existing?"（当前: "+existing.substring(0,3)+"****"+existing.substring(7)+"，输入新号码可换绑）":""), existing);
    if(input===null) return;
    input = input.trim();
    if(!input){showErr("手机号不能为空");return}
    if(!/^1[3-9]\d{9}$/.test(input)){showErr("请输入正确的11位手机号");return}
    // 更新 currentUser
    currentUser.phone = input;
    lsSet("currentUser", currentUser);
    // 更新本地用户库
    var users = getLocalUsers();
    if(users[currentUser.id]){users[currentUser.id].phone = input; saveLocalUsers(users);}
    // 同步到共享文件
    saveUserInfoToShared();
    showToast("✅ 手机号绑定成功");
    if(typeof renderProfile==="function")renderProfile();
  }catch(e){showErr("绑定失败:"+e.message)}
}

function doPhoneLogin(){
  try{
    var phone = $("loginPhone").value.trim();
    var code = $("loginSmsCode").value.trim();
    if(!phone||phone.length<11){showErr("请输入正确的手机号");return}
    if(!code||code.length<6){showErr("请输入验证码");return}
    var savedCode = lsGet("lastSmsCode")||"";
    var savedPhone = lsGet("lastSmsPhone")||"";
    if(savedCode && savedPhone===phone && code!==savedCode){showErr("验证码错误，请重新输入");return}
    var users = getLocalUsers();
    var uid = "phone_" + phone;
    if(!users[uid]){
      users[uid] = {hash: "phone_login", salt: "", created: Date.now(),  loginMethod: 'phone', phone: phone};
      saveLocalUsers(users);
    }
    authToken = genLocalToken(uid);
    currentUser = {id: uid, name: "用户"+phone.substr(-4), isVip: users[uid].isVip||false, vipExpire: users[uid].vipExpire||0, loginMethod: 'phone', phone: phone};
    lsSet("authToken", authToken);
    lsSet("currentUser", currentUser);
    saveUserInfoToShared();
    showToast("手机号登录成功！");
    applyTheme();
    switchBottomTab("home");
  }catch(e){showErr("手机号登录失败:"+e.message)}
}

var smsCountdown = 0;
var smsUseFirebase = false;
var firebaseConfirmationResult = null;

function sendSmsCode(){
  if(smsCountdown > 0) return;
  var phone = $("loginPhone").value.trim();
  if(!phone||phone.length<11){showErr("请输入正确的手机号");return}
  var hintEl = document.getElementById("smsCodeHint");
  if(hintEl){
    hintEl.innerHTML = "正在发送验证码...";
    hintEl.style.display = "block";
  }
  $("smsBtn").disabled = true;
  if(smsUseFirebase && window.firebase && window.firebase.auth){
    var fullPhone = "+86" + phone;
    var appVerifier = new firebase.auth.RecaptchaVerifier("smsBtn",{"size":"invisible","callback":function(){}});
    firebase.auth().signInWithPhoneNumber(fullPhone, appVerifier).then(function(result){
      firebaseConfirmationResult = result;
      if(hintEl){
        hintEl.innerHTML = "✅ 验证码已通过短信发送至 "+phone+"，请查看手机短信";
        hintEl.style.display = "block";
      }
      showToast("短信已发送，请查收");
      startSmsCountdown();
    }).catch(function(err){
      $("smsBtn").disabled = false;
      if(hintEl){
        hintEl.innerHTML = "⚠ 网络短信发送失败，已切换为本地验证码模式";
        hintEl.style.display = "block";
      }
      var code = String(100000 + Math.floor(Math.random()*900000));
      lsSet("lastSmsCode", code);
      lsSet("lastSmsPhone", phone);
      if(hintEl){
        hintEl.innerHTML = "验证码已发送至 "+phone+"，验证码: <b style='font-size:18px;color:#7c3aed'>"+code+"</b>";
      }
      startSmsCountdown();
    });
  }else{
    var code = String(100000 + Math.floor(Math.random()*900000));
    lsSet("lastSmsCode", code);
    lsSet("lastSmsPhone", phone);
    if(hintEl){
      hintEl.innerHTML = "验证码已发送至 "+phone+"，验证码: <b style='font-size:18px;color:#7c3aed'>"+code+"</b>";
      hintEl.style.display = "block";
    }
    startSmsCountdown();
  }
}

function startSmsCountdown(){
  smsCountdown = 60;
  var btn = $("smsBtn");
  btn.disabled = true;
  var timer = setInterval(function(){
    smsCountdown--;
    if(btn) btn.textContent = smsCountdown + "s";
    if(smsCountdown <= 0){
      clearInterval(timer);
      if(btn){ btn.textContent = "获取验证码"; btn.disabled = false; }
    }
  }, 1000);
}

