// ===== v9.3.0 账号绑定与修改密码 =====
function showAccountSecurity(){
  try{
    var existing=$("accountSecDialog");
    if(existing)existing.remove();
    var dlg=document.createElement("div");
    dlg.id="accountSecDialog";
    dlg.style.cssText="position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.7);backdrop-filter:blur(8px);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px";
    var box=document.createElement("div");
    box.style.cssText="background:linear-gradient(135deg,#1a1a3a,#0f0f25);border-radius:24px;padding:24px;max-width:380px;width:100%;max-height:85vh;overflow-y:auto;border:1px solid rgba(124,92,252,.2);box-shadow:0 20px 60px rgba(0,0,0,.6)";
    var uid=currentUser?currentUser.id:"";
    var users=getLocalUsers();
    var u=users[uid]||{};
    var wxBound=u.bindWechat||false;
    var qqBound=u.bindQQ||false;
    var emailBound=u.email||u.bindEmail||false;
    var h="";
    h+='<div style="text-align:center;margin-bottom:16px"><div style="font-size:32px">🔐</div><div style="font-size:18px;font-weight:800;color:#a78bfa">账号与安全</div></div>';
    // 修改密码
    h+='<div style="background:rgba(8,8,20,.5);border-radius:14px;padding:14px;margin-bottom:12px">';
    h+='<div style="font-size:13px;font-weight:700;color:#5cfca8;margin-bottom:10px">🔑 修改密码</div>';
    h+='<input id="chgOldPass" type="password" placeholder="当前密码" style="width:100%;padding:10px;background:rgba(20,20,46,.6);border:1px solid rgba(124,92,252,.15);border-radius:10px;color:#e8e8f0;margin-bottom:8px;font-size:14px">';
    h+='<input id="chgNewPass" type="password" placeholder="新密码（至少4位）" style="width:100%;padding:10px;background:rgba(20,20,46,.6);border:1px solid rgba(124,92,252,.15);border-radius:10px;color:#e8e8f0;margin-bottom:8px;font-size:14px">';
    h+='<input id="chgNewPass2" type="password" placeholder="确认新密码" style="width:100%;padding:10px;background:rgba(20,20,46,.6);border:1px solid rgba(124,92,252,.15);border-radius:10px;color:#e8e8f0;margin-bottom:8px;font-size:14px">';
    h+='<button onclick="doChangePassword()" style="width:100%;padding:10px;background:linear-gradient(135deg,#8b6cff,#5b3fd6);color:#fff;border:none;border-radius:10px;font-size:14px;font-weight:700;cursor:pointer">确认修改</button>';
    h+='</div>';
    // 绑定账号
    h+='<div style="background:rgba(8,8,20,.5);border-radius:14px;padding:14px;margin-bottom:12px">';
    h+='<div style="font-size:13px;font-weight:700;color:#5cfca8;margin-bottom:10px">🔗 绑定第三方账号</div>';
    h+='<div onclick="bindAccount(\'wechat\')" style="display:flex;align-items:center;justify-content:space-between;padding:12px;background:rgba(20,20,46,.6);border-radius:10px;margin-bottom:8px;cursor:pointer"><span style="font-size:14px">💬 微信</span><span style="font-size:12px;color:'+(wxBound?'#5cfca8':'#666')+'">'+(wxBound?'✅ 已绑定':'点击绑定')+'</span></div>';
    h+='<div onclick="bindAccount(\'qq\')" style="display:flex;align-items:center;justify-content:space-between;padding:12px;background:rgba(20,20,46,.6);border-radius:10px;margin-bottom:8px;cursor:pointer"><span style="font-size:14px">🐧 QQ</span><span style="font-size:12px;color:'+(qqBound?'#5cfca8':'#666')+'">'+(qqBound?'✅ 已绑定':'点击绑定')+'</span></div>';
    h+='</div>';
    // 绑定邮箱
    h+='<div style="background:rgba(8,8,20,.5);border-radius:14px;padding:14px;margin-bottom:12px">';
    h+='<div style="font-size:13px;font-weight:700;color:#5cfca8;margin-bottom:10px">📧 绑定邮箱</div>';
    h+='<input id="bindEmailInput" type="email" placeholder="请输入邮箱地址" value="'+(emailBound?(u.email||u.bindEmail):'')+'" style="width:100%;padding:10px;background:rgba(20,20,46,.6);border:1px solid rgba(124,92,252,.15);border-radius:10px;color:#e8e8f0;margin-bottom:8px;font-size:14px">';
    h+='<button onclick="doBindEmail()" style="width:100%;padding:10px;background:linear-gradient(135deg,#5cfca8,#36d88a);color:#fff;border:none;border-radius:10px;font-size:14px;font-weight:700;cursor:pointer">'+(emailBound?'更新邮箱':'绑定邮箱')+'</button>';
    h+='</div>';
    h+='<button onclick="closeAccountSecDialog()" style="width:100%;padding:12px;background:transparent;color:#666;border:1px solid rgba(124,92,252,.1);border-radius:14px;font-size:14px;cursor:pointer">关闭</button>';
    box.innerHTML=h;
    dlg.appendChild(box);
    dlg.onclick=function(e){if(e.target===dlg)closeAccountSecDialog()};
    document.body.appendChild(dlg);
  }catch(e){showErr("showAccountSecDialog错误:"+e.message)}
}
function closeAccountSecDialog(){var d=$("accountSecDialog");if(d)d.remove()}
function doChangePassword(){
  try{
    var oldP=$("chgOldPass").value;
    var newP=$("chgNewPass").value;
    var newP2=$("chgNewPass2").value;
    if(!oldP||!newP){showErr("请填写所有字段");return}
    if(newP.length<4){showErr("新密码至少4位");return}
    if(newP!==newP2){showErr("两次密码不一致");return}
    var uid=currentUser?currentUser.id:"";
    var users=getLocalUsers();
    if(!users[uid]){showErr("用户信息不存在");return}
    if(users[uid].hash && users[uid].salt){
      var oldHash=localHash(oldP,users[uid].salt);
      if(oldHash!==users[uid].hash){showErr("当前密码错误");return}
    }
    var salt=Math.random().toString(36).substring(2,10);
    users[uid].hash=localHash(newP,salt);
    users[uid].salt=salt;
    saveLocalUsers(users);
    showToast("✅ 密码修改成功");
    closeAccountSecDialog();
  }catch(e){showErr("修改密码失败:"+e.message)}
}
function bindAccount(type){
  try{
    var names={wechat:"微信",qq:"QQ"};
    var uid=currentUser?currentUser.id:"";
    var users=getLocalUsers();
    if(!users[uid]){showErr("用户信息不存在");return}
    var key=type==='wechat'?'bindWechat':'bindQQ';
    if(users[uid][key]){
      if(confirm("确定要解除"+names[type]+"绑定？")){
        users[uid][key]=false;
        saveLocalUsers(users);
        showToast("已解除"+names[type]+"绑定");
        closeAccountSecDialog();
        setTimeout(showAccountSecurity,100);
      }
    }else{
      // 模拟绑定流程（无服务器模式）
      users[uid][key]=true;
      saveLocalUsers(users);
      showToast("✅ "+names[type]+"绑定成功");
      closeAccountSecDialog();
      setTimeout(showAccountSecurity,100);
    }
  }catch(e){showErr("绑定失败:"+e.message)}
}
function doBindEmail(){
  try{
    var email=$("bindEmailInput").value.trim();
    if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){showErr("请输入正确的邮箱地址");return}
    var uid=currentUser?currentUser.id:"";
    var users=getLocalUsers();
    if(!users[uid]){showErr("用户信息不存在");return}
    users[uid].email=email;
    users[uid].bindEmail=true;
    saveLocalUsers(users);
    if(currentUser)currentUser.email=email;
    lsSet("currentUser",currentUser);
    showToast("✅ 邮箱绑定成功");
    closeAccountSecDialog();
  }catch(e){showErr("绑定邮箱失败:"+e.message)}
}

function doLogout(){
  if(confirm("确定退出登录？")){
    authToken = "";
    currentUser = null;
    currentSub = {plan:"free",expire:0};
    lsSet("authToken", "");
    lsSet("currentUser", null);
    lsSet("subscription", currentSub);
    showToast("已退出登录");
    show("vLogin");
  }
}
function loadUserData(){
  try{
    if(!authToken)return;
    var encMsgs=lsGet("encMsgs_"+(currentUser&&currentUser.id?currentUser.id:(currentUser&&currentUser.name?currentUser.name:"anon")));
    if(encMsgs){
      try{var ek=(currentUser&&currentUser.id?currentUser.id:(currentUser&&currentUser.name?currentUser.name:"anon"))+"_key";var d=JSON.parse(xorDecrypt(encMsgs,ek));if(d)msgs=d}catch(e){}
    }
    lsSet("msgs",msgs);
  }catch(e){}
}
function saveUserData(){
  try{
    if(!authToken)return;
    var uid=(currentUser&&currentUser.id?currentUser.id:(currentUser&&currentUser.name?currentUser.name:"anon"));
    var ek=uid+"_key";
    try{lsSet("encMsgs_"+uid,xorEncrypt(JSON.stringify(msgs),ek))}catch(e){}
    lsSet("msgs",msgs);
  }catch(e){}
}

// v9.0.0 本地认证检查
function checkLocalSub(){
  try{
    // v3.14.0 完全免费，永久VIP
    currentSub = {plan: "vip", expire: 9999999999};
    lsSet("subscription", currentSub);
    // v3.14.0 完全免费
    currentSub = {plan:"vip", expire:9999999999};
    lsSet("subscription", currentSub);
  }catch(e){}
}
function checkAuth(){
  if(!authToken){show("vLogin");return false}
  // 本地模式：直接验证令牌格式
  if(authToken.startsWith("local_")){
    var parts = authToken.split("_");
    if(parts.length >= 2){
      var uid = parts[1];
      var users = getLocalUsers();
      if(users[uid] || uid.startsWith("phone_") || uid.startsWith("wechat_") || uid.startsWith("qq_") || uid.startsWith("device_")){
        // 令牌有效
      }
      // 本地订阅检查
      checkLocalSub();
    }
  }
  return true;
}

// v7.0.0 Theme System
function applyTheme(){
  try{
    var t=currentTheme||"dark";
    if(t==="system"){
      var m=window.matchMedia("(prefers-color-scheme: dark)");
      t=m.matches?"dark":"light";
    }
    document.documentElement.setAttribute("data-theme",t);
  }catch(e){}
}
function cycleTheme(){
  var themes=["dark","light","system","green","pink","ocean","sunset","midnight","rose","amber","forest","lavender"];
  var idx=themes.indexOf(currentTheme);
  if(idx<0)idx=0;
  idx=(idx+1)%themes.length;
  currentTheme=themes[idx];
  lsSet("theme",currentTheme);
  applyTheme();
  showToast("主题: "+getThemeLabel());
  renderProfile();
}
function getThemeLabel(){
  var labels={dark:"深色模式",light:"浅色模式",system:"跟随系统",green:"翡翠绿",pink:"樱花粉",ocean:"海洋蓝",sunset:"日落橙",midnight:"午夜紫",rose:"玫瑰红",amber:"琥珀金",forest:"森林绿",lavender:"薰衣草"};
  return labels[currentTheme]||"深色模式";
}
function watchSystemTheme(){
  try{
    var mq=window.matchMedia("(prefers-color-scheme: dark)");
    mq.addEventListener("change",function(){
      if(currentTheme==="system")applyTheme();
    });
  }catch(e){}
}

