var THEME_LIST=[
  {id:"dark",name:"深色",color:"#8b6cff",emoji:"🌌"},
  {id:"light",name:"浅色",color:"#6c4ce0",emoji:"☀️"},
  {id:"green",name:"翡翠",color:"#2dd4a0",emoji:"💚"},
  {id:"pink",name:"樱花",color:"#fc5c8a",emoji:"🌸"},
  {id:"ocean",name:"海洋",color:"#38bdf8",emoji:"🌊"},
  {id:"sunset",name:"日落",color:"#fb923c",emoji:"🌅"},
  {id:"midnight",name:"午夜",color:"#b85cfc",emoji:"🌃"},
  {id:"rose",name:"玫瑰",color:"#f43f5e",emoji:"🌹"},
  {id:"amber",name:"琥珀",color:"#fbbf24",emoji:"🔥"},
  {id:"forest",name:"森林",color:"#22c55e",emoji:"🌲"},
  {id:"lavender",name:"薰衣草",color:"#a78bfa",emoji:"💜"},
  {id:"system",name:"跟随",color:"#888",emoji:"🔄"}
];

function renderThemeGrid(){
  var grid=$("themeGrid");
  if(!grid)return;
  var h="";
  for(var i=0;i<THEME_LIST.length;i++){
    var t=THEME_LIST[i];
    var active=(currentTheme===t.id)?"border-color:"+t.color+";background:rgba("+hexToRgb(t.color)+",.12)":"";
    h+='<div onclick="selectTheme(\''+t.id+'\')" style="background:'+t.color+'15;border:2px solid '+(currentTheme===t.id?t.color:'transparent')+';border-radius:12px;padding:10px 6px;cursor:pointer;text-align:center;transition:all .2s">';
    h+='<div style="font-size:20px;margin-bottom:2px">'+t.emoji+'</div>';
    h+='<div style="font-size:10px;color:var(--txt)">'+t.name+'</div>';
    h+='</div>';
  }
  grid.innerHTML=h;
}

function hexToRgb(hex){
  var r=parseInt(hex.slice(1,3),16);
  var g=parseInt(hex.slice(3,5),16);
  var b=parseInt(hex.slice(5,7),16);
  return r+","+g+","+b;
}

function selectTheme(themeId){
  currentTheme=themeId;
  lsSet("theme",currentTheme);
  applyTheme();
  renderThemeGrid();
  showToast("主题已切换: "+getThemeLabel());
}

function initCustomSettings(){
  try{
    // 推理参数
    if($("cfgTemp")){$("cfgTemp").value=cfg.temp||0.8;$("tempVal").textContent=cfg.temp||0.8}
    if($("cfgTopP")){$("cfgTopP").value=cfg.topP||0.9;$("topPVal").textContent=cfg.topP||0.9}
    if($("cfgTopK")){$("cfgTopK").value=cfg.topK||40;$("topKVal").textContent=cfg.topK||40}
    if($("cfgMaxTok")){$("cfgMaxTok").value=cfg.max||512;$("maxTokVal").textContent=cfg.max||512}
    if($("cfgRepPen")){$("cfgRepPen").value=cfg.repPen||1.1;$("repPenVal").textContent=cfg.repPen||1.1}

    // 对话行为
    if($("cfgCtx")){$("cfgCtx").value=cfg.ctx||8;$("ctxVal").textContent=cfg.ctx||8}
    if($("cfgSysPrompt")){$("cfgSysPrompt").value=cfg.sysPrompt||""}
    if($("cfgTypeSpeed")){$("cfgTypeSpeed").value=cfg.typeSpeed||30;$("typeSpeedVal").textContent=cfg.typeSpeed||30}
    if($("cfgMinLen")){$("cfgMinLen").value=cfg.minLen||20;$("minLenVal").textContent=cfg.minLen||20}
    if($("cfgAutoScroll")){$("cfgAutoScroll").checked=cfg.autoScroll!==false}
    if($("cfgShowInHeart")){$("cfgShowInHeart").checked=cfg.showHeart!==false}
    if($("cfgShowTimestamp")){$("cfgShowTimestamp").checked=cfg.showTimestamp||false}
    if($("cfgEnterSend")){$("cfgEnterSend").checked=cfg.enterSend||false}

    // 外观
    renderThemeGrid();
    highlightFontSizeBtn();
    highlightBubbleStyleBtn();

    if($("cfgGlow")){$("cfgGlow").checked=cfg.glow!==false}
    if($("cfgBlur")){$("cfgBlur").checked=cfg.blur!==false}
    if($("cfgAnim")){$("cfgAnim").checked=cfg.anim!==false}
    if($("cfgPulse")){$("cfgPulse").checked=cfg.pulse!==false}

    // 高级模型管理
    highlightBackendBtn();
    highlightQuantBtn();
    if($("cfgMirror")){$("cfgMirror").value=cfg.mirror||"auto"}
    if($("cfgAutoLoad")){$("cfgAutoLoad").checked=cfg.autoLoad||false}
    if($("cfgCacheModel")){$("cfgCacheModel").checked=cfg.cacheModel!==false}
    if($("cfgStreamOut")){$("cfgStreamOut").checked=cfg.streamOut!==false}

    applyAppearanceSettings();
  }catch(e){console.warn("initCustomSettings error:",e)}
}

