function applyAppearanceSettings(){
  try{
    // 字号
    var fontSize=cfg.fontSize||15;
    document.documentElement.style.setProperty("--chat-font-size",fontSize+"px");
    // 应用到聊天气泡
    var styleId="customAppearanceStyle";
    var old=document.getElementById(styleId);
    if(old)old.remove();
    var s=document.createElement("style");
    s.id=styleId;
    var css="";
    // 字号
    css+=".bub{font-size:"+fontSize+"px!important}\n";
    // 气泡样式
    if(cfg.bubbleStyle==="rounded"){
      css+=".msg.ai .bub{border-radius:18px 18px 18px 4px!important}\n";
      css+=".msg.me .bub{border-radius:18px 18px 4px 18px!important}\n";
    }else if(cfg.bubbleStyle==="flat"){
      css+=".msg .bub{border-radius:4px!important;box-shadow:none!important}\n";
    }else if(cfg.bubbleStyle==="sharp"){
      css+=".msg.ai .bub{border-radius:0 16px 16px 0!important;border-left:3px solid var(--prim)!important}\n";
      css+=".msg.me .bub{border-radius:16px 0 0 16px!important;border-right:3px solid var(--prim)!important}\n";
    }else if(cfg.bubbleStyle==="neon"){
      css+=".msg.ai .bub{border-radius:16px!important;border:1px solid var(--prim)!important;box-shadow:0 0 10px var(--glow1),inset 0 0 8px rgba(124,92,252,.05)!important}\n";
      css+=".msg.me .bub{border-radius:16px!important;box-shadow:0 0 15px var(--glow1)!important}\n";
    }
    // 特效开关
    if(cfg.glow===false){
      css+=".msg.ai .bub,.msg.me .bub{box-shadow:none!important}\n";
      css+=".card,.mode-card,.platform-card{box-shadow:none!important}\n";
    }
    if(cfg.blur===false){
      css+=".card,.bar,.nav,.mode-card,.platform-card{backdrop-filter:none!important;-webkit-backdrop-filter:none!important}\n";
    }
    if(cfg.anim===false){
      css+=".msg{animation:none!important;opacity:1!important;transform:none!important}\n";
    }
    if(cfg.pulse===false){
      css+=".avatar-pulse,.msg.ai img{animation:none!important}\n";
    }
    // 时间戳
    if(cfg.showTimestamp){
      css+=".msg-time{display:block!important}\n";
    }else{
      css+=".msg-time{display:none!important}\n";
    }
    s.textContent=css;
    document.head.appendChild(s);
  }catch(e){console.warn("applyAppearanceSettings error:",e)}
}

