    h+='<button class="b" style="padding:10px 16px;font-size:13px;background:rgba(251,191,36,.15);color:#fbbf24;border-color:rgba(251,191,36,.3)" onclick="addQuickReply()">添加</button>';
    h+='</div>';

    // 列表
