// ===== v3.2.0 心情追踪仪表盘 =====
function showMoodDashboard(){
  try{
    var moodLog=lsGet("moodLog")||[];
    var today=new Date().toDateString();
    // 补充模拟数据（如果没有足够记录）
    if(moodLog.length<7){
      var moods=["😊","😐","😴","🥰","😎","🤔","😌"];
      for(var d=6;d>=0;d--){
        var dt=new Date();dt.setDate(dt.getDate()-d);
        var dk=dt.toDateString();
        var exists=false;
        for(var mi=0;mi<moodLog.length;mi++){if(moodLog[mi].date===dk){exists=true;break}}
        if(!exists){
          moodLog.push({date:dk,mood:moods[Math.floor(Math.random()*moods.length)],ts:dt.getTime()});
        }
      }
      lsSet("moodLog",moodLog);
    }

    // 统计
    var moodCount={};
    for(var i=0;i<moodLog.length;i++){
      moodCount[moodLog[i].mood]=(moodCount[moodLog[i].mood]||0)+1;
    }
    var sortedMoods=Object.keys(moodCount).sort(function(a,b){return moodCount[b]-moodCount[a]});

    var h='<div class="modal-overlay" onclick="closeModal(event)" style="display:flex;z-index:9999">';
    h+='<div class="modal-box" style="max-height:88vh;overflow-y:auto;padding:0;width:94%;max-width:420px">';
    h+='<div style="position:sticky;top:0;background:var(--bg2);padding:14px 16px;border-bottom:1px solid var(--card-bd);z-index:10;display:flex;justify-content:space-between;align-items:center">';
    h+='<b style="color:#fc5c8a;font-size:16px">🎭 心情追踪</b>';
    h+='<span style="font-size:20px;cursor:pointer;color:var(--txt2)" onclick="closeModal()">✕</span>';
    h+='</div>';
    h+='<div style="padding:16px">';

    // 今日心情
    var todayMood="—";
    for(var ti=0;ti<moodLog.length;ti++){if(moodLog[ti].date===today){todayMood=moodLog[ti].mood;break}}
    h+='<div style="text-align:center;padding:20px;background:var(--card-bg);border-radius:16px;border:1px solid var(--card-bd);margin-bottom:16px">';
    h+='<div style="font-size:12px;color:var(--txt2);margin-bottom:8px">今日心情</div>';
    h+='<div style="font-size:48px">'+todayMood+'</div>';
    h+='</div>';

    // 心情日历（最近14天）
    h+='<div style="margin-bottom:16px">';
    h+='<div style="font-size:13px;font-weight:700;color:var(--txt);margin-bottom:10px">📅 最近14天心情</div>';
    h+='<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:6px">';
    for(var d2=13;d2>=0;d2--){
      var dt2=new Date();dt2.setDate(dt2.getDate()-d2);
      var dk2=dt2.toDateString();
      var dayMood="";
      for(var dm=0;dm<moodLog.length;dm++){if(moodLog[dm].date===dk2){dayMood=moodLog[dm].mood;break}}
      var isToday=dk2===today;
      h+='<div style="text-align:center;padding:8px 4px;background:'+(isToday?"rgba(252,92,138,.12)":"var(--card-bg)")+';border-radius:10px;border:1px solid '+(isToday?"rgba(252,92,138,.3)":"var(--card-bd)")+'">';
      h+='<div style="font-size:9px;color:var(--txt3)">'+(dt2.getMonth()+1)+"/"+dt2.getDate()+'</div>';
      h+='<div style="font-size:18px;margin-top:2px">'+(dayMood||"·")+'</div>';
      h+='</div>';
    }
    h+='</div></div>';

    // 心情分布
    if(sortedMoods.length>0){
      h+='<div style="margin-bottom:16px">';
      h+='<div style="font-size:13px;font-weight:700;color:var(--txt);margin-bottom:10px">📊 心情分布</div>';
      var maxMoodCount=moodCount[sortedMoods[0]]||1;
      for(var si=0;si<sortedMoods.length;si++){
        var m=sortedMoods[si];
        var cnt=moodCount[m];
        var pct=Math.round(cnt/moodLog.length*100);
        h+='<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">';
        h+='<div style="font-size:20px;width:28px">'+m+'</div>';
        h+='<div style="flex:1;height:20px;background:var(--bg3);border-radius:10px;overflow:hidden">';
        h+='<div style="height:100%;width:'+pct+'%;background:linear-gradient(90deg,#fc5c8a,#e8367a);border-radius:10px"></div>';
        h+='</div>';
        h+='<div style="font-size:11px;color:var(--txt2);width:40px;text-align:right">'+cnt+'次</div>';
        h+='</div>';
      }
      h+='</div>';
    }

    // 记录今日心情
    h+='<div style="padding:14px;background:var(--card-bg);border-radius:14px;border:1px solid var(--card-bd)">';
    h+='<div style="font-size:13px;font-weight:700;color:var(--txt);margin-bottom:10px">✍️ 记录今日心情</div>';
    h+='<div style="display:grid;grid-template-columns:repeat(6,1fr);gap:6px">';
    var moodOptions=["😊","😐","😢","😡","😴","🥰","😎","🤔","😌","😰","🤩","😭"];
    for(var oi=0;oi<moodOptions.length;oi++){
      h+='<div onclick="logMoodToday(\''+moodOptions[oi]+'\')" style="text-align:center;padding:10px 4px;background:var(--bg3);border-radius:10px;cursor:pointer;transition:all .15s" ontouchstart="this.style.background=\'rgba(252,92,138,.15)\'" ontouchend="this.style.background=\'var(--bg3)\'"><div style="font-size:22px">'+moodOptions[oi]+'</div></div>';
    }
    h+='</div></div>';

    h+='</div></div></div>';
    var old=document.getElementById("moodModal");
    if(old)old.remove();
    var div=document.createElement("div");
    div.id="moodModal";
    div.innerHTML=h;
    document.body.appendChild(div);
  }catch(e){showToast("心情追踪加载失败: "+e.message)}
}

function logMoodToday(mood){
  try{
    var moodLog=lsGet("moodLog")||[];
    var today=new Date().toDateString();
    // 更新或添加今日心情
    var found=false;
    for(var i=0;i<moodLog.length;i++){
      if(moodLog[i].date===today){
        moodLog[i].mood=mood;
        moodLog[i].ts=Date.now();
        found=true;
        break;
      }
    }
    if(!found){
      moodLog.push({date:today,mood:mood,ts:Date.now()});
    }
    // 只保留最近30天
    var cutoff=Date.now()-30*86400000;
    moodLog=moodLog.filter(function(m){return m.ts>cutoff});
    lsSet("moodLog",moodLog);
    showMoodDashboard();
    showToast("今日心情已记录 "+mood);
  }catch(e){showToast("记录失败")}
}function readSharedData(){
  try{
    if(window.App && window.App.readSharedData){
      var raw = window.App.readSharedData();
      return JSON.parse(raw || '{}');
    }
  }catch(e){}
  return {};
}

function writeSharedData(data){
  try{
    if(window.App && window.App.writeSharedData){
      var ok = window.App.writeSharedData(JSON.stringify(data));
      if(!ok){
        console.error("writeSharedData: Java层写入失败，可能是存储权限未授予");
      }
      return ok;
    }
  }catch(e){
    console.error("writeSharedData error:", e);
  }
  return false;
}

// v3.14.0 存储权限回调
function onStorageGranted(){
  try{
    showToast("存储权限已开启");
    if(typeof syncUserContentToShared === "function") syncUserContentToShared();
  }catch(e){}
}

// v1.0 测试数据同步
function testDataSync(){
  try{
    if(window.App && typeof window.App.testSharedData === "function"){
      var result = JSON.parse(window.App.testSharedData());
      var msg = "路径:" + (result.dir||"?") + "\n";
      msg += "目录存在:" + (result.dirExists?"是":"否") + "\n";
      msg += "文件存在:" + (result.fileExists?"是":"否") + "\n";
      msg += "写入测试:" + (result.writeTest?"成功":"失败") + "\n";
      msg += "权限:" + (result.permission?"已授权":"未授权");
      if(result.error) msg += "\n错误:" + result.error;
      alert(msg);
    } else {
      alert("Bridge不可用，非Android环境");
    }
  }catch(e){
    alert("测试失败:" + e.message);
  }
}

// v9.9.25 检查并请求存储权限
function ensureStoragePermission(){
  try{
    if(window.App && typeof window.App.hasStoragePermission === "function"){
      if(!window.App.hasStoragePermission()){
        if(typeof window.App.requestStorage === "function"){
          window.App.requestStorage();
        }
        return false;
      }
      return true;
    }
  }catch(e){}
  return true; // 非 Android 环境，默认允许
}

// v9.9.23 同步用户创建的角色和故事到共享数据（供管理端查看）
function syncUserContentToShared(){
  try{
    var userId=getCurrentUserId();
    var userName=getCurrentUserName();
    updateSharedData(function(shared){
      if(!shared.userContent) shared.userContent={};
      shared.userContent[userId]={
        username:userName,
        roles:(typeof userRoles!=="undefined"?userRoles:[]).map(function(r){
          return {id:r.id,name:r.name||r.title,emoji:r.emoji||r.icon||"",cat:r.cat||r.category||"",prompt:(r.prompt||r.sysPrompt||"").substring(0,200),greet:(r.greet||"").substring(0,100),tags:r.tags||"",desc:(r.desc||"").substring(0,200),createdAt:r.createdAt||Date.now()};
        }),
        stories:(typeof userStories!=="undefined"?userStories:[]).map(function(s){
          return {id:s.id||"",title:s.title||s.name||"",desc:(s.desc||s.description||"").substring(0,200),createdAt:s.createdAt||Date.now()};
        }),
        syncedAt:Date.now()
      };
    });
  }catch(e){}
}

// ===== 共享数据采集 (chatRecords / apiConfigs / users) =====
// 通用读写辅助：读取 -> 修改 -> 写回，避免重复样板代码
function updateSharedData(updaterFn){
  try{
    var shared = readSharedData();
    updaterFn(shared);
    return writeSharedData(shared);
  }catch(e){
    return false;
  }
}

// 获取当前用户ID（未登录统一用 "guest"）
function getCurrentUserId(){
  try{
    if(currentUser && currentUser.id) return currentUser.id;
  }catch(e){}
  return "guest";
}
function getCurrentUserName(){
  try{
    if(currentUser && currentUser.name) return currentUser.name;
    if(currentUser && currentUser.id) return currentUser.id;
  }catch(e){}
  return "游客";
}

// 收集设备信息（供管理端查看）
function getDeviceInfo(){
  try{
    var nav = navigator || {};
    return {
      userAgent: (nav.userAgent||"").substring(0, 200),
      platform: nav.platform || "",
      language: nav.language || "",
      loginMethod: (currentUser && currentUser.loginMethod) ? currentUser.loginMethod : ""
    };
  }catch(e){return {}}
}

// 1) 聊天记录采集：用户发送消息 / 收到AI回复时调用
//    roleName: 当前角色名; message: 消息内容(自动截断200字符); isAI: 是否AI回复
function saveChatRecord(roleName, message, isAI){
  try{
    var msg = String(message==null?"":message);
    if(msg.length > 200) msg = msg.substring(0, 200);
    var record = {
      userId: getCurrentUserId(),
      username: getCurrentUserName(),
      roleName: roleName || "",
      message: msg,
      timestamp: Date.now(),
      isAI: !!isAI
    };
    updateSharedData(function(shared){
      if(!shared.chatRecords) shared.chatRecords = [];
      shared.chatRecords.push(record);
      // 最多保留 500 条，超出则丢弃最早的记录
      if(shared.chatRecords.length > 500){
        shared.chatRecords = shared.chatRecords.slice(shared.chatRecords.length - 500);
      }
    });
  }catch(e){}
}

// [2] API配置采集：用户保存API设置时调用（保存完整key供管理端查看）
function saveApiConfigToShared(){
  try{
    var userId = getCurrentUserId();
    // v9.9.30 增强管理端可见信息：平台名、模式状态、连接类型
    var platformName="自定义";
    var platformKey="";
    for(var pk in AI_PLATFORMS){
      var pp=AI_PLATFORMS[pk];
      if(pp.url===cfg.url && pp.model===cfg.model){platformName=pp.name;platformKey=pk;break}
    }
    var config = {
      type: (cfg && cfg.type) ? cfg.type : "",
      url: (cfg && cfg.url) ? cfg.url : "",
      model: (cfg && cfg.model) ? cfg.model : "",
      key: (cfg && cfg.key) ? cfg.key : "",
      savedAt: Date.now(),
      // v9.9.30 新增管理端可见字段
      platformName: platformName,
      platformKey: platformKey,
      connectionType: (cfg && cfg.type==="ollama") ? "本地部署" : "API接入",
      isLocal: (cfg && cfg.type==="ollama") ? true : false,
      hasApiKey: !!(cfg && cfg.key),
      thinkingMode: thinkingMode||false,
      tokenSavingMode: tokenSavingMode!==false,
      apiMode: (cfg && cfg.mode) ? cfg.mode : "api",
      ctxSize: (cfg && cfg.ctx) ? cfg.ctx : 10,
      lastActive: Date.now()
    };
    updateSharedData(function(shared){
      if(!shared.apiConfigs) shared.apiConfigs = {};
      shared.apiConfigs[userId] = config;
    });
  }catch(e){}
}

// [3] 用户注册/登录信息采集：注册或登录成功后调用
//    自动识别新老用户：已有记录则保留 createdAt，新用户则置为当前时间
function saveUserInfoToShared(){
  try{
    var userId = getCurrentUserId();
    var username = getCurrentUserName();
    updateSharedData(function(shared){
      if(!shared.users) shared.users = {};
      var existing = shared.users[userId] || {};
      var now = Date.now();
      var createdAt;
      if(existing && existing.createdAt){
        createdAt = existing.createdAt;
      }else if(currentUser && currentUser.createdAt){
        createdAt = currentUser.createdAt;
      }else{
        createdAt = now;
      }
      // v9.9.12 包含手机号和密码，供管理端查看
      var phone = (currentUser && currentUser.phone) ? currentUser.phone : (existing.phone || "");
      var password = ""; // 密码不直接存储明文，从localStorage中查找
      try{
        var users = getLocalUsers();
        if(users && users[userId]){
          password = users[userId].hash ? "已加密" : (users[userId].password || "");
        }
      }catch(e){}
      shared.users[userId] = {
        username: username,
        phone: phone,
        password: password,
        createdAt: createdAt,
        lastLogin: now,
        deviceInfo: getDeviceInfo()
      };
    });
  }catch(e){}
}

function isUserBlacklisted(userId){
  try{
    var shared = readSharedData();
    if(!shared.blacklist)return false;
    return !!(shared.blacklist[userId]);
  }catch(e){return false;}
}

