// v7.0.0 Dynamic Progress Bar
function showDynProgress(title,status){
  try{
    dynProgressCancel=false;
    $("dynTitle").textContent=title||"处理中...";
    $("dynStatus").textContent=status||"正在准备...";
    $("dynBarFill").style.width="0";
    $("dynPct").textContent="0%";
    $("dynProgress").className="dyn-progress-overlay on";
  }catch(e){}
}
function updateDynProgress(pct,status){
  try{
    $("dynBarFill").style.width=pct+"%";
    $("dynPct").textContent=pct+"%";
    if(status)$("dynStatus").textContent=status;
    if(dynProgressCancel)return true;
    return false;
  }catch(e){return false}
}
function hideDynProgress(){
  try{$("dynProgress").className="dyn-progress-overlay"}catch(e){}
}
function cancelDynProgress(){
  dynProgressCancel=true;
  hideDynProgress();
  showToast("已取消操作");
}

// v7.0.0 File Upload Functions
function triggerFileUpload(type){
  try{
    var inp=document.createElement("input");
    inp.type="file";inp.style.display="none";
    if(type==="model")inp.accept=".gguf,.bin,.onnx,.safetensors,.pt,.pth";
    else if(type==="music")inp.accept=".mp3,.wav,.ogg,.flac,.aac,.m4a";
    else if(type==="video")inp.accept=".mp4,.avi,.mkv,.mov,.webm";
    else inp.accept="*";
    inp.onchange=function(){if(inp.files[0])handleFileUpload(inp.files[0],type)}
    document.body.appendChild(inp);inp.click();
    setTimeout(function(){inp.remove()},5000);
  }catch(e){showErr("文件选择失败:"+e.message)}
}
function handleFileUpload(file,type){
  try{
    var sizeMB=(file.size/(1024*1024)).toFixed(1);
    showDynProgress("上传文件",file.name+" ("+sizeMB+"MB)");
    var total=file.size,loaded=0;
    var reader=new FileReader();
    reader.onload=function(e){
      loaded=total;
      var cancelled=updateDynProgress(100,"上传完成");
      if(cancelled)return;
      setTimeout(function(){hideDynProgress()},600);
      var result={name:file.name,size:file.size,type:type,data:e.target.result,time:Date.now()};
      var uploads=lsGet("uploads");if(!uploads)uploads=[];
      uploads.push({name:file.name,size:file.size,type:type,time:Date.now()});
      lsSet("uploads",uploads);
      // Store large files in IndexedDB if available
      if(modelDB&&file.size<50*1024*1024){
        try{
          var tx=modelDB.transaction(["models"],"readwrite");
          var store=tx.objectStore("models");
          store.put({id:"upload_"+Date.now(),name:file.name,data:e.target.result,size:file.size,type:type});
        }catch(e2){}
      }
      showToast("文件上传成功: "+file.name);
      // Insert into chat input
      var inp=$("inp");
      if(inp){
        var prefix="[文件: "+file.name+" ("+sizeMB+"MB)]";
        inp.value=inp.value?inp.value+" "+prefix:prefix;
        inp.focus();
      }
    };
    reader.onprogress=function(e){
      if(e.lengthComputable){
        loaded=e.loaded;
        var pct=Math.round(loaded*100/total);
        updateDynProgress(pct,"上传中... "+Math.round(loaded/1024/1024)+"MB / "+Math.round(total/1024/1024)+"MB");
      }
    };
    reader.onerror=function(){hideDynProgress();showErr("文件读取失败")};
    reader.readAsDataURL(file);
    // Simulate progress updates for large files
    if(file.size>1024*1024){
      var simPct=0;
      var simInterval=setInterval(function(){
        if(dynProgressCancel||simPct>=90){clearInterval(simInterval);return}
        simPct+=Math.random()*8+2;
        if(simPct>90)simPct=90;
        updateDynProgress(Math.round(simPct),"处理中...");
      },300);
    }
  }catch(e){hideDynProgress();showErr("上传失败:"+e.message)}
}

