// v9.4.1 全局错误捕获：屏蔽无意义的跨域 Script error，其他错误给出可读提示
window.onerror=function(msg,url,line,col,err){
  try{
    var s=String(msg||"");
    if(s.indexOf("Script error")>=0||line===0){
      console.warn("[window.onerror] 跨域脚本错误，已忽略:",msg,url);
      return true;
    }
    showErr("JS错误:"+s+" (行:"+line+")");
  }catch(e){}
  return false;
};
window.addEventListener("unhandledrejection",function(ev){
  try{
    var r=ev.reason;
    var msg=(r&&r.message)?r.message:String(r);
    if(msg&&msg.indexOf("Failed to fetch")>=0){
      console.warn("[unhandledrejection] 网络请求失败，已忽略:",msg);
      return;
    }
    console.warn("[unhandledrejection]",msg);
  }catch(e){}
});

// v3.2.0 数据备份/恢复（卸载重装不丢失）
var _backupTimer=null;
function _backupToExternal(){
  try{
    if(!window.App||typeof window.App.writeBackup!=="function")return;
    var allData={};
    if(_ls){
      for(var i=0;i<_ls.length;i++){
        var key=_ls.key(i);
        if(key) allData[key]=_ls.getItem(key);
      }
    }
    allData["_backup_time"]=Date.now();
    allData["_backup_version"]="3.2.0";
    window.App.writeBackup(JSON.stringify(allData));
  }catch(e){}
}
function _restoreFromBackup(){
  try{
    if(!window.App||typeof window.App.readBackup!=="function")return;
    var raw=window.App.readBackup();
    if(!raw)return;
    var data=JSON.parse(raw);
    if(!data||!data._backup_version)return;
    // 只在 localStorage 为空时恢复（首次安装/卸载重装）
    var hasData=false;
    if(_ls&&_ls.length>0){
      for(var i=0;i<_ls.length;i++){
        var k=_ls.key(i);
        if(k&&k.indexOf("_backup_")!==0&&k!=="visitedDiscover"){hasData=true;break;}
      }
    }
    if(!hasData){
      for(var key in data){
        if(key==="_backup_time"||key==="_backup_version")continue;
        try{_ls.setItem(key,data[key])}catch(e){}
      }
    }
  }catch(e){}
}
function _startAutoBackup(){
  if(_backupTimer)clearInterval(_backupTimer);
  _backupTimer=setInterval(function(){try{_backupToExternal()}catch(e){}},30000);
}

