// ===== v3.3.0 全局消息搜索引擎 =====
var _gsrTimer=null;
function openGlobalSearch(){
  try{
    var ov=$("globalSearchOverlay");
    if(ov){ov.className="global-search-overlay on";$("gsrInput").value="";$("gsrInput").focus();$("gsrResults").innerHTML='<div class="gsr-empty">输入关键词搜索所有对话</div>'}
  }catch(e){showErr("打开搜索失败:"+e.message)}
}
function closeGlobalSearch(){
  var ov=$("globalSearchOverlay");
  if(ov)ov.className="global-search-overlay";
}
function onGlobalSearchInput(val){
  if(_gsrTimer)clearTimeout(_gsrTimer);
  _gsrTimer=setTimeout(function(){performGlobalSearch(val)},300);
}
function performGlobalSearch(kw){
  try{
    kw=String(kw||"").toLowerCase().replace(/^\s+|\s+$/g,"");
    var box=$("gsrResults");
    if(!kw){box.innerHTML='<div class="gsr-empty">输入关键词搜索所有对话</div>';return}
    var results=[];
    var rolesMap={};
    for(var i=0;i<roles.length;i++){rolesMap[roles[i].id]=roles[i]}
    for(var rid in msgs){
      var ms=msgs[rid]||[];
      var role=rolesMap[rid];
      if(!role)continue;
      for(var j=0;j<ms.length;j++){
        var m=ms[j];
        var txt=String(m.t||"").toLowerCase();
        if(txt.indexOf(kw)>=0){
          results.push({roleId:rid,roleName:role.name,roleEmoji:role.emoji||"✨",msgIdx:j,text:m.t,sender:m.r,time:m.ts||0});
        }
      }
    }
    results.sort(function(a,b){return (b.time||0)-(a.time||0)});
    if(results.length===0){box.innerHTML='<div class="gsr-empty">未找到匹配结果</div>';return}
    var h='<div class="gsr-stats">找到 '+results.length+' 条结果</div>';
    var maxShow=Math.min(results.length,100);
    for(var k=0;k<maxShow;k++){
      var r=results[k];
      var snippet=highlightSearch(r.text,kw,80);
      h+='<div class="gsr-item" onclick="jumpToSearchResult(\''+r.roleId+'\','+r.msgIdx+')">';
      h+='<div class="gsr-role">'+esc(r.roleEmoji)+' '+esc(r.roleName)+' · '+(r.sender==="me"?"我":"AI")+'</div>';
      h+='<div class="gsr-snippet">'+snippet+'</div>';
      if(r.time){
        var dt=new Date(r.time);
        h+='<div class="gsr-meta"><span>'+(dt.getMonth()+1)+'/'+dt.getDate()+' '+dt.getHours()+':'+String(dt.getMinutes()).padStart(2,"0")+'</span></div>';
      }
      h+='</div>';
    }
    if(results.length>100){h+='<div class="gsr-empty">仅显示前100条结果</div>'}
    box.innerHTML=h;
  }catch(e){showErr("搜索失败:"+e.message)}
}
function highlightSearch(text,kw,maxLen){
  try{
    text=String(text||"");
    var lower=text.toLowerCase();
    var idx=lower.indexOf(kw);
    if(idx<0)return esc(text.substring(0,maxLen));
    var start=Math.max(0,idx-30);
    var end=Math.min(text.length,idx+kw.length+30);
    var before=esc(text.substring(start,idx));
    var match='<span class="gsr-highlight">'+esc(text.substring(idx,idx+kw.length))+'</span>';
    var after=esc(text.substring(idx+kw.length,end));
    return (start>0?"...":"")+before+match+after+(end<text.length?"...":"");
  }catch(e){return esc(String(text||"").substring(0,maxLen))}
}
function jumpToSearchResult(roleId,msgIdx){
  try{
    closeGlobalSearch();
    var role=null;
    for(var i=0;i<roles.length;i++){if(roles[i].id===roleId){role=roles[i];break}}
    if(!role)return;
    openChat(role.id);
    setTimeout(function(){
      var box=$("chatBox");
      if(box){
        var msg=box.querySelector('[data-idx="'+msgIdx+'"]');
        if(msg){
          msg.scrollIntoView({behavior:"smooth",block:"center"});
          msg.style.transition="background .3s";
          msg.style.background="rgba(252,184,92,.15)";
          setTimeout(function(){msg.style.background=""},2000);
        }
      }
    },300);
  }catch(e){}
}

// ===== v3.3.0 对话分支系统 =====
function openBranchPanel(){
  try{
    if(!curRole)return;
    var ov=$("branchOverlay");
    if(ov)ov.className="branch-overlay on";
    renderBranchList();
  }catch(e){showErr("打开分支失败:"+e.message)}
}
function closeBranchPanel(){
  var ov=$("branchOverlay");
  if(ov)ov.className="branch-overlay";
}
function renderBranchList(){
  try{
    var box=$("branchList");
    if(!box||!curRole)return;
    var branches=curRole.branches||[];
    var ms=msgs[curRole.id]||[];
    var h="";
    // 当前主线
    h+='<div class="branch-card active">';
    h+='<div class="branch-card-title">📍 主线对话</div>';
    h+='<div class="branch-card-info"><span>💬 '+ms.length+' 条消息</span></div>';
    if(ms.length>0){
      var lastMsg=ms[ms.length-1];
      h+='<div class="branch-card-preview">'+esc(String(lastMsg.t||"").substring(0,80))+(lastMsg.t&&lastMsg.t.length>80?"...":"")+'</div>';
    }
    h+='</div>';
    // 分支
    for(var i=0;i<branches.length;i++){
      var b=branches[i];
      h+='<div class="branch-card">';
      h+='<div class="branch-card-title">🌿 '+esc(b.name||("分支#"+(i+1)))+'</div>';
      h+='<div class="branch-card-info"><span>💬 '+(b.messages?b.messages.length:0)+' 条消息</span>';
      if(b.createdAt)h+='<span>📅 '+new Date(b.createdAt).toLocaleDateString()+'</span>';
      h+='</div>';
      if(b.messages&&b.messages.length>0){
        var lp=b.messages[b.messages.length-1];
        h+='<div class="branch-card-preview">'+esc(String(lp.t||"").substring(0,80))+(lp.t&&lp.t.length>80?"...":"")+'</div>';
      }
      h+='<div class="branch-actions">';
      h+='<button class="branch-btn" onclick="switchToBranch('+i+')">切换</button>';
      h+='<button class="branch-btn" onclick="mergeBranch('+i+')">合并</button>';
      h+='<button class="branch-btn danger" onclick="deleteBranch('+i+')">删除</button>';
      h+='</div>';
      h+='</div>';
    }
    if(branches.length===0){
      h+='<div class="gsr-empty">暂无分支，长按消息可创建分支</div>';
    }
    box.innerHTML=h;
  }catch(e){showErr("渲染分支失败:"+e.message)}
}
function createBranchFromIdx(idx){
  try{
    if(!curRole||idx==null)return;
    if(!curRole.branches)curRole.branches=[];
    var ms=msgs[curRole.id]||[];
    var branchMs=ms.slice(0,idx+1).map(function(m){return JSON.parse(JSON.stringify(m))});
    var bName="分支 #"+(curRole.branches.length+1);
    curRole.branches.push({name:bName,messages:branchMs,createdAt:Date.now(),parentIdx:idx});
    // 保存角色数据
    for(var i=0;i<userRoles.length;i++){if(userRoles[i].id===curRole.id){userRoles[i]=curRole;break}}
    lsSet("userRoles",userRoles);
    showToast("已创建分支: "+bName);
    openBranchPanel();
  }catch(e){showErr("创建分支失败:"+e.message)}
}
function createBranchFromHere(){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    if(ms.length===0){showToast("对话为空，无法创建分支");return}
    createBranchFromIdx(ms.length-1);
  }catch(e){}
}
function switchToBranch(bIdx){
  try{
    if(!curRole||!curRole.branches||!curRole.branches[bIdx])return;
    var b=curRole.branches[bIdx];
    // 保存当前主线为分支
    var ms=msgs[curRole.id]||[];
    if(!curRole._savedBranches)curRole._savedBranches=[];
    curRole._savedBranches.push({name:"主线备份 "+new Date().toLocaleTimeString(),messages:ms.slice(),createdAt:Date.now()});
    // 切换到分支内容
    msgs[curRole.id]=b.messages.map(function(m){return JSON.parse(JSON.stringify(m))});
    lsSet("msgs",msgs);
    renderChat();
    closeBranchPanel();
    showToast("已切换到分支: "+b.name);
  }catch(e){showErr("切换分支失败:"+e.message)}
}
function mergeBranch(bIdx){
  try{
    if(!curRole||!curRole.branches||!curRole.branches[bIdx])return;
    var b=curRole.branches[bIdx];
    var ms=msgs[curRole.id]||[];
    // 将分支消息追加到当前对话
    for(var i=0;i<b.messages.length;i++){
      var found=false;
      for(var j=0;j<ms.length;j++){
        if(ms[j].t===b.messages[i].t&&ms[j].r===b.messages[i].r){found=true;break}
      }
      if(!found)ms.push(JSON.parse(JSON.stringify(b.messages[i])));
    }
    msgs[curRole.id]=ms;
    lsSet("msgs",msgs);
    renderChat();
    showToast("分支已合并到主线");
  }catch(e){showErr("合并分支失败:"+e.message)}
}
function deleteBranch(bIdx){
  try{
    if(!curRole||!curRole.branches||!curRole.branches[bIdx])return;
    if(!confirm("确定删除此分支？"))return;
    curRole.branches.splice(bIdx,1);
    for(var i=0;i<userRoles.length;i++){if(userRoles[i].id===curRole.id){userRoles[i]=curRole;break}}
    lsSet("userRoles",userRoles);
    renderBranchList();
    showToast("分支已删除");
  }catch(e){}
}

// ===== v3.3.0 AI人格滑块面板 =====
function openPersonalityPanel(){
  try{
    if(!curRole)return;
    var p=curRole.personality||{};
    if(!p.extroversion)p.extroversion=50;
    if(!p.humor)p.humor=50;
    if(!p.patience)p.patience=50;
    if(!p.creativity)p.creativity=50;
    if(!p.logic)p.logic=50;
    if(!p.empathy)p.empathy=50;
    if(!p.warmth)p.warmth=50;
    if(!p.formality)p.formality=30;
    if(!p.assertiveness)p.assertiveness=50;
    var sliders=[
      {key:"extroversion",label:"外向程度",desc:"越高越主动健谈",min:"内向害羞",max:"外向活泼"},
      {key:"humor",label:"幽默程度",desc:"越高越爱开玩笑",min:"严肃认真",max:"风趣幽默"},
      {key:"patience",label:"耐心程度",desc:"越高越有耐心",min:"急躁直接",max:"温柔耐心"},
      {key:"creativity",label:"创造力",desc:"越高越有创意",min:"务实保守",max:"天马行空"},
      {key:"logic",label:"逻辑性",desc:"越高越理性",min:"感性为主",max:"理性分析"},
      {key:"empathy",label:"共情能力",desc:"越高越理解他人",min:"自我中心",max:"善解人意"},
      {key:"warmth",label:"温暖度",desc:"越高越温暖",min:"冷淡疏离",max:"热情温暖"},
      {key:"formality",label:"正式程度",desc:"越高越正式",min:"随意口语",max:"正式书面"},
      {key:"assertiveness",label:"主动性",desc:"越高越主动引导",min:"被动回应",max:"主动引导"}
    ];
    var h='<div class="personality-title">🎭 '+esc(curRole.name)+' 的性格</div>';
    for(var i=0;i<sliders.length;i++){
      var s=sliders[i];
      var val=p[s.key]||50;
      h+='<div class="ps-item">';
      h+='<div class="ps-label"><span>'+s.label+'</span><span class="ps-value" id="psv_'+s.key+'">'+val+'</span></div>';
      h+='<input type="range" class="ps-slider" min="0" max="100" value="'+val+'" oninput="updatePersonalityVal(\''+s.key+'\',this.value)">';
      h+='<div class="ps-desc">'+s.min+' ← '+s.desc+' → '+s.max+'</div>';
      h+='</div>';
    }
    h+='<div class="ps-preview" id="psPreview">'+generatePersonalityPreview(p)+'</div>';
    h+='<button class="feat-btn" onclick="savePersonality()">保存性格设置</button>';
    h+='<div style="height:8px"></div>';
    h+='<button class="feat-btn outline" onclick="resetPersonality()">重置为默认</button>';
    var panel=$("personalityPanelContent");
    if(panel)panel.innerHTML=h;
    var ov=$("personalityOverlay");
    if(ov)ov.className="personality-overlay on";
  }catch(e){showErr("打开性格面板失败:"+e.message)}
}
function closePersonalityPanel(){
  var ov=$("personalityOverlay");
  if(ov)ov.className="personality-overlay";
}
function updatePersonalityVal(key,val){
  try{
    if(!curRole)return;
    if(!curRole.personality)curRole.personality={};
    curRole.personality[key]=parseInt(val);
    var lbl=$("psv_"+key);
    if(lbl)lbl.textContent=val;
    var prev=$("psPreview");
    if(prev)prev.innerHTML=generatePersonalityPreview(curRole.personality);
  }catch(e){}
}
function generatePersonalityPreview(p){
  try{
    var traits=[];
    if(p.extroversion>70)traits.push("活泼开朗");
    else if(p.extroversion<30)traits.push("安静内敛");
    if(p.humor>70)traits.push("幽默风趣");
    else if(p.humor<30)traits.push("严肃认真");
    if(p.patience>70)traits.push("温柔耐心");
    else if(p.patience<30)traits.push("急躁直率");
    if(p.creativity>70)traits.push("富有创意");
    if(p.logic>70)traits.push("理性思考");
    if(p.empathy>70)traits.push("善解人意");
    if(p.warmth>70)traits.push("热情温暖");
    else if(p.warmth<30)traits.push("冷淡疏离");
    if(p.formality>70)traits.push("言辞正式");
    else if(p.formality<30)traits.push("随意自然");
    if(p.assertiveness>70)traits.push("主动引导");
    if(traits.length===0)traits.push("平衡中庸");
    return '当前性格倾向：<strong style="color:#a78bfa">'+traits.join("、")+'</strong>';
  }catch(e){return ""}
}
function savePersonality(){
  try{
    if(!curRole)return;
    for(var i=0;i<userRoles.length;i++){if(userRoles[i].id===curRole.id){userRoles[i]=curRole;break}}
    lsSet("userRoles",userRoles);
    // 更新角色prompt以反映性格变化
    applyPersonalityToPrompt();
    // v3.3.0 每日挑战：性格调整
    try{updateChallengeProgress("personality",1)}catch(e){}
    closePersonalityPanel();
    showToast("性格设置已保存");
  }catch(e){showErr("保存失败:"+e.message)}
}
function applyPersonalityToPrompt(){
  try{
    if(!curRole||!curRole.personality)return;
    var p=curRole.personality;
    var additions=[];
    if(p.extroversion>70)additions.push("性格外向活泼，主动开启话题");
    else if(p.extroversion<30)additions.push("性格内向，等待对方先开口");
    if(p.humor>70)additions.push("喜欢用幽默的方式交流");
    if(p.patience>70)additions.push("非常有耐心，会认真倾听");
    else if(p.patience<30)additions.push("说话直接了当");
    if(p.creativity>70)additions.push("富有想象力，经常提出创意想法");
    if(p.logic>70)additions.push("偏理性，善于分析");
    if(p.empathy>70)additions.push("共情能力强，善于理解对方感受");
    if(p.warmth<30)additions.push("态度冷淡，保持距离感");
    if(p.formality>70)additions.push("用词正式，措辞讲究");
    else if(p.formality<30)additions.push("说话随意自然，口语化");
    if(p.assertiveness>70)additions.push("主动引导对话方向");
    if(additions.length>0){
      var traitStr="\n\n【性格特征】"+additions.join("；")+"。";
      if(!curRole._origPrompt)curRole._origPrompt=curRole.prompt||"";
      curRole.prompt=curRole._origPrompt+traitStr;
    }
  }catch(e){}
}
function resetPersonality(){
  try{
    if(!curRole)return;
    curRole.personality={extroversion:50,humor:50,patience:50,creativity:50,logic:50,empathy:50,warmth:50,formality:30,assertiveness:50};
    if(curRole._origPrompt)curRole.prompt=curRole._origPrompt;
    openPersonalityPanel();
    showToast("已重置为默认性格");
  }catch(e){}
}

// ===== v3.3.0 消息表情回应系统 =====
var _reactionEmojis=["👍","❤️","😂","😮","😢","😡","🔥","✨","👏","🤔","😍","🥺","💪","🎉","💯","💔","😴","🤗"];
var _reactionTargetIdx=null;
function openReactionPicker(msgIdx,ev){
  try{
    if(ev)ev.stopPropagation();
    _reactionTargetIdx=msgIdx;
    var box=$("reactionPickerBox");
    if(!box)return;
    var h="";
    for(var i=0;i<_reactionEmojis.length;i++){
      h+='<div class="reaction-emoji" onclick="addReaction('+i+')">'+_reactionEmojis[i]+'</div>';
    }
    box.innerHTML=h;
    var picker=$("reactionPicker");
    if(picker)picker.className="reaction-picker show";
  }catch(e){}
}
function closeReactionPicker(){
  var picker=$("reactionPicker");
  if(picker)picker.className="reaction-picker";
  _reactionTargetIdx=null;
}
function addReaction(emojiIdx){
  try{
    if(_reactionTargetIdx==null||!curRole)return;
    var emoji=_reactionEmojis[emojiIdx];
    var ms=msgs[curRole.id]||[];
    var m=ms[_reactionTargetIdx];
    if(!m)return;
    if(!m.reactions)m.reactions={};
    if(m.reactions[emoji]){
      delete m.reactions[emoji];
    }else{
      m.reactions[emoji]=1;
      // v3.3.0 每日挑战：表情回应
      try{updateChallengeProgress("emoji",1)}catch(e){}
    }
    lsSet("msgs",msgs);
    renderChat();
    closeReactionPicker();
  }catch(e){}
}
function renderReactions(m,idx){
  try{
    if(!m.reactions||Object.keys(m.reactions).length===0)return "";
    var h='<div class="msg-reactions" onclick="event.stopPropagation()">';
    for(var emoji in m.reactions){
      h+='<span class="msg-reaction" onclick="toggleReaction('+idx+',\''+emoji+'\')">'+emoji+' <span class="msg-reaction-count">'+m.reactions[emoji]+'</span></span>';
    }
    h+='<span class="msg-reaction" onclick="openReactionPicker('+idx+',event)" style="opacity:.5">+</span>';
    h+='</div>';
    return h;
  }catch(e){return ""}
}
function toggleReaction(idx,emoji){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    var m=ms[idx];
    if(!m||!m.reactions)return;
    if(m.reactions[emoji]){
      delete m.reactions[emoji];
    }else{
      m.reactions[emoji]=1;
    }
    lsSet("msgs",msgs);
    renderChat();
  }catch(e){}
}

// ===== v3.3.0 对话书签系统 =====
function toggleBookmark(idx){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    var m=ms[idx];
    if(!m)return;
    if(!m.bookmarked){
      m.bookmarked=true;
      var note=prompt("添加书签备注（可选）：");
      if(note!==null)m.bookmarkNote=note;
      m.bookmarkTime=Date.now();
      showToast("已添加书签");
      // v3.3.0 每日挑战：书签
      try{updateChallengeProgress("bookmark",1)}catch(e){}
    }else{
      m.bookmarked=false;
      delete m.bookmarkNote;
      delete m.bookmarkTime;
      showToast("已移除书签");
    }
    lsSet("msgs",msgs);
    renderChat();
  }catch(e){}
}
function openBookmarkPanel(){
  try{
    if(!curRole)return;
    var box=$("bookmarkList");
    if(!box)return;
    var ms=msgs[curRole.id]||[];
    var bms=[];
    for(var i=0;i<ms.length;i++){
      if(ms[i].bookmarked)bms.push({idx:i,msg:ms[i]});
    }
    var h="";
    if(bms.length===0){
      h='<div class="gsr-empty">暂无书签，点击消息操作中的"书签"可添加</div>';
    }else{
      for(var j=0;j<bms.length;j++){
        var b=bms[j];
        h+='<div class="bookmark-item" onclick="jumpToBookmark('+b.idx+')">';
        if(b.msg.bookmarkNote){
          h+='<span class="bm-tag">📝 备注</span>';
          h+='<div class="bm-note">'+esc(b.msg.bookmarkNote)+'</div>';
        }else{
          h+='<span class="bm-tag">🔖 书签</span>';
        }
        h+='<div class="bm-context">'+esc(String(b.msg.t||"").substring(0,100))+'</div>';
        if(b.msg.bookmarkTime){
          h+='<div style="font-size:11px;color:#555;margin-top:4px">'+new Date(b.msg.bookmarkTime).toLocaleString()+'</div>';
        }
        h+='<div style="margin-top:8px"><button class="branch-btn danger" onclick="event.stopPropagation();removeBookmark('+b.idx+')">移除书签</button></div>';
        h+='</div>';
      }
    }
    box.innerHTML=h;
    var ov=$("bookmarkOverlay");
    if(ov)ov.className="feat-overlay on";
  }catch(e){showErr("打开书签失败:"+e.message)}
}
function closeBookmarkPanel(){
  var ov=$("bookmarkOverlay");
  if(ov)ov.className="feat-overlay";
}
function jumpToBookmark(idx){
  try{
    closeBookmarkPanel();
    var box=$("chatBox");
    if(box){
      var msg=box.querySelector('[data-idx="'+idx+'"]');
      if(msg){
        msg.scrollIntoView({behavior:"smooth",block:"center"});
        msg.style.transition="background .3s";
        msg.style.background="rgba(252,184,92,.15)";
        setTimeout(function(){msg.style.background=""},2000);
      }
    }
  }catch(e){}
}
function removeBookmark(idx){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    var m=ms[idx];
    if(!m)return;
    m.bookmarked=false;
    delete m.bookmarkNote;
    delete m.bookmarkTime;
    lsSet("msgs",msgs);
    renderChat();
    openBookmarkPanel();
  }catch(e){}
}

// ===== v3.3.0 AI多版本回复生成 =====
function generateAltReplies(){
  try{
    if(!curRole||isGen)return;
    var ms=msgs[curRole.id]||[];
    if(ms.length===0){showToast("请先发送一条消息");return}
    var lastUserMsg="";
    for(var i=ms.length-1;i>=0;i--){
      if(ms[i].r==="me"&&!ms[i].ooc){lastUserMsg=ms[i].t;break}
    }
    if(!lastUserMsg){showToast("未找到用户消息");return}
    showLoading("正在生成多个回复...");
    var altReplies=[];
    var variants=[
      {tag:"温柔版",mod:"温柔体贴地"},
      {tag:"活泼版",mod:"活泼可爱地"},
      {tag:"深沉版",mod:"深沉内敛地"},
      {tag:"幽默版",mod:"幽默风趣地"}
    ];
    var completed=0;
    for(var v=0;v<variants.length;v++){
      (function(variant){
        var modText="[请"+variant.mod+"回复以下内容] "+lastUserMsg;
        setTimeout(function(){
          try{
            if(cfg.mode==="api"&&cfg.url){
              callAPI(modText,function(resp){
                altReplies.push({tag:variant.tag,text:resp});
                completed++;
                if(completed>=variants.length)showAltReplies(altReplies);
              },function(){
                altReplies.push({tag:variant.tag,text:generateLocalReply(modText,ms.length)});
                completed++;
                if(completed>=variants.length)showAltReplies(altReplies);
              });
            }else{
              var resp=generateLocalReply(modText,ms.length);
              altReplies.push({tag:variant.tag,text:resp});
              completed++;
              if(completed>=variants.length)showAltReplies(altReplies);
            }
          }catch(e){
            altReplies.push({tag:variant.tag,text:"生成失败"});
            completed++;
            if(completed>=variants.length)showAltReplies(altReplies);
          }
        },v*100);
      })(variants[v]);
    }
  }catch(e){hideLoading();showErr("生成失败:"+e.message)}
}
function showAltReplies(replies){
  try{
    hideLoading();
    var box=$("altRepliesContent");
    if(!box)return;
    var h="";
    for(var i=0;i<replies.length;i++){
      var r=replies[i];
      h+='<div class="alt-reply-card">';
      h+='<div class="ar-tag">'+esc(r.tag)+'</div>';
      h+='<div class="ar-text">'+esc(r.text)+'</div>';
      h+='<div class="alt-reply-actions">';
      h+='<button onclick="useAltReply('+i+')">使用此回复</button>';
      h+='<button onclick="copyAltReply('+i+')">复制</button>';
      h+='</div>';
      h+='</div>';
    }
    box.innerHTML=h;
    box._altReplies=replies;
    var ov=$("altRepliesOverlay");
    if(ov)ov.className="feat-overlay on";
  }catch(e){showErr("显示回复失败:"+e.message)}
}
function closeAltReplies(){
  var ov=$("altRepliesOverlay");
  if(ov)ov.className="feat-overlay";
}
function useAltReply(idx){
  try{
    var box=$("altRepliesContent");
    if(!box||!box._altReplies||!box._altReplies[idx])return;
    var text=box._altReplies[idx].text;
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    ms.push({r:"ai",t:text,ts:Date.now()});
    msgs[curRole.id]=ms;
    lsSet("msgs",msgs);
    renderChat();
    closeAltReplies();
    showToast("已使用此回复");
  }catch(e){}
}
function copyAltReply(idx){
  try{
    var box=$("altRepliesContent");
    if(!box||!box._altReplies||!box._altReplies[idx])return;
    var text=box._altReplies[idx].text;
    if(navigator.clipboard){
      navigator.clipboard.writeText(text);
    }else{
      var ta=document.createElement("textarea");ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand("copy");document.body.removeChild(ta);
    }
    showToast("已复制到剪贴板");
  }catch(e){}
}

// ===== v3.3.0 自定义词典/文本替换引擎 =====
function openDictPanel(){
  try{
    var box=$("dictContent");
    if(!box)return;
    var dict=lsGet("customDict")||[];
    var h="";
    h+='<div style="font-size:13px;color:#888;margin-bottom:12px;line-height:1.6">设置文本替换规则，AI回复中的原词将自动替换为目标词。可用于昵称替换、错别字修正等。</div>';
    h+='<div class="dict-row">';
    h+='<input type="text" id="dictFrom" placeholder="原词" style="flex:1">';
    h+='<input type="text" id="dictTo" placeholder="替换为" style="flex:1">';
    h+='<button class="feat-btn" style="width:auto;padding:10px 16px" onclick="addDictEntry()">添加</button>';
    h+='</div>';
    h+='<div style="margin-top:14px">';
    if(dict.length===0){
      h+='<div class="gsr-empty">暂无词典条目</div>';
    }else{
      for(var i=0;i<dict.length;i++){
        h+='<div class="dict-entry">';
        h+='<span class="de-from">'+esc(dict[i].from)+'</span>';
        h+='<span class="de-arrow">→</span>';
        h+='<span class="de-to">'+esc(dict[i].to)+'</span>';
        h+='<button class="de-del" onclick="delDictEntry('+i+')">✕</button>';
        h+='</div>';
      }
    }
    h+='</div>';
    h+='<div style="height:12px"></div>';
    h+='<button class="feat-btn outline" onclick="toggleDictEnabled()">'+(lsGet("dictEnabled")===false?"启用词典":"停用词典")+'</button>';
    box.innerHTML=h;
    var ov=$("dictOverlay");
    if(ov)ov.className="feat-overlay on";
  }catch(e){showErr("打开词典失败:"+e.message)}
}
function closeDictPanel(){
  var ov=$("dictOverlay");
  if(ov)ov.className="feat-overlay";
}
function addDictEntry(){
  try{
    var from=$("dictFrom").value.replace(/^\s+|\s+$/g,"");
    var to=$("dictTo").value.replace(/^\s+|\s+$/g,"");
    if(!from){showToast("请输入原词");return}
    var dict=lsGet("customDict")||[];
    dict.push({from:from,to:to});
    lsSet("customDict",dict);
    openDictPanel();
    showToast("已添加词典条目");
  }catch(e){}
}
function delDictEntry(idx){
  try{
    var dict=lsGet("customDict")||[];
    dict.splice(idx,1);
    lsSet("customDict",dict);
    openDictPanel();
  }catch(e){}
}
function toggleDictEnabled(){
  try{
    var enabled=lsGet("dictEnabled");
    lsSet("dictEnabled",enabled===false?true:false);
    openDictPanel();
    showToast(lsGet("dictEnabled")===false?"词典已停用":"词典已启用");
  }catch(e){}
}
function applyCustomDict(text){
  try{
    if(lsGet("dictEnabled")===false)return text;
    var dict=lsGet("customDict")||[];
    if(dict.length===0)return text;
    var result=text;
    for(var i=0;i<dict.length;i++){
      var from=dict[i].from;
      var to=dict[i].to;
      if(from)result=result.split(from).join(to);
    }
    return result;
  }catch(e){return text}
}

// ===== v3.3.0 每日挑战与任务系统 =====
var DAILY_CHALLENGES=[
  {id:"chat5",icon:"💬",title:"健谈达人",desc:"与角色对话5轮",target:5,type:"chat",reward:"解锁隐藏话题"},
  {id:"chat20",icon:"🗣️",title:"话痨模式",desc:"与角色对话20轮",target:20,type:"chat",reward:"角色好感度+5"},
  {id:"useEmoji",icon:"😊",title:"表情大师",desc:"在对话中使用3次表情回应",target:3,type:"emoji",reward:"解锁表情包"},
  {id:"bookmark",icon:"🔖",title:"收藏家",desc:"添加2个对话书签",target:2,type:"bookmark",reward:"书签管理器"},
  {id:"branch",icon:"🌿",title:"平行世界",desc:"创建1个对话分支",target:1,type:"branch",reward:"分支管理器"},
  {id:"personality",icon:"🎭",title:"调音师",desc:"调整角色性格滑块",target:1,type:"personality",reward:"性格预设"},
  {id:"ooc",icon:"📝",title:"导演模式",desc:"使用3次OOC旁白",target:3,type:"ooc",reward:"导演工具"},
  {id:"regen",icon:"🔄",title:"完美主义",desc:"重新生成2次回复",target:2,type:"regen",reward:"多版本回复"},
  {id:"multichar",icon:"👥",title:"社交达人",desc:"与3个不同角色对话",target:3,type:"multichar",reward:"角色推荐"},
  {id:"longmsg",icon:"✍️",title:"长篇大论",desc:"发送一条超过50字的消息",target:1,type:"longmsg",reward:"写作助手"}
];
function getTodayChallengeKey(){
  var d=new Date();
  return "challenge_"+d.getFullYear()+"_"+(d.getMonth()+1)+"_"+d.getDate();
}
function getChallengeProgress(){
  var key=getTodayChallengeKey();
  return lsGet(key)||{};
}
function updateChallengeProgress(type,amount){
  try{
    var prog=getChallengeProgress();
    var today=new Date().toDateString();
    if(prog._date!==today){prog={_date:today}}
    for(var i=0;i<DAILY_CHALLENGES.length;i++){
      var c=DAILY_CHALLENGES[i];
      if(c.type===type){
        if(!prog[c.id])prog[c.id]=0;
        if(prog[c.id+"_done"]!==true){
          prog[c.id]+=amount||1;
          if(prog[c.id]>=c.target){
            prog[c.id+"_done"]=true;
            showToast("🎉 挑战完成: "+c.title+"！奖励: "+c.reward);
          }
        }
      }
    }
    lsSet(getTodayChallengeKey(),prog);
  }catch(e){}
}
function openChallengePanel(){
  try{
    var box=$("challengeContent");
    if(!box)return;
    var prog=getChallengeProgress();
    var h="";
    h+='<div style="text-align:center;padding:14px;background:linear-gradient(135deg,rgba(124,92,252,.1),rgba(91,63,214,.05));border-radius:16px;margin-bottom:14px">';
    h+='<div style="font-size:14px;color:#a78bfa;font-weight:700">📅 '+new Date().toLocaleDateString("zh-CN",{year:"numeric",month:"long",day:"numeric",weekday:"long"})+'</div>';
    var doneCount=0;
    for(var i=0;i<DAILY_CHALLENGES.length;i++){
      if(prog[DAILY_CHALLENGES[i].id+"_done"])doneCount++;
    }
    h+='<div style="font-size:28px;font-weight:800;color:#e0d4ff;margin:8px 0">'+doneCount+'<span style="font-size:16px;color:#666">/'+DAILY_CHALLENGES.length+'</span></div>';
    h+='<div style="font-size:12px;color:#888">已完成挑战</div>';
    h+='</div>';
    for(var i=0;i<DAILY_CHALLENGES.length;i++){
      var c=DAILY_CHALLENGES[i];
      var cur=prog[c.id]||0;
      var done=prog[c.id+"_done"]===true;
      var pct=Math.min(100,Math.round(cur/c.target*100));
      h+='<div class="challenge-card'+(done?" challenge-done":"")+'">';
      h+='<div class="challenge-title">'+c.icon+' '+c.title+(done?' <span style="color:#5cfca8">✓</span>':'')+'</div>';
      h+='<div class="challenge-desc">'+c.desc+'</div>';
      h+='<div class="challenge-progress"><div class="challenge-fill" style="width:'+pct+'%"></div></div>';
      h+='<div style="display:flex;justify-content:space-between;font-size:11px;color:#666"><span>'+cur+'/'+c.target+'</span><span class="challenge-reward">🎁 '+c.reward+'</span></div>';
      h+='</div>';
    }
    box.innerHTML=h;
    var ov=$("challengeOverlay");
    if(ov)ov.className="feat-overlay on";
  }catch(e){showErr("打开挑战失败:"+e.message)}
}
function closeChallengePanel(){
  var ov=$("challengeOverlay");
  if(ov)ov.className="feat-overlay";
}

// ===== v3.3.0 角色记忆系统增强 =====
function getMemFacts(roleId){
  try{
    var key="memFacts_"+roleId;
    return lsGet(key)||[];
  }catch(e){return []}
}
function saveMemFacts(roleId,facts){
  try{lsSet("memFacts_"+roleId,facts)}catch(e){}
}
function addMemFactManual(){
  try{
    if(!curRole)return;
    var facts=getMemFacts(curRole.id);
    var type=prompt("记忆类型(name/like/dislike/event/habit):","like");
    if(!type)return;
    var content=prompt("记忆内容:");
    if(!content)return;
    facts.push({type:type,content:content,time:Date.now(),manual:true});
    saveMemFacts(curRole.id,facts);
    renderMemFacts();
    showToast("已添加记忆");
  }catch(e){}
}
function addMemFact(){
  addMemFactManual();
}
function autoExtractMemFact(userText){
  try{
    if(!curRole)return;
    var facts=getMemFacts(curRole.id);
    // 简单关键词提取
    var patterns=[
      {re:/我叫([^\s,，。！！？?]+)/,type:"name"},
      {re:/我的名字是([^\s,，。！！？?]+)/,type:"name"},
      {re:/我喜欢([^\s,，。！？?]+)/,type:"like"},
      {re:/我爱([^\s,，。！？?]+)/,type:"like"},
      {re:/我不喜欢([^\s,，。！？?]+)/,type:"dislike"},
      {re:/我讨厌([^\s,，。！？?]+)/,type:"dislike"},
      {re:/我的([^\s,，。！？?]+)是([^\s,，。！？?]+)/,type:"habit"}
    ];
    for(var i=0;i<patterns.length;i++){
      var m=userText.match(patterns[i].re);
      if(m&&m.length>1){
        var content=m[0];
        // 避免重复
        var exists=false;
        for(var j=0;j<facts.length;j++){
          if(facts[j].content===content){exists=true;break}
        }
        if(!exists){
          facts.push({type:patterns[i].type,content:content,time:Date.now()});
          saveMemFacts(curRole.id,facts);
        }
      }
    }
  }catch(e){}
}
function renderMemFacts(){
  try{
    if(!curRole)return;
    var box=$("memEnhancedContent");
    if(!box)return;
    var facts=getMemFacts(curRole.id);
    var typeLabels={name:"姓名",like:"喜欢",dislike:"不喜欢",event:"事件",habit:"习惯"};
    var h="";
    if(facts.length===0){
      h='<div class="gsr-empty">暂无记忆，角色会在对话中自动学习你的信息</div>';
    }else{
      for(var i=0;i<facts.length;i++){
        var f=facts[i];
        h+='<div class="mem-fact">';
        h+='<button class="mem-fact-del" onclick="delMemFact('+i+')">✕</button>';
        h+='<span class="mem-fact-type '+f.type+'">'+(typeLabels[f.type]||f.type)+'</span>';
        h+='<div class="mem-fact-content">'+esc(f.content)+'</div>';
        h+='<div class="mem-fact-time">'+new Date(f.time).toLocaleString()+'</div>';
        h+='</div>';
      }
    }
    box.innerHTML=h;
    var ov=$("memEnhancedOverlay");
    if(ov)ov.className="feat-overlay on";
  }catch(e){}
}
function closeMemEnhancedPanel(){
  var ov=$("memEnhancedOverlay");
  if(ov)ov.className="feat-overlay";
}
function delMemFact(idx){
  try{
    if(!curRole)return;
    var facts=getMemFacts(curRole.id);
    facts.splice(idx,1);
    saveMemFacts(curRole.id,facts);
    renderMemFacts();
  }catch(e){}
}
function buildMemoryContext(){
  try{
    if(!curRole)return "";
    var facts=getMemFacts(curRole.id);
    if(facts.length===0)return "";
    var typeLabels={name:"姓名",like:"喜欢",dislike:"不喜欢",event:"经历",habit:"习惯"};
    var lines=["【你记得的关于对方的信息】"];
    for(var i=0;i<facts.length;i++){
      lines.push("- ("+typeLabels[facts[i].type]+") "+facts[i].content);
    }
    return lines.join("\n");
  }catch(e){return ""}
}

// ===== v3.3.0 对话导出为剧本格式 =====
var _scriptFormat="dialogue";
function openScriptExport(){
  try{
    if(!curRole)return;
    renderScriptExport();
    var ov=$("scriptExportOverlay");
    if(ov)ov.className="feat-overlay on";
  }catch(e){showErr("打开导出失败:"+e.message)}
}
function closeScriptExport(){
  var ov=$("scriptExportOverlay");
  if(ov)ov.className="feat-overlay";
}
function switchScriptFormat(fmt){
  _scriptFormat=fmt;
  renderScriptExport();
}
function renderScriptExport(){
  try{
    var box=$("scriptExportContent");
    if(!box||!curRole)return;
    var ms=msgs[curRole.id]||[];
    var h="";
    h+='<div class="script-format-tabs">';
    h+='<div class="script-format-tab'+(_scriptFormat==="dialogue"?" on":"")+'" onclick="switchScriptFormat(\'dialogue\')">💬 对话</div>';
    h+='<div class="script-format-tab'+(_scriptFormat==="script"?" on":"")+'" onclick="switchScriptFormat(\'script\')">🎬 剧本</div>';
    h+='<div class="script-format-tab'+(_scriptFormat==="novel"?" on":"")+'" onclick="switchScriptFormat(\'novel\')">📖 小说</div>';
    h+='<div class="script-format-tab'+(_scriptFormat==="json"?" on":"")+'" onclick="switchScriptFormat(\'json\')">📄 JSON</div>';
    h+='</div>';
    var preview=generateScript(ms,_scriptFormat);
    h+='<div class="script-preview">'+esc(preview.substring(0,2000))+(preview.length>2000?"\n\n... (完整内容请导出查看)":"")+'</div>';
    h+='<div style="height:12px"></div>';
    h+='<button class="feat-btn" onclick="exportScriptFile()">📥 导出文件</button>';
    h+='<div style="height:8px"></div>';
    h+='<button class="feat-btn outline" onclick="copyScriptToClipboard()">📋 复制到剪贴板</button>';
    box.innerHTML=h;
  }catch(e){}
}
function generateScript(ms,format){
  try{
    var name=curRole?curRole.name:"角色";
    var emoji=curRole?curRole.emoji:"✨";
    var result="";
    if(format==="dialogue"){
      result="═══════════════════════\n";
      result+="  "+name+" 对话记录\n";
      result+="  导出时间: "+new Date().toLocaleString("zh-CN")+"\n";
      result+="  消息数: "+ms.length+"\n";
      result+="═══════════════════════\n\n";
      for(var i=0;i<ms.length;i++){
        var m=ms[i];
        var speaker=m.r==="me"?"我":name;
        var time=m.ts?new Date(m.ts).toLocaleTimeString("zh-CN",{hour:"2-digit",minute:"2-digit"}):"";
        result+="["+time+"] "+speaker+":\n"+m.t+"\n\n";
      }
    }else if(format==="script"){
      result="━━━━━━━━━━━━━━━━━━━━━\n";
      result+="  剧本: "+name+" 的故事\n";
      result="  场景: "+(curRole?curRole.cat||"日常":"日常")+"\n";
      result="  角色: 我, "+name+"("+emoji+")\n";
      result="━━━━━━━━━━━━━━━━━━━━━\n\n";
      result+="[场景开始]\n\n";
      for(var i=0;i<ms.length;i++){
        var m=ms[i];
        if(m.r==="me"){
          result+="  我\n    "+m.t+"\n\n";
        }else{
          result+="  "+name+"\n    "+m.t+"\n\n";
        }
        if(m.ooc){
          result+="  [旁白: "+m.t+"]\n\n";
        }
      }
      result+="[场景结束]\n";
    }else if(format==="novel"){
      result=name+"的故事\n\n";
      result+="那是一个普通的日子，我和"+name+"之间的故事正在展开...\n\n";
      for(var i=0;i<ms.length;i++){
        var m=ms[i];
        if(m.r==="me"){
          result+='"'+m.t+'"\n\n';
          result+="我说道。\n\n";
        }else{
          result+=name+'微微一笑，说道：\n\n';
          result+='"'+m.t+'"\n\n';
        }
      }
      result+="\n（未完待续...）";
    }else if(format==="json"){
      var data={
        title:name+" 对话记录",
        exportTime:new Date().toISOString(),
        role:{name:name,emoji:emoji,prompt:curRole?curRole.prompt:""},
        messages:[]
      };
      for(var i=0;i<ms.length;i++){
        data.messages.push({
          index:i,
          sender:ms[i].r,
          text:ms[i].t,
          timestamp:ms[i].ts?new Date(ms[i].ts).toISOString():null,
          ooc:ms[i].ooc||false,
          bookmarked:ms[i].bookmarked||false
        });
      }
      result=JSON.stringify(data,null,2);
    }
    return result;
  }catch(e){return "生成失败: "+e.message}
}
function exportScriptFile(){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    var content=generateScript(ms,_scriptFormat);
    var ext=_scriptFormat==="json"?"json":"txt";
    var filename=curRole.name+"_对话_"+new Date().toISOString().slice(0,10)+"."+ext;
    var blob=new Blob([content],{type:"text/plain;charset=utf-8"});
    var url=URL.createObjectURL(blob);
    var a=document.createElement("a");
    a.href=url;a.download=filename;a.click();
    URL.revokeObjectURL(url);
    showToast("已导出: "+filename);
  }catch(e){showErr("导出失败:"+e.message)}
}
function copyScriptToClipboard(){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    var content=generateScript(ms,_scriptFormat);
    if(navigator.clipboard){
      navigator.clipboard.writeText(content);
    }else{
      var ta=document.createElement("textarea");ta.value=content;document.body.appendChild(ta);ta.select();document.execCommand("copy");document.body.removeChild(ta);
    }
    showToast("已复制到剪贴板");
  }catch(e){}
}

// ===== v3.3.0 情绪分析仪表盘 =====
function openEmotionAnalysis(){
  try{
    if(!curRole)return;
    var box=$("emotionAnalysisContent");
    if(!box)return;
    var ms=msgs[curRole.id]||[];
    var emotions={happy:0,sad:0,angry:0,surprised:0,neutral:0,love:0};
    var emotionEmojis={happy:"😊",sad:"😢",angry:"😡",surprised:"😮",neutral:"😐",love:"❤️"};
    var emotionLabels={happy:"开心",sad:"悲伤",angry:"生气",surprised:"惊讶",neutral:"平静",love:"心动"};
    for(var i=0;i<ms.length;i++){
      var t=String(ms[i].t||"").toLowerCase();
      var e=detectEmotion(t);
      emotions[e]++;
    }
    var total=ms.length||1;
    var h="";
    h+='<div style="text-align:center;padding:14px;margin-bottom:14px">';
    h+='<div style="font-size:14px;color:#a78bfa;font-weight:700;margin-bottom:8px">📊 '+esc(curRole.name)+' 对话情绪分析</div>';
    h+='<div style="font-size:12px;color:#666">基于 '+ms.length+' 条消息</div>';
    h+='</div>';
    // 情绪柱状图
    h+='<div class="emotion-chart">';
    var maxVal=0;
    for(var e in emotions){if(emotions[e]>maxVal)maxVal=emotions[e]}
    for(var e in emotions){
      var pct=maxVal>0?Math.round(emotions[e]/maxVal*100):0;
      h+='<div class="emotion-bar" style="height:'+Math.max(4,pct)+'%" title="'+emotionLabels[e]+': '+emotions[e]+'">';
      h+='<div class="emotion-bar-label">'+emotionEmojis[e]+'</div>';
      h+='</div>';
    }
    h+='</div>';
    h+='<div style="height:20px"></div>';
    // 统计卡片
    h+='<div class="emotion-stats">';
    for(var e in emotions){
      var pct=Math.round(emotions[e]/total*100);
      h+='<div class="emotion-stat">';
      h+='<div class="emotion-stat-val">'+pct+'%</div>';
      h+='<div class="emotion-stat-label">'+emotionEmojis[e]+' '+emotionLabels[e]+'</div>';
      h+='</div>';
    }
    h+='</div>';
    // 对话统计
    var userMsgs=0,aiMsgs=0,totalChars=0;
    for(var i=0;i<ms.length;i++){
      if(ms[i].r==="me")userMsgs++;else aiMsgs++;
      totalChars+=String(ms[i].t||"").length;
    }
    h+='<div class="chat-stat-grid">';
    h+='<div class="chat-stat-item"><div class="chat-stat-num">'+ms.length+'</div><div class="chat-stat-label">总消息数</div></div>';
    h+='<div class="chat-stat-item"><div class="chat-stat-num">'+totalChars+'</div><div class="chat-stat-label">总字数</div></div>';
    h+='<div class="chat-stat-item"><div class="chat-stat-num">'+userMsgs+'</div><div class="chat-stat-label">我发送</div></div>';
    h+='<div class="chat-stat-item"><div class="chat-stat-num">'+aiMsgs+'</div><div class="chat-stat-label">AI回复</div></div>';
    h+='</div>';
    // 活跃度热力图
    h+='<div style="font-size:13px;color:#a78bfa;font-weight:700;margin:14px 0 8px">🔥 活跃度热力图</div>';
    h+='<div class="chat-heatmap" id="emotionHeatmap"></div>';
    box.innerHTML=h;
    var ov=$("emotionAnalysisOverlay");
    if(ov)ov.className="feat-overlay on";
    // 生成热力图
    setTimeout(function(){
      var hm=$("emotionHeatmap");
      if(hm){
        var today=new Date();
        var cells="";
        for(var d=90;d>=0;d--){
          var date=new Date(today.getTime()-d*86400000);
          var dateStr=date.toISOString().slice(0,10);
          var count=0;
          for(var i=0;i<ms.length;i++){
            if(ms[i].ts){
              var md=new Date(ms[i].ts).toISOString().slice(0,10);
              if(md===dateStr)count++;
            }
          }
          var level=count===0?"":count<=2?"l1":count<=5?"l2":count<=10?"l3":"l4";
          cells+='<div class="heat-cell '+level+'" title="'+dateStr+': '+count+'条"></div>';
        }
        hm.innerHTML=cells;
      }
    },100);
  }catch(e){showErr("情绪分析失败:"+e.message)}
}
function closeEmotionAnalysis(){
  var ov=$("emotionAnalysisOverlay");
  if(ov)ov.className="feat-overlay";
}
function detectEmotion(text){
  try{
    text=String(text||"").toLowerCase();
    if(/[哈哈|嘻嘻|嘿嘿|呵呵|开心|快乐|高兴|笑|lol|happy|😄|😊|🤣|😂]/.test(text))return "happy";
    if(/[难过|伤心|悲伤|哭|委屈|心痛|sad|cry|😢|😭|💔]/.test(text))return "sad";
    if(/[生气|愤怒|气死|讨厌|烦|angry|mad|😡|😤|😠]/.test(text))return "angry";
    if(/[惊讶|震惊|天哪|哇|真的吗|surprise|wow|😮|😱|🤯]/.test(text))return "surprised";
    if(/[喜欢|爱|心动|想你|亲|抱|love|❤️|💕|💗|💖|💘]/.test(text))return "love";
    return "neutral";
  }catch(e){return "neutral"}
}

// ===== v3.3.0 沉浸阅读模式 =====
var _readerFontSize=16;
var _readerTheme=0;
function openReaderMode(){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    if(ms.length===0){showToast("暂无消息可阅读");return}
    var titleEl=$("readerTitle");
    if(titleEl)titleEl.textContent=curRole.emoji+" "+curRole.name;
    var content=$("readerContent");
    if(!content)return;
    var h="";
    for(var i=0;i<ms.length;i++){
      var m=ms[i];
      var speaker=m.r==="me"?"我":curRole.name;
      h+='<div class="reader-msg '+(m.r==="me"?"me":"ai")+'">';
      h+='<div class="rm-speaker">'+esc(speaker)+'</div>';
      h+='<div class="rm-text">'+esc(m.t)+'</div>';
      h+='</div>';
    }
    content.innerHTML=h;
    content.style.fontSize=_readerFontSize+"px";
    var ov=$("readerMode");
    if(ov)ov.className="reader-mode on";
  }catch(e){showErr("打开阅读模式失败:"+e.message)}
}
function closeReaderMode(){
  var ov=$("readerMode");
  if(ov)ov.className="reader-mode";
  if(window.speechSynthesis)window.speechSynthesis.cancel();
}
function readerFontAdjust(delta){
  _readerFontSize=Math.max(12,Math.min(28,_readerFontSize+delta));
  var content=$("readerContent");
  if(content)content.style.fontSize=_readerFontSize+"px";
  var valEl=$("readerFsVal");
  if(valEl)valEl.textContent=_readerFontSize+"px";
}
function readerToggleTheme(){
  _readerTheme=(_readerTheme+1)%3;
  var content=$("readerContent");
  if(!content)return;
  var themes=[
    {bg:"#060614",txt:"#e8e8f0"},
    {bg:"#1a1a2e",txt:"#e0d4ff"},
    {bg:"#f5f5dc",txt:"#333333"}
  ];
  var t=themes[_readerTheme];
  content.style.background=t.bg;
  content.style.color=t.txt;
  var msgs=content.querySelectorAll(".rm-text");
  for(var i=0;i<msgs.length;i++)msgs[i].style.color=t.txt;
}
function speakReaderMode(){
  try{
    if(!window.speechSynthesis)return;
    if(window.speechSynthesis.speaking){
      window.speechSynthesis.cancel();
      showToast("已停止朗读");
      return;
    }
    var ms=msgs[curRole.id]||[];
    var text="";
    for(var i=0;i<ms.length;i++){
      var speaker=ms[i].r==="me"?"我说：":curRole.name+"说：";
      text+=speaker+ms[i].t+". ";
    }
    var utter=new SpeechSynthesisUtterance(text.substring(0,3000));
    utter.lang="zh-CN";
    utter.rate=1.0;
    window.speechSynthesis.speak(utter);
    showToast("开始朗读");
  }catch(e){}
}
