var _replayState={playing:false,index:0,speed:1000,timer:null};
function openReplay(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(active.length<2){showToast("对话内容太少");return}
    var box=$("replayOverlay");
    if(!box)return;
    box.className="replay-overlay on";
    var title=$("replayTitle");
    if(title)title.textContent="对话回放 - "+curRole.name;
    _replayState.index=0;
    _replayState.playing=false;
    var stage=$("replayStage");
    if(stage)stage.innerHTML="";
    var fill=$("replayProgressFill");
    if(fill)fill.style.width="0%";
    var btn=$("replayPlayBtn");
    if(btn)btn.textContent="▶";
  }catch(e){showToast("打开回放失败: "+e.message)}
}
function closeReplay(){
  try{
    _replayState.playing=false;
    if(_replayState.timer){clearTimeout(_replayState.timer);_replayState.timer=null}
    var box=$("replayOverlay");
    if(box)box.className="replay-overlay";
  }catch(e){}
}
function toggleReplay(){
  try{
    _replayState.playing=!_replayState.playing;
    var btn=$("replayPlayBtn");
    if(btn)btn.textContent=_replayState.playing?"⏸":"▶";
    if(_replayState.playing){
      replayStep();
    }else{
      if(_replayState.timer){clearTimeout(_replayState.timer);_replayState.timer=null}
    }
  }catch(e){}
}
function setReplaySpeed(speed,el){
  _replayState.speed=speed;
  var btns=document.querySelectorAll(".replay-speed-btn");
  for(var i=0;i<btns.length;i++){btns[i].className="replay-speed-btn"}
  if(el)el.className="replay-speed-btn active";
}
function replayStep(){
  try{
    if(!_replayState.playing)return;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(_replayState.index>=active.length){
      _replayState.playing=false;
      var btn=$("replayPlayBtn");
      if(btn)btn.textContent="▶";
      showToast("回放结束");
      return;
    }
    var m=active[_replayState.index];
    var stage=$("replayStage");
    if(stage){
      var h='<div class="replay-msg '+(m.r==="me"?"me":"ai")+'">';
      h+='<div class="rm-sender">'+(m.r==="me"?"我":esc(curRole.name))+'</div>';
      h+='<div class="rm-bub">'+esc(m.t)+'</div>';
      h+='</div>';
      stage.insertAdjacentHTML("beforeend",h);
      stage.scrollTop=stage.scrollHeight;
    }
    _replayState.index++;
    var fill=$("replayProgressFill");
    if(fill)fill.style.width=Math.round((_replayState.index/active.length)*100)+"%";
    _replayState.timer=setTimeout(replayStep,_replayState.speed);
  }catch(e){}
}

