function openSchedulePanel(){
  try{
    var box=$("scheduleOverlay");
    if(!box)return;
    box.className="schedule-overlay on";
    renderScheduleList();
    var timeInput=$("scheduleTimeInput");
    if(timeInput)timeInput.value="";
    var delayInput=$("scheduleDelayInput");
    if(delayInput)delayInput.value="";
    var msgInput=$("scheduleMsgInput");
    if(msgInput){msgInput.value="";msgInput.focus()}
  }catch(e){}
}
function closeScheduleOverlay(e){
  if(e&&e.target&&e.target.id!=="scheduleOverlay")return;
  var box=$("scheduleOverlay");
  if(box)box.className="schedule-overlay";
}
function addScheduledMessage(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var timeInput=$("scheduleTimeInput");
    var delayInput=$("scheduleDelayInput");
    var msgInput=$("scheduleMsgInput");
    if(!msgInput||!msgInput.value.trim()){showToast("请输入消息内容");return}
    var sendAt=0;
    if(timeInput&&timeInput.value){
      var parts=timeInput.value.split(":");
      var d=new Date();
      d.setHours(parseInt(parts[0]),parseInt(parts[1]),0,0);
      if(d.getTime()<Date.now())d.setDate(d.getDate()+1);
      sendAt=d.getTime();
    }else if(delayInput&&delayInput.value){
      sendAt=Date.now()+parseInt(delayInput.value)*60000;
    }else{
      showToast("请设置发送时间或延迟");
      return;
    }
    var schedules=lsGet("scheduledMessages")||[];
    schedules.push({
      roleId:curRole.id,
      roleName:curRole.name,
      message:msgInput.value.trim(),
      sendAt:sendAt,
      sent:false
    });
    lsSet("scheduledMessages",schedules);
    msgInput.value="";
    if(timeInput)timeInput.value="";
    if(delayInput)delayInput.value="";
    renderScheduleList();
    showToast("定时消息已添加");
  }catch(e){showToast("添加失败: "+e.message)}
}
function deleteScheduledMessage(idx){
  try{
    var schedules=lsGet("scheduledMessages")||[];
    schedules.splice(idx,1);
    lsSet("scheduledMessages",schedules);
    renderScheduleList();
  }catch(e){}
}
function renderScheduleList(){
  try{
    var list=$("scheduleList");
    if(!list)return;
    var schedules=lsGet("scheduledMessages")||[];
    if(schedules.length===0){
      list.innerHTML="";
      return;
    }
    var h="";
    for(var i=0;i<schedules.length;i++){
      var s=schedules[i];
      var timeStr=new Date(s.sendAt).toLocaleString("zh-CN",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"});
      h+='<div class="schedule-list-item">';
      h+='<div class="sli-time">'+timeStr+'</div>';
      h+='<div class="sli-msg">'+esc(s.message.substring(0,30))+'</div>';
      if(s.sent){
        h+='<span style="font-size:11px;color:#5cfca8">✓已发送</span>';
      }else{
        h+='<span class="sli-del" onclick="deleteScheduledMessage('+i+')">✕</span>';
      }
      h+='</div>';
    }
    list.innerHTML=h;
  }catch(e){}
}
function checkScheduledMessages(){
  try{
    var schedules=lsGet("scheduledMessages")||[];
    var changed=false;
    for(var i=0;i<schedules.length;i++){
      if(!schedules[i].sent&&schedules[i].sendAt<=Date.now()){
        // 发送消息
        var roleId=schedules[i].roleId;
        if(!msgs[roleId])msgs[roleId]=[];
        msgs[roleId].push({r:"me",t:schedules[i].message,ooc:isOOCMessage(schedules[i].message),ts:Date.now()});
        lsSet("msgs",msgs);
        schedules[i].sent=true;
        changed=true;
        // 如果当前正在该角色对话中，刷新
        if(curRole&&curRole.id===roleId){
          renderChat();
          genReply(isOOCMessage(schedules[i].message));
        }
        showToast("定时消息已发送给"+schedules[i].roleName);
      }
    }
    if(changed)lsSet("scheduledMessages",schedules);
  }catch(e){}
}

