// ===== v3.4.0 消息特效 =====
function triggerMessageEffect(text){
  try{
    var effects={
      "爱":["❤️","💕","💖","💗","💝"],
      "开心":["😄","🎉","✨","🌟","💫"],
      "生气":["💢","🔥","⚡","😡","💥"],
      "哭":["😢","💧","😭","💦","💔"],
      "惊喜":["😮","✨","🎉","🎊","🌟"],
      "晚安":["🌙","⭐","💤","😴","✨"],
      "早安":["☀️","🌞","⭐","✨","🌈"]
    };
    var keywords={
      "爱":["爱","喜欢","心动","heart"],
      "开心":["开心","高兴","哈哈","快乐","笑"],
      "生气":["生气","怒","可恶","混蛋","气死"],
      "哭":["哭","难过","伤心","呜呜","sad"],
      "惊喜":["哇","天啊","真的吗","不敢相信"],
      "晚安":["晚安","睡了","睡觉","good night"],
      "早安":["早安","早上好","起床","good morning"]
    };
    var lowerText=String(text||"").toLowerCase();
    for(var effect in keywords){
      var kws=keywords[effect];
      for(var k=0;k<kws.length;k++){
        if(lowerText.indexOf(kws[k])>=0){
          createParticles(effects[effect]);
          return;
        }
      }
    }
  }catch(e){}
}
function createParticles(emojis){
  try{
    for(var i=0;i<8;i++){
      setTimeout(function(){
        var p=document.createElement("div");
        p.className="fx-particle";
        p.textContent=emojis[Math.floor(Math.random()*emojis.length)];
        p.style.left=Math.random()*window.innerWidth+"px";
        p.style.top=(window.innerHeight-100)+"px";
        p.style.animationDelay=Math.random()*0.3+"s";
        document.body.appendChild(p);
        setTimeout(function(){if(p.parentNode)p.parentNode.removeChild(p)},1800);
      },i*80);
    }
  }catch(e){}
}
function triggerShake(el){
  try{
    if(!el)return;
    el.className+=" fx-shake";
    setTimeout(function(){el.className=el.className.replace(" fx-shake","")},400);
  }catch(e){}
}
function triggerBurst(x,y,color){
  try{
    var b=document.createElement("div");
    b.className="fx-burst";
    b.style.left=(x-50)+"px";
    b.style.top=(y-50)+"px";
    b.style.background="radial-gradient(circle,"+color+",transparent)";
    document.body.appendChild(b);
    setTimeout(function(){if(b.parentNode)b.parentNode.removeChild(b)},700);
  }catch(e){}
}

// ===== v3.4.0 初始化 =====
function initV34Features(){
  try{
    // 初始化知识库
    if(!lsGet("aiKnowledgeBase"))lsSet("aiKnowledgeBase",[]);
    // 初始化定时消息列表
    if(!lsGet("scheduledMessages"))lsSet("scheduledMessages",[]);
    // 启动定时消息检查
    setInterval(checkScheduledMessages,10000);
    // 启动AI主动消息检查（每5分钟检查一次）
    setInterval(checkProactiveMessage,300000);
    // 绑定知识库分类选择
    var catOpts=document.querySelectorAll("#kbCatSelect .kb-cat-option");
    for(var i=0;i<catOpts.length;i++){
      catOpts[i].onclick=function(){
        var opts=document.querySelectorAll("#kbCatSelect .kb-cat-option");
        for(var j=0;j<opts.length;j++){opts[j].className="kb-cat-option"}
        this.className="kb-cat-option active";
        _kbCat=this.getAttribute("data-cat");
      };
    }
  }catch(e){}
}

// 延迟初始化v3.4功能
setTimeout(function(){try{initV34Features()}catch(e){}},1500);

