function exportAsJSON(){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    var data={
      app:"幻语AI",
      version:"3.8.0",
      role:curRole,
      messages:ms,
      exportTime:new Date().toISOString()
    };
    saveExportFile(JSON.stringify(data,null,2),"json");
  }catch(e){showToast("导出失败")}
}
function exportAsMarkdown(){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    var md="# 与"+curRole.name+"的对话\n\n";
    md+="> 导出于 "+new Date().toLocaleString()+" · 共"+active.length+"条消息\n\n";
    md+="---\n\n";
    for(var i=0;i<active.length;i++){
      var m=active[i];
      var sender=m.r==="me"?"**我**":"**"+curRole.name+"**";
      md+="### "+sender+"\n\n"+(m.t||"")+"\n\n---\n\n";
    }
    saveExportFile(md,"md");
  }catch(e){showToast("导出失败")}
}
function exportAsScript(){
  try{
    if(!curRole)return;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    var script="================================\n";
    script+="  幻语AI 剧本导出\n";
    script+="  角色: "+curRole.name+"\n";
    script+="  日期: "+new Date().toLocaleString()+"\n";
    script+="================================\n\n";
    var scene=1;
    for(var i=0;i<active.length;i++){
      var m=active[i];
      var sender=m.r==="me"?"用户":curRole.name;
      var text=(m.t||"").replace(/\(.*?\)/g,"").replace(/（.*?）/g,"").trim();
      if(text.length===0)text=m.t||"";
      if(i%6===0){
        script+="\n--- 场景"+scene+" ---\n\n";
        scene++;
      }
      script+=sender+": \""+text+"\"\n\n";
    }
    script+="\n================================\n  剧终\n================================\n";
    saveExportFile(script,"txt");
  }catch(e){showToast("导出失败")}
}
function saveExportFile(content,ext){
  try{
    var filename=getExportFilename(ext);
    if(typeof App!=="undefined"&&App.saveFile){
      var path=App.saveFile(filename,content);
      if(path){
        showToast("已导出: "+filename);
        closeExportPanel();
        return;
      }
    }
    // Web下载fallback
    var blob=new Blob([content],{type:"text/plain;charset=utf-8"});
    var url=URL.createObjectURL(blob);
    var a=document.createElement("a");
    a.href=url;a.download=filename;
    document.body.appendChild(a);a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast("已导出: "+filename);
    closeExportPanel();
  }catch(e){showToast("保存失败")}
}

