// ===== v3.9.0 AI情感分析仪表盘 =====
// ==========================================================================
var EMOTION_TYPES=[
  {id:"happy",icon:"😊",name:"开心",color:"#5cfca8",keywords:["开心","快乐","高兴","哈哈","嘻嘻","笑","愉快","棒","好棒","太好了","开心死了","超开心"]},
  {id:"sad",icon:"😢",name:"悲伤",color:"#6b8ccc",keywords:["难过","伤心","悲伤","哭","心痛","委屈","失落","孤独","寂寞","想哭","心疼","不好受"]},
  {id:"angry",icon:"😡",name:"愤怒",color:"#fc6b6b",keywords:["生气","愤怒","讨厌","烦","烦死","气死","可恶","混蛋","烦人","受不了","气死了","讨厌死了"]},
  {id:"love",icon:"❤️",name:"喜爱",color:"#fc5c8a",keywords:["喜欢","爱","想你","想你啦","爱你","心动","甜蜜","温暖","抱抱","亲亲","离不开","放不下"]},
  {id:"anxious",icon:"😰",name:"焦虑",color:"#fcb85c",keywords:["担心","害怕","紧张","不安","焦虑","恐惧","怕","害怕","犹豫","纠结","忐忑","慌"]},
  {id:"calm",icon:"😌",name:"平静",color:"#a78bfa",keywords:["嗯","好的","好吧","知道了","没事","算了","行","可以","好的吧","也是","确实","嗯嗯"]},
  {id:"surprise",icon:"😮",name:"惊讶",color:"#fcd75c",keywords:["什么","真的吗","不会吧","天哪","哇","啊","吃惊","震惊","没想到","竟然","居然","不可思议"]},
  {id:"shy",icon:"😳",name:"害羞",color:"#fc8ad4",keywords:["脸红","不好意思","害羞","羞","丢人","尴尬","别说了","不要","讨厌啦","哼","才不是","没有啦"]}
];
function analyzeEmotion(text){
  try{
    if(!text||text.length===0)return {dominant:"calm",scores:{}};
    var scores={};
    for(var i=0;i<EMOTION_TYPES.length;i++){
      scores[EMOTION_TYPES[i].id]=0;
      var kws=EMOTION_TYPES[i].keywords;
      for(var j=0;j<kws.length;j++){
        var idx=text.indexOf(kws[j]);
        while(idx>=0){
          scores[EMOTION_TYPES[i].id]++;
          idx=text.indexOf(kws[j],idx+kws[j].length);
        }
      }
    }
    var dominant="calm";
    var maxScore=0;
    for(var key in scores){
      if(scores[key]>maxScore){
        maxScore=scores[key];
        dominant=key;
      }
    }
    if(maxScore===0)dominant="calm";
    return {dominant:dominant,scores:scores};
  }catch(e){return {dominant:"calm",scores:{}}}
}
function getConversationEmotionStats(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    var totals={};
    for(var i=0;i<EMOTION_TYPES.length;i++)totals[EMOTION_TYPES[i].id]=0;
    var aiMsgs=active.filter(function(m){return m.r!=="me"});
    for(var i=0;i<aiMsgs.length;i++){
      var result=analyzeEmotion(aiMsgs[i].t||"");
      for(var key in result.scores)totals[key]=(totals[key]||0)+result.scores[key];
    }
    var total=0;
    for(var key in totals)total+=totals[key];
    if(total===0)totals.calm=1,total=1;
    var dominant="calm";
    var maxVal=0;
    for(var key in totals){
      if(totals[key]>maxVal){maxVal=totals[key];dominant=key}
    }
    return {totals:totals,total:total,dominant:dominant,msgCount:aiMsgs.length};
  }catch(e){return null}
}
function openEmotionDashboard(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var box=$("emotionDashboard");
    if(!box)return;
    box.className="emotion-dashboard show";
    var body=$("emotionDashBody");
    if(!body)return;
    var stats=getConversationEmotionStats();
    if(!stats){body.innerHTML="<div style='text-align:center;color:#666;padding:40px'>暂无数据</div>";return}
    var h="";
    // 主情感环
    var domEmo=EMOTION_TYPES.find(function(e){return e.id===stats.dominant})||EMOTION_TYPES[5];
    var domPercent=Math.round((stats.totals[stats.dominant]/stats.total)*100);
    h+='<div class="emotion-ring-container">';
    h+='<div class="emotion-ring">';
    var circumference=2*Math.PI*65;
    var offset=circumference*(1-domPercent/100);
    h+='<svg width="160" height="160">';
    h+='<circle class="emotion-ring-track" cx="80" cy="80" r="65"></circle>';
    h+='<circle class="emotion-ring-fill" cx="80" cy="80" r="65" stroke="'+domEmo.color+'" stroke-dasharray="'+circumference+'" stroke-dashoffset="'+offset+'"></circle>';
    h+='</svg>';
    h+='<div class="emotion-ring-center">';
    h+='<div class="emotion-ring-emoji">'+domEmo.icon+'</div>';
    h+='<div class="emotion-ring-label">'+domEmo.name+' '+domPercent+'%</div>';
    h+='</div></div></div>';
    // 情感分布条
    h+='<div class="emotion-bars">';
    for(var i=0;i<EMOTION_TYPES.length;i++){
      var emo=EMOTION_TYPES[i];
      var val=stats.totals[emo.id]||0;
      var pct=stats.total>0?Math.round((val/stats.total)*100):0;
      h+='<div class="emotion-bar-item">';
      h+='<div class="emotion-bar-header">';
      h+='<span class="emotion-bar-icon">'+emo.icon+'</span>';
      h+='<span class="emotion-bar-name">'+emo.name+'</span>';
      h+='<span class="emotion-bar-value">'+pct+'%</span>';
      h+='</div>';
      h+='<div class="emotion-bar-track">';
      h+='<div class="emotion-bar-fill" style="width:'+pct+'%;background:'+emo.color+'"></div>';
      h+='</div></div>';
    }
    h+='</div>';
    // 趋势图（最近20条AI消息）
    h+='<div class="emotion-trend-chart">';
    h+='<div class="emotion-trend-title">📈 情感趋势（最近20条）</div>';
    var ms=msgs[curRole.id]||[];
    var aiMsgs=ms.filter(function(m){return !m.rolled&&m.r!=="me"});
    var recent=aiMsgs.slice(-20);
    h+='<svg class="emotion-trend-svg" viewBox="0 0 300 120" preserveAspectRatio="none">';
    // 绘制折线
    var points=[];
    for(var i=0;i<recent.length;i++){
      var r=analyzeEmotion(recent[i].t||"");
      var emoIdx=0;
      for(var j=0;j<EMOTION_TYPES.length;j++){
        if(EMOTION_TYPES[j].id===r.dominant){emoIdx=j;break}
      }
      var x=(recent.length>1)?(i/(recent.length-1))*280+10:150;
      var y=110-(emoIdx/(EMOTION_TYPES.length-1))*100;
      points.push(x+","+y);
    }
    if(points.length>1){
      h+='<polyline points="'+points.join(" ")+'" fill="none" stroke="#a78bfa" stroke-width="2" stroke-linejoin="round"/>';
    }
    for(var i=0;i<points.length;i++){
      var p=points[i].split(",");
      h+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3" fill="#5cfca8"/>';
    }
    h+='</svg></div>';
    // 统计卡片
    h+='<div class="emotion-stat-grid">';
    h+='<div class="emotion-stat-card"><div class="emotion-stat-num">'+stats.msgCount+'</div><div class="emotion-stat-label">AI消息总数</div></div>';
    h+='<div class="emotion-stat-card"><div class="emotion-stat-num">'+EMOTION_TYPES.length+'</div><div class="emotion-stat-label">情感维度</div></div>';
    h+='</div>';
    // 关键词云
    h+='<div class="emotion-trend-chart" style="margin-top:16px">';
    h+='<div class="emotion-trend-title">☁️ 高频情感关键词</div>';
    h+='<div class="emotion-keyword-cloud" id="emoKeywordCloud"></div>';
    h+='</div>';
    body.innerHTML=h;
    // 填充关键词云
    var kwCloud=$("emoKeywordCloud");
    if(kwCloud){
      var kwMap={};
      for(var i=0;i<aiMsgs.length;i++){
        var txt=aiMsgs[i].t||"";
        for(var j=0;j<EMOTION_TYPES.length;j++){
          var kws=EMOTION_TYPES[j].keywords;
          for(var k=0;k<kws.length;k++){
            if(txt.indexOf(kws[k])>=0){
              kwMap[kws[k]]=(kwMap[kws[k]]||0)+1;
            }
          }
        }
      }
      var sorted=Object.keys(kwMap).sort(function(a,b){return kwMap[b]-kwMap[a]}).slice(0,15);
      var kwh="";
      for(var i=0;i<sorted.length;i++){
        var size=12+Math.min(kwMap[sorted[i]]*2,10);
        var opacity=0.5+Math.min(kwMap[sorted[i]]*0.1,0.5);
        kwh+='<span class="emotion-keyword" style="font-size:'+size+'px;color:rgba(167,139,250,'+opacity+');background:rgba(124,92,252,0.06)">'+sorted[i]+'</span>';
      }
      kwCloud.innerHTML=kwh||"<span style='color:#666;font-size:12px'>暂无关键词</span>";
    }
  }catch(e){showToast("打开仪表盘失败")}
}
