var ACHIEVEMENTS=[
  {id:"first_chat",icon:"💬",name:"初次对话",desc:"第一次与AI角色聊天",check:function(s){return s.totalMsgs>=1}},
  {id:"msg_50",icon:"📜",name:"话唠初成",desc:"累计发送50条消息",check:function(s){return s.totalMsgs>=50}},
  {id:"msg_100",icon:"🗣️",name:"百条达人",desc:"累计发送100条消息",check:function(s){return s.totalMsgs>=100}},
  {id:"msg_500",icon:"🏆",name:"千言万语",desc:"累计发送500条消息",check:function(s){return s.totalMsgs>=500}},
  {id:"msg_1000",icon:"💎",name:"对话大师",desc:"累计发送1000条消息",check:function(s){return s.totalMsgs>=1000}},
  {id:"streak_3",icon:"🔥",name:"三日打卡",desc:"连续3天与AI对话",check:function(s){return s.maxStreak>=3}},
  {id:"streak_7",icon:"⚡",name:"一周坚持",desc:"连续7天与AI对话",check:function(s){return s.maxStreak>=7}},
  {id:"streak_30",icon:"🌟",name:"月度坚守",desc:"连续30天与AI对话",check:function(s){return s.maxStreak>=30}},
  {id:"roles_3",icon:"🎭",name:"多面手",desc:"与3个不同角色对话",check:function(s){return s.roleCount>=3}},
  {id:"roles_5",icon:"🎪",name:"角色收集者",desc:"与5个不同角色对话",check:function(s){return s.roleCount>=5}},
  {id:"night_owl",icon:"🦉",name:"夜猫子",desc:"在凌晨0-3点聊天",check:function(s){return s.nightChats>0}},
  {id:"early_bird",icon:"🐦",name:"早起鸟",desc:"在早上5-7点聊天",check:function(s){return s.earlyChats>0}},
  {id:"long_msg",icon:"✍️",name:"长篇大论",desc:"发送超过200字的消息",check:function(s){return s.longMsgs>0}},
  {id:"emoji_lover",icon:"😍",name:"表情达人",desc:"使用20个以上表情",check:function(s){return s.emojiCount>=20}},
  {id:"export_data",icon:"📤",name:"数据管家",desc:"导出对话记录",check:function(s){return s.exported}},
  {id:"emotion_master",icon:"🧠",name:"情感大师",desc:"查看情感分析仪表盘",check:function(s){return s.viewedEmotion}},
  {id:"mask_switcher",icon:"🎭",name:"面具切换",desc:"使用角色面具系统",check:function(s){return s.usedMask}},
  {id:"voice_listener",icon:"🔊",name:"聆听者",desc:"使用语音朗读功能",check:function(s){return s.usedTTS}},
  {id:"topic_explorer",icon:"🔍",name:"话题探索",desc:"使用对话主题推荐",check:function(s){return s.usedTopic}},
  {id:"daily_7",icon:"📅",name:"一周打卡",desc:"使用7天以上",check:function(s){return s.activeDays>=7}}
];
function getAchvStats(){
  try{
    var stats={totalMsgs:0,roleCount:0,maxStreak:0,nightChats:0,earlyChats:0,longMsgs:0,emojiCount:0,exported:false,viewedEmotion:false,usedMask:false,usedTTS:false,usedTopic:false,activeDays:0};
    var roleIds=Object.keys(msgs);
    stats.roleCount=roleIds.length;
    var allDates={};
    for(var ri=0;ri<roleIds.length;ri++){
      var ms=msgs[roleIds[ri]]||[];
      var active=ms.filter(function(m){return !m.rolled});
      stats.totalMsgs+=active.length;
      for(var i=0;i<active.length;i++){
        var m=active[i];
        if(m.time){
          var d=new Date(m.time);
          var hour=d.getHours();
          if(hour>=0&&hour<3)stats.nightChats++;
          if(hour>=5&&hour<7)stats.earlyChats++;
          var dateKey=d.getFullYear()+"-"+(d.getMonth()+1)+"-"+d.getDate();
          allDates[dateKey]=true;
        }
        if(m.r==="me"&&m.t&&m.t.length>200)stats.longMsgs++;
        if(m.t){
          var emojis=m.t.match(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F700}-\u{1F77F}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu);
          if(emojis)stats.emojiCount+=emojis.length;
        }
      }
    }
    var dateList=Object.keys(allDates).sort();
    stats.activeDays=dateList.length;
    // 计算最大连续天数
    var maxStreak=0,curStreak=0,prevDate=null;
    for(var i=0;i<dateList.length;i++){
      var parts=dateList[i].split("-");
      var d=new Date(parseInt(parts[0]),parseInt(parts[1])-1,parseInt(parts[2]));
      if(prevDate){
        var diff=(d-prevDate)/(86400000);
        if(diff===1){curStreak++;if(curStreak>maxStreak)maxStreak=curStreak}
        else{curStreak=1}
      }else{curStreak=1;if(curStreak>maxStreak)maxStreak=curStreak}
      prevDate=d;
    }
    stats.maxStreak=maxStreak;
    // 从localStorage读取标志
    try{stats.exported=lsGet("achv_exported")||false}catch(e){}
    try{stats.viewedEmotion=lsGet("achv_viewedEmotion")||false}catch(e){}
    try{stats.usedMask=lsGet("achv_usedMask")||false}catch(e){}
    try{stats.usedTTS=lsGet("achv_usedTTS")||false}catch(e){}
    try{stats.usedTopic=lsGet("achv_usedTopic")||false}catch(e){}
    return stats;
  }catch(e){return {totalMsgs:0,roleCount:0,maxStreak:0,nightChats:0,earlyChats:0,longMsgs:0,emojiCount:0,activeDays:0}}
}
function getUnlockedAchievements(){
  try{
    var unlocked=lsGet("achv_unlocked")||{};
    var stats=getAchvStats();
    var newlyUnlocked=[];
    for(var i=0;i<ACHIEVEMENTS.length;i++){
      var achv=ACHIEVEMENTS[i];
      var isUnlocked=unlocked[achv.id]||false;
      if(!isUnlocked&&achv.check(stats)){
        unlocked[achv.id]=true;
        newlyUnlocked.push(achv);
      }
    }
    if(newlyUnlocked.length>0){
      lsSet("achv_unlocked",unlocked);
      for(var i=0;i<newlyUnlocked.length;i++){
        showAchvToast(newlyUnlocked[i]);
      }
    }
    return unlocked;
  }catch(e){return {}}
}
function showAchvToast(achv){
  try{
    var toast=$("achvToast");
    if(!toast)return;
    $("achvToastIcon").textContent=achv.icon;
    $("achvToastTitle").textContent="成就解锁: "+achv.name;
    $("achvToastDesc").textContent=achv.desc;
    toast.className="achv-toast show";
    setTimeout(function(){toast.className="achv-toast"},3500);
  }catch(e){}
}
function openAchievementPanel(){
  try{
    var unlocked=getUnlockedAchievements();
    var box=$("achievementOverlay");
    if(!box)return;
    box.className="achievement-overlay show";
    var body=$("achvBody");
    if(!body)return;
    var unlockedCount=0;
    for(var key in unlocked)if(unlocked[key])unlockedCount++;
    var total=ACHIEVEMENTS.length;
    var pct=Math.round((unlockedCount/total)*100);
    var h="";
    h+='<div class="achv-progress-summary">';
    h+='<div class="achv-progress-ring">';
    var circumference=2*Math.PI*50;
    var offset=circumference*(1-pct/100);
    h+='<svg width="120" height="120">';
    h+='<circle fill="none" stroke="rgba(124,92,252,.08)" stroke-width="10" cx="60" cy="60" r="50"></circle>';
    h+='<circle fill="none" stroke="#5cfca8" stroke-width="10" stroke-linecap="round" cx="60" cy="60" r="50" stroke-dasharray="'+circumference+'" stroke-dashoffset="'+offset+'" transform="rotate(-90 60 60)"></circle>';
    h+='</svg>';
    h+='<div class="achv-progress-text">';
    h+='<div class="achv-progress-num">'+unlockedCount+'/'+total+'</div>';
    h+='<div class="achv-progress-label">已解锁 '+pct+'%</div>';
    h+='</div></div></div>';
    h+='<div class="achv-grid">';
    for(var i=0;i<ACHIEVEMENTS.length;i++){
      var achv=ACHIEVEMENTS[i];
      var isUnlocked=unlocked[achv.id]||false;
      h+='<div class="achv-card '+(isUnlocked?"unlocked":"locked")+'">';
      h+='<span class="achv-card-badge '+(isUnlocked?"done":"todo")+'">'+(isUnlocked?"已解锁":"未解锁")+'</span>';
      h+='<div class="achv-card-icon">'+(isUnlocked?achv.icon:"🔒")+'</div>';
      h+='<div class="achv-card-name">'+achv.name+'</div>';
      h+='<div class="achv-card-desc">'+achv.desc+'</div>';
      h+='</div>';
    }
    h+='</div>';
    body.innerHTML=h;
  }catch(e){showToast("打开成就面板失败")}
}
function closeAchievementPanel(){
  try{var box=$("achievementOverlay");if(box)box.className="achievement-overlay"}catch(e){}
}

