// ===== v3.9.0 AI自画像生成系统 =====
// ==========================================================================
var PORTRAIT_TRAITS=[
  {id:"warmth",icon:"🔥",name:"热情度",color:"#fc6b6b",desc:"表达温暖和热情的倾向"},
  {id:"intellect",icon:"🧠",name:"智慧度",color:"#a78bfa",desc:"逻辑思考和知识深度"},
  {id:"humor",icon:"😄",name:"幽默度",color:"#fcd75c",desc:"搞笑和调侃的能力"},
  {id:"empathy",icon:"💝",name:"共情度",color:"#fc5c8a",desc:"理解和感受他人情感"},
  {id:"creativity",icon:"🎨",name:"创造力",color:"#5cfca8",desc:"想象力和创新表达"},
  {id:"courage",icon:"⚔️",name:"勇气值",color:"#fcb85c",desc:"坦诚和直率的程度"},
  {id:"gentleness",icon:"🌸",name:"温柔度",color:"#fc8ad4",desc:"柔和细腻的表达方式"},
  {id:"mystery",icon:"🌙",name:"神秘感",color:"#6b8ccc",desc:"保持神秘和留白的能力"}
];
function generatePortrait(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var aiMsgs=ms.filter(function(m){return !m.rolled&&m.r!=="me"});
    if(aiMsgs.length===0)return null;
    var traits={};
    for(var i=0;i<PORTRAIT_TRAITS.length;i++)traits[PORTRAIT_TRAITS[i].id]=0;
    // 基于消息内容分析特质
    for(var i=0;i<aiMsgs.length;i++){
      var txt=(aiMsgs[i].t||"").toLowerCase();
      // 热情度
      if(/哈哈|嘻嘻|太好了|好棒|开心|快乐|热情/.test(txt))traits.warmth+=2;
      if(/！|!/.test(txt))traits.warmth+=1;
      // 智慧度
      if(/因为|所以|其实|事实上|理论上|逻辑/.test(txt))traits.intellect+=2;
      if(txt.length>100)traits.intellect+=1;
      // 幽默度
      if(/哈哈|搞笑|有趣|开玩笑|逗|皮|梗/.test(txt))traits.humor+=2;
      // 共情度
      if(/理解|感受|心疼|抱抱|没关系|我懂|我知道你的感受/.test(txt))traits.empathy+=2;
      // 创造力
      if(/想象|如果|假如|或许|可能|梦幻|奇妙/.test(txt))traits.creativity+=2;
      // 勇气值
      if(/直接|坦白|说实话|告诉你|其实我|不想骗你/.test(txt))traits.courage+=2;
      // 温柔度
      if(/轻轻|慢慢|温柔|小心|柔软|温暖/.test(txt))traits.gentleness+=2;
      // 神秘感
      if(/秘密|不能说|你猜|也许|谁知道|未来会/.test(txt))traits.mystery+=2;
    }
    // 归一化到0-100
    var maxVal=0;
    for(var key in traits)if(traits[key]>maxVal)maxVal=traits[key];
    if(maxVal===0)maxVal=1;
    for(var key in traits){
      traits[key]=Math.round((traits[key]/(maxVal*1.5))*100);
      if(traits[key]>100)traits[key]=100;
      if(traits[key]<5)traits[key]=5+Math.floor(Math.random()*10);
    }
    // 生成描述
    var topTraits=Object.keys(traits).sort(function(a,b){return traits[b]-traits[a]}).slice(0,3);
    var desc="这是"+curRole.name+"的自画像。\n\n";
    for(var i=0;i<topTraits.length;i++){
      var trait=PORTRAIT_TRAITS.find(function(t){return t.id===topTraits[i]});
      if(trait){
        desc+=trait.icon+" "+trait.name+": "+traits[topTraits[i]]+"分\n";
        if(traits[topTraits[i]]>=70)desc+="  "+trait.desc+"，在对话中表现突出。\n";
        else desc+="  "+trait.desc+"，表现中等。\n";
      }
    }
    desc+="\n基于"+aiMsgs.length+"条AI消息分析生成。";
    // 选择代表emoji
    var emojiMap={"warmth":"🔥","intellect":"🧠","humor":"😄","empathy":"💝","creativity":"🎨","courage":"⚔️","gentleness":"🌸","mystery":"🌙"};
    var avatar=emojiMap[topTraits[0]]||"✨";
    return {traits:traits,desc:desc,avatar:avatar,topTraits:topTraits};
  }catch(e){return null}
}
function openPortraitPanel(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var box=$("portraitOverlay");
    if(!box)return;
    box.className="portrait-overlay show";
    var body=$("portraitBody");
    if(!body)return;
    var portrait=generatePortrait();
    if(!portrait){body.innerHTML="<div style='text-align:center;color:#666;padding:40px'>暂无足够对话数据<br>请先与角色聊几句话</div>";return}
    var h="";
    h+='<div class="portrait-canvas">';
    h+='<div class="portrait-avatar">'+portrait.avatar+'</div>';
    h+='</div>';
    h+='<div style="text-align:center;font-size:16px;color:#e0d4ff;font-weight:700;margin-bottom:6px">'+esc(curRole.name)+'</div>';
    h+='<div style="text-align:center;font-size:12px;color:#666;margin-bottom:20px">基于对话分析的AI人格画像</div>';
    h+='<div class="portrait-traits">';
    for(var i=0;i<PORTRAIT_TRAITS.length;i++){
      var trait=PORTRAIT_TRAITS[i];
      var val=portrait.traits[trait.id]||0;
      h+='<div class="portrait-trait-row">';
      h+='<span class="portrait-trait-icon">'+trait.icon+'</span>';
      h+='<div class="portrait-trait-info">';
      h+='<div class="portrait-trait-name">'+trait.name+' <span class="portrait-trait-val">'+val+'</span></div>';
      h+='<div class="portrait-trait-bar"><div class="portrait-trait-fill" style="width:'+val+'%;background:'+trait.color+'"></div></div>';
      h+='</div></div>';
    }
    h+='</div>';
    h+='<div class="portrait-desc">'+esc(portrait.desc)+'</div>';
    h+='<button class="portrait-regen-btn" onclick="openPortraitPanel()">🔄 重新分析</button>';
    body.innerHTML=h;
  }catch(e){showToast("打开自画像失败")}
}
function closePortraitPanel(){
  try{var box=$("portraitOverlay");if(box)box.className="portrait-overlay"}catch(e){}
}

