var BUBBLE_FX_LIST=[
  {id:"hearts",icon:"❤️",name:"爱心",particles:["❤️","💕","💖","💗","💓"]},
  {id:"stars",icon:"⭐",name:"星光",particles:["⭐","✨","🌟","💫","✦"]},
  {id:"flowers",icon:"🌸",name:"花瓣",particles:["🌸","🌺","🌻","🌷","🌹"]},
  {id:"confetti",icon:"🎉",name:"彩纸",particles:["🎉","🎊","🎈","🎆","🎇"]},
  {id:"bubbles",icon:"🫧",name:"泡泡",particles:["🫧","💧","💦","🌊","☁️"]},
  {id:"fire",icon:"🔥",name:"火焰",particles:["🔥","💥","⚡","☄️","✨"]},
  {id:"snow",icon:"❄️",name:"雪花",particles:["❄️","⛄","🌨️","✦","❅"]},
  {id:"music",icon:"🎵",name:"音符",particles:["🎵","🎶","🎸","🥁","🎤"]},
  {id:"shock",icon:"⚡",name:"震动",particles:["⚡","💥","💢","🔥","✨"]},
  {id:"rainbow",icon:"🌈",name:"彩虹",particles:["🌈","🦄","✨","💫","🌟"]},
  {id:"crown",icon:"👑",name:"皇冠",particles:["👑","💎","💍","🏆","✨"]},
  {id:"love_letter",icon:"💌",name:"情书",particles:["💌","💌","💌","💕","❤️"]}
];
function triggerBubbleFx(fxId){
  try{
    var fx=BUBBLE_FX_LIST.find(function(f){return f.id===fxId});
    if(!fx)return;
    var layer=$("bubbleFxLayer");
    if(!layer)return;
    var chatList=$("chatList");
    var rect=chatList?chatList.getBoundingClientRect():{left:0,top:0,width:window.innerWidth,height:window.innerHeight};
    var centerX=rect.left+rect.width/2;
    var centerY=rect.top+rect.height*0.7;
    var count=15+Math.floor(Math.random()*10);
    for(var i=0;i<count;i++){
      var p=document.createElement("div");
      p.className="bubble-fx-particle";
      p.textContent=fx.particles[Math.floor(Math.random()*fx.particles.length)];
      var startX=centerX+(Math.random()-0.5)*200;
      var startY=centerY+(Math.random()-0.5)*100;
      p.style.left=startX+"px";
      p.style.top=startY+"px";
      var dx=(Math.random()-0.5)*300;
      var dy=-100-Math.random()*200;
      p.style.setProperty("--dx",dx+"px");
      p.style.setProperty("--dy",dy+"px");
      p.style.animation="fxBurst "+(1.5+Math.random())+"s ease-out forwards";
      p.style.animationDelay=(Math.random()*0.3)+"s";
      layer.appendChild(p);
      (function(el){setTimeout(function(){if(el.parentNode)el.parentNode.removeChild(el)},3000)})(p);
    }
  }catch(e){}
}
function openFxMenu(){
  try{
    var menu=$("fxMenu");
    if(!menu)return;
    var grid=$("fxGrid");
    if(!grid)return;
    var h="";
    for(var i=0;i<BUBBLE_FX_LIST.length;i++){
      var fx=BUBBLE_FX_LIST[i];
      h+='<div class="fx-item" onclick="triggerBubbleFx(\''+fx.id+'\');closeFxMenu()">';
      h+='<div class="fx-item-icon">'+fx.icon+'</div>';
      h+='<div class="fx-item-name">'+fx.name+'</div>';
      h+='</div>';
    }
    grid.innerHTML=h;
    menu.className="fx-menu show";
  }catch(e){}
}
function closeFxMenu(){
  try{var menu=$("fxMenu");if(menu)menu.className="fx-menu"}catch(e){}
}

// ==========================================================================
// ===== v3.9.0 深夜模式自动切换 =====
// ==========================================================================
function checkDeepNightMode(){
  try{
    var hour=new Date().getHours();
    var settings=lsGet("nightModeSettings")||{auto:true,startHour:22,endHour:6};
    if(!settings.auto)return;
    var inNight=false;
    if(settings.startHour>settings.endHour){
      inNight=(hour>=settings.startHour||hour<settings.endHour);
    }else{
      inNight=(hour>=settings.startHour&&hour<settings.endHour);
    }
    var body=document.body;
    var indicator=$("deepNightIndicator");
    if(inNight){
      body.classList.add("deep-night-mode");
      if(indicator)indicator.className="deep-night-indicator show";
    }else{
      body.classList.remove("deep-night-mode");
      if(indicator)indicator.className="deep-night-indicator";
    }
  }catch(e){}
}
function toggleDeepNightMode(){
  try{
    var body=document.body;
    if(body.classList.contains("deep-night-mode")){
      body.classList.remove("deep-night-mode");
      var indicator=$("deepNightIndicator");
      if(indicator)indicator.className="deep-night-indicator";
    }else{
      body.classList.add("deep-night-mode");
      var indicator=$("deepNightIndicator");
      if(indicator)indicator.className="deep-night-indicator show";
    }
  }catch(e){}
}

// ==========================================================================
// ===== v3.9.0 对话热力图 =====
// ==========================================================================
function getHeatmapData(){
  try{
    var data={};
    var roleIds=Object.keys(msgs);
    for(var ri=0;ri<roleIds.length;ri++){
      var ms=msgs[roleIds[ri]]||[];
      var active=ms.filter(function(m){return !m.rolled});
      for(var i=0;i<active.length;i++){
        if(active[i].time){
          var d=new Date(active[i].time);
          var dateKey=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
          data[dateKey]=(data[dateKey]||0)+1;
        }
      }
    }
    return data;
  }catch(e){return {}}
}
function openHeatmapPanel(){
  try{
    var box=$("heatmapOverlay");
    if(!box)return;
    box.className="heatmap-overlay show";
    var body=$("heatmapBody");
    if(!body)return;
    var data=getHeatmapData();
    var now=new Date();
    var days=[];
    var maxCount=0;
    for(var i=83;i>=0;i--){
      var d=new Date(now.getTime()-i*86400000);
      var dateKey=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
      var count=data[dateKey]||0;
      if(count>maxCount)maxCount=count;
      days.push({date:d,key:dateKey,count:count});
    }
    var h="";
    h+='<div style="font-size:13px;color:#888;margin-bottom:8px">最近12周的对话活动</div>';
    h+='<div class="heatmap-grid">';
    // 星期标签
    var dayLabels=["日","一","二","三","四","五","六"];
    for(var i=0;i<7;i++){
      h+='<div style="font-size:9px;color:#555;text-align:center;padding:2px">'+dayLabels[i]+'</div>';
    }
    // 填充热力图
    for(var i=0;i<days.length;i++){
      var day=days[i];
      var intensity=0;
      if(maxCount>0)intensity=day.count/maxCount;
      var bg="rgba(124,92,252,0.04)";
      if(intensity>0){
        if(intensity>0.75)bg="rgba(124,92,252,0.9)";
        else if(intensity>0.5)bg="rgba(124,92,252,0.6)";
        else if(intensity>0.25)bg="rgba(124,92,252,0.35)";
        else bg="rgba(124,92,252,0.15)";
      }
      var dayNum=day.date.getDate();
      h+='<div class="heatmap-cell" style="background:'+bg+'" title="'+day.key+': '+day.count+'条">'+dayNum+'</div>';
    }
    h+='</div>';
    // 图例
    h+='<div class="heatmap-legend">';
    h+='<span>少</span>';
    h+='<div class="heatmap-legend-box" style="background:rgba(124,92,252,0.04)"></div>';
    h+='<div class="heatmap-legend-box" style="background:rgba(124,92,252,0.15)"></div>';
    h+='<div class="heatmap-legend-box" style="background:rgba(124,92,252,0.35)"></div>';
    h+='<div class="heatmap-legend-box" style="background:rgba(124,92,252,0.6)"></div>';
    h+='<div class="heatmap-legend-box" style="background:rgba(124,92,252,0.9)"></div>';
    h+='<span>多</span>';
    h+='</div>';
    // 统计
    var totalDays=days.filter(function(d){return d.count>0}).length;
    var totalMsgs=0;
    for(var key in data)totalMsgs+=data[key];
    var avgPerDay=totalDays>0?Math.round(totalMsgs/totalDays):0;
    h+='<div class="heatmap-stats">';
    h+='<div class="heatmap-stat-card"><div class="heatmap-stat-num">'+totalMsgs+'</div><div class="heatmap-stat-label">总消息数</div></div>';
    h+='<div class="heatmap-stat-card"><div class="heatmap-stat-num">'+totalDays+'</div><div class="heatmap-stat-label">活跃天数</div></div>';
    h+='<div class="heatmap-stat-card"><div class="heatmap-stat-num">'+avgPerDay+'</div><div class="heatmap-stat-label">日均消息</div></div>';
    h+='</div>';
    body.innerHTML=h;
  }catch(e){showToast("打开热力图失败")}
}
function closeHeatmapPanel(){
  try{var box=$("heatmapOverlay");if(box)box.className="heatmap-overlay"}catch(e){}
}

// ==========================================================================
// ===== v3.9.0 初始化与菜单注入 =====
// ==========================================================================
function initV39Features(){
  try{
    // 初始化深夜模式
    checkDeepNightMode();
    // 每小时检查一次
    setInterval(function(){checkDeepNightMode()},3600000);
    // 注入功能入口到设置面板
    setTimeout(function(){
      try{
        // 在角色面板添加v3.9功能按钮
        var charPanel=$("charPanelBox");
        if(charPanel){
          var existingActions=charPanel.querySelector(".cp-actions");
          if(existingActions){
            var newBtns=document.createElement("div");
            newBtns.className="cp-actions";
            newBtns.style.marginTop="4px";
            newBtns.innerHTML=
              '<div class="cp-act-btn" onclick="openEmotionDashboard();closeCharPanel(event)">📊情感</div>'+
              '<div class="cp-act-btn" onclick="openAchievementPanel();closeCharPanel(event)">🏆成就</div>'+
              '<div class="cp-act-btn" onclick="openPortraitPanel();closeCharPanel(event)">🎨画像</div>'+
              '<div class="cp-act-btn" onclick="openHeatmapPanel();closeCharPanel(event)">🔥热力图</div>'+
              '<div class="cp-act-btn" onclick="openFxMenu()">✨动效</div>'+
              '<div class="cp-act-btn" onclick="toggleDeepNightMode()">🌙夜间</div>';
            existingActions.parentNode.insertBefore(newBtns,existingActions.nextSibling);
          }
        }
      }catch(e){}
    },1500);
    // 检查成就解锁
    setTimeout(function(){try{getUnlockedAchievements()}catch(e){}},5000);
    // 标记成就
    var origOpenEmotion=openEmotionDashboard;
    window.openEmotionDashboard=function(){lsSet("achv_viewedEmotion",true);origOpenEmotion()};
    var origOpenFx=openFxMenu;
    window.openFxMenu=function(){origOpenFx()};
    // 在导出时标记成就
    var origExport=saveExportFile;
    window.saveExportFile=function(c,e){lsSet("achv_exported",true);origExport(c,e)};
  }catch(e){}
}
// 延迟初始化v3.9功能
setTimeout(function(){try{initV39Features()}catch(e){}},4000);

