var DREAM_THEMES=[
  {id:"starlight",icon:"✨",name:"星空之梦",fragments:["繁星如雨般洒落","月亮在耳边低语","银河蜿蜒流过指尖","星辰编织成摇篮","宇宙在瞳孔中旋转"]},
  {id:"ocean",icon:"🌊",name:"海洋之梦",fragments:["海浪轻抚着沙滩","鲸鱼在云端游弋","珊瑚城市闪烁光芒","潮汐带走了所有忧愁","深蓝中有歌声回荡"]},
  {id:"forest",icon:"🌲",name:"森林之梦",fragments:["古树在月光下低语","萤火虫指引着方向","苔藓上长满了记忆","溪水叮咚弹奏琴键","蘑菇屋亮起暖灯"]},
  {id:"sky",icon:"☁️",name:"天空之梦",fragments:["云朵柔软如棉花糖","风托起翅膀飞翔","彩虹桥连接两个世界","阳光穿透薄雾","雨滴在空中跳舞"]},
  {id:"memory",icon:"🔮",name:"记忆之梦",fragments:["旧照片缓缓转动","童年的笑声从远处传来","时间凝固成琥珀","记忆的碎片重新拼合","昨天的雨今天才落下"]},
  {id:"fantasy",icon:"🦄",name:"奇幻之梦",fragments:["独角兽踏着月光而来","水晶宫在深海闪耀","魔法书自动翻页","龙在云间沉睡","时间之钟倒转"]},
  {id:"warm",icon:"🔥",name:"温暖之梦",fragments:["壁炉的火光跳动","毛毯裹住整个世界","热可可的香气弥漫","猫在膝上打呼噜","窗外的雪静静下着"]},
  {id:"mystery",icon:"🌙",name:"神秘之梦",fragments:["迷雾中有影子闪过","古老的门缓缓打开","面具下是另一张面具","时钟指向第十三小时","镜子里的世界不同"]}
];
var _dreamCurTheme="starlight";
function generateDream(themeId){
  try{
    var theme=DREAM_THEMES.find(function(t){return t.id===themeId})||DREAM_THEMES[0];
    var fragments=theme.fragments.slice();
    // 随机选取3-4个片段
    var count=3+Math.floor(Math.random()*2);
    var selected=[];
    for(var i=0;i<count&&fragments.length>0;i++){
      var idx=Math.floor(Math.random()*fragments.length);
      selected.push(fragments.splice(idx,1)[0]);
    }
    // 添加角色相关内容
    var roleName=curRole?curRole.name:"";
    var dream="";
    if(roleName){
      dream+="在梦的入口，"+roleName+"正等着我。\n\n";
    }
    dream+=selected.join("，\n");
    dream+="。\n\n";
    // 添加结尾
    var endings=["一切如此美好，不愿醒来。","梦的尽头，是温柔的光。","我在梦中微笑了。","这个梦，我会一直记得。","星辰见证了这个梦。"];
    dream+=endings[Math.floor(Math.random()*endings.length)];
    // 保存到历史
    var history=lsGet("dreamHistory")||[];
    history.unshift({id:Date.now(),theme:themeId,text:dream,createdAt:Date.now()});
    if(history.length>20)history=history.slice(0,20);
    lsSet("dreamHistory",history);
    return dream;
  }catch(e){return "梦境生成失败，请重试。"}
}
function openDreamPanel(){
  try{
    var box=$("dreamOverlayOld");
    if(!box)return;
    box.className="dream-overlay show";
    renderDreamPanel();
  }catch(e){showToast("打开梦境生成器失败")}
}
function renderDreamPanel(){
  try{
    var body=$("dreamBody");
    if(!body)return;
    var h="";
    // 主题选择
    h+='<div class="dream-theme-tags">';
    for(var i=0;i<DREAM_THEMES.length;i++){
      h+='<span class="dream-theme-tag '+(_dreamCurTheme===DREAM_THEMES[i].id?"active":"")+'" onclick="selectDreamTheme(\''+DREAM_THEMES[i].id+'\')">'+DREAM_THEMES[i].icon+' '+DREAM_THEMES[i].name+'</span>';
    }
    h+='</div>';
    // 梦境画布
    h+='<div class="dream-canvas">';
    h+='<div class="dream-stars" id="dreamStars"></div>';
    h+='<div class="dream-content" id="dreamContent">';
    h+='<div class="dream-content-empty">🌙 选择主题后点击生成<br>让AI为你编织一个梦</div>';
    h+='</div>';
    h+='</div>';
    h+='<button class="dream-generate-btn" onclick="generateAndShowDream()">✨ 生成梦境</button>';
    // 历史
    var history=lsGet("dreamHistory")||[];
    if(history.length>0){
      h+='<div class="dream-history">';
      h+='<div class="dream-history-title">📜 历史梦境</div>';
      for(var i=0;i<Math.min(history.length,8);i++){
        var dream=history[i];
        h+='<div class="dream-history-item" onclick="showDreamHistory('+i+')">';
        h+='<div class="dream-history-date">'+new Date(dream.createdAt).toLocaleString()+'</div>';
        h+='<div class="dream-history-preview">'+esc(dream.text.substring(0,100))+'</div>';
        h+='</div>';
      }
      h+='</div>';
    }
    body.innerHTML=h;
    // 添加星星动画
    var stars=$("dreamStars");
    if(stars){
      var starHTML="";
      for(var i=0;i<30;i++){
        var x=Math.random()*100;
        var y=Math.random()*100;
        var size=1+Math.random()*2;
        var delay=Math.random()*3;
        starHTML+='<div style="position:absolute;left:'+x+'%;top:'+y+'%;width:'+size+'px;height:'+size+'px;background:#fff;border-radius:50%;opacity:'+ (0.3+Math.random()*0.7) +';animation:fxGlow 2s infinite;animation-delay:'+delay+'s"></div>';
      }
      stars.innerHTML=starHTML;
    }
  }catch(e){}
}
function selectDreamTheme(themeId){
  try{
    _dreamCurTheme=themeId;
    renderDreamPanel();
  }catch(e){}
}
function generateAndShowDream(){
  try{
    var dream=generateDream(_dreamCurTheme);
    var el=$("dreamContent");
    if(el){
      el.innerHTML='<div style="font-size:14px;color:#d4c8ff;line-height:2;white-space:pre-wrap;text-align:center">'+esc(dream)+'</div>';
    }
    // 重新渲染以更新历史
    setTimeout(function(){renderDreamPanel();var el2=$("dreamContent");if(el2)el2.innerHTML='<div style="font-size:14px;color:#d4c8ff;line-height:2;white-space:pre-wrap;text-align:center">'+esc(dream)+'</div>'},100);
  }catch(e){showToast("生成失败")}
}
function showDreamHistory(idx){
  try{
    var history=lsGet("dreamHistory")||[];
    if(idx<0||idx>=history.length)return;
    var el=$("dreamContent");
    if(el){
      el.innerHTML='<div style="font-size:14px;color:#d4c8ff;line-height:2;white-space:pre-wrap;text-align:center">'+esc(history[idx].text)+'</div>';
    }
  }catch(e){}
}
function closeDreamPanel(){
  try{var box=$("dreamOverlay");if(box)box.className="dream-overlay"}catch(e){}
}

