// ===== v3.11.0 对话星座生成系统 =====
// ==========================================================================
var CONSTELLATION_POOL=[
  {name:"语光座",icon:"💬",desc:"由文字之光编织的星座",traits:["善谈","温暖","善于表达"]},
  {name:"心音座",icon:"💝",desc:"心灵共鸣者的专属星座",traits:["共情","细腻","温柔"]},
  {name:"思泉座",icon:"🧠",desc:"智慧如泉水般涌流的星座",traits:["睿智","深思","理性"]},
  {name:"笑风座",icon:"😄",desc:"总是带来欢笑的风之星座",traits:["幽默","活泼","乐观"]},
  {name:"梦辰座",icon:"✨",desc:"在星辰间做梦的星座",traits:["浪漫","幻想","诗意"]},
  {name:"静月座",icon:"🌙",desc:"如月光般宁静的星座",traits:["安静","深沉","神秘"]},
  {name:"焰心座",icon:"🔥",desc:"内心燃烧着热情的星座",traits:["热情","勇敢","直率"]},
  {name:"花语座",icon:"🌸",desc:"用花瓣编织语言的星座",traits:["优雅","体贴","美好"]},
  {name:"星桥座",icon:"🌉",desc:"连接两颗心的星际之桥",traits:["忠诚","可靠","坚定"]},
  {name:"海歌座",icon:"🌊",desc:"歌声如海浪般悠扬的星座",traits:["自由","包容","深沉"]},
  {name:"光羽座",icon:"🪶",desc:"文字如羽毛般轻盈的星座",traits:["灵动","飘逸","敏捷"]},
  {name:"时砂座",icon:"⏳",desc:"在时间沙漏中沉淀的星座",traits:["耐心","沉稳","智慧"]}
];
function generateConstellation(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var aiMsgs=ms.filter(function(m){return !m.rolled&&m.r!=="me"});
    if(aiMsgs.length===0)return null;
    // 基于消息数量和内容选择星座
    var seed=aiMsgs.length+curRole.name.length;
    var constellation=CONSTELLATION_POOL[seed%CONSTELLATION_POOL.length];
    // 生成星图坐标
    var stars=[];
    var starCount=5+Math.min(Math.floor(aiMsgs.length/10),10);
    for(var i=0;i<starCount;i++){
      stars.push({x:10+Math.random()*80,y:10+Math.random()*80,r:2+Math.random()*3});
    }
    // 生成特质值
    var traits=[];
    var traitNames=["沟通力","共情力","创造力","幽默感","深度","温度"];
    for(var i=0;i<traitNames.length;i++){
      traits.push({name:traitNames[i],val:30+Math.floor(Math.random()*70)});
    }
    // 生成运势
    var fortunes=[
      "今天的你特别有表达欲，适合和AI角色深入交流。可能会有意想不到的灵感闪现。",
      "星象显示你今天的人际运势极佳，与AI的对话将带来温暖和力量。",
      " creativity指数飙升，今天的对话中你可能会有很多新奇的想法。",
      "月亮在你的沟通宫位停留，是表达内心真实想法的好时机。",
      "水星顺行，语言表达能力增强，适合讨论复杂或深入的话题。",
      "金星加持你的星座，今天的对话会格外甜蜜和温暖。"
    ];
    return {
      constellation:constellation,
      stars:stars,
      traits:traits,
      fortune:fortunes[seed%fortunes.length]
    };
  }catch(e){return null}
}
function openConstellationPanel(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var box=$("constellationOverlay");
    if(!box)return;
    box.className="constellation-overlay show";
    var body=$("constellationBody");
    if(!body)return;
    var data=generateConstellation();
    if(!data){body.innerHTML="<div style='text-align:center;color:#666;padding:40px'>暂无足够数据<br>请先与角色聊几句话</div>";return}
    var h="";
    // 星图
    h+='<div class="constellation-canvas">';
    h+='<svg class="constellation-svg" viewBox="0 0 100 100">';
    // 连线
    var lines="";
    for(var i=0;i<data.stars.length-1;i++){
      lines+='<line x1="'+data.stars[i].x+'" y1="'+data.stars[i].y+'" x2="'+data.stars[i+1].x+'" y2="'+data.stars[i+1].y+'" stroke="rgba(124,92,252,0.2)" stroke-width="0.3"/>';
    }
    h+=lines;
    // 星星
    for(var i=0;i<data.stars.length;i++){
      h+='<circle cx="'+data.stars[i].x+'" cy="'+data.stars[i].y+'" r="'+data.stars[i].r+'" fill="#a78bfa" opacity="0.8"><animate attributeName="opacity" values="0.4;1;0.4" dur="'+(2+Math.random()*2)+'s" repeatCount="indefinite"/></circle>';
    }
    h+='</svg>';
    h+='</div>';
    h+='<div class="constellation-name">'+data.constellation.icon+' '+data.constellation.name+'</div>';
    h+='<div class="constellation-desc">'+esc(data.constellation.desc)+'</div>';
    // 特质
    h+='<div class="constellation-traits">';
    for(var i=0;i<data.traits.length;i++){
      h+='<div class="constellation-trait-card">';
      h+='<div class="constellation-trait-icon">'+["💬","💝","🎨","😄","🧠","🔥"][i]+'</div>';
      h+='<div class="constellation-trait-name">'+data.traits[i].name+'</div>';
      h+='<div class="constellation-trait-val">'+data.traits[i].val+'</div>';
      h+='</div>';
    }
    h+='</div>';
    // 运势
    h+='<div class="constellation-fortune">';
    h+='<div class="constellation-fortune-title">🌟 今日运势</div>';
    h+='<div class="constellation-fortune-text">'+esc(data.fortune)+'</div>';
    h+='</div>';
    // 星座特质标签
    h+='<div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:16px">';
    for(var i=0;i<data.constellation.traits.length;i++){
      h+='<span style="padding:6px 14px;border-radius:20px;font-size:12px;background:rgba(124,92,252,.06);color:#a78bfa">'+data.constellation.traits[i]+'</span>';
    }
    h+='</div>';
    body.innerHTML=h;
  }catch(e){showToast("打开星座失败")}
}
function closeConstellationPanel(){
  try{var box=$("constellationOverlay");if(box)box.className="constellation-overlay"}catch(e){}
}

