// ===== v3.11.0 AI塔罗牌占卜 =====
// ==========================================================================
var TAROT_CARDS=[
  {name:"愚者",icon:"🤡",upright:"新的开始，冒险精神，无限可能",reversed:"冲动，鲁莽，缺乏计划"},
  {name:"魔术师",icon:"🎩",upright:"创造力，意志力，掌控全局",reversed:"欺骗，缺乏自信，能力不足"},
  {name:"女祭司",icon:"🔮",upright:"直觉，神秘，内在智慧",reversed:"秘密，压抑，缺乏直觉"},
  {name:"皇后",icon:"👑",upright:"丰盛，母性，创造力的绽放",reversed:"依赖，过度保护，创造受阻"},
  {name:"皇帝",icon:"⚜️",upright:"权威，秩序，坚定的领导力",reversed:"专制，固执，缺乏自律"},
  {name:"恋人",icon:"💕",upright:"爱情，选择，价值观的契合",reversed:"分离，失衡，错误选择"},
  {name:"战车",icon:"⚔️",upright:"胜利，意志，克服困难",reversed:"失控，方向不明，挫败"},
  {name:"力量",icon:"🦁",upright:"勇气，耐心，内在力量",reversed:"自我怀疑，脆弱，失控"},
  {name:"隐士",icon:"🕯️",upright:"独处，内省，寻找答案",reversed:"孤立，固执，拒绝建议"},
  {name:"命运之轮",icon:"🎡",upright:"转机，好运，命运的转折",reversed:"厄运，抗拒变化，错失良机"},
  {name:"正义",icon:"⚖️",upright:"公平，真相，因果报应",reversed:"不公，偏见，逃避责任"},
  {name:"倒吊人",icon:"🙃",upright:"牺牲，新视角，暂停反思",reversed:"无谓牺牲，拖延，停滞"},
  {name:"死神",icon:"💀",upright:"结束，蜕变，旧的不去新的不来",reversed:"抗拒变化，恐惧，停滞不前"},
  {name:"节制",icon:" angel",upright:"平衡，调和，耐心",reversed:"失衡，过度，缺乏协调"},
  {name:"恶魔",icon:"😈",upright:"束缚，欲望，物质依赖",reversed:"解脱，觉醒，挣脱束缚"},
  {name:"高塔",icon:"🗼",upright:"突变，毁灭，重建根基",reversed:"避免灾难，恐惧变化，延缓必然"},
  {name:"星星",icon:"⭐",upright:"希望，灵感，宁静",reversed:"失望，悲观，失去信心"},
  {name:"月亮",icon:"🌙",upright:"幻觉，直觉，潜意识",reversed:"困惑，恐惧，被欺骗"},
  {name:"太阳",icon:"☀️",upright:"快乐，成功，活力四射",reversed:"暂时的挫折，过度乐观，延迟成功"},
  {name:"审判",icon:"🎺",upright:"重生，觉醒，最终决定",reversed:"自我怀疑，犹豫，错过召唤"},
  {name:"世界",icon:"🌍",upright:"圆满，成就，旅程完成",reversed:"未完成，停滞，差一步"}
];
var _tarotDrawn=[];
var _tarotQuestion="";
function drawTarotCards(){
  try{
    var pool=TAROT_CARDS.slice();
    var drawn=[];
    for(var i=0;i<3&&pool.length>0;i++){
      var idx=Math.floor(Math.random()*pool.length);
      var card=pool.splice(idx,1)[0];
      card.isUpright=Math.random()>0.4;
      drawn.push(card);
    }
    _tarotDrawn=drawn;
    return drawn;
  }catch(e){return []}
}
function openTarotPanel(){
  try{
    var box=$("tarotOverlay");
    if(!box)return;
    box.className="tarot-overlay show";
    _tarotDrawn=[];
    renderTarotPanel();
  }catch(e){showToast("打开塔罗占卜失败")}
}
function renderTarotPanel(){
  try{
    var body=$("tarotBody");
    if(!body)return;
    var h="";
    h+='<input class="tarot-question-input" id="tarotQuestionInput" placeholder="输入你的问题（可选）..." maxlength="50" value="'+esc(_tarotQuestion)+'">';
    // 牌面
    h+='<div class="tarot-cards-row">';
    var positions=["过去","现在","未来"];
    for(var i=0;i<3;i++){
      var card=_tarotDrawn[i];
      h+='<div style="text-align:center">';
      if(card){
        h+='<div class="tarot-card flipped" onclick="flipTarotCard('+i+')">';
        h+='<div class="tarot-card-back">🔮</div>';
        h+='<div class="tarot-card-front">';
        h+='<div class="tarot-card-front-icon">'+card.icon+'</div>';
        h+='<div class="tarot-card-front-name">'+card.name+(card.isUpright?"":" 逆")+'</div>';
        h+='</div></div>';
      }else{
        h+='<div class="tarot-card" onclick="flipTarotCard('+i+')">';
        h+='<div class="tarot-card-back">🔮</div>';
        h+='</div>';
      }
      h+='<div class="tarot-card-position">'+positions[i]+'</div>';
      h+='</div>';
    }
    h+='</div>';
    if(_tarotDrawn.length<3){
      h+='<button class="tarot-draw-btn" onclick="drawAndShowTarot()">🔮 抽牌</button>';
    }else{
      // 解读
      h+='<div class="tarot-reading show">';
      h+='<div class="tarot-reading-title">📜 牌面解读</div>';
      for(var i=0;i<3;i++){
        var card=_tarotDrawn[i];
        var meaning=card.isUpright?card.upright:card.reversed;
        h+='<div class="tarot-reading-item">';
        h+='<div class="tarot-reading-pos">'+positions[i]+'</div>';
        h+='<div class="tarot-reading-name">'+card.icon+' '+card.name+(card.isUpright?" (正位)":" (逆位)")+'</div>';
        h+='<div class="tarot-reading-meaning">'+esc(meaning)+'</div>';
        h+='</div>';
      }
      // 总结
      var summary="综合三张牌来看，";
      if(_tarotQuestion){
        summary+="关于「"+_tarotQuestion+"」这个问题，";
      }
      var hasUpright=_tarotDrawn.filter(function(c){return c.isUpright}).length;
      if(hasUpright>=2){
        summary+="整体趋势是积极的。过去的经历为你奠定了基础，现在的你正处于有利的 position，未来充满希望。保持这份正向的能量，一切都会朝着好的方向发展。";
      }else if(hasUpright===1){
        summary+="虽然面临一些挑战，但并非没有转机。需要你静下心来思考，调整方向。记住，每一张逆位牌都蕴含着成长的契机。";
      }else{
        summary+="当前可能处于低谷期，但这正是反思和蓄力的时刻。逆位不代表绝望，而是提醒你需要换一个角度看问题。相信时间会带来转机。";
      }
      h+='<div class="tarot-reading-summary">'+esc(summary)+'</div>';
      h+='</div>';
      h+='<button class="tarot-draw-btn" onclick="openTarotPanel()">🔮 重新占卜</button>';
    }
    body.innerHTML=h;
  }catch(e){}
}
function drawAndShowTarot(){
  try{
    var input=$("tarotQuestionInput");
    _tarotQuestion=input?input.value.trim():"";
    drawTarotCards();
    renderTarotPanel();
    // 逐张翻开
    setTimeout(function(){
      var cards=document.querySelectorAll(".tarot-card");
      for(var i=0;i<cards.length;i++){
        (function(idx){setTimeout(function(){if(cards[idx])cards[idx].className="tarot-card flipped"},idx*500)})(i);
      }
    },100);
  }catch(e){showToast("抽牌失败")}
}
function flipTarotCard(idx){
  try{
    if(_tarotDrawn.length===0)return;
    var cards=document.querySelectorAll(".tarot-card");
    if(cards[idx])cards[idx].className="tarot-card flipped";
  }catch(e){}
}
function closeTarotPanel(){
  try{var box=$("tarotOverlay");if(box)box.className="tarot-overlay"}catch(e){}
}

// ==========================================================================
// ===== v3.11.0 对话心愿瓶 =====
// ==========================================================================
function getWishes(){
  try{return lsGet("wishBottles")||[]}catch(e){return []}
}
function saveWishes(w){
  try{lsSet("wishBottles",w)}catch(e){}
}
function getStrangerWishes(){
  try{
    var saved=lsGet("strangerWishes");
    if(!saved||saved.length===0){
      // 生成初始陌生人愿望
      var stranger=[
        {text:"希望明天的考试顺利通过！",likes:42,time:Date.now()-86400000*3},
        {text:"想对远方的妈妈说一声：我想你了。",likes:87,time:Date.now()-86400000*7},
        {text:"希望能找到一份喜欢的工作，不再将就。",likes:56,time:Date.now()-86400000*5},
        {text:"愿世界温柔以待每一个努力的人。",likes:123,time:Date.now()-86400000*1},
        {text:"希望明年的自己比今年更好。",likes:95,time:Date.now()-86400000*10},
        {text:"想对那个女孩说：遇见你是我最大的幸运。",likes:68,time:Date.now()-86400000*2},
        {text:"希望爸爸的身体早日康复。",likes:156,time:Date.now()-86400000*4},
        {text:"愿每一个失眠的夜晚都有人陪伴。",likes:73,time:Date.now()-86400000*6}
      ];
      lsSet("strangerWishes",stranger);
      return stranger;
    }
    return saved;
  }catch(e){return []}
}
function openWishPanel(){
  try{
    var box=$("wishOverlay");
    if(!box)return;
    box.className="wish-overlay show";
    var body=$("wishBody");
    if(!body)return;
    var wishes=getWishes();
    var strangers=getStrangerWishes();
    var h="";
    h+='<button class="wish-create-btn" onclick="createWishBottle()">🍾 投出一个心愿瓶</button>';
    // 海洋展示
    h+='<div class="wish-ocean">';
    h+='<div class="wish-ocean-wave"></div>';
    var oceanBottles="";
    var allBottles=[{own:true,list:wishes},{own:false,list:strangers}];
    var totalShow=0;
    for(var bi=0;bi<allBottles.length&&totalShow<8;bi++){
      for(var wi=0;wi<allBottles[bi].list.length&&totalShow<8;wi++){
        var emojis=["🍾","🧴","📬","📦"];
        oceanBottles+='<span class="wish-bottle" onclick="openWishPanel()" style="position:relative;top:'+(20+Math.random()*40)+'px;left:'+(Math.random()*20-10)+'px">'+emojis[totalShow%4]+'</span>';
        totalShow++;
      }
    }
    if(totalShow===0)oceanBottles='<div style="text-align:center;color:#666;padding:40px;font-size:13px">🌊 海面上还没有心愿瓶<br>投出第一个吧</div>';
    h+=oceanBottles;
    h+='</div>';
    // 我的心愿瓶
    h+='<div style="font-size:13px;color:#888;margin-bottom:10px">🍾 我的心愿瓶</div>';
    if(wishes.length===0){
      h+='<div style="text-align:center;color:#555;padding:20px;font-size:12px">还没有投出心愿瓶</div>';
    }else{
      for(var i=0;i<wishes.length;i++){
        h+='<div class="wish-bottle-item own">';
        h+='<div class="wish-bottle-icon">🍾</div>';
        h+='<div class="wish-bottle-text">'+esc(wishes[i].text)+'</div>';
        h+='<div class="wish-bottle-meta"><span>'+new Date(wishes[i].time).toLocaleDateString()+'</span><span class="wish-bottle-like" onclick="deleteWish('+i+')">🗑 删除</span></div>';
        h+='</div>';
      }
    }
    // 来自海上的心愿
    h+='<div style="font-size:13px;color:#888;margin:16px 0 10px">🌊 来自海上的心愿</div>';
    strangers.sort(function(a,b){return b.time-a.time});
    for(var i=0;i<Math.min(strangers.length,6);i++){
      var s=strangers[i];
      h+='<div class="wish-bottle-item stranger">';
      h+='<div class="wish-bottle-icon">漂流瓶</div>';
      h+='<div class="wish-bottle-text">'+esc(s.text)+'</div>';
      h+='<div class="wish-bottle-meta"><span>'+new Date(s.time).toLocaleDateString()+'</span><span class="wish-bottle-like" onclick="likeWish('+i+')">❤️ '+s.likes+'</span></div>';
      h+='</div>';
    }
    body.innerHTML=h;
  }catch(e){showToast("打开心愿瓶失败")}
}
function createWishBottle(){
  try{
    var wish=prompt("写下你的心愿，投入海洋...");
    if(!wish||!wish.trim())return;
    var wishes=getWishes();
    wishes.push({text:wish.trim(),time:Date.now()});
    saveWishes(wishes);
    openWishPanel();
    showToast("🍾 心愿瓶已投入海洋！");
  }catch(e){showToast("投递失败")}
}
function deleteWish(idx){
  try{
    var wishes=getWishes();
    if(idx<0||idx>=wishes.length)return;
    wishes.splice(idx,1);
    saveWishes(wishes);
    openWishPanel();
    showToast("已删除");
  }catch(e){}
}
function likeWish(idx){
  try{
    var strangers=getStrangerWishes();
    if(idx<0||idx>=strangers.length)return;
    strangers[idx].likes++;
    lsSet("strangerWishes",strangers);
    openWishPanel();
  }catch(e){}
}
