// ===== v3.11.0 对话心情日历 =====
// ==========================================================================
var _moodCalDate=new Date();
function getMoodCalendarData(){
  try{
    var data={};
    var roleIds=Object.keys(msgs);
    for(var ri=0;ri<roleIds.length;ri++){
      var ms=msgs[roleIds[ri]]||[];
      var active=ms.filter(function(m){return !m.rolled});
      for(var i=0;i<active.length;i++){
        if(active[i].time){
          var d=new Date(active[i].time);
          var key=d.getFullYear()+"-"+(d.getMonth()+1)+"-"+d.getDate();
          if(!data[key])data[key]={msgs:[],mood:"calm"};
          data[key].msgs.push(active[i]);
          // 分析当天情绪
          if(typeof analyzeEmotion==="function"){
            var result=analyzeEmotion(active[i].t||"");
            if(result.dominant!=="calm")data[key].mood=result.dominant;
          }
        }
      }
    }
    return data;
  }catch(e){return {}}
}
function openMoodCalPanel(){
  try{
    var box=$("moodCalOverlay");
    if(!box)return;
    box.className="mood-cal-overlay show";
    renderMoodCalendar();
  }catch(e){showToast("打开心情日历失败")}
}
function renderMoodCalendar(){
  try{
    var body=$("moodCalBody");
    if(!body)return;
    var year=_moodCalDate.getFullYear();
    var month=_moodCalDate.getMonth();
    var data=getMoodCalendarData();
    var moodEmojis={happy:"😊",sad:"😢",angry:"😡",love:"❤️",anxious:"😰",calm:"😌",surprise:"😮",shy:"😳"};
    var h="";
    // 导航
    h+='<div class="mood-cal-nav">';
    h+='<button class="mood-cal-nav-btn" onclick="navMoodCal(-1)">‹</button>';
    h+='<div class="mood-cal-nav-month">'+year+'年'+(month+1)+'月</div>';
    h+='<button class="mood-cal-nav-btn" onclick="navMoodCal(1)">›</button>';
    h+='</div>';
    // 日历网格
    h+='<div class="mood-cal-grid">';
    var weekdays=["日","一","二","三","四","五","六"];
    for(var i=0;i<7;i++)h+='<div class="mood-cal-weekday">'+weekdays[i]+'</div>';
    var firstDay=new Date(year,month,1).getDay();
    var daysInMonth=new Date(year,month+1,0).getDate();
    var today=new Date();
    // 空白格
    for(var i=0;i<firstDay;i++)h+='<div></div>';
    for(var d=1;d<=daysInMonth;d++){
      var key=year+"-"+(month+1)+"-"+d;
      var dayData=data[key];
      var isToday=(d===today.getDate()&&month===today.getMonth()&&year===today.getFullYear());
      if(dayData){
        var emoji=moodEmojis[dayData.mood]||"💬";
        h+='<div class="mood-cal-day has-mood today" onclick="showMoodCalDetail(\''+key+'\')">';
        h+='<div class="mood-cal-day-emoji">'+emoji+'</div>';
        h+='<div class="mood-cal-day-num">'+d+'</div>';
        h+='</div>';
      }else{
        h+='<div class="mood-cal-day'+(isToday?" today":"")+'">';
        h+='<div class="mood-cal-day-num">'+d+'</div>';
        h+='</div>';
      }
    }
    h+='</div>';
    // 图例
    h+='<div class="mood-cal-legend">';
    var legend=[{e:"😊",n:"开心"},{e:"😢",n:"悲伤"},{e:"❤️",n:"喜爱"},{e:"😌",n:"平静"},{e:"😰",n:"焦虑"},{e:"😡",n:"愤怒"}];
    for(var i=0;i<legend.length;i++){
      h+='<div class="mood-cal-legend-item"><span class="mood-cal-legend-emoji">'+legend[i].e+'</span>'+legend[i].n+'</div>';
    }
    h+='</div>';
    // 详情区域
    h+='<div class="mood-cal-detail" id="moodCalDetail"><div style="color:#666;text-align:center">点击有表情的日期查看详情</div></div>';
    body.innerHTML=h;
  }catch(e){}
}
function navMoodCal(delta){
  try{
    _moodCalDate.setMonth(_moodCalDate.getMonth()+delta);
    renderMoodCalendar();
  }catch(e){}
}
function showMoodCalDetail(key){
  try{
    var detail=$("moodCalDetail");
    if(!detail)return;
    var parts=key.split("-");
    var d=new Date(parseInt(parts[0]),parseInt(parts[1])-1,parseInt(parts[2]));
    var data=getMoodCalendarData();
    var dayData=data[key];
    if(!dayData){detail.innerHTML="<div style='color:#666;text-align:center'>这一天没有对话记录</div>";detail.className="mood-cal-detail show";return}
    var moodEmojis={happy:"😊 开心",sad:"😢 悲伤",angry:"😡 愤怒",love:"❤️ 喜爱",anxious:"😰 焦虑",calm:"😌 平静",surprise:"😮 惊讶",shy:"😳 害羞"};
    var h="";
    h+='<div class="mood-cal-detail-date">📅 '+d.toLocaleDateString()+'</div>';
    h+='<div class="mood-cal-detail-content">主导心情: '+(moodEmojis[dayData.mood]||"😌 平静")+'</div>';
    h+='<div class="mood-cal-detail-content">消息数: '+dayData.msgs.length+'条</div>';
    // 展示前3条消息
    h+='<div class="mood-cal-detail-content" style="margin-top:8px">精彩片段:</div>';
    for(var i=0;i<Math.min(dayData.msgs.length,3);i++){
      var msg=dayData.msgs[i];
      var sender=msg.r==="me"?"我":(curRole?curRole.name:"AI");
      h+='<div style="font-size:12px;color:#888;margin-top:6px;padding:8px;background:rgba(124,92,252,.04);border-radius:8px"><b>'+esc(sender)+'</b>: '+esc((msg.t||"").substring(0,80))+'</div>';
    }
    detail.innerHTML=h;
    detail.className="mood-cal-detail show";
  }catch(e){}
}
function closeMoodCalPanel(){
  try{var box=$("moodCalOverlay");if(box)box.className="mood-cal-overlay"}catch(e){}
}

