// ==========================================================================
// ===== v3.12.0 AI对话情绪光谱分析 =====
// ==========================================================================
var EMOTION_SPECTRUM=[
  {key:"happy",emoji:"😊",name:"开心",color:"#fcb85c"},
  {key:"excited",emoji:"🤩",name:"兴奋",color:"#fc6b6b"},
  {key:"calm",emoji:"😌",name:"平静",color:"#5cfca8"},
  {key:"sad",emoji:"😢",name:"悲伤",color:"#5cb4fc"},
  {key:"angry",emoji:"😠",name:"生气",color:"#fc5c5c"},
  {key:"surprised",emoji:"😮",name:"惊讶",color:"#a78bfa"},
  {key:"love",emoji:"🥰",name:"喜爱",color:"#fc5c8a"},
  {key:"thinking",emoji:"🤔",name:"思考",color:"#7c8cf0"}
];
function detectEmotionSimple(text){
  try{
    if(!text)return "calm";
    var t=text.toLowerCase();
    var scores={};
    var rules={
      happy:["开心","快乐","高兴","哈哈","嘻嘻","😄","👍","好的","不错","棒","happy","lol","great"],
      excited:["太棒了","超级","激动","兴奋","哇","🎉","太好了","amazing","awesome","wow"],
      calm:["嗯","好的","明白","了解","嗯嗯","ok","fine","平静"],
      sad:["难过","伤心","哭","悲伤","郁闷","😢","😭","sad","sorry","遗憾"],
      angry:["生气","愤怒","烦","讨厌","气","😠","😡","angry","damn"],
      surprised:["什么","真的吗","不会吧","天啊","哇塞","wow","really","surprise"],
      love:["喜欢","爱","想你","宝贝","亲爱的","❤️","💕","love","miss"],
      thinking:["嗯...","让我想想","思考","其实","也许","可能","hmm","think"]
    };
    for(var k in rules){
      scores[k]=0;
      for(var i=0;i<rules[k].length;i++){
        if(t.indexOf(rules[k][i])>=0)scores[k]++;
      }
    }
    var maxKey="calm";var maxVal=0;
    for(var k in scores){
      if(scores[k]>maxVal){maxVal=scores[k];maxKey=k}
    }
    return maxVal>0?maxKey:"calm";
  }catch(e){return "calm"}
}
function generateEmotionSpectrum(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(active.length===0)return null;
    var emotions=[];
    var distribution={};
    for(var i=0;i<EMOTION_SPECTRUM.length;i++){
      distribution[EMOTION_SPECTRUM[i].key]=0;
    }
    for(var i=0;i<active.length;i++){
      var em=detectEmotionSimple(active[i].t||"");
      emotions.push({idx:i,emotion:em,text:(active[i].t||"").substring(0,40)});
      distribution[em]++;
    }
    var dominant="calm";var domCount=0;
    for(var k in distribution){
      if(distribution[k]>domCount){domCount=distribution[k];dominant=k}
    }
    var total=active.length;
    var distList=[];
    for(var i=0;i<EMOTION_SPECTRUM.length;i++){
      var pct=Math.round(distribution[EMOTION_SPECTRUM[i].key]/total*100);
      if(pct>0){
        distList.push({emoji:EMOTION_SPECTRUM[i].emoji,name:EMOTION_SPECTRUM[i].name,color:EMOTION_SPECTRUM[i].color,pct:pct,key:EMOTION_SPECTRUM[i].key});
      }
    }
    distList.sort(function(a,b){return b.pct-a.pct});
    return{
      emotions:emotions,
      distribution:distList,
      dominant:dominant,
      total:total,
      dominantEmoji:EMOTION_SPECTRUM.find(function(e){return e.key===dominant})?EMOTION_SPECTRUM.find(function(e){return e.key===dominant}).emoji:"😌"
    };
  }catch(e){return null}
}
function openSpectrumPanel(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var data=generateEmotionSpectrum();
    var box=$("spectrumOverlay");
    var body=$("spectrumBody");
    if(!box||!body)return;
    if(!data){
      body.innerHTML='<div style="text-align:center;color:#666;padding:40px;font-size:13px">暂无对话数据，开始聊天后再来查看吧～</div>';
      box.className="spectrum-overlay show";
      return;
    }
    var h="";
    // 柱状图
    h+='<div class="spectrum-canvas-box">';
    h+='<div class="spectrum-bar-chart">';
    var maxLen=Math.min(data.emotions.length,30);
    var step=Math.max(1,Math.floor(data.emotions.length/maxLen));
    for(var i=0;i<data.emotions.length;i+=step){
      var em=data.emotions[i];
      var emInfo=EMOTION_SPECTRUM.find(function(e){return e.key===em.emotion})||EMOTION_SPECTRUM[2];
      var height=20+Math.random()*80;
      h+='<div class="spectrum-bar" style="height:'+height+'%;background:linear-gradient(180deg,'+emInfo.color+','+emInfo.color+'55)" title="'+emInfo.emoji+' '+emInfo.name+'"></div>';
    }
    h+='</div>';
    // 图例
    h+='<div class="spectrum-legend">';
    for(var i=0;i<EMOTION_SPECTRUM.length;i++){
      h+='<div class="spectrum-legend-item"><div class="spectrum-legend-dot" style="background:'+EMOTION_SPECTRUM[i].color+'"></div>'+EMOTION_SPECTRUM[i].emoji+' '+EMOTION_SPECTRUM[i].name+'</div>';
    }
    h+='</div>';
    h+='</div>';
    // 摘要
    h+='<div class="spectrum-summary">';
    h+='<div class="spectrum-summary-title">📊 情绪分析报告</div>';
    var dominantInfo=EMOTION_SPECTRUM.find(function(e){return e.key===data.dominant})||EMOTION_SPECTRUM[2];
    h+='<div class="spectrum-summary-text">在共'+data.total+'条对话中，主导情绪是 '+dominantInfo.emoji+' '+dominantInfo.name+'。';
    var summaries={
      happy:"对话氛围积极愉快，充满了正能量。",
      excited:"对话充满激情和活力，互动频率很高。",
      calm:"对话风格平和稳定，像静静流淌的溪水。",
      sad:"对话中有一些忧伤的时刻，但也代表着真实的情感表达。",
      angry:"对话中有些激烈的交流，但冲突也是关系深化的契机。",
      surprised:"对话中充满了惊喜和新鲜感，总能发现意想不到的内容。",
      love:"对话中充满了温暖和爱意，是一段美好的交流。",
      thinking:"对话以深度思考为主，充满了智慧的碰撞。"
    };
    h+=(summaries[data.dominant]||"")+'</div>';
    // 分布
    h+='<div class="spectrum-distribution">';
    for(var i=0;i<data.distribution.length;i++){
      var d=data.distribution[i];
      h+='<div class="spectrum-dist-item">';
      h+='<div class="spectrum-dist-emoji">'+d.emoji+'</div>';
      h+='<div class="spectrum-dist-name">'+d.name+'</div>';
      h+='<div class="spectrum-dist-bar"><div class="spectrum-dist-fill" style="width:'+d.pct+'%;background:'+d.color+'"></div></div>';
      h+='<div class="spectrum-dist-pct">'+d.pct+'%</div>';
      h+='</div>';
    }
    h+='</div>';
    h+='</div>';
    body.innerHTML=h;
    box.className="spectrum-overlay show";
  }catch(e){}
}
function closeSpectrumPanel(){
  try{var box=$("spectrumOverlay");if(box)box.className="spectrum-overlay"}catch(e){}
}

// ==========================================================================
// ===== v3.12.0 对话时光机 =====
// ==========================================================================
var _tmCurrentIdx=-1;
function generateTimemachineData(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(active.length===0)return null;
    // 按天分组
    var days={};
    for(var i=0;i<active.length;i++){
      var d=new Date(active[i].time||Date.now());
      var key=d.getFullYear()+"-"+(d.getMonth()+1)+"-"+d.getDate();
      if(!days[key])days[key]={date:d,messages:[]};
      days[key].messages.push(active[i]);
    }
    var dayList=Object.keys(days).sort();
    var nodes=[];
    for(var i=0;i<dayList.length;i++){
      var d=days[dayList[i]];
      var preview="";
      if(d.messages.length>0){
        preview=(d.messages[0].t||"").substring(0,50);
      }
      nodes.push({
        date:d.date,
        key:dayList[i],
        preview:preview,
        count:d.messages.length,
        messages:d.messages
      });
    }
    return nodes;
  }catch(e){return null}
}
function openTimemachinePanel(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var data=generateTimemachineData();
    var box=$("timemachineOverlay");
    var body=$("timemachineBody");
    if(!box||!body)return;
    if(!data||data.length===0){
      body.innerHTML='<div style="text-align:center;color:#666;padding:40px;font-size:13px">暂无对话记录，开始聊天后可以乘坐时光机回顾～</div>';
      box.className="timemachine-overlay show";
      return;
    }
    var h="";
    // 时间线
    h+='<div class="timemachine-timeline" id="tmTimeline">';
    for(var i=0;i<data.length;i++){
      var node=data[i];
      h+='<div class="timemachine-node'+(i===data.length-1?' active':'')+'" onclick="selectTimemachineNode('+i+')" data-idx="'+i+'">';
      h+='<div class="timemachine-node-date">📅 '+node.date.toLocaleDateString()+' '+["日","一","二","三","四","五","六"][node.date.getDay()]+'</div>';
      h+='<div class="timemachine-node-preview">'+esc(node.preview)+'</div>';
      h+='<div class="timemachine-node-stats">'+node.count+'条消息</div>';
      h+='</div>';
    }
    h+='</div>';
    // 回放区域
    h+='<div class="timemachine-replay" id="tmReplay">';
    h+='<div class="timemachine-replay-empty">点击上方时间节点，查看那天的对话回忆</div>';
    h+='</div>';
    // 控制按钮
    h+='<div class="timemachine-controls">';
    h+='<div class="timemachine-ctrl-btn" onclick="tmPrev()">⬅️ 前一天</div>';
    h+='<div class="timemachine-ctrl-btn" onclick="tmNext()">后一天 ➡️</div>';
    h+='<div class="timemachine-ctrl-btn" onclick="tmJumpToday()">📍 最新</div>';
    h+='</div>';
    body.innerHTML=h;
    box.className="timemachine-overlay show";
    _tmCurrentIdx=data.length-1;
    selectTimemachineNode(_tmCurrentIdx);
  }catch(e){}
}
function selectTimemachineNode(idx){
  try{
    var data=generateTimemachineData();
    if(!data||idx<0||idx>=data.length)return;
    _tmCurrentIdx=idx;
    // 更新节点状态
    var nodes=document.querySelectorAll("#tmTimeline .timemachine-node");
    for(var i=0;i<nodes.length;i++){
      nodes[i].className="timemachine-node"+(i===idx?" active":"");
    }
    // 显示消息
    var replay=$("tmReplay");
    if(!replay)return;
    var node=data[idx];
    var h="";
    h+='<div style="font-size:13px;color:#a78bfa;font-weight:600;margin-bottom:12px">📅 '+node.date.toLocaleDateString()+' 共'+node.count+'条消息</div>';
    for(var i=0;i<Math.min(node.messages.length,20);i++){
      var msg=node.messages[i];
      var sender=msg.r==="me"?"我":(curRole?curRole.name:"AI");
      h+='<div class="timemachine-replay-msg '+msg.r+'"><div class="sender">'+esc(sender)+'</div>'+esc(msg.t||"")+'</div>';
    }
    if(node.messages.length>20){
      h+='<div style="text-align:center;color:#555;font-size:11px;padding:8px">还有'+(node.messages.length-20)+'条消息未显示...</div>';
    }
    replay.innerHTML=h;
    replay.scrollTop=0;
  }catch(e){}
}
function tmPrev(){
  try{if(_tmCurrentIdx>0)selectTimemachineNode(_tmCurrentIdx-1)}catch(e){}
}
function tmNext(){
  try{
    var data=generateTimemachineData();
    if(data&&_tmCurrentIdx<data.length-1)selectTimemachineNode(_tmCurrentIdx+1);
  }catch(e){}
}
function tmJumpToday(){
  try{
    var data=generateTimemachineData();
    if(data)selectTimemachineNode(data.length-1);
  }catch(e){}
}
function closeTimemachinePanel(){
  try{var box=$("timemachineOverlay");if(box)box.className="timemachine-overlay"}catch(e){}
}

