// ===== v3.12.0 AI角色关系图谱 =====
// ==========================================================================
function generateRelationGraph(){
  try{
    var roles=getAllRoles();
    if(!roles||roles.length===0)return null;
    var nodes=[];
    var links=[];
    for(var i=0;i<roles.length;i++){
      var r=roles[i];
      var ms=msgs[r.id]||[];
      var active=ms.filter(function(m){return !m.rolled});
      var totalMsg=active.length;
      nodes.push({
        id:r.id,
        name:r.name,
        icon:r.avatar||"✨",
        msgCount:totalMsg,
        x:50+40*Math.cos(i*2*Math.PI/roles.length),
        y:50+40*Math.sin(i*2*Math.PI/roles.length),
        r:16+Math.min(totalMsg/10,14)
      });
    }
    // 生成连接：按消息量
    for(var i=0;i<nodes.length;i++){
      for(var j=i+1;j<nodes.length;j++){
        var strength=Math.min(nodes[i].msgCount,nodes[j].msgCount);
        if(strength>0){
          links.push({from:i,to:j,strength:Math.min(strength,50)});
        }
      }
    }
    links.sort(function(a,b){return b.strength-a.strength});
    links=links.slice(0,8);
    // 统计信息
    var totalMsgs=0;
    var maxMsgs=0;
    var topRole=null;
    for(var i=0;i<nodes.length;i++){
      totalMsgs+=nodes[i].msgCount;
      if(nodes[i].msgCount>maxMsgs){maxMsgs=nodes[i].msgCount;topRole=nodes[i]}
    }
    return{nodes:nodes,links:links,totalRoles:nodes.length,totalMsgs:totalMsgs,topRole:topRole};
  }catch(e){return null}
}
function openRelationPanel(){
  try{
    var data=generateRelationGraph();
    var box=$("relationOverlay");
    var body=$("relationBody");
    if(!box||!body)return;
    if(!data||data.nodes.length===0){
      body.innerHTML='<div style="text-align:center;color:#666;padding:40px;font-size:13px">暂无角色数据，创建角色后可以查看关系图谱～</div>';
      box.className="relation-overlay show";
      return;
    }
    var h="";
    // SVG图谱
    h+='<div class="relation-canvas-box">';
    h+='<svg class="relation-svg" viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet">';
    // 连接线
    for(var i=0;i<data.links.length;i++){
      var link=data.links[i];
      var from=data.nodes[link.from];var to=data.nodes[link.to];
      if(!from||!to)continue;
      var opacity=0.05+link.strength/100*0.2;
      h+='<line x1="'+from.x+'" y1="'+from.y+'" x2="'+to.x+'" y2="'+to.y+'" stroke="rgba(124,92,252,'+opacity+')" stroke-width="'+(0.3+link.strength/100*0.8)+'"/>';
    }
    // 节点
    for(var i=0;i<data.nodes.length;i++){
      var n=data.nodes[i];
      h+='<circle class="relation-node-circle" cx="'+n.x+'" cy="'+n.y+'" r="'+n.r+'" fill="rgba(124,92,252,0.12)" stroke="rgba(124,92,252,0.3)" stroke-width="0.5"/>';
      h+='<text x="'+n.x+'" y="'+(n.y+1)+'" text-anchor="middle" font-size="'+(n.r*0.8)+'" fill="#e0d4ff">'+n.icon+'</text>';
      h+='<text x="'+n.x+'" y="'+(n.y+n.r+3)+'" text-anchor="middle" font-size="2.5" fill="#888">'+esc(n.name.substring(0,6))+'</text>';
    }
    h+='</svg>';
    h+='</div>';
    // 统计信息
    h+='<div class="relation-info">';
    h+='<div class="relation-info-title">📊 角色关系概览</div>';
    h+='<div class="relation-info-grid">';
    h+='<div class="relation-info-item"><div class="relation-info-icon">👥</div><div class="relation-info-label">角色总数</div><div class="relation-info-val">'+data.totalRoles+'</div></div>';
    h+='<div class="relation-info-item"><div class="relation-info-icon">💬</div><div class="relation-info-label">总消息数</div><div class="relation-info-val">'+data.totalMsgs+'</div></div>';
    h+='<div class="relation-info-item"><div class="relation-info-icon">🏆</div><div class="relation-info-label">最活跃</div><div class="relation-info-val">'+(data.topRole?esc(data.topRole.name.substring(0,6)):"-")+'</div></div>';
    h+='<div class="relation-info-item"><div class="relation-info-icon">🔗</div><div class="relation-info-label">关系连接</div><div class="relation-info-val">'+data.links.length+'</div></div>';
    h+='</div>';
    h+='</div>';
    // 角色列表
    h+='<div style="font-size:13px;color:#a78bfa;font-weight:600;margin-bottom:10px">角色活跃度排行</div>';
    var sortedNodes=data.nodes.slice().sort(function(a,b){return b.msgCount-a.msgCount});
    for(var i=0;i<Math.min(sortedNodes.length,10);i++){
      var n=sortedNodes[i];
      var pct=n.msgCount>0&&data.totalMsgs>0?Math.round(n.msgCount/data.totalMsgs*100):0;
      h+='<div class="relation-list-item">';
      h+='<div class="relation-list-avatar">'+n.icon+'</div>';
      h+='<div class="relation-list-info"><div class="relation-list-name">'+esc(n.name)+'</div><div class="relation-list-desc">'+n.msgCount+'条消息</div></div>';
      h+='<div class="relation-list-bar"><div class="relation-list-fill" style="width:'+pct+'%"></div></div>';
      h+='</div>';
    }
    body.innerHTML=h;
    box.className="relation-overlay show";
  }catch(e){}
}
function closeRelationPanel(){
  try{var box=$("relationOverlay");if(box)box.className="relation-overlay"}catch(e){}
}

