var STORY_THEMES=[
  {id:"fantasy",name:"🏰 奇幻冒险",prompt:"在一个充满魔法的世界里"},
  {id:"scifi",name:"🚀 科幻未来",prompt:"在2250年的太空殖民地"},
  {id:"mystery",name:"🔍 悬疑推理",prompt:"一个雨夜，神秘的信封出现在门口"},
  {id:"romance",name:"💕 浪漫故事",prompt:"春天的樱花树下"},
  {id:"horror",name:"👻 恐怖惊悚",prompt:"深夜的老旧公寓里"},
  {id:"wuxia",name:"⚔️ 武侠江湖",prompt:"江湖风云再起"},
  {id:"fairy",name:"🧚 童话寓言",prompt:"很久很久以前"},
  {id:"daily",name:"🏠 日常故事",prompt:"一个普通的周一早晨"}
];
var _storyChain={theme:null,paragraphs:[],rounds:0};
function openStorychainPanel(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var box=$("storychainOverlay");
    var body=$("storychainBody");
    if(!box||!body)return;
    // 恢复已保存的故事
    var saved=lsGet("storychain_"+(curRole?curRole.id:""));
    if(saved&&typeof saved==="object"){
      _storyChain=saved;
    }
    var h="";
    // 主题选择
    h+='<div class="storychain-theme-box">';
    h+='<div class="storychain-theme-title">🎨 选择故事主题</div>';
    h+='<div class="storychain-theme-btns">';
    for(var i=0;i<STORY_THEMES.length;i++){
      h+='<div class="storychain-theme-btn'+(_storyChain.theme===STORY_THEMES[i].id?' active':'')+'" onclick="selectStoryTheme(\''+STORY_THEMES[i].id+'\')">'+STORY_THEMES[i].name+'</div>';
    }
    h+='</div>';
    h+='</div>';
    // 统计
    h+='<div class="storychain-stats">';
    h+='<div class="storychain-stat"><div class="storychain-stat-num">'+_storyChain.rounds+'</div><div class="storychain-stat-label">接龙轮数</div></div>';
    h+='<div class="storychain-stat"><div class="storychain-stat-num">'+_storyChain.paragraphs.length+'</div><div class="storychain-stat-label">段落总数</div></div>';
    h+='<div class="storychain-stat"><div class="storychain-stat-num">'+(_storyChain.paragraphs.reduce(function(s,p){return s+(p.text||"").length},0))+'</div><div class="storychain-stat-label">总字数</div></div>';
    h+='</div>';
    // 故事内容
    h+='<div class="storychain-story" id="storyChainStory">';
    if(_storyChain.paragraphs.length===0){
      h+='<div class="storychain-empty">选择主题后，输入第一段故事开始接龙吧～\n你和AI角色将轮流续写故事。</div>';
    }else{
      for(var i=0;i<_storyChain.paragraphs.length;i++){
        var p=_storyChain.paragraphs[i];
        h+='<div class="storychain-paragraph '+(p.who==="me"?'me-para':'ai-para')+'">'+esc(p.text)+'</div>';
      }
    }
    h+='</div>';
    // 输入框
    h+='<div class="storychain-input-box">';
    h+='<textarea class="storychain-input" id="storyChainInput" placeholder="'+(_storyChain.paragraphs.length===0?'输入故事的开头...':'续写下一段故事...')+'" rows="2"></textarea>';
    h+='<div class="storychain-send-btn" onclick="sendStoryChain()">➤</div>';
    h+='</div>';
    // 重置按钮
    if(_storyChain.paragraphs.length>0){
      h+='<div style="text-align:center"><div class="timemachine-ctrl-btn" style="max-width:200px;margin:0 auto" onclick="resetStoryChain()">🗑️ 重新开始</div></div>';
    }
    body.innerHTML=h;
    box.className="storychain-overlay show";
  }catch(e){}
}
function selectStoryTheme(themeId){
  try{
    _storyChain.theme=themeId;
    var theme=STORY_THEMES.find(function(t){return t.id===themeId});
    if(theme&&_storyChain.paragraphs.length===0){
      // 自动添加AI开头
      _storyChain.paragraphs.push({who:"ai",text:theme.prompt+"，故事开始了..."});
    }
    saveStoryChain();
    openStorychainPanel();
  }catch(e){}
}
function sendStoryChain(){
  try{
    var input=$("storyChainInput");
    if(!input||!input.value.trim())return;
    var text=input.value.trim();
    _storyChain.paragraphs.push({who:"me",text:text});
    _storyChain.rounds++;
    input.value="";
    input.placeholder="AI正在续写...";
    input.disabled=true;
    saveStoryChain();
    // 更新显示
    var storyBox=$("storyChainStory");
    if(storyBox){
      var h="";
      for(var i=0;i<_storyChain.paragraphs.length;i++){
        var p=_storyChain.paragraphs[i];
        h+='<div class="storychain-paragraph '+(p.who==="me"?'me-para':'ai-para')+'">'+esc(p.text)+'</div>';
      }
      h+='<div class="storychain-paragraph ai-para" style="opacity:.5">✍️ AI正在思考下一句...</div>';
      storyBox.innerHTML=h;
      storyBox.scrollTop=storyBox.scrollHeight;
    }
    // 调用AI续写
    var context="";
    for(var i=0;i<_storyChain.paragraphs.length;i++){
      context+=_storyChain.paragraphs[i].text+"\n";
    }
    var theme=STORY_THEMES.find(function(t){return t.id===_storyChain.theme});
    var prompt="我们正在一起写一个接龙故事。主题："+(theme?theme.name:"自由创作")+"。\n\n已有的故事内容：\n"+context+"\n\n请续写故事的下一段（50-100字），保持风格一致，推动情节发展。只输出故事内容，不要加任何解释：";
    if(typeof callAI==="function"){
      callAI(prompt,function(reply){
        try{
          _storyChain.paragraphs.push({who:"ai",text:reply||"（故事继续...）"});
          _storyChain.rounds++;
          if(_storyChain.rounds>=5)lsSet("achv_storyRounds",_storyChain.rounds);
          saveStoryChain();
          openStorychainPanel();
        }catch(e){}
      },"");
    }else{
      // 没有AI可用，生成模板回复
      var templates=[
        "就在这时，意想不到的事情发生了...",
        "空气中弥漫着紧张的气氛，一切都变得不同了。",
        "时间仿佛静止了一瞬，然后一切都不一样了。",
        "远处的光芒越来越近，带着某种不可名状的力量。",
        "一个声音从虚空中传来，回荡在每个人的心头。"
      ];
      _storyChain.paragraphs.push({who:"ai",text:templates[Math.floor(Math.random()*templates.length)]});
      _storyChain.rounds++;
      saveStoryChain();
      openStorychainPanel();
    }
  }catch(e){}
}
function saveStoryChain(){
  try{
    if(curRole)lsSet("storychain_"+curRole.id,_storyChain);
  }catch(e){}
}
function resetStoryChain(){
  try{
    _storyChain={theme:null,paragraphs:[],rounds:0};
    if(curRole)lsSet("storychain_"+curRole.id,_storyChain);
    openStorychainPanel();
  }catch(e){}
}
function closeStorychainPanel(){
  try{var box=$("storychainOverlay");if(box)box.className="storychain-overlay"}catch(e){}
}

