// ===== v3.12.0 对话天气预报 =====
// ==========================================================================
var WEATHER_TYPES=[
  {key:"sunny",icon:"☀️",name:"晴朗",temp:"28°",desc:"阳光明媚，适合愉快聊天",mood:"happy",color:"#fcb85c"},
  {key:"cloudy",icon:"⛅",name:"多云",temp:"22°",desc:"偶尔有云，情绪多变",mood:"calm",color:"#a78bfa"},
  {key:"rainy",icon:"🌧️",name:"小雨",temp:"15°",desc:"细雨绵绵，适合深入交流",mood:"sad",color:"#5cb4fc"},
  {key:"storm",icon:"⛈️",name:"雷雨",temp:"12°",desc:"电闪雷鸣，充满激情",mood:"excited",color:"#fc6b6b"},
  {key:"snow",icon:"❄️",name:"飘雪",temp:"-2°",desc:"白雪皑皑，纯洁宁静",mood:"calm",color:"#5cfca8"},
  {key:"foggy",icon:"🌫️",name:"雾霭",temp:"10°",desc:"朦胧神秘，适合冥想",mood:"thinking",color:"#7c8cf0"},
  {key:"rainbow",icon:"🌈",name:"彩虹",temp:"25°",desc:"雨过天晴，充满希望",mood:"love",color:"#fc5c8a"},
  {key:"starry",icon:"星空",name:"星空",temp:"18°",desc:"繁星点点，浪漫夜晚",mood:"love",color:"#a78bfa"}
];
function generateConversationWeather(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(active.length===0){
      return{current:WEATHER_TYPES[0],forecast:[],details:{},suggestion:"开始你的第一段对话，让天气变得丰富起来吧！"};
    }
    // 分析最近消息的情绪
    var recentMsgs=active.slice(-10);
    var emotions=[];
    for(var i=0;i<recentMsgs.length;i++){
      emotions.push(detectEmotionSimple(recentMsgs[i].t||""));
    }
    // 计算主导情绪
    var emCount={};
    for(var i=0;i<emotions.length;i++){
      emCount[emotions[i]]=(emCount[emotions[i]]||0)+1;
    }
    var dominantEm="calm";var domCount=0;
    for(var k in emCount){
      if(emCount[k]>domCount){domCount=emCount[k];dominantEm=k}
    }
    // 映射情绪到天气
    var moodToWeather={
      happy:"sunny",excited:"storm",calm:"cloudy",sad:"rainy",
      angry:"storm",surprised:"rainbow",love:"starry",thinking:"foggy"
    };
    var currentKey=moodToWeather[dominantEm]||"cloudy";
    var current=WEATHER_TYPES.find(function(w){return w.key===currentKey})||WEATHER_TYPES[1];
    // 生成3天预报
    var forecast=[];
    var allEmotions=[];
    for(var i=0;i<active.length;i++){
      allEmotions.push(detectEmotionSimple(active[i].t||""));
    }
    for(var i=0;i<3;i++){
      var idx=Math.floor(allEmotions.length*(0.3+i*0.25))%allEmotions.length;
      var em=allEmotions[idx]||"calm";
      var wk=moodToWeather[em]||"cloudy";
      var w=WEATHER_TYPES.find(function(x){return x.key===wk})||WEATHER_TYPES[1];
      forecast.push({
        day:["明天","后天","大后天"][i],
        icon:w.icon,
        temp:w.temp,
        desc:w.name,
        weatherKey:wk
      });
    }
    // 详细数据
    var avgLen=0;
    for(var i=0;i<recentMsgs.length;i++){
      avgLen+=(recentMsgs[i].t||"").length;
    }
    avgLen=Math.round(avgLen/Math.max(recentMsgs.length,1));
    var responseRate=0;
    var myMsgs=recentMsgs.filter(function(m){return m.r==="me"});
    var aiMsgs=recentMsgs.filter(function(m){return m.r!=="me"});
    responseRate=myMsgs.length>0?Math.round(aiMsgs.length/myMsgs.length*100):0;
    var details={
      avgLen:avgLen,
      responseRate:Math.min(responseRate,100),
      totalMsgs:active.length,
      recentMsgs:recentMsgs.length,
      emotionVariety:Object.keys(emCount).length,
      chatTemp:Math.round(20+domCount/recentMsgs.length*15)+"°"
    };
    // 建议
    var suggestions={
      sunny:"☀️ 今天是对话的好日子！氛围轻松愉快，适合聊聊开心的话题，分享生活中的趣事。",
      cloudy:"⛅ 情绪如同多云的天气，时而明朗时而沉静。适合进行一些有深度的对话，但不要太沉重。",
      rainy:"🌧️ 对话带着一丝忧伤的气息。可以聊一些感性的话题，或者互相安慰和鼓励。",
      storm:"⛈️ 对话充满激情和能量！注意控制情绪，享受这种充满活力的交流。",
      snow:"❄️ 宁静如雪的对话氛围。适合慢慢聊，享受安静的陪伴时光。",
      foggy:"🌫️ 对话带着神秘的雾气。适合探讨哲学问题，或者分享内心深处的想法。",
      rainbow:"🌈 对话充满了惊喜和新鲜感！这是一个适合发现新话题的好时机。",
      starry:"🌟 浪漫的星空下，适合聊些温柔的话题，享受美好的对话时光。"
    };
    return{
      current:current,
      forecast:forecast,
      details:details,
      suggestion:suggestions[currentKey]||"享受每一段对话时光。"
    };
  }catch(e){return null}
}
function openWeatherPanel(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var data=generateConversationWeather();
    var box=$("weatherOverlay");
    var body=$("weatherBody");
    if(!box||!body)return;
    if(!data){
      body.innerHTML='<div style="text-align:center;color:#666;padding:40px;font-size:13px">暂无对话数据，开始聊天后可以查看对话天气预报～</div>';
      box.className="weather-overlay show";
      return;
    }
    var h="";
    // 当前天气
    h+='<div class="weather-current">';
    h+='<div class="weather-current-icon">'+data.current.icon+'</div>';
    h+='<div class="weather-current-temp">'+data.details.chatTemp+'</div>';
    h+='<div class="weather-current-desc">'+data.current.name+' · '+data.current.desc+'</div>';
    h+='<div class="weather-current-mood">基于最近'+data.details.recentMsgs+'条对话分析</div>';
    h+='</div>';
    // 3天预报
    h+='<div class="weather-forecast">';
    for(var i=0;i<data.forecast.length;i++){
      var f=data.forecast[i];
      h+='<div class="weather-forecast-card">';
      h+='<div class="weather-forecast-day">'+f.day+'</div>';
      h+='<div class="weather-forecast-icon">'+f.icon+'</div>';
      h+='<div class="weather-forecast-temp">'+f.temp+'</div>';
      h+='<div class="weather-forecast-desc">'+f.desc+'</div>';
      h+='</div>';
    }
    h+='</div>';
    // 详细数据
    h+='<div class="weather-detail">';
    h+='<div class="weather-detail-title">📋 对话气象数据</div>';
    h+='<div class="weather-detail-row"><div class="weather-detail-label">平均消息长度</div><div class="weather-detail-val">'+data.details.avgLen+' 字</div></div>';
    h+='<div class="weather-detail-row"><div class="weather-detail-label">互动响应率</div><div class="weather-detail-val">'+data.details.responseRate+'%</div></div>';
    h+='<div class="weather-detail-row"><div class="weather-detail-label">总消息数</div><div class="weather-detail-val">'+data.details.totalMsgs+' 条</div></div>';
    h+='<div class="weather-detail-row"><div class="weather-detail-label">情绪多样性</div><div class="weather-detail-val">'+data.details.emotionVariety+' 种</div></div>';
    h+='</div>';
    // 建议
    h+='<div class="weather-suggestion">';
    h+='<div class="weather-suggestion-title">💡 对话建议</div>';
    h+='<div class="weather-suggestion-text">'+data.suggestion+'</div>';
    h+='</div>';
    body.innerHTML=h;
    box.className="weather-overlay show";
    lsSet("achv_weatherView",true);
  }catch(e){}
}
function closeWeatherPanel(){
  try{var box=$("weatherOverlay");if(box)box.className="weather-overlay"}catch(e){}
}

