function initV312Features(){
  try{
    // 注入功能入口到角色面板
    setTimeout(function(){
      try{
        var charPanel=$("charPanelBox");
        if(charPanel){
          var existingActions=charPanel.querySelector(".cp-actions");
          if(existingActions){
            var existing=charPanel.querySelector("[data-v312]");
            if(!existing){
              var newBtns=document.createElement("div");
              newBtns.className="cp-actions";
              newBtns.setAttribute("data-v312","1");
              newBtns.style.marginTop="4px";
              newBtns.innerHTML=
                '<div class="cp-act-btn" onclick="openSpectrumPanel();closeCharPanel(event)">🌈光谱</div>'+
                '<div class="cp-act-btn" onclick="openTimemachinePanel();closeCharPanel(event)">⏰时光机</div>'+
                '<div class="cp-act-btn" onclick="openRelationPanel();closeCharPanel(event)">🕸️图谱</div>'+
                '<div class="cp-act-btn" onclick="openHalloffamePanel();closeCharPanel(event)">🏆殿堂</div>'+
                '<div class="cp-act-btn" onclick="openStorychainPanel();closeCharPanel(event)">📖接龙</div>'+
                '<div class="cp-act-btn" onclick="openWeatherPanel();closeCharPanel(event)">🌤️天气</div>';
              existingActions.parentNode.insertBefore(newBtns,existingActions.nextSibling);
            }
          }
        }
      }catch(e){}
    },3500);
    // 拦截消息发送，标记成就
    var origSendV312=window.sendMsg;
    if(origSendV312&&!window._v312Hooked){
      window._v312Hooked=true;
      window.sendMsg=function(){
        try{
          var hour=new Date().getHours();
          if(hour>=0&&hour<=4)lsSet("achv_nightOwl",true);
          if(hour>=5&&hour<=7)lsSet("achv_earlyBird",true);
          // 检查深夜聊天成就
          if(curRole&&hour>=0&&hour<=4){
            var ms=msgs[curRole.id]||[];
            var nightMsgs=ms.filter(function(m){
              var d=new Date(m.time||Date.now());
              return d.getHours()>=0&&d.getHours()<=4&&!m.rolled;
            }).length;
            if(nightMsgs>=20)lsSet("achv_deepNight20",true);
          }
        }catch(e){}
        return origSendV312.apply(this,arguments);
      };
    }
    // 标记其他成就
    var origOpenTarot=window.openTarotPanel;
    if(origOpenTarot){
      window.openTarotPanel=function(){
        try{lsSet("achv_tarotDivined",true)}catch(e){}
        return origOpenTarot.apply(this,arguments);
      };
    }
    var origOpenMemoir=window.openMemoirPanel;
    if(origOpenMemoir){
      window.openMemoirPanel=function(){
        try{lsSet("achv_memoirGen",true)}catch(e){}
        return origOpenMemoir.apply(this,arguments);
      };
    }
    var origOpenConstellation=window.openConstellationPanel;
    if(origOpenConstellation){
      window.openConstellationPanel=function(){
        try{lsSet("achv_constellation",true)}catch(e){}
        return origOpenConstellation.apply(this,arguments);
      };
    }
  }catch(e){}
}
// 延迟初始化v3.12功能
setTimeout(function(){try{initV312Features()}catch(e){}},5500);

