// --- AI 语音助手 ---
var VOICE_RECOGNIZING=false;
var VOICE_RESULT="";
var VOICE_LANG="zh-CN";
function openVoiceAssistant(){
  var el=$("voiceOverlay");
  if(!el)return;
  el.style.display="flex";
  VOICE_RECOGNIZING=false;
  var btn=$("voiceBtn");if(btn){btn.textContent="🎤";btn.className="voice-btn"}
  var st=$("voiceStatus");if(st)st.textContent="点击麦克风开始说话";
  var r=$("voiceResult");if(r)r.style.display="none";
}
function closeVoiceAssistant(){
  var el=$("voiceOverlay");if(el)el.style.display="none";
  if(VOICE_RECOGNIZING)stopVoiceRecognition();
}
function toggleVoiceRecognition(){
  if(VOICE_RECOGNIZING){stopVoiceRecognition();return}
  startVoiceRecognition();
}
function startVoiceRecognition(){
  var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){showToast("当前浏览器不支持语音识别");return}
  var recognition=new SR();
  recognition.lang=VOICE_LANG;
  recognition.continuous=false;
  recognition.interimResults=true;
  VOICE_RECOGNIZING=true;
  var btn=$("voiceBtn");if(btn){btn.textContent="🔴";btn.className="voice-btn recording"}
  var st=$("voiceStatus");if(st)st.textContent="正在聆听...";
  recognition.onresult=function(e){
    var t="";
    for(var i=e.resultIndex;i<e.results.length;i++)t+=e.results[i][0].transcript;
    VOICE_RESULT=t;
    var r=$("voiceResult");if(r){r.style.display="block";r.textContent="▍"+t}
  };
  recognition.onend=function(){
    VOICE_RECOGNIZING=false;
    var btn=$("voiceBtn");if(btn){btn.textContent="🎤";btn.className="voice-btn"}
    var st=$("voiceStatus");if(st)st.textContent=VOICE_RESULT?"识别完成":"未检测到语音，点击重试";
    if(VOICE_RESULT){processVoiceResult(VOICE_RESULT)}
  };
  recognition.onerror=function(e){
    VOICE_RECOGNIZING=false;
    var btn=$("voiceBtn");if(btn){btn.textContent="🎤";btn.className="voice-btn"}
    var st=$("voiceStatus");if(st)st.textContent="错误: "+e.error;
    showToast("语音识别错误: "+e.error);
  };
  window._voiceRec=recognition;
  try{recognition.start()}catch(e){}
}
function stopVoiceRecognition(){
  if(window._voiceRec){try{window._voiceRec.stop()}catch(e){}window._voiceRec=null}
  VOICE_RECOGNIZING=false;
  var btn=$("voiceBtn");if(btn){btn.textContent="🎤";btn.className="voice-btn"}
}
function setVoiceLang(lang){
  VOICE_LANG=lang;
  document.querySelectorAll(".voice-lang-btn").forEach(function(el){el.className="voice-lang-btn"+(el.dataset.lang===lang?" active":"")});
}
function processVoiceResult(text){
  if(!text||!text.trim())return;
  var r=$("voiceResult");if(r)r.textContent="📝 "+text;
  var input=document.querySelector(".chat-view .input-area textarea");
  if(input){input.value=text;sendMessage()}
}

// --- 智能备忘 ---
var SMART_NOTES=[];
var NOTE_CATS=[{id:"todo",icon:"✅",label:"待办"},{id:"idea",icon:"💡",label:"灵感"},{id:"note",icon:"📝",label:"笔记"},{id:"reminder",icon:"⏰",label:"提醒"}];
function initSmartNotes(){
  try{SMART_NOTES=JSON.parse(lsGet("huanyu_notes")||"[]")}catch(e){SMART_NOTES=[]}
}
function saveSmartNotes(){lsSet("huanyu_notes",JSON.stringify(SMART_NOTES))}
function openSmartNotes(){
  initSmartNotes();
  var el=$("smartnoteOverlay");if(el)el.style.display="flex";
  renderSmartNotes();
}
function closeSmartNotes(){var el=$("smartnoteOverlay");if(el)el.style.display="none"}
function addSmartNote(){
  var input=$("smartnoteInput");if(!input)return;
  var text=input.value.trim();
  if(!text){showToast("请输入内容");return}
  var catEl=document.querySelector(".smartnote-tool.active");
  var catId=catEl?catEl.dataset.cat:"todo";
  SMART_NOTES.unshift({id:Date.now()+"",text:text,cat:catId,time:new Date().toLocaleString("zh-CN"),done:false});
  saveSmartNotes();
  input.value="";
  renderSmartNotes();
  showToast("✅ 已保存");
}
function renderSmartNotes(){
  var el=$("smartnoteList");if(!el)return;
  if(SMART_NOTES.length===0){el.innerHTML='<div class="smartnote-empty">📋 还没有备忘，快来记录吧</div>';return}
  var html="";
  for(var i=0;i<SMART_NOTES.length;i++){
    var n=SMART_NOTES[i];
    var icon=NOTE_CATS.find(function(c){return c.id===n.cat})||{icon:"📝"};
    html+='<div class="smartnote-item'+(n.done?" done":"")+'"><div class="sn-icon">'+icon.icon+'</div><div class="sn-content"><div class="sn-text">'+esc(n.text)+'</div><div class="sn-time">'+n.time+'</div></div><div class="sn-check'+(n.done?" done":"")+'" onclick="toggleNoteDone('+i+')">'+(n.done?"✓":"")+'</div><div class="sn-del" onclick="deleteNote('+i+')">✕</div></div>';
  }
  el.innerHTML=html;
}
function toggleNoteDone(idx){SMART_NOTES[idx].done=!SMART_NOTES[idx].done;saveSmartNotes();renderSmartNotes()}
function deleteNote(idx){SMART_NOTES.splice(idx,1);saveSmartNotes();renderSmartNotes()}
function setNoteCat(cat,el){
  document.querySelectorAll(".smartnote-tool").forEach(function(e){e.className="smartnote-tool"});
  el.className="smartnote-tool active";
}

