  var today=new Date();
  var dateStr=today.getFullYear()+"年"+(today.getMonth()+1)+"月"+today.getDate()+"日";
  var html='<div class="horoscope-card"><div class="hc-date">📅 '+dateStr+'</div><div class="hc-sign">'+sign.icon+' '+sign.name+'</div><div class="horoscope-rating">'+stars.split("").map(function(s){return s==="★"?'<span class="hr-star on">★</span>':'<span class="hr-star">☆</span>'}).join("")+'</div><div class="hc-lucky"><div class="hc-lucky-item"><div class="hl-label">幸运数字</div><div class="hl-value">'+luckNum+'</div></div><div class="hc-lucky-item"><div class="hl-label">幸运颜色</div><div class="hl-value">'+luckyColor+'</div></div><div class="hc-lucky-item"><div class="hl-label">幸运物</div><div class="hl-value">'+luckyItem+'</div></div></div><div class="hc-text">'+texts[fi]+'</div></div>';
