var QUIZ_STATE={};
var QUIZ_QUESTIONS={general:[{q:"地球上最大的海洋是？",opts:["大西洋","太平洋","印度洋","北冰洋"],ans:1},{q:"光年是什么单位？",opts:["时间","速度","距离","亮度"],ans:2},{q:"人体最大的器官是？",opts:["心脏","肝脏","皮肤","大脑"],ans:2},{q:"太阳系中最大的行星是？",opts:["土星","木星","天王星","海王星"],ans:1},{q:"水的化学式是？",opts:["CO2","H2O","NaCl","O2"],ans:1},{q:"中国最长的河流是？",opts:["黄河","长江","珠江","淮河"],ans:1},{q:"一年有多少天？",opts:["360","365","366","370"],ans:1},{q:"声音在什么介质中传播最快？",opts:["空气","水","固体","真空"],ans:2},{q:"世界上最长的城墙是？",opts:["柏林墙","万里长城","哈德良长城","罗马城墙"],ans:1},{q:"人体有多少块骨骼？",opts:["106","206","306","406"],ans:1}],science:[{q:"原子的组成部分不包括？",opts:["质子","中子","电子","分子"],ans:3},{q:"光速约为多少？",opts:["3万km/s","30万km/s","300万km/s","3000万km/s"],ans:1},{q:"DNA的双螺旋结构是谁发现的？",opts:["达尔文","爱因斯坦","沃森和克里克","牛顿"],ans:2},{q:"地球的卫星是？",opts:["太阳","火星","月球","金星"],ans:2},{q:"绝对零度是多少？",opts:["-100°C","-173°C","-273.15°C","-373°C"],ans:2}],history:[{q:"中国的四大发明不包括？",opts:["造纸术","指南针","火药","瓷器"],ans:3},{q:"第一次世界大战爆发年份？",opts:["1912","1914","1916","1918"],ans:1},{q:"秦始皇统一六国在公元前？",opts:["221年","331年","441年","551年"],ans:0},{q:"文艺复兴起源于哪个国家？",opts:["英国","法国","意大利","德国"],ans:2},{q:"人类第一次登月是？",opts:["1965","1969","1972","1975"],ans:1}],tech:[{q:"互联网的发明者是？",opts:["比尔盖茨","蒂姆·伯纳斯-李","史蒂夫·乔布斯","马克·扎克伯格"],ans:1},{q:"Python的作者是？",opts:["Guido van Rossum","Brendan Eich","James Gosling","Dennis Ritchie"],ans:0},{q:"世界上第一个程序员是？",opts:["图灵","Ada Lovelace","冯·诺依曼","巴贝奇"],ans:1},{q:"Linux系统的创始人？",opts:["Richard Stallman","Linus Torvalds","Ken Thompson","Andrew Tanenbaum"],ans:1},{q:"AI一词最早由谁提出？",opts:["图灵","McCarthy","Minsky","Simon"],ans:1}]};
function openQuiz(){
  QUIZ_STATE={phase:"select",score:0,total:0,idx:0,cat:"general",questions:[]};
  var el=$("quizOverlay");if(el)el.style.display="flex";
  renderQuiz();
}
function closeQuiz(){var el=$("quizOverlay");if(el)el.style.display="none"}
function renderQuiz(){
  if(QUIZ_STATE.phase==="select")renderQuizSelect();
  else if(QUIZ_STATE.phase==="playing")renderQuizQuestion();
  else if(QUIZ_STATE.phase==="result")renderQuizResult();
}
function renderQuizSelect(){
  var el=$("quizBody");if(!el)return;
  el.innerHTML='<div style="text-align:center;width:100%"><h2 style="color:#e0d4ff;margin:20px 0 8px;font-size:20px">🧠 知识问答</h2><p style="color:#888;font-size:13px;margin-bottom:20px">选择分类开始挑战</p><div class="quiz-cat-select"><div class="quiz-cat-btn" onclick="setQuizCat(&#39;general&#39;)"><div style="font-size:24px;margin-bottom:4px">🌍</div><div style="font-size:12px;color:#888">综合</div><div style="font-size:10px;color:#555;margin-top:4px">百科知识</div></div><div class="quiz-cat-btn" onclick="setQuizCat(&#39;science&#39;)"><div style="font-size:24px;margin-bottom:4px">🔬</div><div style="font-size:12px;color:#888">科学</div><div style="font-size:10px;color:#555;margin-top:4px">自然科学</div></div><div class="quiz-cat-btn" onclick="setQuizCat(&#39;history&#39;)"><div style="font-size:24px;margin-bottom:4px">📜</div><div style="font-size:12px;color:#888">历史</div><div style="font-size:10px;color:#555;margin-top:4px">人文历史</div></div><div class="quiz-cat-btn" onclick="setQuizCat(&#39;tech&#39;)"><div style="font-size:24px;margin-bottom:4px">💻</div><div style="font-size:12px;color:#888">科技</div><div style="font-size:10px;color:#555;margin-top:4px">科技前沿</div></div></div><button class="quiz-start-btn" onclick="startQuiz()">开始答题 🚀</button></div>';
}
function setQuizCat(cat){
  QUIZ_STATE.cat=cat;
  document.querySelectorAll(".quiz-cat-btn").forEach(function(e){e.classList.remove("selected")});
  var btns=document.querySelectorAll(".quiz-cat-btn");
  var idx=["general","science","history","tech"].indexOf(cat);
  if(btns[idx])btns[idx].classList.add("selected");
}
function startQuiz(){
  var qs=QUIZ_QUESTIONS[QUIZ_STATE.cat]||QUIZ_QUESTIONS.general;
  QUIZ_STATE.questions=qs.slice().sort(function(){return Math.random()-.5}).slice(0,5);
  QUIZ_STATE.phase="playing";QUIZ_STATE.idx=0;QUIZ_STATE.score=0;
  renderQuiz();
}
function renderQuizQuestion(){
  var qs=QUIZ_STATE.questions,idx=QUIZ_STATE.idx;
  if(idx>=qs.length){QUIZ_STATE.phase="result";renderQuizResult();return}
  var q=qs[idx],total=qs.length,progress=(idx/total*100);
  var el=$("quizBody");if(!el)return;
  el.innerHTML='<div style="width:100%;max-width:360px"><div class="quiz-score">第 '+(idx+1)+'/'+total+' 题 · 得分: '+QUIZ_STATE.score+'</div><div class="story-progress" style="margin-bottom:12px"><div class="story-progress-bar" style="width:'+progress+'%"></div></div><div class="quiz-question"><div class="quiz-q-text">'+q.q+'</div><div class="quiz-options">'+q.opts.map(function(o,i){return '<div class="quiz-option" onclick="answerQuiz('+i+',this)">'+String.fromCharCode(65+i)+'. '+o+'</div>'}).join("")+'</div></div></div>';
}
function answerQuiz(idx,el){
  var q=QUIZ_STATE.questions[QUIZ_STATE.idx];
  var opts=el.parentElement.querySelectorAll(".quiz-option");
  opts.forEach(function(o){o.classList.add("disabled")});
  if(idx===q.ans){el.classList.add("correct");QUIZ_STATE.score++}else{el.classList.add("wrong");opts[q.ans].classList.add("correct")}
  setTimeout(function(){QUIZ_STATE.idx++;renderQuiz()},1200);
}
function renderQuizResult(){
  var total=QUIZ_STATE.questions.length,score=QUIZ_STATE.score,pct=Math.round(score/total*100);
  var stars=pct>=80?"⭐⭐⭐":pct>=60?"⭐⭐":"⭐";
  var msg=pct>=80?"太棒了！":pct>=60?"不错哦！":"再试试吧！";
  var el=$("quizBody");if(!el)return;
  el.innerHTML='<div class="quiz-result"><div class="qr-score">'+score+'/'+total+'</div><div class="qr-label">'+msg+'</div><div class="qr-stars">'+stars+'</div><div class="qr-detail">正确率: '+pct+'%</div><button class="quiz-start-btn" style="margin-top:20px" onclick="startQuiz()">再来一次 🔄</button></div>';
}

// --- 番茄钟加强版 ---
var TIMER_STATE={mode:"work",time:25*60,remaining:25*60,running:false,tasks:[],completed:0};
function initTimer(){
  try{TIMER_STATE.tasks=JSON.parse(lsGet("huanyu_timer_tasks")||"[]");TIMER_STATE.completed=parseInt(lsGet("huanyu_timer_completed")||"0")}catch(e){}
}
function saveTimerState(){lsSet("huanyu_timer_tasks",JSON.stringify(TIMER_STATE.tasks));lsSet("huanyu_timer_completed",TIMER_STATE.completed+"")}
function openTimer(){
  initTimer();
  var el=$("timerOverlay");if(el)el.style.display="flex";
  renderTimer();
}
function closeTimer(){
  var el=$("timerOverlay");if(el)el.style.display="none";
  if(TIMER_STATE.running){clearInterval(TIMER_STATE._interval);TIMER_STATE.running=false}
}
function setTimerMode(mode){
  TIMER_STATE.mode=mode;TIMER_STATE.running=false;
  if(TIMER_STATE._interval){clearInterval(TIMER_STATE._interval)}
  TIMER_STATE.time=mode==="work"?25*60:mode==="short"?5*60:15*60;
  TIMER_STATE.remaining=TIMER_STATE.time;
  renderTimer();
}
function toggleTimer(){
  if(TIMER_STATE.running){clearInterval(TIMER_STATE._interval);TIMER_STATE.running=false;renderTimer();return}
  TIMER_STATE.running=true;
  TIMER_STATE._interval=setInterval(function(){
    TIMER_STATE.remaining--;
    if(TIMER_STATE.remaining<=0){
      clearInterval(TIMER_STATE._interval);TIMER_STATE.running=false;TIMER_STATE.completed++;
      saveTimerState();
      showToast("🎉 "+(TIMER_STATE.mode==="work"?"工作完成！休息一下吧":"休息结束！加油！"));
      if(TIMER_STATE.mode==="work"){TIMER_STATE.mode="short";TIMER_STATE.time=5*60;TIMER_STATE.remaining=5*60}
      else{TIMER_STATE.mode="work";TIMER_STATE.time=25*60;TIMER_STATE.remaining=25*60}
    }
    renderTimer();
  },1000);
  renderTimer();
}
function resetTimer(){clearInterval(TIMER_STATE._interval);TIMER_STATE.running=false;TIMER_STATE.remaining=TIMER_STATE.time;renderTimer()}
function renderTimer(){
  var mins=Math.floor(TIMER_STATE.remaining/60),secs=TIMER_STATE.remaining%60;
  var display=mins.toString().padStart(2,"0")+":"+secs.toString().padStart(2,"0");
  var el=$("timerDisplay");if(el){el.textContent=display;el.className="timer-display "+(TIMER_STATE.mode==="work"?"work":"break")}
  var playBtn=$("timerPlayBtn");if(playBtn){playBtn.textContent=TIMER_STATE.running?"⏸":"▶";playBtn.className="timer-ctrl-btn "+(TIMER_STATE.running?"pause":"play")}
  var completed=$("timerCompleted");if(completed)completed.textContent=TIMER_STATE.completed;
  var total=$("timerTotal");if(total)total.textContent=TIMER_STATE.tasks.length;
  var tasks=$("timerTasks");if(!tasks)return;
  var html="<div style='font-size:12px;color:#a78bfa;margin-bottom:8px;font-weight:600'>📋 待办任务</div>";
  for(var i=0;i<TIMER_STATE.tasks.length;i++){
    var t=TIMER_STATE.tasks[i];
    html+='<div class="timer-task-item"><div class="tt-dot" style="background:'+(t.done?"#5cfca8":"#8b6cff")+'"></div><div class="tt-text'+(t.done?" tt-done":"")+'">'+esc(t.text)+'</div><span style="font-size:10px;color:#555;cursor:pointer" onclick="toggleTimerTask('+i+')">'+(t.done?"↩":"✓")+'</span></div>';
  }
  tasks.innerHTML=html;
}
function addTimerTask(){
  var input=$("timerTaskInput");if(!input)return;
  var text=input.value.trim();if(!text)return;
  TIMER_STATE.tasks.push({text:text,done:false});saveTimerState();input.value="";renderTimer();
}
function toggleTimerTask(idx){TIMER_STATE.tasks[idx].done=!TIMER_STATE.tasks[idx].done;saveTimerState();renderTimer()}
function initV301Features(){initSmartNotes();initHabits();initTimer()}


