var WCLOCK_CITIES=[{name:"北京",tz:"Asia/Shanghai"},{name:"东京",tz:"Asia/Tokyo"},{name:"纽约",tz:"America/New_York"},{name:"伦敦",tz:"Europe/London"},{name:"巴黎",tz:"Europe/Paris"},{name:"迪拜",tz:"Asia/Dubai"},{name:"悉尼",tz:"Australia/Sydney"},{name:"洛杉矶",tz:"America/Los_Angeles"}],WCLOCK_TIMER=null;function openWorldClock(){var el=$("wclockOverlay");if(!el)return;el.style.display="flex";renderWClock();if(WCLOCK_TIMER)clearInterval(WCLOCK_TIMER);WCLOCK_TIMER=setInterval(renderWClock,1000)}function getTimeInTZ(tz){try{var now=new Date();var opt={timeZone:tz,hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false};var t=new Intl.DateTimeFormat("en-US",opt).format(now);var dopt={timeZone:tz,weekday:"short",year:"numeric",month:"2-digit",day:"2-digit"};var d=new Intl.DateTimeFormat("en-US",dopt).format(now);return{time:t,date:d}}catch(e){return{time:"--:--:--",date:"----"}}}function renderWClock(){var body=$("wclockBody");if(!body)return;var h="";for(var i=0;i<WCLOCK_CITIES.length;i++){var c=WCLOCK_CITIES[i];var t=getTimeInTZ(c.tz);var off="";try{var now=new Date();var tz1=Intl.DateTimeFormat("en-US",{timeZone:c.tz,timeZoneName:"short"}).formatToParts(now);for(var p=0;p<tz1.length;p++){if(tz1[p].type==="timeZoneName"){off=tz1[p].value;break}}}catch(e){}h+='<div class="wclock-card"><div class="wclock-city">'+c.name+' <span style="font-size:12px;color:#7a7a9a">'+off+'</span><span style="float:right;cursor:pointer;color:#fc6b6b;font-size:14px" onclick="removeWClockCity('+i+')">✕</span></div><div class="wclock-time">'+t.time+'</div><div class="wclock-date">'+t.date+'</div></div>'}body.innerHTML=h}function addWClockCity(){var name=prompt("输入城市名称:");if(!name)return;var tz=prompt("输入时区 (如 Asia/Shanghai):");if(!tz)return;WCLOCK_CITIES.push({name:name,tz:tz});renderWClock()}function removeWClockCity(idx){WCLOCK_CITIES.splice(idx,1);renderWClock()}function closeWorldClock(){var el=$("wclockOverlay");if(el)el.style.display="none";if(WCLOCK_TIMER){clearInterval(WCLOCK_TIMER);WCLOCK_TIMER=null}}

