var CHART_TYPE="bar",CHART_DATA=[80,50,120,70],CHART_LABELS=["A","B","C","D"];function openChartGen(){var el=$("chartgenOverlay");if(!el)return;el.style.display="flex";setTimeout(drawChart,100)}function setChartType(type){CHART_TYPE=type;document.querySelectorAll(".chartgen-btn").forEach(function(b){b.className="chartgen-btn"+(b.textContent.trim()==={bar:"柱状图",line:"折线图",pie:"饼图",doughnut:"环形图"}[type]?" active":"")});drawChart()}function updateChartData(){var vals=[];var labels=[];for(var i=1;i<=4;i++){var inp=$("cd"+i);if(inp){vals.push(parseFloat(inp.value)||0);if(i===1)labels.push("A");else if(i===2)labels.push("B");else if(i===3)labels.push("C");else labels.push("D")}}CHART_DATA=vals;CHART_LABELS=labels;drawChart()}function drawChart(){var canvas=$("chartCanvas");if(!canvas)return;var ctx=canvas.getContext("2d");var w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle="#1a1a2e";ctx.fillRect(0,0,w,h);var colors=["#8b6cff","#5cfca8","#ff6b6b","#6bb5ff","#ffd700","#ff69b4","#00ced1","#ff8c00"];if(CHART_TYPE==="bar"){drawBarChart(ctx,w,h)}else if(CHART_TYPE==="line"){drawLineChart(ctx,w,h)}else if(CHART_TYPE==="pie"){drawPieChart(ctx,w,h,false)}else if(CHART_TYPE==="doughnut"){drawPieChart(ctx,w,h,true)}}function drawBarChart(ctx,w,h){var pad=30;var chartW=w-pad*2,chartH=h-pad*2;var max=Math.max.apply(null,CHART_DATA)||1;var barW=chartW/CHART_DATA.length*0.6;var gap=chartW/CHART_DATA.length*0.4;ctx.strokeStyle="rgba(255,255,255,.1)";ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad,pad);ctx.lineTo(pad,h-pad);ctx.lineTo(w-pad,h-pad);ctx.stroke();for(var i=0;i<CHART_DATA.length;i++){var barH=(CHART_DATA[i]/max)*(chartH-20);var x=pad+i*(barW+gap)+gap/2;var y=h-pad-barH-10;var g=ctx.createLinearGradient(x,y,x,h-pad-10);var c=colors[i%colors.length];g.addColorStop(0,c);g.addColorStop(1,c+"44");ctx.fillStyle=g;ctx.beginPath();ctx.roundRect(x,y,barW,barH+10,4);ctx.fill();ctx.fillStyle="#e0d4ff";ctx.font="10px sans-serif";ctx.textAlign="center";ctx.fillText(CHART_LABELS[i],x+barW/2,h-pad-2);ctx.fillStyle="#8b6cff";ctx.fillText(CHART_DATA[i],x+barW/2,y-4)}}function drawLineChart(ctx,w,h){var pad=30;var chartW=w-pad*2,chartH=h-pad*2;var max=Math.max.apply(null,CHART_DATA)||1;ctx.strokeStyle="rgba(255,255,255,.1)";ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad,pad);ctx.lineTo(pad,h-pad);ctx.lineTo(w-pad,h-pad);ctx.stroke();ctx.strokeStyle="#8b6cff";ctx.lineWidth=2;ctx.beginPath();var points=[];for(var i=0;i<CHART_DATA.length;i++){var x=pad+i*(chartW/(CHART_DATA.length-1||1));var y=h-pad-(CHART_DATA[i]/max)*(chartH-20)-10;points.push({x:x,y:y});if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke();for(var i=0;i<points.length;i++){var g=ctx.createRadialGradient(points[i].x,points[i].y,2,points[i].x,points[i].y,8);g.addColorStop(0,"#5cfca8");g.addColorStop(1,"#8b6cff");ctx.fillStyle=g;ctx.beginPath();ctx.arc(points[i].x,points[i].y,5,0,Math.PI*2);ctx.fill();ctx.fillStyle="#e0d4ff";ctx.font="10px sans-serif";ctx.textAlign="center";ctx.fillText(CHART_DATA[i],points[i].x,points[i].y-10);ctx.fillText(CHART_LABELS[i],points[i].x,h-pad-2)}}function drawPieChart(ctx,w,h,isDoughnut){var cx=w/2,cy=h/2,r=Math.min(w,h)/2-20;var total=0;for(var i=0;i<CHART_DATA.length;i++)total+=CHART_DATA[i];if(total===0)return;var startAngle=-Math.PI/2;for(var i=0;i<CHART_DATA.length;i++){var sliceAngle=(CHART_DATA[i]/total)*Math.PI*2;ctx.fillStyle=colors[i%colors.length];ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,startAngle,startAngle+sliceAngle);ctx.closePath();ctx.fill();if(isDoughnut){ctx.fillStyle="#1a1a2e";ctx.beginPath();ctx.arc(cx,cy,r*.5,0,Math.PI*2);ctx.fill()}var midAngle=startAngle+sliceAngle/2;var labelR=isDoughnut?r*.7:r*.6;var lx=cx+Math.cos(midAngle)*labelR;var ly=cy+Math.sin(midAngle)*labelR;ctx.fillStyle="#fff";ctx.font="10px sans-serif";ctx.textAlign="center";ctx.fillText(CHART_LABELS[i]+" "+Math.round(CHART_DATA[i]/total*100)+"%",lx,ly);startAngle+=sliceAngle}}function closeChartGen(){var el=$("chartgenOverlay");if(el)el.style.display="none"}

