// --- 待办事项 ---
var TODOS=[];function openTodoList(){var el=$("todoOverlay");if(!el)return;el.style.display="flex";loadTodos();renderTodos()}function loadTodos(){try{var d=localStorage.getItem("huanyu_todos");if(d)TODOS=JSON.parse(d)}catch(e){TODOS=[]}if(!Array.isArray(TODOS))TODOS=[]}function saveTodos(){try{localStorage.setItem("huanyu_todos",JSON.stringify(TODOS))}catch(e){}}function addTodo(){var inp=$("todoInput");if(!inp||!inp.value.trim())return;TODOS.push({text:inp.value.trim(),done:false,time:new Date().toLocaleDateString()});inp.value="";saveTodos();renderTodos()}function toggleTodo(idx){if(TODOS[idx]){TODOS[idx].done=!TODOS[idx].done;saveTodos();renderTodos()}}function delTodo(idx){TODOS.splice(idx,1);saveTodos();renderTodos()}function renderTodos(){var list=$("todoList");if(!list)return;var h="";var done=0;for(var i=0;i<TODOS.length;i++){var t=TODOS[i];if(t.done)done++;h+='<div class="todo-item"><button class="todo-check'+(t.done?" done":"")+'" onclick="toggleTodo(&#39;+i+&#39;)">'+(t.done?"✓":"")+'</button><span class="todo-text'+(t.done?" done":"")+'">'+esc(t.text)+'</span><span style="font-size:10px;color:#7a7a9a">'+t.time+'</span><button class="todo-del" onclick="delTodo(&#39;+i+&#39;)">✕</button></div>'}list.innerHTML=h||'<p style="color:#7a7a9a;font-size:14px;margin:20px 0">暂无待办，添加一个吧 📝</p>';var stats=$("todoStats");if(stats)stats.textContent="共 "+TODOS.length+" 项，已完成 "+done+" 项";var inp=$("todoInput");if(inp)inp.focus()}function closeTodoList(){var el=$("todoOverlay");if(el)el.style.display="none"}

// --- 记账本 ---
var EXPENSES=[],EXP_CAT="餐饮";function openExpenseTracker(){var el=$("expenseOverlay");if(!el)return;el.style.display="flex";loadExpenses();renderExpenses()}function loadExpenses(){try{var d=localStorage.getItem("huanyu_expenses");if(d)EXPENSES=JSON.parse(d)}catch(e){}if(!Array.isArray(EXPENSES))EXPENSES=[]}function saveExpenses(){try{localStorage.setItem("huanyu_expenses",JSON.stringify(EXPENSES))}catch(e){}}function addExpense(){var amt=$("expAmount");var desc=$("expDesc");var type=$("expType");if(!amt||!desc||!type)return;var val=parseFloat(amt.value);if(!val||val<=0)return;EXPENSES.push({amount:val,desc:desc.value.trim()||"未分类",category:EXP_CAT,type:type.value,date:new Date().toISOString().slice(0,10)});amt.value="";desc.value="";saveExpenses();renderExpenses()}function renderExpenses(){var list=$("expenseList");if(!list)return;var totalIncome=0,totalExpense=0;for(var i=0;i<EXPENSES.length;i++){var e=EXPENSES[i];if(e.type==="income")totalIncome+=e.amount;else totalExpense+=e.amount}var inc=$("expIncome");if(inc)inc.textContent="¥"+totalIncome.toFixed(2);var exp=$("expExpense");if(exp)exp.textContent="¥"+totalExpense.toFixed(2);var bal=$("expBalance");if(bal)bal.textContent="¥"+(totalIncome-totalExpense).toFixed(2);var h="";var sorted=EXPENSES.slice().reverse();for(var i=0;i<Math.min(sorted.length,50);i++){var e=sorted[i];var icon={餐饮:"🍜",交通:"🚗",购物:"🛍️",娱乐:"🎮",其他:"📦"}[e.category]||"📦";h+='<div class="expense-item"><span>'+icon+" "+esc(e.desc)+'</span><span style="color:'+(e.type==="income"?"#5cfca8":"#ff6b6b")+';font-weight:600">'+(e.type==="income"?"+":"-")+"¥"+e.amount.toFixed(2)+'</span><span style="font-size:10px;color:#7a7a9a">'+e.date+'</span><button onclick="delExpense(&#39;+i+&#39;)" style="background:none;border:none;color:#fc6b6b;cursor:pointer;font-size:12px">✕</button></div>'}list.innerHTML=h||'<p style="color:#7a7a9a;font-size:14px;margin:20px;text-align:center">暂无记录，开始记账吧 💰</p>'}document.querySelectorAll(".expense-cat").forEach(function(b){b.onclick=function(){document.querySelectorAll(".expense-cat").forEach(function(x){x.className="expense-cat"});this.className="expense-cat active";EXP_CAT=this.getAttribute("data-cat")}});function delExpense(idx){var realIdx=EXPENSES.length-1-idx;if(realIdx>=0&&realIdx<EXPENSES.length){EXPENSES.splice(realIdx,1);saveExpenses();renderExpenses()}}function closeExpenseTracker(){var el=$("expenseOverlay");if(el)el.style.display="none"}

