// ===== v3.13.0 AI对话词汇云 =====
// ==========================================================================
var STOP_WORDS=["的","了","是","我","你","他","她","它","们","在","有","和","就","不","人","都","一","上","也","很","到","说","要","去","会","着","没有","看","好","自己","这","那","里","为","什么","吗","吧","呢","啊","哦","嗯","一个","可以","这个","那个","怎么","这样","那样","如果","但是","因为","所以","或者","还是","已经","可能","应该","需要","觉得","知道","现在","时候","什么","怎么","为什么","哪些","哪个","哪里","some","the","a","an","is","are","was","were","be","been","being","have","has","had","do","does","did","will","would","could","should","may","might","must","can","to","of","in","on","at","by","for","with","about","against","between","into","through","during","before","after","above","below","from","up","down","out","off","over","under","again","further","then","once","here","there","when","where","why","how","all","each","every","both","few","more","most","other","some","such","no","nor","not","only","own","same","so","than","too","very","s","t","just","don","now","it","this","that","these","those","am","as","if","or","and","but","my","your","his","her","its","our","their","what","which","who","whom","where","when","why","how"];
function generateWordCloud(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(active.length===0)return null;
    var wordCount={};
    for(var i=0;i<active.length;i++){
      var text=active[i].t||"";
      // 中文分词（简单2-4字组合）
      var cleanText=text.replace(/[^\u4e00-\u9fa5a-zA-Z\s]/g," ");
      // 提取中文2-4字词
      var cnWords=cleanText.match(/[\u4e00-\u9fa5]{2,4}/g)||[];
      for(var j=0;j<cnWords.length;j++){
        var w=cnWords[j];
        if(STOP_WORDS.indexOf(w)>=0)continue;
        if(w.length<2)continue;
        wordCount[w]=(wordCount[w]||0)+1;
      }
      // 提取英文单词
      var enWords=cleanText.match(/[a-zA-Z]{3,}/g)||[];
      for(var j=0;j<enWords.length;j++){
        var w=enWords[j].toLowerCase();
        if(STOP_WORDS.indexOf(w)>=0)continue;
        wordCount[w]=(wordCount[w]||0)+1;
      }
    }
    // 排序取前50
    var sorted=Object.keys(wordCount).map(function(k){return{word:k,count:wordCount[k]}}).sort(function(a,b){return b.count-a.count}).slice(0,50);
    if(sorted.length===0)return null;
    var maxCount=sorted[0].count;
    var minCount=sorted[sorted.length-1].count;
    return{words:sorted,maxCount:maxCount,minCount:minCount,totalWords:Object.keys(wordCount).length,totalMsgs:active.length};
  }catch(e){return null}
}
function openWordcloudPanel(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var data=generateWordCloud();
    var box=$("wordcloudOverlay");
    var body=$("wordcloudBody");
    if(!box||!body)return;
    if(!data){
      body.innerHTML='<div style="text-align:center;color:#666;padding:40px;font-size:13px">暂无对话数据，开始聊天后可以查看词汇云～</div>';
      box.className="wordcloud-overlay show";
      return;
    }
    var h="";
    // 词汇云
    var colors=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#fc5c8a","#5cfcc8"];
    h+='<div class="wordcloud-canvas">';
    for(var i=0;i<data.words.length;i++){
      var w=data.words[i];
      var size=11+Math.round((w.count-data.minCount)/Math.max(data.maxCount-data.minCount,1)*18);
      var color=colors[i%colors.length];
      var opacity=0.4+0.6*(w.count-data.minCount)/Math.max(data.maxCount-data.minCount,1);
      h+='<span class="wordcloud-tag" style="font-size:'+size+'px;color:'+color+';opacity:'+opacity+'">'+esc(w.word)+'</span>';
    }
    h+='</div>';
    // 统计
    h+='<div class="wordcloud-stats">';
    h+='<div class="wordcloud-stat"><div class="wordcloud-stat-num">'+data.totalWords+'</div><div class="wordcloud-stat-label">独立词汇</div></div>';
    h+='<div class="wordcloud-stat"><div class="wordcloud-stat-num">'+data.totalMsgs+'</div><div class="wordcloud-stat-label">消息总数</div></div>';
    h+='<div class="wordcloud-stat"><div class="wordcloud-stat-num">'+data.maxCount+'</div><div class="wordcloud-stat-label">最高频次</div></div>';
    h+='</div>';
    // Top 10
    h+='<div class="wordcloud-top">';
    h+='<div class="wordcloud-top-title">🏆 高频词汇 TOP 10</div>';
    for(var i=0;i<Math.min(data.words.length,10);i++){
      var w=data.words[i];
      h+='<div class="wordcloud-top-item">';
      h+='<div class="wordcloud-top-rank">'+(i+1)+'</div>';
      h+='<div class="wordcloud-top-word">'+esc(w.word)+'</div>';
      h+='<div class="wordcloud-top-count">'+w.count+'次</div>';
      h+='</div>';
    }
    h+='</div>';
    body.innerHTML=h;
    box.className="wordcloud-overlay show";
  }catch(e){}
}
function closeWordcloudPanel(){
  try{var box=$("wordcloudOverlay");if(box)box.className="wordcloud-overlay"}catch(e){}
}

// ==========================================================================
// ===== v3.13.0 对话节奏分析 =====
// ==========================================================================
function generateRhythmData(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(active.length<2)return null;
    // 计算消息间隔
    var intervals=[];
    for(var i=1;i<active.length;i++){
      var t1=active[i-1].time||Date.now();
      var t2=active[i].time||Date.now();
      intervals.push({idx:i,diff:t2-t1,from:active[i-1],to:active[i]});
    }
    // 统计
    var totalDiff=0;
    var maxDiff=0;
    var minDiff=Infinity;
    for(var i=0;i<intervals.length;i++){
      totalDiff+=intervals[i].diff;
      if(intervals[i].diff>maxDiff)maxDiff=intervals[i].diff;
      if(intervals[i].diff<minDiff)minDiff=intervals[i].diff;
    }
    var avgDiff=Math.round(totalDiff/intervals.length/1000);
    // 消息长度分析
    var myLens=[];var aiLens=[];
    for(var i=0;i<active.length;i++){
      var len=(active[i].t||"").length;
      if(active[i].r==="me")myLens.push(len);
      else aiLens.push(len);
    }
    var avgMyLen=Math.round(myLens.reduce(function(a,b){return a+b},0)/Math.max(myLens.length,1));
    var avgAiLen=Math.round(aiLens.reduce(function(a,b){return a+b},0)/Math.max(aiLens.length,1));
    // 活跃时段分析
    var hourCount={};
    for(var i=0;i<active.length;i++){
      var h=new Date(active[i].time||Date.now()).getHours();
      hourCount[h]=(hourCount[h]||0)+1;
    }
    var peakHour=0;var peakCount=0;
    for(var h in hourCount){
      if(hourCount[h]>peakCount){peakCount=hourCount[h];peakHour=parseInt(h)}
    }
    // 节奏类型判定
    var rhythmType="";
    var rhythmDesc="";
    if(avgDiff<10){rhythmType="⚡ 闪电节奏";rhythmDesc="你们的对话速度非常快，像闪电一样来回穿梭，充满了即时互动的激情。"}
    else if(avgDiff<60){rhythmType="🔥 热烈节奏";rhythmDesc="对话节奏热烈而紧凑，双方都在积极回应，互动频率很高。"}
    else if(avgDiff<600){rhythmType="🌿 自然节奏";rhythmDesc="对话节奏自然舒适，不紧不慢，像溪水一样流淌。"}
    else if(avgDiff<3600){rhythmType="🌙 悠闲节奏";rhythmDesc="对话节奏悠闲从容，双方都给彼此足够的思考空间。"}
    else{rhythmType="📭 慢节奏";rhythmDesc="对话间隔较长，更像书信往来，每条消息都经过深思熟虑。"}
    // 波形数据
    var wavePoints=[];
    var maxBars=Math.min(active.length,40);
    var step=Math.max(1,Math.floor(active.length/maxBars));
    for(var i=0;i<active.length;i+=step){
      var len=(active[i].t||"").length;
      wavePoints.push({len:Math.min(len,100),isMe:active[i].r==="me"});
    }
    return{
      intervals:intervals,avgDiff:avgDiff,maxDiff:Math.round(maxDiff/1000),minDiff:Math.round(minDiff/1000),
      avgMyLen:avgMyLen,avgAiLen:avgAiLen,peakHour:peakHour,peakCount:peakCount,
      rhythmType:rhythmType,rhythmDesc:rhythmDesc,wavePoints:wavePoints,totalMsgs:active.length
    };
  }catch(e){return null}
}
function openRhythmPanel(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var data=generateRhythmData();
    var box=$("rhythmOverlay");
    var body=$("rhythmBody");
    if(!box||!body)return;
    if(!data){
      body.innerHTML='<div style="text-align:center;color:#666;padding:40px;font-size:13px">暂无足够的对话数据，多聊几句再来查看节奏分析～</div>';
      box.className="rhythm-overlay show";
      return;
    }
    var h="";
    // 波形图
    h+='<div class="rhythm-wave-box">';
    h+='<svg class="rhythm-wave-svg" viewBox="0 0 300 140" preserveAspectRatio="none">';
    var baseline=120;
    var barW=Math.max(2,280/Math.max(data.wavePoints.length,1));
    for(var i=0;i<data.wavePoints.length;i++){
      var p=data.wavePoints[i];
      var h2=Math.max(4,p.len/100*100);
      var x=10+i*barW;
      var y=baseline-h2;
      var color=p.isMe?"rgba(124,92,252,0.4)":"rgba(92,252,168,0.35)";
      h+='<rect x="'+x+'" y="'+y+'" width="'+(barW-1)+'" height="'+h2+'" rx="2" fill="'+color+'"/>';
    }
    h+='<line x1="5" y1="'+baseline+'" x2="295" y2="'+baseline+'" stroke="rgba(124,92,252,0.1)" stroke-width="0.5"/>';
    h+='</svg>';
    h+='<div style="display:flex;gap:12px;justify-content:center;margin-top:8px">';
    h+='<span style="font-size:10px;color:#7c5cfc">● 我的消息</span>';
    h+='<span style="font-size:10px;color:#5cfca8">● AI回复</span>';
    h+='</div>';
    h+='</div>';
    // 统计卡片
    h+='<div class="rhythm-stats">';
    h+='<div class="rhythm-stat-card"><div class="rhythm-stat-icon">⏱️</div><div class="rhythm-stat-val">'+formatTime(data.avgDiff)+'</div><div class="rhythm-stat-label">平均间隔</div></div>';
    h+='<div class="rhythm-stat-card"><div class="rhythm-stat-icon">📏</div><div class="rhythm-stat-val">'+data.avgMyLen+'</div><div class="rhythm-stat-label">我的均长</div></div>';
    h+='<div class="rhythm-stat-card"><div class="rhythm-stat-icon">📐</div><div class="rhythm-stat-val">'+data.avgAiLen+'</div><div class="rhythm-stat-label">AI均长</div></div>';
    h+='<div class="rhythm-stat-card"><div class="rhythm-stat-icon">🕐</div><div class="rhythm-stat-val">'+data.peakHour+':00</div><div class="rhythm-stat-label">活跃时段</div></div>';
    h+='</div>';
    // 节奏模式
    h+='<div class="rhythm-pattern">';
    h+='<div class="rhythm-pattern-title">📊 节奏模式分析</div>';
    var myPct=Math.round(data.avgMyLen/(data.avgMyLen+data.avgAiLen)*100);
    var aiPct=100-myPct;
    h+='<div class="rhythm-pattern-row"><div class="rhythm-pattern-label">我的篇幅</div><div class="rhythm-pattern-bar"><div class="rhythm-pattern-fill" style="width:'+myPct+'%;background:#7c5cfc"></div></div><div class="rhythm-pattern-val">'+myPct+'%</div></div>';
    h+='<div class="rhythm-pattern-row"><div class="rhythm-pattern-label">AI篇幅</div><div class="rhythm-pattern-bar"><div class="rhythm-pattern-fill" style="width:'+aiPct+'%;background:#5cfca8"></div></div><div class="rhythm-pattern-val">'+aiPct+'%</div></div>';
    var fastPct=Math.round(data.intervals.filter(function(d){return d.diff<30000}).length/data.intervals.length*100);
    h+='<div class="rhythm-pattern-row"><div class="rhythm-pattern-label">快速回应</div><div class="rhythm-pattern-bar"><div class="rhythm-pattern-fill" style="width:'+fastPct+'%;background:#fcb85c"></div></div><div class="rhythm-pattern-val">'+fastPct+'%</div></div>';
    var slowPct=Math.round(data.intervals.filter(function(d){return d.diff>600000}).length/data.intervals.length*100);
    h+='<div class="rhythm-pattern-row"><div class="rhythm-pattern-label">慢速回应</div><div class="rhythm-pattern-bar"><div class="rhythm-pattern-fill" style="width:'+slowPct+'%;background:#fc6b6b"></div></div><div class="rhythm-pattern-val">'+slowPct+'%</div></div>';
    h+='</div>';
    // 总结
    h+='<div class="rhythm-summary">';
    h+='<div class="rhythm-summary-title">🎵 '+data.rhythmType+'</div>';
    h+='<div class="rhythm-summary-text">'+data.rhythmDesc+' 共'+data.totalMsgs+'条消息，最活跃时段为'+data.peakHour+':00左右。</div>';
    h+='</div>';
    body.innerHTML=h;
    box.className="rhythm-overlay show";
  }catch(e){}
}
function formatTime(secs){
  try{
    if(secs<60)return secs+"秒";
    if(secs<3600)return Math.round(secs/60)+"分";
    return Math.round(secs/3600)+"时";
  }catch(e){return secs+"秒"}
}
function closeRhythmPanel(){
  try{var box=$("rhythmOverlay");if(box)box.className="rhythm-overlay"}catch(e){}
}

