function getCollectedCards(){
  try{return lsGet("collectedCards")||[]}catch(e){return[]}
}
function openCardcollPanel(){
  try{
    var box=$("cardcollOverlay");
    var body=$("cardcollBody");
    if(!box||!body)return;
    var collected=getCollectedCards();
    var h="";
    // 进度
    h+='<div class="cardcoll-progress">';
    h+='<div class="cardcoll-progress-text">已收集 '+collected.length+' / '+CARD_POOL.length+' 张卡牌</div>';
    h+='<div class="cardcoll-progress-bar"><div class="cardcoll-progress-fill" style="width:'+Math.round(collected.length/CARD_POOL.length*100)+'%"></div></div>';
    h+='</div>';
    // 卡牌网格
    h+='<div class="cardcoll-grid">';
    for(var i=0;i<CARD_POOL.length;i++){
      var card=CARD_POOL[i];
      var isCollected=collected.indexOf(card.id)>=0;
      // 如果与该角色有对话也算收集
      if(!isCollected){
        var role=PRESET_ROLES.find(function(r){return r.id===card.roleId});
        if(role){
          var ms=msgs[role.id]||[];
          if(ms.filter(function(m){return !m.rolled}).length>0){
            collected.push(card.id);
            isCollected=true;
          }
        }
      }
      h+='<div class="cardcoll-card cardcoll-card-rarity-'+card.rarity+' '+(isCollected?'unlocked':'locked')+'">';
      h+='<div class="cardcoll-card-rarity-badge">'+card.rarity+'</div>';
      h+='<div class="cardcoll-card-top">';
      h+='<div class="cardcoll-card-icon">'+(isCollected?card.icon:"❓")+'</div>';
      h+='<div class="cardcoll-card-name">'+(isCollected?esc(card.name):"???")+'</div>';
      h+='</div>';
      h+='<div class="cardcoll-card-desc">'+(isCollected?esc(card.desc):"与对应角色对话解锁")+'</div>';
      h+='</div>';
    }
    h+='</div>';
    // 抽卡按钮
    h+='<div class="cardcoll-draw-btn" onclick="drawRandomCard()">🎁 随机抽卡（需500能量）</div>';
    body.innerHTML=h;
    box.className="cardcoll-overlay show";
    // 保存收集状态
    lsSet("collectedCards",collected);
  }catch(e){}
}
function drawRandomCard(){
  try{
    var collected=getCollectedCards();
    var uncollected=CARD_POOL.filter(function(c){return collected.indexOf(c.id)<0});
    if(uncollected.length===0){showToast("已收集全部卡牌！");return}
    // 检查能量
    var energy=parseInt(lsGet("energyValue")||"0");
    if(energy<500){showToast("能量不足，需要500能量");return}
    // 扣除能量
    lsSet("energyValue",energy-500);
    // 随机抽一张（稀有度权重）
    var pool=[];
    for(var i=0;i<uncollected.length;i++){
      var weight={N:50,R:30,SR:15,SSR:5}[uncollected[i].rarity]||10;
      for(var j=0;j<weight;j++)pool.push(uncollected[i]);
    }
    var drawn=pool[Math.floor(Math.random()*pool.length)];
    collected.push(drawn.id);
    lsSet("collectedCards",collected);
    showToast("🎉 抽到 "+drawn.rarity+" 卡牌：「"+drawn.name+"」！");
    openCardcollPanel();
  }catch(e){}
}
function closeCardcollPanel(){
  try{var box=$("cardcollOverlay");if(box)box.className="cardcoll-overlay"}catch(e){}
}

