function initV313Features(){
  try{
    // 功能中心按钮已经在HTML中，不需要额外注入
    // 标记成就
    lsSet("achv_weatherView",true);
    // 自动收集卡牌
    var collected=getCollectedCards();
    var changed=false;
    for(var i=0;i<CARD_POOL.length;i++){
      var card=CARD_POOL[i];
      if(collected.indexOf(card.id)>=0)continue;
      var role=PRESET_ROLES.find(function(r){return r.id===card.roleId});
      if(role){
        var ms=msgs[role.id]||[];
        if(ms.filter(function(m){return !m.rolled}).length>0){
          collected.push(card.id);
          changed=true;
        }
      }
    }
    if(changed)lsSet("collectedCards",collected);
  }catch(e){}
}

// ==========================================================================
// ===== v3.14.0 AI对话基因库 =====
// ==========================================================================
function generateConversationGene(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(active.length===0)return null;
    var traits={humor:0,empathy:0,creativity:0,logic:0,positivity:0,detail:0,question:0,storytelling:0};
    var traitRules={
      humor:["哈哈","笑死","搞笑","幽默","玩笑","有趣","滑稽","好玩"],
      empathy:["理解","感受","难过","开心","心疼","安慰","支持","陪伴"],
      creativity:["想象","创造","假如","如果","幻想","创意","独特","奇妙"],
      logic:["因为","所以","因此","道理","逻辑","分析","推理","证明"],
      positivity:["加油","努力","希望","美好","成功","积极","乐观","幸运"],
      detail:["描述","细节","样子","颜色","形状","感觉","气味","声音"],
      question:["为什么","什么","怎么","如何","哪里","谁","吗","呢"],
      storytelling:["从前","故事","后来","然后","接着","开始","结束","经历"]
    };
    for(var i=0;i<active.length;i++){
      var text=(active[i].t||"").toLowerCase();
      for(var trait in traitRules){
        for(var j=0;j<traitRules[trait].length;j++){
          if(text.indexOf(traitRules[trait][j])>=0){traits[trait]++;break}
        }
      }
    }
    var maxCount=0;
    for(var t in traits){if(traits[t]>maxCount)maxCount=traits[t]}
    if(maxCount===0)maxCount=1;
    for(var trait in traits){traits[trait]=Math.round(traits[trait]/maxCount*100)}
    var traitDescriptions={
      humor:"你的对话充满幽默感，总能用轻松的方式化解紧张气氛。",
      empathy:"你非常善于理解他人感受，是天生的倾听者和安慰者。",
      creativity:"你的想象力丰富，总能提出独特有趣的想法和视角。",
      logic:"你思维清晰，逻辑性强，擅长分析问题和讲道理。",
      positivity:"你总是积极乐观，能给周围的人带来正能量和希望。",
      detail:"你注重细节描述，能让对话内容变得生动具体。",
      question:"你善于提问，通过问题深入了解事物本质和他人想法。",
      storytelling:"你擅长讲故事，能把简单的事情变得引人入胜。"
    };
    var sortedTraits=Object.keys(traits).sort(function(a,b){return traits[b]-traits[a]});
    var topTraits=sortedTraits.slice(0,3);
    return{traits:traits,topTraits:topTraits,descriptions:traitDescriptions,totalMsgs:active.length};
  }catch(e){console.error("generateConversationGene error:",e);return null}
}
function openGenePanel(){
  try{
    if(!curRole){showToast("请先选择角色");return}
    var data=generateConversationGene();
    var box=$("geneOverlay");
    var body=$("geneBody");
    if(!box||!body)return;
    if(!data){
      body.innerHTML='<div style="text-align:center;color:#666;padding:40px;font-size:13px">暂无对话数据，开始聊天后可以分析对话基因～</div>';
      box.className="gene-overlay show";
      return;
    }
    var h="";
    h+='<div class="gene-helix-box">';
    h+='<svg class="gene-helix-svg" viewBox="0 0 200 120" preserveAspectRatio="xMidYMid meet">';
    h+='<path d="M20,60 C40,30 60,90 80,60 C100,30 120,90 140,60 C160,30 180,90 180,60" fill="none" stroke="rgba(124,92,252,0.2)" stroke-width="2"/>';
    h+='<path d="M20,60 C40,90 60,30 80,60 C100,90 120,30 140,60 C160,90 180,30 180,60" fill="none" stroke="rgba(92,252,168,0.2)" stroke-width="2"/>';
    var colors=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#fc5c8a","#5cfcc8"];
    for(var i=0;i<8;i++){
      var x=20+i*20;
      var y=i%2===0?30:90;
      h+='<circle cx="'+x+'" cy="'+y+'" r="6" fill="'+colors[i]+'" opacity="0.4"/>';
    }
    h+='</svg></div>';
    h+='<div class="gene-traits">';
    var traitIcons={humor:"😄",empathy:"🤝",creativity:"💡",logic:"🧠",positivity:"☀️",detail:"🔍",question:"❓",storytelling:"📖"};
    var traitNames={humor:"幽默感",empathy:"共情力",creativity:"创造力",logic:"逻辑性",positivity:"积极性",detail:"细节描述",question:"提问倾向",storytelling:"叙事能力"};
    var idx=0;
    for(var trait in data.traits){
      h+='<div class="gene-trait-card">';
      h+='<div class="gene-trait-icon">'+traitIcons[trait]+'</div>';
      h+='<div class="gene-trait-name">'+traitNames[trait]+'</div>';
      h+='<div class="gene-trait-bar"><div class="gene-trait-fill" style="width:'+data.traits[trait]+'%;background:'+colors[idx%8]+'"></div></div>';
      h+='<div class="gene-trait-val">'+data.traits[trait]+'%</div>';
      h+='</div>';
      idx++;
    }
    h+='</div>';
    h+='<div class="gene-report">';
    h+='<div class="gene-report-title">📊 对话基因报告</div>';
    h+='<div class="gene-report-text">基于'+data.totalMsgs+'条对话分析，你的对话基因具有以下特点：</div>';
    h+='<ul style="margin:10px 0 0 20px;color:#ccc;line-height:1.8;font-size:13px">';
    for(var i=0;i<data.topTraits.length;i++){
      h+='<li>'+traitIcons[data.topTraits[i]]+' '+data.descriptions[data.topTraits[i]]+'</li>';
    }
    h+='</ul>';
    h+='<div class="gene-tags">';
    h+='<span class="gene-tag">对话基因</span>';
    h+='<span class="gene-tag">共'+data.totalMsgs+'条消息</span>';
    h+='<span class="gene-tag">分析时间：'+new Date().toLocaleString()+'</span>';
    h+='</div></div>';
    body.innerHTML=h;
    box.className="gene-overlay show";
  }catch(e){console.error("openGenePanel error:",e)}
}
function closeGenePanel(){
  try{var box=$("geneOverlay");if(box)box.className="gene-overlay"}catch(e){}
}

