var danmakuList=[];
var danmakuColor="#e0d4ff";
var danmakuColors=["#e0d4ff","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#fc5c8a","#5cfcc8"];
function openDanmakuPanel(){
  try{
    var box=$("danmakuOverlay");
    var body=$("danmakuBody");
    if(!box||!body)return;
    danmakuList=lsGet("danmakuList")||[];
    var h="";
    h+='<div class="danmaku-stage" id="danmakuStage"></div>';
    h+='<div class="danmaku-color-btns">';
    for(var i=0;i<danmakuColors.length;i++){
      h+='<div class="danmaku-color-btn'+(danmakuColors[i]===danmakuColor?" active":"")+'" style="background:'+danmakuColors[i]+'" onclick="setDanmakuColor(\''+danmakuColors[i]+'\')"></div>';
    }
    h+='</div>';
    h+='<div class="danmaku-input-box">';
    h+='<input type="text" class="danmaku-input" id="danmakuInput" placeholder="发送弹幕..." maxlength="50" onkeydown="if(event.key===\'Enter\')sendDanmaku()">';
    h+='<button class="danmaku-send-btn" onclick="sendDanmaku()">➤</button>';
    h+='</div>';
    h+='<div class="danmaku-history" id="danmakuHistory">';
    if(danmakuList.length===0){
      h+='<div style="text-align:center;color:#666;padding:20px;font-size:12px">暂无弹幕记录</div>';
    }else{
      for(var i=danmakuList.length-1;i>=0&&i>=danmakuList.length-20;i--){
        h+='<div class="danmaku-history-item" style="color:'+(danmakuList[i].color||"#ccc")+'">'+esc(danmakuList[i].text)+'</div>';
      }
    }
    h+='</div>';
    body.innerHTML=h;
    box.className="danmaku-overlay show";
    // Play existing danmaku
    setTimeout(function(){playAllDanmaku()},300);
  }catch(e){console.error("openDanmakuPanel error:",e)}
}
function setDanmakuColor(color){
  danmakuColor=color;
  var btns=document.querySelectorAll(".danmaku-color-btn");
  for(var i=0;i<btns.length;i++){
    btns[i].className="danmaku-color-btn"+(btns[i].style.backgroundColor===color?" active":"");
  }
}
function sendDanmaku(){
  try{
    var input=$("danmakuInput");
    if(!input||!input.value.trim())return;
    var text=input.value.trim();
    var item={text:text,color:danmakuColor,ts:Date.now()};
    danmakuList.push(item);
    if(danmakuList.length>100)danmakuList=danmakuList.slice(-100);
    lsSet("danmakuList",danmakuList);
    input.value="";
    playDanmakuItem(item);
    // Update history
    var hist=$("danmakuHistory");
    if(hist){
      var div=document.createElement("div");
      div.className="danmaku-history-item";
      div.style.color=item.color;
      div.textContent=text;
      hist.insertBefore(div,hist.firstChild);
    }
  }catch(e){}
}
function playDanmakuItem(item){
  try{
    var stage=$("danmakuStage");
    if(!stage)return;
    var div=document.createElement("div");
    div.className="danmaku-track";
    div.style.color=item.color||"#e0d4ff";
    div.textContent=item.text;
    var top=Math.random()*160+10;
    div.style.top=top+"px";
    var duration=5+Math.random()*3;
    div.style.animationDuration=duration+"s";
    div.addEventListener("animationend",function(){this.remove()});
    stage.appendChild(div);
  }catch(e){}
}
function playAllDanmaku(){
  try{
    for(var i=0;i<danmakuList.length;i++){
      (function(item,delay){
        setTimeout(function(){playDanmakuItem(item)},delay);
      })(danmakuList[i],i*800);
    }
  }catch(e){}
}
function closeDanmakuPanel(){
  try{var box=$("danmakuOverlay");if(box)box.className="danmaku-overlay"}catch(e){}
}

