var WHEEL_ITEMS=[
  {icon:"🎁",text:"惊喜礼物",desc:"你将收到一份意外的惊喜！",color:"#7c5cfc"},
  {icon:"🌟",text:"幸运之星",desc:"今天你的运气爆棚！",color:"#5cfca8"},
  {icon:"📚",text:"知识时刻",desc:"适合学习新知识的好时机。",color:"#fcb85c"},
  {icon:"💕",text:"桃花朵朵",desc:"感情运势上升中～",color:"#fc5c8a"},
  {icon:"💰",text:"财运亨通",desc:"有意外收入的机会。",color:"#5cfcc8"},
  {icon:"🎮",text:"游戏时间",desc:"放松一下，玩玩游戏吧！",color:"#5cb4fc"},
  {icon:"🌙",text:"安静时刻",desc:"适合独处和思考。",color:"#a78bfa"},
  {icon:"⚡",text:"灵感爆发",desc:"创意源源不断涌来！",color:"#fc6b6b"}
];
var wheelSpinning=false;
function openWheelPanel(){
  try{
    var box=$("wheelOverlay");
    var body=$("wheelBody");
    if(!box||!body)return;
    var h="";
    h+='<div class="wheel-canvas-box">';
    h+='<div class="wheel-pointer">🔻</div>';
    h+='<svg class="wheel-svg" id="wheelSvg" viewBox="0 0 200 200">';
    var cx=100,cy=100,r=90;
    var anglePer=360/WHEEL_ITEMS.length;
    for(var i=0;i<WHEEL_ITEMS.length;i++){
      var startAngle=i*anglePer-90;
      var endAngle=(i+1)*anglePer-90;
      var x1=cx+r*Math.cos(startAngle*Math.PI/180);
      var y1=cy+r*Math.sin(startAngle*Math.PI/180);
      var x2=cx+r*Math.cos(endAngle*Math.PI/180);
      var y2=cy+r*Math.sin(endAngle*Math.PI/180);
      h+='<path d="M'+cx+','+cy+' L'+x1+','+y1+' A'+r+','+r+' 0 0,1 '+x2+','+y2+' Z" fill="'+WHEEL_ITEMS[i].color+'" opacity="0.3" stroke="rgba(124,92,252,0.3)" stroke-width="1"/>';
      var midAngle=(startAngle+endAngle)/2;
      var tx=cx+(r*0.6)*Math.cos(midAngle*Math.PI/180);
      var ty=cy+(r*0.6)*Math.sin(midAngle*Math.PI/180);
      h+='<text x="'+tx+'" y="'+ty+'" text-anchor="middle" dominant-baseline="middle" font-size="18">'+WHEEL_ITEMS[i].icon+'</text>';
    }
    h+='<circle cx="'+cx+'" cy="'+cy+'" r="12" fill="rgba(124,92,252,0.3)" stroke="rgba(124,92,252,0.5)" stroke-width="2"/>';
    h+='</svg></div>';
    h+='<button class="wheel-spin-btn" onclick="spinWheel()">🎯 开始转盘</button>';
    h+='<div class="wheel-result" id="wheelResult">';
    h+='<div class="wheel-result-icon" id="wheelResultIcon"></div>';
    h+='<div class="wheel-result-text" id="wheelResultText"></div>';
    h+='<div class="wheel-result-desc" id="wheelResultDesc"></div>';
    h+='</div>';
    body.innerHTML=h;
    box.className="wheel-overlay show";
  }catch(e){console.error("openWheelPanel error:",e)}
}
function spinWheel(){
  try{
    if(wheelSpinning)return;
    wheelSpinning=true;
    var svg=$("wheelSvg");
    var result=$("wheelResult");
    if(result)result.className="wheel-result";
    var winnerIdx=Math.floor(Math.random()*WHEEL_ITEMS.length);
    var anglePer=360/WHEEL_ITEMS.length;
    var targetRotation=360*5+(360-winnerIdx*anglePer-anglePer/2);
    if(svg)svg.style.transform="rotate("+targetRotation+"deg)";
    setTimeout(function(){
      var item=WHEEL_ITEMS[winnerIdx];
      if($("wheelResultIcon"))$("wheelResultIcon").textContent=item.icon;
      if($("wheelResultText"))$("wheelResultText").textContent=item.text;
      if($("wheelResultDesc"))$("wheelResultDesc").textContent=item.desc;
      if(result)result.className="wheel-result show";
      wheelSpinning=false;
    },4200);
  }catch(e){console.error("spinWheel error:",e)}
}
function closeWheelPanel(){
  try{var box=$("wheelOverlay");if(box)box.className="wheel-overlay"}catch(e){}
}

// ==========================================================================
// ===== v3.14.0 对话拼图 =====
// ==========================================================================
var puzzleData=null;
var puzzleSelected=null;
var puzzleMatched=0;
var puzzleMoves=0;
var puzzleStartTime=0;
function openPuzzlePanel(){
  try{
    var box=$("puzzleOverlay");
    var body=$("puzzleBody");
    if(!box||!body)return;
    startPuzzleGame();
    box.className="puzzle-overlay show";
  }catch(e){console.error("openPuzzlePanel error:",e)}
}
function startPuzzleGame(){
  try{
    var pairs=generatePuzzlePairs();
    puzzleData={pairs:pairs,shuffled:shufflePuzzle(pairs)};
    puzzleSelected=null;
    puzzleMatched=0;
    puzzleMoves=0;
    puzzleStartTime=Date.now();
    renderPuzzle();
  }catch(e){}
}
function generatePuzzlePairs(){
  var allPairs=[
    {q:"开心",a:"😊"},
    {q:"难过",a:"😢"},
    {q:"生气",a:"😡"},
    {q:"惊讶",a:"😲"},
    {q:"害怕",a:"😨"},
    {q:"困倦",a:"😴"},
    {q:"得意",a:"😎"},
    {q:"困惑",a:"🤔"},
    {q:"感动",a:"🥺"},
    {q:"兴奋",a:"🤩"}
  ];
  return allPairs.slice(0,6);
}
function shufflePuzzle(pairs){
  var items=[];
  for(var i=0;i<pairs.length;i++){
    items.push({type:"q",text:pairs[i].q,pairId:i});
    items.push({type:"a",text:pairs[i].a,pairId:i});
  }
  for(var i=items.length-1;i>0;i--){
    var j=Math.floor(Math.random()*(i+1));
    var tmp=items[i];items[i]=items[j];items[j]=tmp;
  }
  return items;
}
function renderPuzzle(){
  try{
    var body=$("puzzleBody");
    if(!body||!puzzleData)return;
    var elapsed=Math.floor((Date.now()-puzzleStartTime)/1000);
    var h="";
    h+='<div class="puzzle-stats">';
    h+='<div class="puzzle-stat"><div class="puzzle-stat-num">'+puzzleMatched+'/'+puzzleData.pairs.length+'</div><div class="puzzle-stat-label">已配对</div></div>';
    h+='<div class="puzzle-stat"><div class="puzzle-stat-num">'+puzzleMoves+'</div><div class="puzzle-stat-label">步数</div></div>';
    h+='<div class="puzzle-stat"><div class="puzzle-stat-num">'+elapsed+'s</div><div class="puzzle-stat-label">用时</div></div>';
    h+='</div>';
    h+='<div class="puzzle-grid">';
    for(var i=0;i<puzzleData.shuffled.length;i++){
      var item=puzzleData.shuffled[i];
      var cls="puzzle-piece";
      if(item.matched)cls+=" matched";
      if(puzzleSelected===i)cls+=" selected";
      h+='<div class="'+cls+'" onclick="clickPuzzlePiece('+i+')">'+esc(item.text)+'</div>';
    }
    h+='</div>';
    if(puzzleMatched===puzzleData.pairs.length){
      h+='<div style="text-align:center;padding:20px;background:rgba(92,252,168,.06);border-radius:14px;margin-bottom:12px">';
      h+='<div style="font-size:36px;margin-bottom:8px">🎉</div>';
      h+='<div style="font-size:15px;color:#5cfca8;font-weight:700">恭喜完成！</div>';
      h+='<div style="font-size:12px;color:#888;margin-top:4px">用时'+elapsed+'秒，共'+puzzleMoves+'步</div>';
      h+='</div>';
    }
    h+='<div class="puzzle-restart-btn" onclick="startPuzzleGame()">🔄 重新开始</div>';
    body.innerHTML=h;
  }catch(e){}
}
function clickPuzzlePiece(idx){
  try{
    if(!puzzleData||puzzleData.shuffled[idx].matched)return;
    if(puzzleSelected===null){
      puzzleSelected=idx;
      renderPuzzle();
    }else if(puzzleSelected===idx){
      puzzleSelected=null;
      renderPuzzle();
    }else{
      puzzleMoves++;
      var a=puzzleData.shuffled[puzzleSelected];
      var b=puzzleData.shuffled[idx];
      if(a.pairId===b.pairId&&a.type!==b.type){
        a.matched=true;
        b.matched=true;
        puzzleMatched++;
        puzzleSelected=null;
        renderPuzzle();
        if(puzzleMatched===puzzleData.pairs.length){
          setTimeout(function(){renderPuzzle()},100);
        }
      }else{
        puzzleSelected=null;
        renderPuzzle();
        var prevBody=$("puzzleBody");
        if(prevBody){
          setTimeout(function(){renderPuzzle()},500);
        }
      }
    }
  }catch(e){}
}
function closePuzzlePanel(){
  try{var box=$("puzzleOverlay");if(box)box.className="puzzle-overlay"}catch(e){}
}

