function openMailboxPanel(){
  try{
    var box=$("mailboxOverlay");
    var body=$("mailboxBody");
    if(!box||!body)return;
    var letters=lsGet("timeLetters")||[];
    var now=Date.now();
    var h="";
    h+='<div class="mailbox-compose">';
    h+='<div class="mailbox-compose-title">✉️ 给未来的自己写一封信</div>';
    h+='<textarea class="mailbox-input" id="mailboxInput" placeholder="写下你想对未来的自己说的话..." maxlength="500"></textarea>';
    h+='<div class="mailbox-date-row">';
    var tomorrow=new Date(now+86400000);
    var defaultDate=tomorrow.toISOString().slice(0,10);
    h+='<input type="date" class="mailbox-date-input" id="mailboxDate" value="'+defaultDate+'" min="'+new Date(now+3600000).toISOString().slice(0,10)+'">';
    h+='<input type="text" class="mailbox-date-input" id="mailboxSign" placeholder="署名（可选）" maxlength="20">';
    h+='</div>';
    h+='<div class="mailbox-send-btn" onclick="sendTimeLetter()">📮 寄出信件</div>';
    h+='</div>';
    h+='<div style="font-size:13px;color:#a78bfa;font-weight:600;margin-bottom:10px;padding:0 4px">📬 我的信件 ('+letters.length+')</div>';
    h+='<div class="mailbox-letters">';
    if(letters.length===0){
      h+='<div style="text-align:center;color:#666;padding:30px;font-size:12px">还没有信件，写一封寄给未来的自己吧～</div>';
    }else{
      for(var i=letters.length-1;i>=0;i--){
        var letter=letters[i];
        var isSealed=letter.openDate>now;
        h+='<div class="mailbox-letter'+(isSealed?" sealed":"")+'">';
        h+='<div class="mailbox-letter-header">';
        h+='<div class="mailbox-letter-date">📅 '+new Date(letter.sendDate).toLocaleDateString()+'</div>';
        h+='<div class="mailbox-letter-status '+(isSealed?"sealed":"opened")+'">'+(isSealed?"🔒 封存中":"✉️ 已开启")+'</div>';
        h+='</div>';
        if(isSealed){
          h+='<div class="mailbox-letter-text" style="text-align:center;padding:20px 0">🔐 此信将在 '+new Date(letter.openDate).toLocaleDateString()+' 自动开启</div>';
          h+='<div class="mailbox-letter-seal">🔒</div>';
        }else{
          h+='<div class="mailbox-letter-text">'+esc(letter.text)+'</div>';
          if(letter.sign)h+='<div style="font-size:11px;color:#888;margin-top:8px;text-align:right">—— '+esc(letter.sign)+'</div>';
        }
        h+='</div>';
      }
    }
    h+='</div>';
    body.innerHTML=h;
    box.className="mailbox-overlay show";
    // Check for newly opened letters
    var changed=false;
    for(var i=0;i<letters.length;i++){
      if(letters[i].openDate<=now&&!letters[i].opened){
        letters[i].opened=true;
        changed=true;
      }
    }
    if(changed)lsSet("timeLetters",letters);
  }catch(e){console.error("openMailboxPanel error:",e)}
}
function sendTimeLetter(){
  try{
    var input=$("mailboxInput");
    var dateInput=$("mailboxDate");
    var signInput=$("mailboxSign");
    if(!input||!input.value.trim()){showToast("请写信内容");return}
    var openDate=new Date(dateInput.value).getTime();
    if(!openDate||openDate<=Date.now()){showToast("请选择未来日期");return}
    var letters=lsGet("timeLetters")||[];
    letters.push({
      text:input.value.trim(),
      sendDate:Date.now(),
      openDate:openDate,
      sign:signInput?signInput.value.trim():"",
      opened:false
    });
    if(letters.length>50)letters=letters.slice(-50);
    lsSet("timeLetters",letters);
    showToast("信件已寄出，将在指定日期开启");
    openMailboxPanel();
  }catch(e){showToast("寄信失败")}
}
function closeMailboxPanel(){try{var b=$("mailboxOverlay");if(b)b.className="mailbox-overlay"}catch(e){}}

