// ===== v3.15.0 AI灵感之树 =====
// ==========================================================================
function generateInspirationTree(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(active.length===0)return null;
    var topics={};
    var topicKeywords={
      "情感":["爱","喜欢","想念","难过","开心","感动","心疼","温暖","幸福","孤独"],
      "梦想":["梦想","未来","目标","希望","计划","想成为","想要","追求"],
      "哲学":["人生","意义","为什么","存在","命运","自由","选择","真理"],
      "创意":["想象","假如","如果","设计","创造","发明","灵感","艺术"],
      "日常":["今天","吃饭","睡觉","工作","学习","天气","早上","晚上"],
      "冒险":["旅行","探险","远方","出发","未知","挑战","勇敢"],
      "回忆":["记得","以前","小时候","过去","那时候","回忆"],
      "成长":["改变","学习","进步","努力","坚持","变得","成长"]
    };
    for(var i=0;i<active.length;i++){
      var text=active[i].t||"";
      for(var topic in topicKeywords){
        for(var j=0;j<topicKeywords[topic].length;j++){
          if(text.indexOf(topicKeywords[topic][j])>=0){
            topics[topic]=(topics[topic]||0)+1;
            break;
          }
        }
      }
    }
    var sortedTopics=Object.keys(topics).sort(function(a,b){return topics[b]-topics[a]});
    return{
      topics:topics,
      sortedTopics:sortedTopics,
      totalMsgs:active.length,
      totalChars:active.reduce(function(s,m){return s+(m.t||"").length},0)
    };
  }catch(e){return null}
}
function openTreePanel(){
  try{
    var box=$("treeOverlay");
    var body=$("treeBody");
    if(!box||!body)return;
    var data=generateInspirationTree();
    if(!data){
      body.innerHTML='<div style="text-align:center;color:#666;padding:40px;font-size:13px">暂无对话数据，开始聊天后灵感之树会生长～</div>';
      box.className="tree-overlay show";
      return;
    }
    var h="";
    h+='<div class="tree-canvas-box">';
    h+='<svg class="tree-svg" viewBox="0 0 300 280" preserveAspectRatio="xMidYMax meet">';
    var trunkHeight=Math.min(120,40+data.totalMsgs*2);
    var trunkY=270-trunkHeight;
    h+='<rect x="145" y="'+trunkY+'" width="10" height="'+trunkHeight+'" fill="rgba(139,90,43,0.4)" rx="3"/>';
    var branches=data.sortedTopics.slice(0,6);
    var branchColors=["#5cfca8","#7c5cfc","#fcb85c","#5cb4fc","#fc5c8a","#a78bfa"];
    for(var i=0;i<branches.length;i++){
      var angle=-60+i*(120/Math.max(branches.length-1,1));
      var rad=angle*Math.PI/180;
      var len=30+Math.min(40,topics_count(data,branches[i])*5);
      var bx1=150+Math.cos(rad)*15;
      var by1=trunkY+10;
      var bx2=150+Math.cos(rad)*(15+len);
      var by2=trunkY+10+Math.sin(rad)*len;
      h+='<line x1="'+bx1+'" y1="'+by1+'" x2="'+bx2+'" y2="'+by2+'" stroke="'+branchColors[i%6]+'" stroke-width="3" opacity="0.5" stroke-linecap="round"/>';
      var leafSize=8+Math.min(8,data.topics[branches[i]]*2);
      h+='<circle cx="'+bx2+'" cy="'+by2+'" r="'+leafSize+'" fill="'+branchColors[i%6]+'" opacity="0.3"/>';
      h+='<text x="'+bx2+'" y="'+(by2-leafSize-2)+'" text-anchor="middle" font-size="10" fill="'+branchColors[i%6]+'">'+branches[i]+'</text>';
    }
    if(branches.length===0){
      h+='<text x="150" y="200" text-anchor="middle" font-size="12" fill="#666">对话更多让树枝生长</text>';
    }
    h+='</svg></div>';
    h+='<div class="tree-stats">';
    h+='<div class="tree-stat"><div class="tree-stat-num">'+data.totalMsgs+'</div><div class="tree-stat-label">消息（养分）</div></div>';
    h+='<div class="tree-stat"><div class="tree-stat-num">'+data.sortedTopics.length+'</div><div class="tree-stat-label">话题分支</div></div>';
    h+='<div class="tree-stat"><div class="tree-stat-num">'+data.totalChars+'</div><div class="tree-stat-label">总字数</div></div>';
    h+='</div>';
    h+='<div class="tree-topics">';
    h+='<div class="tree-topics-title">🌿 生长的话题分支</div>';
    if(data.sortedTopics.length===0){
      h+='<div style="font-size:12px;color:#666;padding:8px">暂无明确话题，继续对话让树生长</div>';
    }else{
      for(var i=0;i<data.sortedTopics.length;i++){
        var t=data.sortedTopics[i];
        h+='<span class="tree-topic-tag">'+t+' ('+data.topics[t]+')</span>';
      }
    }
    h+='</div>';
    body.innerHTML=h;
    box.className="tree-overlay show";
  }catch(e){console.error("openTreePanel error:",e)}
}
function topics_count(data,topic){return data.topics[topic]||0}
function closeTreePanel(){try{var b=$("treeOverlay");if(b)b.className="tree-overlay"}catch(e){}}

