function generatePlanets(){
  try{
    var planets=[];
    for(var i=0;i<PRESET_ROLES.length&&i<8;i++){
      var role=PRESET_ROLES[i];
      var ms=msgs[role.id]||[];
      var active=ms.filter(function(m){return !m.rolled});
      if(active.length===0)continue;
      var totalChars=active.reduce(function(s,m){return s+(m.t||"").length},0);
      var size=Math.min(28,10+active.length*0.5);
      var orbitRadius=60+i*32;
      var colors=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#fc5c8a","#5cfcc8"];
      var types=["岩石行星","气态行星","冰晶行星","熔岩行星","海洋行星","沙漠行星","森林行星","水晶行星"];
      var moods=["活跃","平静","热情","神秘","温柔","冷峻","欢快","深沉"];
      planets.push({
        id:role.id,
        name:role.name,
        icon:role.avatar||"🌟",
        size:size,
        orbitRadius:orbitRadius,
        color:colors[i%8],
        type:types[i%8],
        mood:moods[i%8],
        msgs:active.length,
        chars:totalChars,
        angle:i*45
      });
    }
    return planets;
  }catch(e){return[]}
}
function openPlanetPanel(){
  try{
    var box=$("planetOverlay");
    var body=$("planetBody");
    if(!box||!body)return;
    var planets=generatePlanets();
    var h="";
    h+='<div class="planet-solar-system" id="solarSystem">';
    h+='<div class="planet-sun"></div>';
    for(var i=0;i<planets.length;i++){
      var p=planets[i];
      var d=p.orbitRadius*2;
      h+='<div class="planet-orbit" style="width:'+d+'px;height:'+d+'px"></div>';
      var px=Math.cos(p.angle*Math.PI/180)*p.orbitRadius;
      var py=Math.sin(p.angle*Math.PI/180)*p.orbitRadius;
      h+='<div class="planet-body-item" style="width:'+p.size+'px;height:'+p.size+'px;background:radial-gradient(circle at 30% 30%,'+p.color+',rgba(8,8,20,.8));left:calc(50% + '+px+'px - '+(p.size/2)+'px);top:calc(50% + '+py+'px - '+(p.size/2)+'px)" onclick="showPlanetInfo('+i+')"></div>';
    }
    h+='</div>';
    h+='<div class="planet-info" id="planetInfo">';
    h+='<div class="planet-info-name" id="planetInfoName">点击星球查看详情</div>';
    h+='</div>';
    h+='<div style="font-size:13px;color:#a78bfa;font-weight:600;margin-bottom:10px;padding:0 4px">🪐 星球列表 ('+planets.length+')</div>';
    h+='<div class="planet-list">';
    if(planets.length===0){
      h+='<div style="text-align:center;color:#666;padding:30px;font-size:12px">暂无星球，开始对话创建你的太阳系～</div>';
    }else{
      for(var i=0;i<planets.length;i++){
        var p=planets[i];
        h+='<div class="planet-list-item" onclick="showPlanetInfo('+i+')">';
        h+='<div class="planet-list-dot" style="background:'+p.color+'"></div>';
        h+='<div class="planet-list-info">';
        h+='<div class="planet-list-name">'+esc(p.name)+' · '+p.type+'</div>';
        h+='<div class="planet-list-desc">'+p.mood+' · '+p.msgs+'条消息 · '+p.chars+'字</div>';
        h+='</div></div>';
      }
    }
    h+='</div>';
    body.innerHTML=h;
    box.className="planet-overlay show";
    body._planets=planets;
  }catch(e){console.error("openPlanetPanel error:",e)}
}
