// ==========================================================================
var MUSIC_NOTES=[{n:"do",f:262,e:"do"},{n:"re",f:294,e:"re"},{n:"mi",f:330,e:"mi"},{n:"fa",f:349,e:"fa"},{n:"sol",f:392,e:"sol"},{n:"la",f:440,e:"la"},{n:"si",f:494,e:"si"}];
var musicGenerated=[];
var musicPlaying=false;
var musicTempo=400;
function generateConversationMusic(){
  try{
    if(!curRole)return [];
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(active.length===0)return [];
    var notes=[];
    for(var i=0;i<active.length&&i<16;i++){
      var t=active[i].t||"";
      var len=t.length;
      var noteIdx=Math.min(6,Math.floor(len/15));
      var isUser=active[i].role==="user";
      if(isUser)noteIdx=(noteIdx+3)%7;
      notes.push(MUSIC_NOTES[noteIdx]);
    }
    return notes;
  }catch(e){return[]}
}
function openMusicPanel(){
  try{
    var box=$("musicOverlay");
    var body=$("musicBody");
    if(!box||!body)return;
    musicGenerated=generateConversationMusic();
    var h="";
    h+='<div class="music-visual" id="musicVisual">';
    if(musicGenerated.length===0){
      h+='<div style="text-align:center;color:#666;padding:40px;font-size:13px">暂无对话数据，开始聊天生成音乐～</div>';
    }else{
      for(var i=0;i<musicGenerated.length;i++){
        var height=20+Math.random()*80;
        var colors=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#5cfcc8"];
        h+='<div class="music-bar" style="height:'+height+'px;background:'+colors[i%7]+'" id="musicBar_'+i+'"></div>';
      }
    }
    h+='</div>';
    h+='<div class="music-controls">';
    h+='<div class="music-btn" onclick="playConversationMusic()">▶️ 播放</div>';
    h+='<div class="music-btn" onclick="stopConversationMusic()">⏹ 停止</div>';
    h+='</div>';
    h+='<div class="music-tempo-box">';
    h+='<div class="music-tempo-label"><span>节奏速度</span><span id="musicTempoVal">中速</span></div>';
    h+='<input type="range" class="music-tempo-slider" min="150" max="800" step="50" value="'+musicTempo+'" oninput="musicTempo=parseInt(this.value);$(\'musicTempoVal\').textContent=musicTempo<300?\'快速\':musicTempo<550?\'中速\':\'慢速\'">';
    h+='</div>';
    h+='<div class="music-notes">';
    if(musicGenerated.length===0){
      h+='<div style="color:#666;font-size:12px;padding:20px">对话越多，旋律越丰富</div>';
    }else{
      for(var i=0;i<musicGenerated.length;i++){
        var colors=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#5cfcc8"];
        h+='<div class="music-note" style="background:'+colors[i%7]+'20;color:'+colors[i%7]+'" onclick="playSingleNote('+i+')">'+musicGenerated[i].n+'</div>';
      }
    }
    h+='</div>';
    h+='<div class="music-info">';
    h+='<div>🎼 旋律由 '+musicGenerated.length+' 个音符组成，基于对话消息长度生成</div>';
    h+='<div>🎵 用户消息和AI消息使用不同音域，形成对话感的旋律</div>';
    h+='</div>';
    body.innerHTML=h;
    box.className="music-overlay show";
  }catch(e){console.error("openMusicPanel error:",e)}
}
function playSingleNote(idx){
  try{
    if(!musicGenerated[idx])return;
    if(!window.AudioContext&&!window.webkitAudioContext)return;
    var ctx=window.AudioContext||window.webkitAudioContext;
    if(!window._musicCtx)window._musicCtx=new ctx();
    var osc=window._musicCtx.createOscillator();
    var gain=window._musicCtx.createGain();
    osc.frequency.value=musicGenerated[idx].f;
    osc.type="sine";
    gain.gain.setValueAtTime(0.3,window._musicCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01,window._musicCtx.currentTime+0.5);
    osc.connect(gain);
    gain.connect(window._musicCtx.destination);
    osc.start();
    osc.stop(window._musicCtx.currentTime+0.5);
    var bar=$("musicBar_"+idx);
    if(bar){bar.style.transform="scaleY(1.3)";setTimeout(function(){bar.style.transform="scaleY(1)"},300)}
  }catch(e){}
}
function playConversationMusic(){
  try{
    if(musicPlaying||musicGenerated.length===0)return;
    musicPlaying=true;
    var i=0;
    function playNext(){
      if(!musicPlaying||i>=musicGenerated.length){musicPlaying=false;return}
      playSingleNote(i);
      var bar=$("musicBar_"+i);
      if(bar){bar.style.opacity="1";bar.style.transform="scaleY(1.3)"}
      if(i>0){var prev=$("musicBar_"+(i-1));if(prev){prev.style.opacity="0.5";prev.style.transform="scaleY(1)"}}
      i++;
      setTimeout(playNext,musicTempo);
    }
    playNext();
  }catch(e){}
}
function stopConversationMusic(){musicPlaying=false}
function closeMusicPanel(){try{stopConversationMusic();var b=$("musicOverlay");if(b)b.className="music-overlay"}catch(e){}}

