var mazeData=null;
var mazePlayer={x:0,y:0};
var mazeMoves=0;
var mazeStartTime=0;
var mazeWon=false;
var MAZE_SIZE=7;
function generateMaze(){
  try{
    var grid=[];
    for(var y=0;y<MAZE_SIZE;y++){
      grid[y]=[];
      for(var x=0;x<MAZE_SIZE;x++){
        var isWall=Math.random()<0.3;
        if((x===0&&y===0)||(x===MAZE_SIZE-1&&y===MAZE_SIZE-1))isWall=false;
        grid[y][x]=isWall?1:0;
      }
    }
    grid[0][0]=0;
    grid[MAZE_SIZE-1][MAZE_SIZE-1]=2;
    return grid;
  }catch(e){return[]}
}
function openMazePanel(){
  try{
    var box=$("mazeOverlay");
    var body=$("mazeBody");
    if(!box||!body)return;
    mazeData=generateMaze();
    mazePlayer={x:0,y:0};
    mazeMoves=0;
    mazeStartTime=Date.now();
    mazeWon=false;
    renderMaze();
    box.className="maze-overlay show";
  }catch(e){console.error("openMazePanel error:",e)}
}
function renderMaze(){
  try{
    var body=$("mazeBody");
    if(!body||!mazeData)return;
    var elapsed=Math.floor((Date.now()-mazeStartTime)/1000);
    var h="";
    h+='<div class="maze-stats">';
    h+='<div class="maze-stat"><div class="maze-stat-num">'+mazeMoves+'</div><div class="maze-stat-label">步数</div></div>';
    h+='<div class="maze-stat"><div class="maze-stat-num">'+elapsed+'s</div><div class="maze-stat-label">用时</div></div>';
    h+='<div class="maze-stat"><div class="maze-stat-num">'+(mazeWon?"✅":"🎮")+'</div><div class="maze-stat-label">状态</div></div>';
    h+='</div>';
    h+='<div class="maze-canvas-box">';
    h+='<div class="maze-grid" style="grid-template-columns:repeat('+MAZE_SIZE+',28px)">';
    for(var y=0;y<MAZE_SIZE;y++){
      for(var x=0;x<MAZE_SIZE;x++){
        var cls="maze-cell ";
        if(mazeData[y][x]===1)cls+="wall";
        else if(mazeData[y][x]===2)cls+="goal";
        else if(mazePlayer.x===x&&mazePlayer.y===y)cls+="player";
        else cls+="path";
        var icon="";
        if(mazePlayer.x===x&&mazePlayer.y===y)icon="🧑";
        else if(mazeData[y][x]===2)icon="🎯";
        else if(mazeData[y][x]===1)icon="🧱";
        h+='<div class="'+cls+'">'+icon+'</div>';
      }
    }
    h+='</div></div>';
    if(mazeWon){
      h+='<div style="text-align:center;padding:16px;background:rgba(92,252,168,.06);border-radius:14px;margin-bottom:12px">';
      h+='<div style="font-size:32px;margin-bottom:4px">🎉</div>';
      h+='<div style="font-size:14px;color:#5cfca8;font-weight:700">恭喜通关！</div>';
      h+='<div style="font-size:12px;color:#888;margin-top:4px">用时'+elapsed+'秒，共'+mazeMoves+'步</div>';
      h+='</div>';
    }
    h+='<div class="maze-controls">';
    h+='<div></div><div class="maze-ctrl-btn" onclick="moveMazePlayer(0,-1)">⬆️</div><div></div>';
    h+='<div class="maze-ctrl-btn" onclick="moveMazePlayer(-1,0)">⬅️</div>';
    h+='<div class="maze-ctrl-btn" onclick="moveMazePlayer(0,1)">⬇️</div>';
    h+='<div class="maze-ctrl-btn" onclick="moveMazePlayer(1,0)">➡️</div>';
    h+='</div>';
    h+='<div class="maze-ctrl-btn" style="max-width:200px;margin:0 auto" onclick="openMazePanel()">🔄 重新生成</div>';
    body.innerHTML=h;
  }catch(e){}
}
function moveMazePlayer(dx,dy){
  try{
    if(mazeWon||!mazeData)return;
    var nx=mazePlayer.x+dx;
    var ny=mazePlayer.y+dy;
    if(nx<0||ny<0||nx>=MAZE_SIZE||ny>=MAZE_SIZE)return;
    if(mazeData[ny][nx]===1)return;
    mazePlayer.x=nx;
    mazePlayer.y=ny;
    mazeMoves++;
    if(mazeData[ny][nx]===2){
      mazeWon=true;
      showToast("🎉 迷宫通关！");
    }
    renderMaze();
  }catch(e){}
}
function closeMazePanel(){try{var b=$("mazeOverlay");if(b)b.className="maze-overlay"}catch(e){}}

