// ==========================================================================
var RAINBOW_EMOTIONS=[
  {color:"#fc6b6b",label:"愤怒",keywords:["生气","愤怒","讨厌","烦","气","恨","怒"]},
  {color:"#fcb85c",label:"快乐",keywords:["开心","快乐","哈哈","笑","高兴","好玩","有趣","棒"]},
  {color:"#5cfca8",label:"平静",keywords:["好的","嗯","知道","明白","理解","可以","行"]},
  {color:"#5cb4fc",label:"忧伤",keywords:["难过","伤心","哭","悲伤","孤独","失落","心痛"]},
  {color:"#a78bfa",label:"思考",keywords:["为什么","怎么","什么","思考","想","觉得","认为"]},
  {color:"#fc5c8a",label:"爱意",keywords:["喜欢","爱","想你","心动","温暖","幸福","甜蜜"]},
  {color:"#5cfcc8",label:"惊喜",keywords:["哇","天啊","真的吗","不可思议","没想到","居然"]},
  {color:"#fcb85c",label:"恐惧",keywords:["害怕","恐惧","担心","紧张","可怕","吓"]}
];
function generateRainbowData(){
  try{
    if(!curRole)return null;
    var ms=msgs[curRole.id]||[];
    var active=ms.filter(function(m){return !m.rolled});
    if(active.length===0)return null;
    var emotionCounts={};
    for(var i=0;i<RAINBOW_EMOTIONS.length;i++)emotionCounts[i]=0;
    for(var i=0;i<active.length;i++){
      var text=active[i].t||"";
      for(var e=0;e<RAINBOW_EMOTIONS.length;e++){
        var emo=RAINBOW_EMOTIONS[e];
        for(var k=0;k<emo.keywords.length;k++){
          if(text.indexOf(emo.keywords[k])>=0){emotionCounts[e]++;break}
        }
      }
    }
    var total=0;
    for(var e in emotionCounts)total+=emotionCounts[e];
    if(total===0)total=1;
    return{counts:emotionCounts,total:total,msgs:active.length};
  }catch(e){return null}
}
function openRainbowPanel(){
  try{
    var box=$("rainbowOverlay");
    var body=$("rainbowBody");
    if(!box||!body)return;
    var data=generateRainbowData();
    if(!data){
      body.innerHTML='<div style="text-align:center;color:#666;padding:40px;font-size:13px">暂无对话数据，开始聊天建造彩虹桥～</div>';
      box.className="rainbow-overlay show";
      return;
    }
    var h="";
    h+='<div class="rainbow-bridge">';
    var maxR=140;
    for(var i=0;i<RAINBOW_EMOTIONS.length;i++){
      var emo=RAINBOW_EMOTIONS[i];
      var count=data.counts[i]||0;
      if(count===0)continue;
      var radius=maxR-i*16;
      h+='<div class="rainbow-arc" style="width:'+(radius*2)+'px;height:'+radius+'px;border:'+ (16)+'px solid '+emo.color+';opacity:'+(0.15+count/data.total*0.3)+'"></div>';
    }
    h+='</div>';
    h+='<div class="rainbow-spectrum">';
    for(var i=0;i<RAINBOW_EMOTIONS.length;i++){
      var emo=RAINBOW_EMOTIONS[i];
      var count=data.counts[i]||0;
      var pct=data.total>0?Math.round(count/data.total*100):0;
      if(count>0){
        h+='<div class="rainbow-spectrum-seg" style="background:'+emo.color+';flex:'+(count||1)+'">'+pct+'%</div>';
      }
    }
    h+='</div>';
    h+='<div class="rainbow-legend">';
    for(var i=0;i<RAINBOW_EMOTIONS.length;i++){
      var emo=RAINBOW_EMOTIONS[i];
      var count=data.counts[i]||0;
      h+='<div class="rainbow-legend-item"><div class="rainbow-dot" style="background:'+emo.color+'"></div>'+emo.label+' ('+count+')</div>';
    }
    h+='</div>';
    var sortedIdx=Object.keys(data.counts).sort(function(a,b){return data.counts[b]-data.counts[a]});
    var dominant=RAINBOW_EMOTIONS[sortedIdx[0]];
    var dominantCount=data.counts[sortedIdx[0]];
    var dominantPct=Math.round(dominantCount/data.total*100);
    h+='<div class="rainbow-dominant">';
    h+='<div class="rainbow-dominant-title">🌈 彩虹桥分析</div>';
    h+='<div class="rainbow-dominant-text">基于'+data.msgs+'条对话分析，你的情绪彩虹以 <span style="color:'+dominant.color+';font-weight:600">'+dominant.label+'</span> 为主色调，占比'+dominantPct+'%。';
    if(dominantPct>50){
      h+='这段对话充满了'+dominant.label+'的色彩，是一段非常鲜明情感的对话。';
    }else{
      h+='情绪色彩较为丰富多元，是一段层次分明的对话。';
    }
    h+='</div></div>';
    body.innerHTML=h;
    box.className="rainbow-overlay show";
  }catch(e){console.error("openRainbowPanel error:",e)}
}
function closeRainbowPanel(){try{var b=$("rainbowOverlay");if(b)b.className="rainbow-overlay"}catch(e){}}

