// ==========================================================================
// ===== v3.16.0 对话方块消除 =====
// ==========================================================================
var BLOCK_EMOJIS=["😄","😢","😡","😍","🤔","😴"];
var BLOCK_COLORS=["#fcb85c","#5cb4fc","#fc6b6b","#fc5c8a","#a78bfa","#5cfcc8"];
var blockGrid=[];
var BLOCK_ROWS=8;
var BLOCK_COLS=6;
var blockScore=0;
var blockCombo=0;
var blockSelected=null;
var blockMoves=0;
function initBlockGrid(){
  try{
    blockGrid=[];
    for(var r=0;r<BLOCK_ROWS;r++){
      blockGrid[r]=[];
      for(var c=0;c<BLOCK_COLS;c++){
        blockGrid[r][c]=Math.floor(Math.random()*BLOCK_EMOJIS.length);
      }
    }
    blockScore=0;
    blockCombo=0;
    blockSelected=null;
    blockMoves=0;
  }catch(e){}
}
function openBlockPanel(){
  try{
    var box=$("blockOverlay");
    var body=$("blockBody");
    if(!box||!body)return;
    var saved=lsGet("blockBest")||0;
    initBlockGrid();
    renderBlock();
    box.className="block-overlay show";
  }catch(e){console.error("openBlockPanel error:",e)}
}
function renderBlock(){
  try{
    var body=$("blockBody");
    if(!body)return;
    var best=lsGet("blockBest")||0;
    var h="";
    h+='<div class="block-stats">';
    h+='<div class="block-stat"><div class="block-stat-num">'+blockScore+'</div><div class="block-stat-label">分数</div></div>';
    h+='<div class="block-stat"><div class="block-stat-num">'+blockMoves+'</div><div class="block-stat-label">步数</div></div>';
    h+='<div class="block-stat"><div class="block-stat-num">'+best+'</div><div class="block-stat-label">最高分</div></div>';
    h+='</div>';
    h+='<div class="block-game-area">';
    h+='<div class="block-grid">';
    for(var r=0;r<BLOCK_ROWS;r++){
      for(var c=0;c<BLOCK_COLS;c++){
        var val=blockGrid[r][c];
        var cls="block-cell";
        if(val===-1)cls+=" empty";
        if(blockSelected&&blockSelected.r===r&&blockSelected.c===c)cls+=" selected";
        var style=val>=0?("background:"+BLOCK_COLORS[val]+"30;border:1px solid "+BLOCK_COLORS[val]+"50"):"";
        h+='<div class="'+cls+'" style="'+style+'" onclick="clickBlock('+r+','+c+')">';
        if(val>=0)h+='<span class="block-emoji">'+BLOCK_EMOJIS[val]+'</span>';
        h+='</div>';
      }
    }
    h+='</div></div>';
    h+='<div class="block-restart-btn" onclick="initBlockGrid();renderBlock()">🔄 重新开始</div>';
    body.innerHTML=h;
  }catch(e){}
}
function clickBlock(r,c){
  try{
    if(blockGrid[r][c]<0)return;
    if(!blockSelected){
      blockSelected={r:r,c:c};
      renderBlock();
    }else{
      var dr=Math.abs(blockSelected.r-r);
      var dc=Math.abs(blockSelected.c-c);
      if((dr===1&&dc===0)||(dr===0&&dc===1)){
        var tmp=blockGrid[blockSelected.r][blockSelected.c];
        blockGrid[blockSelected.r][blockSelected.c]=blockGrid[r][c];
        blockGrid[r][c]=tmp;
        blockMoves++;
        var cleared=checkBlockMatches();
        if(cleared>0){
          blockScore+=cleared*10*++blockCombo;
        }else{
          tmp=blockGrid[blockSelected.r][blockSelected.c];
          blockGrid[blockSelected.r][blockSelected.c]=blockGrid[r][c];
          blockGrid[r][c]=tmp;
          blockCombo=0;
        }
        blockSelected=null;
        var best=lsGet("blockBest")||0;
        if(blockScore>best)lsSet("blockBest",blockScore);
        renderBlock();
      }else{
        blockSelected={r:r,c:c};
        renderBlock();
      }
    }
  }catch(e){}
}
function checkBlockMatches(){
  try{
    var toClear={};
    var totalCleared=0;
    for(var r=0;r<BLOCK_ROWS;r++){
      var runStart=0;
      for(var c=1;c<=BLOCK_COLS;c++){
        if(c===BLOCK_COLS||blockGrid[r][c]!==blockGrid[r][runStart]||blockGrid[r][c]<0){
          if(c-runStart>=3&&blockGrid[r][runStart]>=0){
            for(var cc=runStart;cc<c;cc++)toClear[r+"_"+cc]=1;
          }
          runStart=c;
        }
      }
    }
    for(var c=0;c<BLOCK_COLS;c++){
      var runStart=0;
      for(var r=1;r<=BLOCK_ROWS;r++){
        if(r===BLOCK_ROWS||blockGrid[r][c]!==blockGrid[runStart][c]||blockGrid[r][c]<0){
          if(r-runStart>=3&&blockGrid[runStart][c]>=0){
            for(var rr=runStart;rr<r;rr++)toClear[rr+"_"+c]=1;
          }
          runStart=r;
        }
      }
    }
    for(var key in toClear){
      var parts=key.split("_");
      var r=parseInt(parts[0]),c=parseInt(parts[1]);
      blockGrid[r][c]=-1;
      totalCleared++;
    }
    if(totalCleared>0){
      for(var c=0;c<BLOCK_COLS;c++){
        var colVals=[];
        for(var r=BLOCK_ROWS-1;r>=0;r--){
          if(blockGrid[r][c]>=0)colVals.push(blockGrid[r][c]);
        }
        for(var r=BLOCK_ROWS-1;r>=0;r--){
          var idx=BLOCK_ROWS-1-r;
          blockGrid[r][c]=idx<colVals.length?colVals[idx]:Math.floor(Math.random()*BLOCK_EMOJIS.length);
        }
      }
    }
    return totalCleared;
  }catch(e){return 0}
}
function closeBlockPanel(){try{var b=$("blockOverlay");if(b)b.className="block-overlay"}catch(e){}}

