// ===== v3.18.0 AI对话绘画板 =====
// ==========================================================================
var drawbdColor="#7c5cfc";
var drawbdSize=3;
var drawbdIsDrawing=false;
var drawbdCtx=null;
var drawbdLastX=0,drawbdLastY=0;
var DRAWBD_COLORS=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#fc5c8a","#5cfcc8","#ffffff","#000000"];
function openDrawbdPanel(){
  try{
    var box=$("drawbdOverlay");
    var body=$("drawbdBody");
    if(!box||!body)return;
    var h="";
    h+='<div class="drawbd-canvas-box">';
    h+='<canvas class="drawbd-canvas" id="drawbdCanvas" width="320" height="320"></canvas>';
    h+='</div>';
    h+='<div class="drawbd-colors">';
    for(var i=0;i<DRAWBD_COLORS.length;i++){
      h+='<div class="drawbd-color'+(DRAWBD_COLORS[i]===drawbdColor?" active":"")+'" style="background:'+DRAWBD_COLORS[i]+'" onclick="setDrawbdColor(\''+DRAWBD_COLORS[i]+'\')"></div>';
    }
    h+='</div>';
    h+='<div class="drawbd-size-box">';
    h+='<div class="drawbd-size-label">画笔大小</div>';
    h+='<input type="range" class="drawbd-size-slider" min="1" max="20" value="'+drawbdSize+'" oninput="drawbdSize=parseInt(this.value);$(\'drawbdSizeVal\').textContent=this.value">';
    h+='<div class="drawbd-size-val" id="drawbdSizeVal">'+drawbdSize+'</div>';
    h+='</div>';
    h+='<div class="drawbd-tools">';
    h+='<div class="drawbd-tool" onclick="clearDrawbdCanvas()">🗑️ 清空</div>';
    h+='<div class="drawbd-tool" onclick="eraserDrawbd()">🧽 橡皮</div>';
    h+='<div class="drawbd-tool" onclick="saveDrawbdCanvas()">💾 保存</div>';
    h+='</div>';
    body.innerHTML=h;
    box.className="drawbd-overlay show";
    setTimeout(initDrawbdCanvas,100);
  }catch(e){console.error("openDrawbdPanel error:",e)}
}
function initDrawbdCanvas(){
  try{
    var canvas=$("drawbdCanvas");
    if(!canvas)return;
    drawbdCtx=canvas.getContext("2d");
    drawbdCtx.fillStyle="#fff";
    drawbdCtx.fillRect(0,0,320,320);
    drawbdCtx.lineCap="round";
    drawbdCtx.lineJoin="round";
    canvas.addEventListener("touchstart",function(e){
      e.preventDefault();
      drawbdIsDrawing=true;
      var rect=canvas.getBoundingClientRect();
      var touch=e.touches[0];
      drawbdLastX=(touch.clientX-rect.left)*(320/rect.width);
      drawbdLastY=(touch.clientY-rect.top)*(320/rect.height);
    },{passive:false});
    canvas.addEventListener("touchmove",function(e){
      e.preventDefault();
      if(!drawbdIsDrawing||!drawbdCtx)return;
      var rect=canvas.getBoundingClientRect();
      var touch=e.touches[0];
      var x=(touch.clientX-rect.left)*(320/rect.width);
      var y=(touch.clientY-rect.top)*(320/rect.height);
      drawbdCtx.strokeStyle=drawbdColor;
      drawbdCtx.lineWidth=drawbdSize;
      drawbdCtx.beginPath();
      drawbdCtx.moveTo(drawbdLastX,drawbdLastY);
      drawbdCtx.lineTo(x,y);
      drawbdCtx.stroke();
      drawbdLastX=x;drawbdLastY=y;
    },{passive:false});
    canvas.addEventListener("touchend",function(){drawbdIsDrawing=false},{passive:false});
  }catch(e){}
}
function setDrawbdColor(color){
  drawbdColor=color;
  var btns=document.querySelectorAll(".drawbd-color");
  for(var i=0;i<btns.length;i++){
    btns[i].className="drawbd-color"+(btns[i].style.backgroundColor===color?" active":"");
  }
}
function clearDrawbdCanvas(){try{if(drawbdCtx){drawbdCtx.fillStyle="#fff";drawbdCtx.fillRect(0,0,320,320)}}catch(e){}}
function eraserDrawbd(){
  drawbdColor="#ffffff";
  var btns=document.querySelectorAll(".drawbd-color");
  for(var i=0;i<btns.length;i++)btns[i].className="drawbd-color";
}
function saveDrawbdCanvas(){
  try{
    var canvas=$("drawbdCanvas");
    if(!canvas)return;
    var dataUrl=canvas.toDataURL("image/png");
    var gallery=lsGet("drawbdGallery")||[];
    gallery.push({img:dataUrl,ts:Date.now()});
    if(gallery.length>20)gallery=gallery.slice(-20);
    lsSet("drawbdGallery",gallery);
    showToast("画作已保存到画廊！");
  }catch(e){showToast("保存失败")}
}
function closeDrawbdPanel(){try{var b=$("drawbdOverlay");if(b)b.className="drawbd-overlay"}catch(e){}}

