// ===== v3.18.0 对话飞行棋 =====
// ==========================================================================
var flychessPlayers=[{name:"你",emoji:"🧑",pos:0,color:"#7c5cfc"},{name:"AI",emoji:"🤖",pos:0,color:"#5cfca8"}];
var flychessCurrent=0;
var flychessDice=0;
var flychessLog=[];
var flychessBoard=[];
var FLYCHESS_SPECIAL={5:"🚀+3",10:"⭐+2",12:"🐌-2",15:"🌈+3",18:"💨+2",20:"🌀-3",22:"🎁+2"};
var FLYCHESS_CELLS=25;
function openFlychessPanel(){
  try{
    flychessPlayers=[{name:"你",emoji:"🧑",pos:0,color:"#7c5cfc"},{name:"AI",emoji:"🤖",pos:0,color:"#5cfca8"}];
    flychessCurrent=0;
    flychessDice=0;
    flychessLog=[];
    flychessBoard=[];
    for(var i=0;i<FLYCHESS_CELLS;i++)flychessBoard.push(FLYCHESS_SPECIAL[i]||"");
    renderFlychess();
    $("flychessOverlay").className="flychess-overlay show";
  }catch(e){console.error("openFlychessPanel:",e)}
}
function renderFlychess(){
  try{
    var body=$("flychessBody");
    if(!body)return;
    var h="";
    h+='<div class="flychess-info">';
    for(var i=0;i<flychessPlayers.length;i++){
      h+='<div class="flychess-player'+(i===flychessCurrent?" active":"")+'">';
      h+='<div class="flychess-player-name">'+flychessPlayers[i].emoji+' '+flychessPlayers[i].name+'</div>';
      h+='<div class="flychess-player-pos">位置: '+flychessPlayers[i].pos+'/'+(FLYCHESS_CELLS-1)+'</div>';
      h+='</div>';
    }
    h+='</div>';
    h+='<div class="flychess-board">';
    h+='<div class="flychess-grid">';
    for(var i=0;i<FLYCHESS_CELLS;i++){
      var cls="flychess-cell ";
      if(i===0)cls+="start";
      else if(i===FLYCHESS_CELLS-1)cls+="end";
      else if(FLYCHESS_SPECIAL[i])cls+="special";
      else cls+="normal";
      var pawns="";
      for(var p=0;p<flychessPlayers.length;p++){
        if(flychessPlayers[p].pos===i)pawns+=flychessPlayers[p].emoji;
      }
      h+='<div class="'+cls+'">';
      if(FLYCHESS_SPECIAL[i])h+='<div class="flychess-emoji">'+FLYCHESS_SPECIAL[i].split(/[-+]/)[0]+'</div>';
      h+='<div style="font-size:11px">'+pawns+'</div>';
      h+='</div>';
    }
    h+='</div>';
    h+='</div>';
    h+='<div class="flychess-dice-area">';
    h+='<div class="flychess-dice" onclick="rollFlychessDice()">'+(flychessDice>0?flychessDice:"🎲")+'</div>';
    h+='</div>';
    h+='<div class="flychess-roll-btn" onclick="rollFlychessDice()">'+(flychessCurrent===0?"掷骰子":"AI回合中...")+'</div>';
    h+='<div class="flychess-log" id="flychessLog">';
    for(var i=flychessLog.length-1;i>=0&&i>=flychessLog.length-6;i--){
      h+='<div class="flychess-log-item">'+flychessLog[i]+'</div>';
    }
    h+='</div>';
    body.innerHTML=h;
  }catch(e){}
}
function rollFlychessDice(){
  try{
    if(flychessCurrent!==0)return;
    flychessDice=Math.floor(Math.random()*6)+1;
    flychessLog.push(flychessPlayers[0].name+"掷出"+flychessDice+"点");
    moveFlychessPlayer(0,flychessDice);
    renderFlychess();
    if(flychessPlayers[0].pos>=FLYCHESS_CELLS-1){
      flychessLog.push("🎉 你赢了！");
      renderFlychess();
      showToast("🎉 恭喜你赢了！");
      return;
    }
    flychessCurrent=1;
    renderFlychess();
    setTimeout(aiFlychessTurn,1500);
  }catch(e){}
}
function aiFlychessTurn(){
  try{
    flychessDice=Math.floor(Math.random()*6)+1;
    flychessLog.push(flychessPlayers[1].name+"掷出"+flychessDice+"点");
    moveFlychessPlayer(1,flychessDice);
    renderFlychess();
    if(flychessPlayers[1].pos>=FLYCHESS_CELLS-1){
      flychessLog.push("🤖 AI赢了！");
      renderFlychess();
      showToast("🤖 AI赢了，再来一局吧！");
      return;
    }
    flychessCurrent=0;
    renderFlychess();
  }catch(e){}
}
function moveFlychessPlayer(idx,steps){
  try{
    var np=flychessPlayers[idx].pos+steps;
    if(np>FLYCHESS_CELLS-1)np=FLYCHESS_CELLS-1;
    flychessPlayers[idx].pos=np;
    if(FLYCHESS_SPECIAL[np]){
      var sp=FLYCHESS_SPECIAL[np];
      var sign=sp.match(/[-+]/)[0];
      var val=parseInt(sp.match(/\d+/)[0]);
      if(sign==="+"){
        flychessPlayers[idx].pos=Math.min(FLYCHESS_CELLS-1,flychessPlayers[idx].pos+val);
        flychessLog.push(flychessPlayers[idx].name+"触发"+sp+"→前进"+val);
      }else{
        flychessPlayers[idx].pos=Math.max(0,flychessPlayers[idx].pos-val);
        flychessLog.push(flychessPlayers[idx].name+"触发"+sp+"→后退"+val);
      }
    }
  }catch(e){}
}
function closeFlychessPanel(){try{var b=$("flychessOverlay");if(b)b.className="flychess-overlay"}catch(e){}}

// ==========================================================================
// ===== v3.18.0 AI角色养成农场 =====
// ==========================================================================
var farmPlots=[];
var farmCoins=100;
var farmSelectedSeed=0;
var FARM_SEEDS=[
  {name:"小麦",emoji:"🌾",cost:5,growTime:30000,reward:15},
  {name:"胡萝卜",emoji:"🥕",cost:10,growTime:60000,reward:30},
  {name:"番茄",emoji:"🍅",cost:15,growTime:90000,reward:50},
  {name:"草莓",emoji:"🍓",cost:20,growTime:120000,reward:70},
  {name:"西瓜",emoji:"🍉",cost:30,growTime:180000,reward:120}
];
function openFarmPanel(){
  try{
    var saved=lsGet("farmData");
    if(saved){
      farmPlots=saved.plots||[];
      farmCoins=saved.coins||100;
    }
    if(farmPlots.length===0){
      for(var i=0;i<9;i++)farmPlots.push({seed:-1,plantTime:0});
    }
    renderFarm();
    $("farmOverlay").className="farm-overlay show";
  }catch(e){console.error("openFarmPanel:",e)}
}
function renderFarm(){
  try{
    var body=$("farmBody");
    if(!body)return;
    var h="";
    h+='<div class="farm-stats">';
    h+='<div class="farm-stat"><div class="farm-stat-num" id="farmCoins">'+farmCoins+'</div><div class="farm-stat-label">金币</div></div>';
    h+='<div class="farm-stat"><div class="farm-stat-num" id="farmHarvest">'+getFarmHarvestCount()+'</div><div class="farm-stat-label">可收获</div></div>';
    h+='<div class="farm-stat"><div class="farm-stat-num" id="farmTotal">'+getFarmTotalHarvested()+'</div><div class="farm-stat-label">总收获</div></div>';
    h+='</div>';
    h+='<div class="farm-grid">';
    var now=Date.now();
    for(var i=0;i<farmPlots.length;i++){
      var plot=farmPlots[i];
      var cls="farm-plot ";
      var emoji="🌱";
      var stage="";
      if(plot.seed<0){
        cls+="farm-plot-empty";
        emoji="🟫";
      }else{
        var seed=FARM_SEEDS[plot.seed];
        var elapsed=now-plot.plantTime;
        var progress=elapsed/seed.growTime;
        if(progress>=1){
          cls+="ready";
          emoji=seed.emoji;
          stage="可收获";
        }else{
          cls+="growing";
          if(progress<0.3)emoji="🌱";
          else if(progress<0.7)emoji="🌿";
          else emoji="🍃";
          stage=Math.floor(progress*100)+"%";
        }
      }
      h+='<div class="'+cls+'" onclick="onFarmPlotClick('+i+')">';
      h+='<div>'+emoji+'</div>';
      if(stage)h+='<div class="farm-plot-stage">'+stage+'</div>';
      h+='</div>';
    }
    h+='</div>';
    h+='<div style="font-size:12px;color:#888;margin-bottom:8px;text-align:center">选择种子种植</div>';
    h+='<div class="farm-seeds">';
    for(var i=0;i<FARM_SEEDS.length;i++){
      h+='<div class="farm-seed'+(i===farmSelectedSeed?" selected":"")+'" onclick="farmSelectedSeed='+i+';renderFarm()">';
      h+=FARM_SEEDS[i].emoji+" "+FARM_SEEDS[i].name+" 💰"+FARM_SEEDS[i].cost;
      h+='</div>';
    }
    h+='</div>';
    h+='<div class="farm-action-btn" onclick="harvestAllFarm()">🌾 全部收获</div>';
    body.innerHTML=h;
    saveFarmData();
  }catch(e){}
}
function onFarmPlotClick(idx){
  try{
    var plot=farmPlots[idx];
    var now=Date.now();
    if(plot.seed<0){
      var seed=FARM_SEEDS[farmSelectedSeed];
      if(farmCoins>=seed.cost){
        farmCoins-=seed.cost;
        plot.seed=farmSelectedSeed;
        plot.plantTime=now;
        showToast("种下了"+seed.name+"！");
      }else{
        showToast("金币不足！");
      }
    }else{
      var seed=FARM_SEEDS[plot.seed];
      var elapsed=now-plot.plantTime;
      if(elapsed>=seed.growTime){
        farmCoins+=seed.reward;
        plot.seed=-1;
        plot.plantTime=0;
        var total=lsGet("farmTotalHarvested")||0;
        lsSet("farmTotalHarvested",total+1);
        showToast("收获"+seed.name+"！+"+seed.reward+"金币");
      }else{
        showToast("还在生长中...");
      }
    }
    renderFarm();
  }catch(e){}
}
function harvestAllFarm(){
  try{
    var now=Date.now();
    var count=0;
    var earned=0;
    for(var i=0;i<farmPlots.length;i++){
      var plot=farmPlots[i];
      if(plot.seed>=0){
        var seed=FARM_SEEDS[plot.seed];
        if(now-plot.plantTime>=seed.growTime){
          farmCoins+=seed.reward;
          plot.seed=-1;
          plot.plantTime=0;
          count++;
          earned+=seed.reward;
        }
      }
    }
    if(count>0){
      var total=lsGet("farmTotalHarvested")||0;
      lsSet("farmTotalHarvested",total+count);
      showToast("收获"+count+"个作物！+"+earned+"金币");
    }else{
      showToast("没有可收获的作物");
    }
    renderFarm();
  }catch(e){}
}
function getFarmHarvestCount(){
  var now=Date.now();
  var c=0;
  for(var i=0;i<farmPlots.length;i++){
    if(farmPlots[i].seed>=0){
      var seed=FARM_SEEDS[farmPlots[i].seed];
      if(now-farmPlots[i].plantTime>=seed.growTime)c++;
    }
  }
  return c;
}
function getFarmTotalHarvested(){return lsGet("farmTotalHarvested")||0}
function saveFarmData(){try{lsSet("farmData",{plots:farmPlots,coins:farmCoins})}catch(e){}}
function closeFarmPanel(){try{saveFarmData();var b=$("farmOverlay");if(b)b.className="farm-overlay"}catch(e){}}

// ==========================================================================
// ===== v3.18.0 对话万花筒 =====
// ==========================================================================
var kaleidoCtx=null;
var kaleidoAngle=0;
var kaleidoColors=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#fc5c8a"];
var kaleidoColorIdx=0;
var kaleidoSymmetry=8;
var kaleidoAnimating=false;
var kaleidoRAF=null;
var kaleidoLastX=0,kaleidoLastY=0;
var kaleidoIsDrawing=false;
function openKaleidoPanel(){
  try{
    var body=$("kaleidoBody");
    if(!body)return;
    var h="";
    h+='<div class="kaleido-canvas-box">';
    h+='<canvas class="kaleido-canvas" id="kaleidoCanvas" width="300" height="300"></canvas>';
    h+='</div>';
    h+='<div class="kaleido-controls">';
    h+='<div class="kaleido-btn" onclick="changeKaleidoSymmetry()">对称数: '+kaleidoSymmetry+'</div>';
    h+='<div class="kaleido-btn" onclick="changeKaleidoColor()">🎨 换色</div>';
    h+='<div class="kaleido-btn" onclick="clearKaleido()">🗑️ 清空</div>';
    h+='<div class="kaleido-btn" onclick="toggleKaleidoAnim()">'+(kaleidoAnimating?"⏸ 暂停":"▶ 自动")+'</div>';
    h+='</div>';
    h+='<div class="kaleido-info">在画布上滑动手指绘制图案，万花筒将自动镜像对称。点击对称数切换4/6/8/12对称。</div>';
    body.innerHTML=h;
    $("kaleidoOverlay").className="kaleido-overlay show";
    setTimeout(initKaleidoCanvas,100);
  }catch(e){console.error("openKaleidoPanel:",e)}
}
function initKaleidoCanvas(){
  try{
    var canvas=$("kaleidoCanvas");
    if(!canvas)return;
    kaleidoCtx=canvas.getContext("2d");
    kaleidoCtx.fillStyle="#000";
    kaleidoCtx.fillRect(0,0,300,300);
    kaleidoCtx.strokeStyle=kaleidoColors[kaleidoColorIdx];
    kaleidoCtx.lineWidth=2;
    kaleidoCtx.lineCap="round";
    canvas.addEventListener("touchstart",function(e){
      e.preventDefault();
      kaleidoIsDrawing=true;
      var rect=canvas.getBoundingClientRect();
      var touch=e.touches[0];
      kaleidoLastX=(touch.clientX-rect.left)*(300/rect.width)-150;
      kaleidoLastY=(touch.clientY-rect.top)*(300/rect.height)-150;
    },{passive:false});
    canvas.addEventListener("touchmove",function(e){
      e.preventDefault();
      if(!kaleidoIsDrawing||!kaleidoCtx)return;
      var rect=canvas.getBoundingClientRect();
      var touch=e.touches[0];
      var x=(touch.clientX-rect.left)*(300/rect.width)-150;
      var y=(touch.clientY-rect.top)*(300/rect.height)-150;
      drawKaleidoLine(kaleidoLastX,kaleidoLastY,x,y);
      kaleidoLastX=x;kaleidoLastY=y;
    },{passive:false});
    canvas.addEventListener("touchend",function(){kaleidoIsDrawing=false},{passive:false});
    if(kaleidoAnimating)startKaleidoAnim();
  }catch(e){}
}
function drawKaleidoLine(x1,y1,x2,y2){
  try{
    if(!kaleidoCtx)return;
    var cx=150,cy=150;
    var angleStep=(Math.PI*2)/kaleidoSymmetry;
    for(var i=0;i<kaleidoSymmetry;i++){
      kaleidoCtx.save();
      kaleidoCtx.translate(cx,cy);
      kaleidoCtx.rotate(angleStep*i);
      kaleidoCtx.beginPath();
      kaleidoCtx.moveTo(x1,y1);
      kaleidoCtx.lineTo(x2,y2);
      kaleidoCtx.stroke();
      kaleidoCtx.scale(1,-1);
      kaleidoCtx.beginPath();
      kaleidoCtx.moveTo(x1,y1);
      kaleidoCtx.lineTo(x2,y2);
      kaleidoCtx.stroke();
      kaleidoCtx.restore();
    }
  }catch(e){}
}
function changeKaleidoSymmetry(){
  var opts=[4,6,8,12];
  var idx=opts.indexOf(kaleidoSymmetry);
  kaleidoSymmetry=opts[(idx+1)%opts.length];
  openKaleidoPanel();
}
function changeKaleidoColor(){
  kaleidoColorIdx=(kaleidoColorIdx+1)%kaleidoColors.length;
  if(kaleidoCtx)kaleidoCtx.strokeStyle=kaleidoColors[kaleidoColorIdx];
  showToast("颜色已切换");
}
function clearKaleido(){
  try{
    if(kaleidoCtx){kaleidoCtx.fillStyle="#000";kaleidoCtx.fillRect(0,0,300,300)}
  }catch(e){}
}
function toggleKaleidoAnim(){
  kaleidoAnimating=!kaleidoAnimating;
  if(kaleidoAnimating)startKaleidoAnim();
  else stopKaleidoAnim();
  openKaleidoPanel();
}
function startKaleidoAnim(){
  try{
    if(kaleidoRAF)cancelAnimationFrame(kaleidoRAF);
    var t=0;
    function anim(){
      if(!kaleidoAnimating||!kaleidoCtx)return;
      t+=0.02;
      var r=60+Math.sin(t*2)*30;
      var x1=Math.cos(t)*r;
      var y1=Math.sin(t)*r;
      var x2=Math.cos(t+0.1)*r;
      var y2=Math.sin(t+0.1)*r;
      kaleidoColorIdx=Math.floor(t)%kaleidoColors.length;
      kaleidoCtx.strokeStyle=kaleidoColors[kaleidoColorIdx];
      drawKaleidoLine(x1,y1,x2,y2);
      kaleidoRAF=requestAnimationFrame(anim);
    }
    anim();
  }catch(e){}
}
function stopKaleidoAnim(){
  try{
    kaleidoAnimating=false;
    if(kaleidoRAF){cancelAnimationFrame(kaleidoRAF);kaleidoRAF=null}
  }catch(e){}
}
function closeKaleidoPanel(){
  try{
    stopKaleidoAnim();
    var b=$("kaleidoOverlay");
    if(b)b.className="kaleido-overlay";
  }catch(e){}
}

