// ==========================================================================
var pixelGrid=[];
var pixelSize=16;
var pixelColor="#7c5cfc";
var PIXEL_COLORS=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#fc5c8a","#5cfcc8","#ffffff","#000000","#888888","#fcb85c"];
function openPixelPanel(){
  try{
    pixelGrid=[];
    for(var i=0;i<pixelSize;i++){
      var row=[];
      for(var j=0;j<pixelSize;j++)row.push("#1a1a2e");
      pixelGrid.push(row);
    }
    renderPixel();
    $("pixelOverlay").className="pixel-overlay show";
  }catch(e){console.error("openPixelPanel:",e)}
}
function renderPixel(){
  try{
    var body=$("pixelBody");
    if(!body)return;
    var h="";
    h+='<div class="pixel-canvas-box">';
    h+='<div class="pixel-grid" id="pixelGrid">';
    for(var i=0;i<pixelSize;i++){
      for(var j=0;j<pixelSize;j++){
        h+='<div class="pixel-cell" style="background:'+pixelGrid[i][j]+'" onclick="paintPixel('+i+','+j+')" ontouchstart="paintPixel('+i+','+j+')"></div>';
      }
    }
    h+='</div>';
    h+='</div>';
    h+='<div class="pixel-colors">';
    for(var i=0;i<PIXEL_COLORS.length;i++){
      h+='<div class="pixel-pcolor'+(PIXEL_COLORS[i]===pixelColor?" active":"")+'" style="background:'+PIXEL_COLORS[i]+'" onclick="setPixelColor(\''+PIXEL_COLORS[i]+'\')"></div>';
    }
    h+='</div>';
    h+='<div class="pixel-size-btns">';
    var sizes=[8,16,24];
    for(var i=0;i<sizes.length;i++){
      h+='<div class="pixel-size-btn'+(pixelSize===sizes[i]?" active":"")+'" onclick="pixelSize='+sizes[i]+';openPixelPanel()">'+sizes[i]+'×'+sizes[i]+'</div>';
    }
    h+='</div>';
    h+='<div class="pixel-tools">';
    h+='<div class="pixel-tool" onclick="clearPixelGrid()">🗑️ 清空</div>';
    h+='<div class="pixel-tool" onclick="randomPixelArt()">🎲 随机</div>';
    h+='<div class="pixel-tool" onclick="savePixelArt()">💾 保存</div>';
    h+='</div>';
    body.innerHTML=h;
  }catch(e){}
}
function paintPixel(row,col){
  try{
    if(pixelGrid[row]&&pixelGrid[row][col]!==undefined){
      pixelGrid[row][col]=pixelColor;
      renderPixel();
    }
  }catch(e){}
}
function setPixelColor(color){
  pixelColor=color;
  renderPixel();
}
function clearPixelGrid(){
  try{
    for(var i=0;i<pixelSize;i++){
      for(var j=0;j<pixelSize;j++)pixelGrid[i][j]="#1a1a2e";
    }
    renderPixel();
  }catch(e){}
}
function randomPixelArt(){
  try{
    var emojis=["🌸","🌟","❤️"," smile","🐱","🌈"];
    var palette=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa"];
    for(var i=0;i<pixelSize;i++){
      for(var j=0;j<pixelSize;j++){
        if(Math.random()<0.4){
          pixelGrid[i][j]=palette[Math.floor(Math.random()*palette.length)];
        }else{
          pixelGrid[i][j]="#1a1a2e";
        }
      }
    }
    renderPixel();
    showToast("随机图案已生成！");
  }catch(e){}
}
function savePixelArt(){
  try{
    var canvas=document.createElement("canvas");
    var scale=10;
    canvas.width=pixelSize*scale;
    canvas.height=pixelSize*scale;
    var ctx=canvas.getContext("2d");
    for(var i=0;i<pixelSize;i++){
      for(var j=0;j<pixelSize;j++){
        ctx.fillStyle=pixelGrid[i][j];
        ctx.fillRect(j*scale,i*scale,scale,scale);
      }
    }
    var dataUrl=canvas.toDataURL("image/png");
    var gallery=lsGet("pixelGallery")||[];
    gallery.push({img:dataUrl,ts:Date.now()});
    if(gallery.length>20)gallery=gallery.slice(-20);
    lsSet("pixelGallery",gallery);
    showToast("像素画已保存！");
  }catch(e){showToast("保存失败")}
}
function closePixelPanel(){try{var b=$("pixelOverlay");if(b)b.className="pixel-overlay"}catch(e){}}

// ==========================================================================
// ===== v3.20.0 AI对话俄罗斯方块 =====
// ==========================================================================
var tetrisGrid=[];
var tetrisPiece=null;
var tetrisScore=0;
var tetrisLines=0;
var tetrisLevel=1;
var tetrisTimer=null;
var tetrisGameOver=false;
var TETRIS_ROWS=14;
var TETRIS_COLS=8;
var TETRIS_SHAPES=[
  {shape:[[1,1,1,1]],color:"#5cb4fc"},
  {shape:[[1,1],[1,1]],color:"#fcb85c"},
  {shape:[[0,1,0],[1,1,1]],color:"#a78bfa"},
  {shape:[[1,0,0],[1,1,1]],color:"#5cfca8"},
  {shape:[[0,0,1],[1,1,1]],color:"#fc6b6b"},
  {shape:[[0,1,1],[1,1,0]],color:"#fc5c8a"},
  {shape:[[1,1,0],[0,1,1]],color:"#5cfcc8"}
];
function openTetrisPanel(){
  try{
    tetrisScore=0;tetrisLines=0;tetrisLevel=1;tetrisGameOver=false;
    tetrisGrid=[];
    for(var r=0;r<TETRIS_ROWS;r++){
      var row=[];
      for(var c=0;c<TETRIS_COLS;c++)row.push(null);
      tetrisGrid.push(row);
    }
    spawnTetrisPiece();
    renderTetris();
    startTetrisTimer();
    $("tetrisOverlay").className="tetris-overlay show";
  }catch(e){console.error("openTetrisPanel:",e)}
}
function spawnTetrisPiece(){
  try{
    var idx=Math.floor(Math.random()*TETRIS_SHAPES.length);
    var s=TETRIS_SHAPES[idx];
    tetrisPiece={shape:s.shape,color:s.color,x:Math.floor(TETRIS_COLS/2)-1,y:0};
    if(checkTetrisCollision(tetrisPiece.shape,tetrisPiece.x,tetrisPiece.y)){
      tetrisGameOver=true;
      stopTetrisTimer();
      showToast("游戏结束！得分："+tetrisScore);
    }
  }catch(e){}
}
function checkTetrisCollision(shape,px,py){
  try{
    for(var r=0;r<shape.length;r++){
      for(var c=0;c<shape[r].length;c++){
        if(shape[r][c]){
          var nx=px+c,ny=py+r;
          if(nx<0||nx>=TETRIS_COLS||ny>=TETRIS_ROWS)return true;
          if(ny>=0&&tetrisGrid[ny][nx])return true;
        }
      }
    }
    return false;
  }catch(e){return true}
}
function mergeTetrisPiece(){
  try{
    for(var r=0;r<tetrisPiece.shape.length;r++){
      for(var c=0;c<tetrisPiece.shape[r].length;c++){
        if(tetrisPiece.shape[r][c]){
          var ny=tetrisPiece.y+r,nx=tetrisPiece.x+c;
          if(ny>=0&&ny<TETRIS_ROWS)tetrisGrid[ny][nx]=tetrisPiece.color;
        }
      }
    }
  }catch(e){}
}
function clearTetrisLines(){
  try{
    var cleared=0;
    for(var r=TETRIS_ROWS-1;r>=0;r--){
      var full=true;
      for(var c=0;c<TETRIS_COLS;c++){
        if(!tetrisGrid[r][c]){full=false;break}
      }
      if(full){
        tetrisGrid.splice(r,1);
        var emptyRow=[];
        for(var c=0;c<TETRIS_COLS;c++)emptyRow.push(null);
        tetrisGrid.unshift(emptyRow);
        cleared++;
        r++;
      }
    }
    if(cleared>0){
      tetrisLines+=cleared;
      tetrisScore+=[0,100,300,500,800][cleared]*tetrisLevel;
      if(tetrisLines>=tetrisLevel*5)tetrisLevel++;
    }
  }catch(e){}
}
function moveTetrisDown(){
  try{
    if(tetrisGameOver)return;
    if(!checkTetrisCollision(tetrisPiece.shape,tetrisPiece.x,tetrisPiece.y+1)){
      tetrisPiece.y++;
    }else{
      mergeTetrisPiece();
      clearTetrisLines();
      spawnTetrisPiece();
    }
    renderTetris();
  }catch(e){}
}
function moveTetrisLeft(){
  try{
    if(tetrisGameOver)return;
    if(!checkTetrisCollision(tetrisPiece.shape,tetrisPiece.x-1,tetrisPiece.y)){
      tetrisPiece.x--;
      renderTetris();
    }
  }catch(e){}
}
function moveTetrisRight(){
  try{
    if(tetrisGameOver)return;
    if(!checkTetrisCollision(tetrisPiece.shape,tetrisPiece.x+1,tetrisPiece.y)){
      tetrisPiece.x++;
      renderTetris();
    }
  }catch(e){}
}
function rotateTetris(){
  try{
    if(tetrisGameOver)return;
    var newShape=[];
    for(var c=0;c<tetrisPiece.shape[0].length;c++){
      var newRow=[];
      for(var r=tetrisPiece.shape.length-1;r>=0;r--){
        newRow.push(tetrisPiece.shape[r][c]);
      }
      newShape.push(newRow);
    }
    if(!checkTetrisCollision(newShape,tetrisPiece.x,tetrisPiece.y)){
      tetrisPiece.shape=newShape;
      renderTetris();
    }
  }catch(e){}
}
function renderTetris(){
  try{
    var body=$("tetrisBody");
    if(!body)return;
    var h="";
    h+='<div class="tetris-stats">';
    h+='<div class="tetris-stat"><div class="tetris-stat-num">'+tetrisScore+'</div><div class="tetris-stat-label">分数</div></div>';
    h+='<div class="tetris-stat"><div class="tetris-stat-num">'+tetrisLines+'</div><div class="tetris-stat-label">消行</div></div>';
    h+='<div class="tetris-stat"><div class="tetris-stat-num">'+tetrisLevel+'</div><div class="tetris-stat-label">等级</div></div>';
    h+='</div>';
    h+='<div class="tetris-board-box">';
    h+='<div class="tetris-board">';
    var displayGrid=[];
    for(var r=0;r<TETRIS_ROWS;r++){
      displayGrid.push([]);
      for(var c=0;c<TETRIS_COLS;c++)displayGrid[r].push(tetrisGrid[r][c]);
    }
    if(tetrisPiece&&!tetrisGameOver){
      for(var r=0;r<tetrisPiece.shape.length;r++){
        for(var c=0;c<tetrisPiece.shape[r].length;c++){
          if(tetrisPiece.shape[r][c]){
            var ny=tetrisPiece.y+r,nx=tetrisPiece.x+c;
            if(ny>=0&&ny<TETRIS_ROWS&&nx>=0&&nx<TETRIS_COLS)displayGrid[ny][nx]=tetrisPiece.color;
          }
        }
      }
    }
    for(var r=0;r<TETRIS_ROWS;r++){
      for(var c=0;c<TETRIS_COLS;c++){
        var cell=displayGrid[r][c];
        h+='<div class="tetris-cell'+(cell?' filled':'')+'" style="'+(cell?'background:'+cell:'')+'"></div>';
      }
    }
    h+='</div>';
    h+='</div>';
    h+='<div class="tetris-controls">';
    h+='<div class="tetris-btn" onclick="moveTetrisLeft()">⬅️</div>';
    h+='<div class="tetris-btn" onclick="rotateTetris()">🔄</div>';
    h+='<div class="tetris-btn" onclick="moveTetrisRight()">➡️</div>';
    h+='<div class="tetris-btn" onclick="moveTetrisDown()">⬇️</div>';
    h+='</div>';
    if(tetrisGameOver){
      h+='<div class="tetris-start-btn" onclick="openTetrisPanel()">🔄 重新开始</div>';
    }
    body.innerHTML=h;
  }catch(e){}
}
function startTetrisTimer(){
  try{
    stopTetrisTimer();
    var speed=Math.max(300,1000-tetrisLevel*100);
    tetrisTimer=setInterval(function(){moveTetrisDown()},speed);
  }catch(e){}
}
function stopTetrisTimer(){try{if(tetrisTimer){clearInterval(tetrisTimer);tetrisTimer=null}}catch(e){}}
function closeTetrisPanel(){try{stopTetrisTimer();var b=$("tetrisOverlay");if(b)b.className="tetris-overlay"}catch(e){}}

