// ===== v3.20.0 AI角色宠物养成 =====
// ==========================================================================
var petData=null;
var PET_TYPES=[
  {name:"小猫",emoji:"🐱",baseMood:"😺"},
  {name:"小狗",emoji:"🐶",baseMood:"😃"},
  {name:"兔子",emoji:"🐰",baseMood:"😊"},
  {name:"小鸟",emoji:"🐦",baseMood:"🎶"},
  {name:"仓鼠",emoji:"🐹",baseMood:"😴"}
];
function openPetPanel(){
  try{
    petData=lsGet("petData");
    if(!petData){
      var petType=Math.floor(Math.random()*PET_TYPES.length);
      petData={
        type:petType,
        name:PET_TYPES[petType].name,
        level:1,
        exp:0,
        hunger:80,
        happy:80,
        clean:80,
        energy:80,
        lastUpdate:Date.now()
      };
      lsSet("petData",petData);
    }
    updatePetStats();
    renderPet();
    $("petOverlay").className="pet-overlay show";
  }catch(e){console.error("openPetPanel:",e)}
}
function updatePetStats(){
  try{
    if(!petData)return;
    var now=Date.now();
    var elapsed=(now-petData.lastUpdate)/1000;
    var decay=elapsed/60;
    petData.hunger=Math.max(0,petData.hunger-decay);
    petData.happy=Math.max(0,petData.happy-decay);
    petData.clean=Math.max(0,petData.clean-decay*0.5);
    petData.energy=Math.min(100,petData.energy+decay*0.3);
    petData.lastUpdate=now;
    lsSet("petData",petData);
  }catch(e){}
}
function getPetMoodEmoji(){
  try{
    if(!petData)return"😊";
    if(petData.hunger<20)return"🤤";
    if(petData.clean<20)return"🤢";
    if(petData.happy<20)return"😢";
    if(petData.energy<20)return"😴";
    if(petData.happy>70&&petData.hunger>50)return"😄";
    return"😊";
  }catch(e){return"😊"}
}
function renderPet(){
  try{
    var body=$("petBody");
    if(!body||!petData)return;
    var pt=PET_TYPES[petData.type];
    var h="";
    h+='<div class="pet-display">';
    h+='<div class="pet-avatar">'+pt.emoji+'</div>';
    h+='<div class="pet-name">'+petData.name+'</div>';
    h+='<div class="pet-level">Lv.'+petData.level+' (EXP '+petData.exp+'/'+(petData.level*100)+')</div>';
    h+='<div class="pet-mood">'+getPetMoodEmoji()+'</div>';
    h+='</div>';
    h+='<div class="pet-stats">';
    h+='<div class="pet-stat"><div class="pet-stat-label">饱食度</div><div class="pet-stat-bar"><div class="pet-stat-fill" style="width:'+petData.hunger+'%;background:linear-gradient(to right,#fcb85c,#fc6b6b)"></div></div></div>';
    h+='<div class="pet-stat"><div class="pet-stat-label">快乐度</div><div class="pet-stat-bar"><div class="pet-stat-fill" style="width:'+petData.happy+'%;background:linear-gradient(to right,#5cfca8,#5cb4fc)"></div></div></div>';
    h+='<div class="pet-stat"><div class="pet-stat-label">清洁度</div><div class="pet-stat-bar"><div class="pet-stat-fill" style="width:'+petData.clean+'%;background:linear-gradient(to right,#5cb4fc,#a78bfa)"></div></div></div>';
    h+='<div class="pet-stat"><div class="pet-stat-label">精力值</div><div class="pet-stat-bar"><div class="pet-stat-fill" style="width:'+petData.energy+'%;background:linear-gradient(to right,#a78bfa,#fc5c8a)"></div></div></div>';
    h+='</div>';
    h+='<div class="pet-actions">';
    h+='<div class="pet-action" onclick="petFeed()">🍎 喂食</div>';
    h+='<div class="pet-action" onclick="petPlay()">🎾 玩耍</div>';
    h+='<div class="pet-action" onclick="petClean()">🛁 洗澡</div>';
    h+='<div class="pet-action" onclick="petSleep()">💤 睡觉</div>';
    h+='</div>';
    body.innerHTML=h;
  }catch(e){}
}
function petFeed(){
  try{
    updatePetStats();
    petData.hunger=Math.min(100,petData.hunger+25);
    petData.exp+=5;
    checkPetLevelUp();
    lsSet("petData",petData);
    renderPet();
    showToast("🍎 "+petData.name+"吃饱了！");
  }catch(e){}
}
function petPlay(){
  try{
    updatePetStats();
    if(petData.energy<15){showToast("😴 "+petData.name+"太累了，让它休息吧");return}
    petData.happy=Math.min(100,petData.happy+20);
    petData.energy=Math.max(0,petData.energy-15);
    petData.hunger=Math.max(0,petData.hunger-5);
    petData.exp+=8;
    checkPetLevelUp();
    lsSet("petData",petData);
    renderPet();
    showToast("🎾 "+petData.name+"玩得很开心！");
  }catch(e){}
}
function petClean(){
  try{
    updatePetStats();
    petData.clean=Math.min(100,petData.clean+35);
    petData.happy=Math.min(100,petData.happy+5);
    petData.exp+=5;
    checkPetLevelUp();
    lsSet("petData",petData);
    renderPet();
    showToast("🛁 "+petData.name+"洗得干干净净！");
  }catch(e){}
}
function petSleep(){
  try{
    updatePetStats();
    petData.energy=Math.min(100,petData.energy+40);
    petData.exp+=3;
    checkPetLevelUp();
    lsSet("petData",petData);
    renderPet();
    showToast("💤 "+petData.name+"睡了个好觉！");
  }catch(e){}
}
function checkPetLevelUp(){
  try{
    var need=petData.level*100;
    if(petData.exp>=need){
      petData.exp-=need;
      petData.level++;
      showToast("🎉 "+petData.name+"升级了！Lv."+petData.level);
    }
  }catch(e){}
}
function closePetPanel(){try{if(petData)lsSet("petData",petData);var b=$("petOverlay");if(b)b.className="pet-overlay"}catch(e){}}

