// ===== v3.20.0 对话烟花工坊 =====
// ==========================================================================
var fireworkCtx=null;
var fireworkParticles=[];
var fireworkRAF=null;
var fireworkAuto=false;
var fireworkColors=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#fc5c8a","#5cfcc8"];
function openFireworkPanel(){
  try{
    var body=$("fireworkBody");
    var h="";
    h+='<div class="firework-canvas-box">';
    h+='<canvas class="firework-canvas" id="fireworkCanvas" width="340" height="400"></canvas>';
    h+='</div>';
    h+='<div class="firework-controls">';
    h+='<div class="firework-btn" onclick="launchFirework()">🎆 发射</div>';
    h+='<div class="firework-btn" onclick="fireworkAuto=!fireworkAuto;this.textContent=fireworkAuto?\'⏸ 停止\':\'▶ 自动\'">▶ 自动</div>';
    h+='<div class="firework-btn" onclick="clearFirework()">🗑️ 清空</div>';
    h+='</div>';
    h+='<div class="firework-info">点击画布发射烟花，开启自动模式持续绽放</div>';
    body.innerHTML=h;
    $("fireworkOverlay").className="firework-overlay show";
    setTimeout(initFireworkCanvas,100);
  }catch(e){console.error("openFireworkPanel:",e)}
}
function initFireworkCanvas(){
  try{
    var canvas=$("fireworkCanvas");
    if(!canvas)return;
    fireworkCtx=canvas.getContext("2d");
    canvas.addEventListener("touchstart",function(e){
      e.preventDefault();
      var rect=canvas.getBoundingClientRect();
      var touch=e.touches[0];
      var x=(touch.clientX-rect.left)*(340/rect.width);
      var y=(touch.clientY-rect.top)*(400/rect.height);
      launchFireworkAt(x,y);
    },{passive:false});
    fireworkCtx.fillStyle="#000";
    fireworkCtx.fillRect(0,0,340,400);
    startFireworkAnim();
  }catch(e){}
}
function launchFirework(){
  try{
    var x=50+Math.random()*240;
    var y=50+Math.random()*150;
    launchFireworkAt(x,y);
  }catch(e){}
}
function launchFireworkAt(x,y){
  try{
    var color=fireworkColors[Math.floor(Math.random()*fireworkColors.length)];
    var count=20+Math.floor(Math.random()*20);
    for(var i=0;i<count;i++){
      var angle=(Math.PI*2/count)*i;
      var speed=2+Math.random()*3;
      fireworkParticles.push({
        x:x,y:y,
        vx:Math.cos(angle)*speed,
        vy:Math.sin(angle)*speed,
        life:1,
        color:color,
        size:2+Math.random()*2
      });
    }
  }catch(e){}
}
function startFireworkAnim(){
  try{
    if(fireworkRAF)cancelAnimationFrame(fireworkRAF);
    function anim(){
      if(!fireworkCtx)return;
      fireworkCtx.fillStyle="rgba(0,0,0,.15)";
      fireworkCtx.fillRect(0,0,340,400);
      for(var i=fireworkParticles.length-1;i>=0;i--){
        var p=fireworkParticles[i];
        p.x+=p.vx;
        p.y+=p.vy;
        p.vy+=0.05;
        p.vx*=0.99;
        p.life-=0.015;
        if(p.life<=0){fireworkParticles.splice(i,1);continue}
        fireworkCtx.beginPath();
        fireworkCtx.arc(p.x,p.y,p.size*p.life,0,Math.PI*2);
        fireworkCtx.fillStyle=p.color;
        fireworkCtx.globalAlpha=p.life;
        fireworkCtx.fill();
      }
      fireworkCtx.globalAlpha=1;
      if(fireworkAuto&&Math.random()<0.05)launchFirework();
      fireworkRAF=requestAnimationFrame(anim);
    }
    anim();
  }catch(e){}
}
function clearFirework(){
  try{
    fireworkParticles=[];
    if(fireworkCtx){fireworkCtx.fillStyle="#000";fireworkCtx.fillRect(0,0,340,400)}
  }catch(e){}
}
function closeFireworkPanel(){
  try{
    fireworkAuto=false;
    if(fireworkRAF){cancelAnimationFrame(fireworkRAF);fireworkRAF=null}
    var b=$("fireworkOverlay");
    if(b)b.className="firework-overlay";
  }catch(e){}
}

