// ===== v3.20.0 AI对话记忆翻牌 =====
// ==========================================================================
var memoryCards=[];
var memoryFlipped=[];
var memoryMatched=0;
var memoryMoves=0;
var memoryStartTime=0;
var MEMORY_EMOJIS=["🌸","🌟","🎵","🦋","🌈","🌙","⚡","🔥"];
function openMemoryPanel(){
  try{
    var pairs=MEMORY_EMOJIS.slice(0,8);
    var cards=pairs.concat(pairs);
    for(var i=cards.length-1;i>0;i--){
      var j=Math.floor(Math.random()*(i+1));
      var temp=cards[i];cards[i]=cards[j];cards[j]=temp;
    }
    memoryCards=cards.map(function(e){return{emoji:e,flipped:false,matched:false}});
    memoryFlipped=[];
    memoryMatched=0;
    memoryMoves=0;
    memoryStartTime=Date.now();
    renderMemory();
    $("memoryOverlay").className="memory-overlay show";
  }catch(e){console.error("openMemoryPanel:",e)}
}
function renderMemory(){
  try{
    var body=$("memoryBody");
    if(!body)return;
    var elapsed=memoryStartTime?Math.floor((Date.now()-memoryStartTime)/1000):0;
    var h="";
    h+='<div class="memory-stats">';
    h+='<div class="memory-stat"><div class="memory-stat-num">'+memoryMoves+'</div><div class="memory-stat-label">步数</div></div>';
    h+='<div class="memory-stat"><div class="memory-stat-num">'+memoryMatched+'/8</div><div class="memory-stat-label">配对</div></div>';
    h+='<div class="memory-stat"><div class="memory-stat-num">'+elapsed+'s</div><div class="memory-stat-label">用时</div></div>';
    h+='</div>';
    h+='<div class="memory-grid">';
    for(var i=0;i<memoryCards.length;i++){
      var c=memoryCards[i];
      h+='<div class="memory-card'+(c.flipped||c.matched?' flipped':'')+(c.matched?' matched':'')+'" onclick="flipMemoryCard('+i+')">';
      h+='<div class="memory-card-inner">';
      h+='<div class="memory-card-front">?</div>';
      h+='<div class="memory-card-back">'+c.emoji+'</div>';
      h+='</div>';
      h+='</div>';
    }
    h+='</div>';
    if(memoryMatched>=8){
      h+='<div style="text-align:center;font-size:14px;color:#5cfca8;margin-bottom:12px">🎉 全部配对完成！'+elapsed+'秒/'+memoryMoves+'步</div>';
    }
    h+='<div class="memory-restart-btn" onclick="openMemoryPanel()">🔄 重新开始</div>';
    body.innerHTML=h;
  }catch(e){}
}
function flipMemoryCard(idx){
  try{
    if(memoryFlipped.length>=2)return;
    if(memoryCards[idx].flipped||memoryCards[idx].matched)return;
    memoryCards[idx].flipped=true;
    memoryFlipped.push(idx);
    renderMemory();
    if(memoryFlipped.length===2){
      memoryMoves++;
      var a=memoryFlipped[0],b=memoryFlipped[1];
      if(memoryCards[a].emoji===memoryCards[b].emoji){
        memoryCards[a].matched=true;
        memoryCards[b].matched=true;
        memoryMatched++;
        memoryFlipped=[];
        renderMemory();
        if(memoryMatched>=8){
          showToast("🎉 恭喜通关！");
        }
      }else{
        setTimeout(function(){
          memoryCards[a].flipped=false;
          memoryCards[b].flipped=false;
          memoryFlipped=[];
          renderMemory();
        },800);
      }
    }
  }catch(e){}
}
function closeMemoryPanel(){try{var b=$("memoryOverlay");if(b)b.className="memory-overlay"}catch(e){}}

