// ==========================================================================
var colormixR=124,colormixG=92,colormixB=252;
var colormixHistory=[];
var COLORMIX_PRESETS=[
  {name:"梦幻紫",r:124,g:92,b:252},
  {name:"薄荷绿",r:92,g:252,b:168},
  {name:"暖阳橙",r:252,g:184,b:92},
  {name:"珊瑚红",r:252,g:107,b:107},
  {name:"天空蓝",r:92,g:180,b:252},
  {name:"樱花粉",r:252,g:92,b:138}
];
function openColormixPanel(){
  try{
    colormixHistory=lsGet("colormixHistory")||[];
    renderColormix();
    $("colormixOverlay").className="colormix-overlay show";
  }catch(e){console.error("openColormixPanel:",e)}
}
function renderColormix(){
  try{
    var body=$("colormixBody");
    if(!body)return;
    var hex="#"+[colormixR,colormixG,colormixB].map(function(v){return v.toString(16).padStart(2,"0")}).join("");
    var h="";
    h+='<div class="colormix-display" style="background:rgb('+colormixR+','+colormixG+','+colormixB+')"></div>';
    h+='<div class="colormix-hex">'+hex.toUpperCase()+'</div>';
    h+='<div class="colormix-sliders">';
    h+='<div class="colormix-slider-row">';
    h+='<div class="colormix-slider-label r">R</div>';
    h+='<input type="range" class="colormix-slider r" min="0" max="255" value="'+colormixR+'" oninput="colormixR=parseInt(this.value);renderColormix()">';
    h+='<div class="colormix-slider-val">'+colormixR+'</div>';
    h+='</div>';
    h+='<div class="colormix-slider-row">';
    h+='<div class="colormix-slider-label g">G</div>';
    h+='<input type="range" class="colormix-slider g" min="0" max="255" value="'+colormixG+'" oninput="colormixG=parseInt(this.value);renderColormix()">';
    h+='<div class="colormix-slider-val">'+colormixG+'</div>';
    h+='</div>';
    h+='<div class="colormix-slider-row">';
    h+='<div class="colormix-slider-label b">B</div>';
    h+='<input type="range" class="colormix-slider b" min="0" max="255" value="'+colormixB+'" oninput="colormixB=parseInt(this.value);renderColormix()">';
    h+='<div class="colormix-slider-val">'+colormixB+'</div>';
    h+='</div>';
    h+='</div>';
    h+='<div style="font-size:12px;color:#888;text-align:center;margin-bottom:8px">预设颜色</div>';
    h+='<div class="colormix-presets">';
    for(var i=0;i<COLORMIX_PRESETS.length;i++){
      var p=COLORMIX_PRESETS[i];
      h+='<div class="colormix-preset" style="background:rgb('+p.r+','+p.g+','+p.b+')" title="'+p.name+'" onclick="colormixR='+p.r+';colormixG='+p.g+';colormixB='+p.b+';renderColormix()"></div>';
    }
    h+='</div>';
    h+='<div style="font-size:12px;color:#888;text-align:center;margin-bottom:8px">历史颜色</div>';
    h+='<div class="colormix-history">';
    for(var i=colormixHistory.length-1;i>=0&&i>=colormixHistory.length-10;i--){
      h+='<div class="colormix-history-item" style="background:'+colormixHistory[i]+'" onclick="loadColormixHistory('+i+')"></div>';
    }
    if(colormixHistory.length===0)h+='<div style="font-size:11px;color:#555">暂无历史</div>';
    h+='</div>';
    h+='<div class="colormix-save-btn" onclick="saveColormix()">💾 保存当前颜色</div>';
    body.innerHTML=h;
  }catch(e){}
}
function saveColormix(){
  try{
    var hex="#"+[colormixR,colormixG,colormixB].map(function(v){return v.toString(16).padStart(2,"0")}).join("");
    colormixHistory.push(hex);
    if(colormixHistory.length>20)colormixHistory=colormixHistory.slice(-20);
    lsSet("colormixHistory",colormixHistory);
    showToast("颜色已保存！");
    renderColormix();
  }catch(e){showToast("保存失败")}
}
function loadColormixHistory(idx){
  try{
    var hex=colormixHistory[idx];
    colormixR=parseInt(hex.substr(1,2),16);
    colormixG=parseInt(hex.substr(3,2),16);
    colormixB=parseInt(hex.substr(5,2),16);
    renderColormix();
  }catch(e){}
}
function closeColormixPanel(){try{var b=$("colormixOverlay");if(b)b.className="colormix-overlay"}catch(e){}}

