// ===== v3.22.0 对话音乐钢琴 =====
// ==========================================================================
var pianoCtx=null;
var pianoKeys=[];
var pianoNotes=["C","D","E","F","G","A","B"];
var PIANO_WHITE_KEYS=7;
var PIANO_BLACK_KEYS=[0,1,3,4,5];
var PIANO_NOTE_FREQ={"C4":262,"D4":294,"E4":330,"F4":349,"G4":392,"A4":440,"B4":494};
var pianoNoteLog=[];
var pianoAutoPlay=false;
var pianoAutoTimer=null;
var pianoMelodyIdx=0;
var PIANO_MELODIES=[
  ["C4","D4","E4","C4","C4","D4","E4","C4","E4","F4","G4","G4","E4","F4","G4"],
  ["G4","E4","G4","A4","G4","C4","G4","E4","G4","F4","E4","D4","C4"],
  ["C4","E4","G4","C5","G4","E4","C4","C4","E4","G4","G4","E4","C4"]
];
function openPianoPanel(){
  try{
    pianoNoteLog=[];
    var body=$("pianoBody");
    var h="";
    h+='<div class="piano-canvas-box">';
    h+='<canvas class="piano-canvas" id="pianoCanvas" width="340" height="200"></canvas>';
    h+='</div>';
    h+='<div class="piano-controls">';
    h+='<div class="piano-btn" onclick="pianoAutoPlay=!pianoAutoPlay;togglePianoAuto()">▶ 自动演奏</div>';
    h+='<div class="piano-btn" onclick="clearPianoLog()">🗑️ 清空</div>';
    h+='</div>';
    h+='<div class="piano-log" id="pianoLogBox">';
    h+='<div style="font-size:11px;color:#555;text-align:center">点击琴键弹奏音乐</div>';
    h+='</div>';
    body.innerHTML=h;
    $("pianoOverlay").className="piano-overlay show";
    setTimeout(initPianoCanvas,100);
  }catch(e){console.error("openPianoPanel:",e)}
}
function initPianoCanvas(){
  try{
    var canvas=$("pianoCanvas");
    if(!canvas)return;
    pianoCtx=canvas.getContext("2d");
    var keyW=40,keyH=140;
    var blackW=24,blackH=90;
    pianoKeys=[];
    for(var i=0;i<PIANO_WHITE_KEYS;i++){
      pianoKeys.push({note:PIANO_NOTES[i]+"4",x:i*keyW+4,y:10,w:keyW-4,h:keyH,isBlack:false,played:false});
    }
    for(var i=0;i<PIANO_BLACK_KEYS.length;i++){
      var idx=PIANO_BLACK_KEYS[i];
      pianoKeys.push({note:PIANO_NOTES[idx]+"#4",x:idx*keyW+keyW-12,y:10,w:blackW,h:blackH,isBlack:true,played:false});
    }
    drawPiano();
    canvas.addEventListener("touchstart",function(e){
      e.preventDefault();
      var rect=canvas.getBoundingClientRect();
      var touch=e.touches[0];
      var x=(touch.clientX-rect.left)*(340/rect.width);
      var y=(touch.clientY-rect.top)*(200/rect.height);
      for(var i=0;i<pianoKeys.length;i++){
        var k=pianoKeys[i];
        if(x>=k.x&&x<=k.x+k.w&&y>=k.y&&y<=k.y+k.h){
          playPianoNote(i);
          break;
        }
      }
    },{passive:false});
  }catch(e){}
}
function drawPiano(){
  try{
    if(!pianoCtx)return;
    pianoCtx.fillStyle="rgba(0,0,0,0)";
    pianoCtx.clearRect(0,0,340,200);
    // White keys
    for(var i=0;i<pianoKeys.length;i++){
      var k=pianoKeys[i];
      if(k.isBlack)continue;
      pianoCtx.fillStyle=k.played?"#e0d4ff":"#fff";
      pianoCtx.fillRect(k.x,k.y,k.w,k.h);
      pianoCtx.strokeStyle="#333";
      pianoCtx.strokeRect(k.x,k.y,k.w,k.h);
      pianoCtx.fillStyle="#888";
      pianoCtx.font="10px Arial";
      pianoCtx.textAlign="center";
      pianoCtx.fillText(k.note.replace("4",""),k.x+k.w/2,k.y+k.h-8);
      k.played=false;
    }
    // Black keys
    for(var i=0;i<pianoKeys.length;i++){
      var k=pianoKeys[i];
      if(!k.isBlack)continue;
      pianoCtx.fillStyle=k.played?"#7c5cfc":"#222";
      pianoCtx.fillRect(k.x,k.y,k.w,k.h);
      k.played=false;
    }
  }catch(e){}
}
function playPianoNote(idx){
  try{
    var k=pianoKeys[idx];
    if(!k)return;
    k.played=true;
    pianoNoteLog.push(k.note);
    if(pianoNoteLog.length>20)pianoNoteLog.shift();
    updatePianoLog();
    drawPiano();
    // Play note with AudioContext
    try{
      var ctx=window._musicCtx||new(window.AudioContext||window.webkitAudioContext)();
      window._musicCtx=ctx;
      var osc=ctx.createOscillator();
      var gain=ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      var freq=PIANO_NOTE_FREQ[k.note]||262;
      osc.frequency.value=freq;
      osc.type="sine";
      gain.gain.setValueAtTime(0.3,ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+0.8);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime+0.8);
    }catch(e){}
    setTimeout(function(){drawPiano()},100);
  }catch(e){}
}
function updatePianoLog(){
  try{
    var box=$("pianoLogBox");
    if(!box)return;
    var h="";
    for(var i=pianoNoteLog.length-1;i>=0;i--){
      h+='<span class="piano-note">'+pianoNoteLog[i]+'</span>';
    }
    box.innerHTML=h;
  }catch(e){}
}
function togglePianoAuto(){
  try{
    if(pianoAutoPlay){
      pianoMelodyIdx=0;
      pianoAutoTimer=setInterval(function(){
        if(pianoMelodyIdx>=PIANO_MELODIES[0].length){
          pianoMelodyIdx=0;
        }
        var note=PIANO_MELODIES[0][pianoMelodyIdx];
        for(var i=0;i<pianoKeys.length;i++){
          if(pianoKeys[i].note===note){
            playPianoNote(i);break;
          }
        }
        pianoMelodyIdx++;
      },400);
    }else{
      if(pianoAutoTimer){clearInterval(pianoAutoTimer);pianoAutoTimer=null}
    }
  }catch(e){}
}
function clearPianoLog(){try{pianoNoteLog=[];updatePianoLog()}catch(e){}}
function closePianoPanel(){
  try{
    pianoAutoPlay=false;
    if(pianoAutoTimer){clearInterval(pianoAutoTimer);pianoAutoTimer=null}
    var b=$("pianoOverlay");if(b)b.className="piano-overlay"
  }catch(e){}
}

