// ===== v3.22.0 对话气泡消除 =====
// ==========================================================================
var bubbleGrid=[];
var bubbleScore=0;
var bubbleSelected=-1;
var BUBBLE_COLORS=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#fc5c8a"];
var BUBBLE_EMOJIS=["🔮","💚","🌟","❤️","💎","🌸"];
function openBubblePanel(){
  try{
    bubbleScore=0;
    bubbleSelected=-1;
    bubbleGrid=[];
    for(var r=0;r<8;r++){
      var row=[];
      for(var c=0;c<6;c++){
        row.push(Math.floor(Math.random()*BUBBLE_COLORS.length));
      }
      bubbleGrid.push(row);
    }
    renderBubble();
    $("bubbleOverlay").className="bubble-overlay show";
  }catch(e){console.error("openBubblePanel:",e)}
}
function renderBubble(){
  try{
    var body=$("bubbleBody");
    if(!body)return;
    var h="";
    h+='<div class="bubble-stats">';
    h+='<div class="bubble-stat"><div class="bubble-stat-num">'+bubbleScore+'</div><div class="bubble-stat-label">分数</div></div>';
    h+='<div class="bubble-stat"><div class="bubble-stat-num">'+getBubbleCount()+'</div><div class="bubble-stat-label">剩余</div></div>';
    h+='</div>';
    h+='<div class="bubble-board-box">';
    h+='<div class="bubble-board">';
    for(var r=0;r<bubbleGrid.length;r++){
      for(var c=0;c<bubbleGrid[r].length;c++){
        var val=bubbleGrid[r][c];
        if(val<0){
          h+='<div class="bubble-cell empty"></div>';
        }else{
          var idx=(r*6+c);
          h+='<div class="bubble-cell'+(idx===bubbleSelected?" selected":"")+'" style="background:'+BUBBLE_COLORS[val]+'" onclick="clickBubble('+r+','+c+')">'+BUBBLE_EMOJIS[val]+'</div>';
        }
      }
    }
    h+='</div>';
    h+='</div>';
    if(getBubbleCount()===0){
      h+='<div style="text-align:center;font-size:14px;color:#5cfca8;margin-bottom:12px">🎉 全部消除！得分：'+bubbleScore+'</div>';
      h+='<div class="bubble-stat" style="padding:12px;cursor:pointer" onclick="openBubblePanel()">🔄 再来一局</div>';
    }
    body.innerHTML=h;
  }catch(e){}
}
function getBubbleCount(){
  var c=0;
  for(var r=0;r<bubbleGrid.length;r++){
    for(var c2=0;c2<bubbleGrid[r].length;c2++){
      if(bubbleGrid[r][c2]>=0)c++;
    }
  }
  return c;
}
function clickBubble(row,col){
  try{
    var val=bubbleGrid[row][col];
    if(val<0)return;
    var idx=row*6+col;
    if(bubbleSelected===idx){
      bubbleSelected=-1;
      renderBubble();
      return;
    }
    // Find connected same-color bubbles
    var visited={};
    var queue=[{r:row,c:col}];
    var connected=[];
    while(queue.length>0){
      var cur=queue.shift();
      var key=cur.r+","+cur.c;
      if(visited[key])continue;
      visited[key]=true;
      if(cur.r<0||cur.r>=bubbleGrid.length||cur.c<0||cur.c>=bubbleGrid[0].length)continue;
      if(bubbleGrid[cur.r][cur.c]!==val)continue;
      connected.push({r:cur.r,c:cur.c});
      queue.push({r:cur.r-1,c:cur.c},{r:cur.r+1,c:cur.c},{r:cur.r,c:cur.c-1},{r:cur.r,c:cur.c+1});
    }
    if(connected.length>=2){
      for(var i=0;i<connected.length;i++){
        bubbleGrid[connected[i].r][connected[i].c]=-1;
      }
      bubbleScore+=connected.length*connected.length;
      bubbleSelected=-1;
      // Drop bubbles down
      for(var c=0;c<6;c++){
        for(var r=bubbleGrid.length-1;r>=0;r--){
          if(bubbleGrid[r][c]<0){
            for(var r2=r-1;r2>=0;r2--){
              if(bubbleGrid[r2][c]>=0){
                bubbleGrid[r][c]=bubbleGrid[r2][c];
                bubbleGrid[r2][c]=-1;
                break;
              }
            }
          }
        }
      }
      renderBubble();
    }else{
      bubbleSelected=idx;
      renderBubble();
    }
  }catch(e){}
}
function closeBubblePanel(){try{var b=$("bubbleOverlay");if(b)b.className="bubble-overlay"}catch(e){}}

