var jokeCategory=0;
var jokeCurrent=null;
var jokeRevealed=false;
function openJokePanel(){
  try{
    jokeCategory=0;
    jokeCurrent=null;
    jokeRevealed=false;
    renderJoke();
    $("jokeOverlay").className="joke-overlay show";
  }catch(e){console.error("openJokePanel:",e)}
}
function renderJoke(){
  try{
    var body=$("jokeBody");
    if(!body)return;
    var h="";
    h+='<div style="font-size:12px;color:#888;text-align:center;margin-bottom:8px">选择分类，生成搞笑笑话</div>';
    h+='<div class="joke-categories">';
    for(var i=0;i<JOKE_CATEGORIES.length;i++){
      h+='<div class="joke-cat'+(i===jokeCategory?" selected":"")+'" onclick="jokeCategory='+i+';jokeCurrent=null;jokeRevealed=false;renderJoke()">'+JOKE_CATEGORIES[i].name+'</div>';
    }
    h+='</div>';
    if(jokeCurrent){
      h+='<div class="joke-card">';
      h+='<div class="joke-emoji">😂</div>';
      h+='<div class="joke-setup">'+jokeCurrent.setup+'</div>';
      h+='<div class="joke-punchline'+(jokeRevealed?" show":"")+'">'+jokeCurrent.punchline+'</div>';
      h+='</div>';
      if(!jokeRevealed){
        h+='<div class="joke-reveal-btn" onclick="revealJoke()">🤔 揭晓答案</div>';
      }
      h+='<div class="joke-next-btn'+(jokeRevealed?" show":"")+'" onclick="getJoke()">🎲 再来一个</div>';
    }else{
      h+='<div class="joke-card" style="justify-content:center;cursor:pointer" onclick="getJoke()">';
      h+='<div style="font-size:48px;margin-bottom:8px">🤣</div>';
      h+='<div style="font-size:14px;color:#a78bfa">点击生成笑话</div>';
      h+='</div>';
    }
    body.innerHTML=h;
  }catch(e){}
}
function getJoke(){
  try{
    var catJokes=JOKE_DATABASE.filter(function(j){return j.cat===jokeCategory});
    if(catJokes.length===0){
      showToast("该分类暂无笑话");
      return;
    }
    jokeCurrent=catJokes[Math.floor(Math.random()*catJokes.length)];
    jokeRevealed=false;
    renderJoke();
  }catch(e){}
}
function revealJoke(){
  jokeRevealed=true;
  renderJoke();
}
function closeJokePanel(){try{var b=$("jokeOverlay");if(b)b.className="joke-overlay"}catch(e){}}

