var doodleCtx=null;
var doodleDrawing=false;
var doodleLastX=0,doodleLastY=0;
var doodleColor="#7c5cfc";
var doodleSize=3;
var doodleEmotion="😊";
var DOODLE_COLORS=["#7c5cfc","#5cfca8","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#fc5c8a","#000000"];
var DOODLE_EMOTIONS=["😊","😢","😡","😍","😱","🤔","😴","🎉"];
function openDoodlePanel(){
  try{
    var body=$("doodleBody");
    var h="";
    h+='<div class="doodle-canvas-box">';
    h+='<canvas class="doodle-canvas" id="doodleCanvas" width="340" height="340"></canvas>';
    h+='</div>';
    h+='<div class="doodle-emotions">';
    for(var i=0;i<DOODLE_EMOTIONS.length;i++){
      h+='<div class="doodle-emotion'+(DOODLE_EMOTIONS[i]===doodleEmotion?" selected":"")+'" onclick="doodleEmotion=\''+DOODLE_EMOTIONS[i]+'\';drawDoodleEmotion()">'+DOODLE_EMOTIONS[i]+'</div>';
    }
    h+='</div>';
    h+='<div class="doodle-tools">';
    for(var i=0;i<DOODLE_COLORS.length;i++){
      h+='<div class="doodle-tool" style="flex:0;width:28px;height:28px;padding:0;border-radius:50%;background:'+DOODLE_COLORS[i]+';border:2px solid '+(DOODLE_COLORS[i]===doodleColor?'#fff':'transparent')+'" onclick="doodleColor=\''+DOODLE_COLORS[i]+'\'"></div>';
    }
    h+='</div>';
    h+='<div class="doodle-tools">';
    h+='<div class="doodle-tool" onclick="clearDoodle()">🗑️ 清空</div>';
    h+='<div class="doodle-tool" onclick="drawDoodleEmotion()">😊 心情</div>';
    h+='</div>';
    h+='<div class="doodle-save-btn" onclick="saveDoodle()">💾 保存心情涂鸦</div>';
    body.innerHTML=h;
    $("doodleOverlay").className="doodle-overlay show";
    setTimeout(initDoodleCanvas,100);
  }catch(e){console.error("openDoodlePanel:",e)}
}
function initDoodleCanvas(){
  try{
    var canvas=$("doodleCanvas");
    if(!canvas)return;
    doodleCtx=canvas.getContext("2d");
    doodleCtx.fillStyle="#fff";
    doodleCtx.fillRect(0,0,340,340);
    doodleCtx.lineCap="round";
    doodleCtx.lineJoin="round";
    canvas.addEventListener("touchstart",function(e){
      e.preventDefault();
      doodleDrawing=true;
      var rect=canvas.getBoundingClientRect();
      var touch=e.touches[0];
      doodleLastX=(touch.clientX-rect.left)*(340/rect.width);
      doodleLastY=(touch.clientY-rect.top)*(340/rect.height);
    },{passive:false});
    canvas.addEventListener("touchmove",function(e){
      e.preventDefault();
      if(!doodleDrawing||!doodleCtx)return;
      var rect=canvas.getBoundingClientRect();
      var touch=e.touches[0];
      var x=(touch.clientX-rect.left)*(340/rect.width);
      var y=(touch.clientY-rect.top)*(340/rect.height);
      doodleCtx.strokeStyle=doodleColor;
      doodleCtx.lineWidth=doodleSize;
      doodleCtx.beginPath();
      doodleCtx.moveTo(doodleLastX,doodleLastY);
      doodleCtx.lineTo(x,y);
      doodleCtx.stroke();
      doodleLastX=x;doodleLastY=y;
    },{passive:false});
    canvas.addEventListener("touchend",function(){doodleDrawing=false},{passive:false});
    drawDoodleEmotion();
  }catch(e){}
}
function drawDoodleEmotion(){
  try{
    if(!doodleCtx)return;
    doodleCtx.font="60px Arial";
    doodleCtx.textAlign="center";
    doodleCtx.textBaseline="middle";
    doodleCtx.fillStyle="rgba(0,0,0,.05)";
    doodleCtx.fillText(doodleEmotion,170,170);
  }catch(e){}
}
function clearDoodle(){
  try{
    if(doodleCtx){doodleCtx.fillStyle="#fff";doodleCtx.fillRect(0,0,340,340);drawDoodleEmotion()}
  }catch(e){}
}
function saveDoodle(){
  try{
    var canvas=$("doodleCanvas");
    if(!canvas)return;
    var dataUrl=canvas.toDataURL("image/png");
    var gallery=lsGet("doodleGallery")||[];
    gallery.push({img:dataUrl,emotion:doodleEmotion,ts:Date.now()});
    if(gallery.length>20)gallery=gallery.slice(-20);
    lsSet("doodleGallery",gallery);
    showToast("心情涂鸦已保存！");
  }catch(e){showToast("保存失败")}
}
function closeDoodlePanel(){try{var b=$("doodleOverlay");if(b)b.className="doodle-overlay"}catch(e){}}

