// ===== v3.24.0 AI对话台球 =====
// ==========================================================================
var billiardCtx=null;
var billiardBalls=[];
var billiardCue={x:0,y:0,angle:0,power:0};
var billiardAiming=false;
var billiardDragging=false;
var billiardScore=0;
var BILLIARD_RADIUS=10;
var BILLIARD_COLORS=["#fff","#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#fc5c8a","#5cfcfc","#888","#222","#5cfca8"];
function openBilliardPanel(){
  try{
    var body=$("billiardBody");
    var h="";
    h+='<div class="billiard-stats">';
    h+='<div class="billiard-stat"><div class="billiard-stat-num" id="billiardScore">0</div><div class="billiard-stat-label">进球</div></div>';
    h+='<div class="billiard-stat"><div class="billiard-stat-num" id="billiardRemain">8</div><div class="billiard-stat-label">剩余</div></div>';
    h+='</div>';
    h+='<div class="billiard-canvas-box">';
    h+='<canvas class="billiard-canvas" id="billiardCanvas" width="340" height="380"></canvas>';
    h+='</div>';
    h+='<div class="billiard-controls">';
    h+='<div class="billiard-btn" onclick="resetBilliard()">🔄 重置</div>';
    h+='<div class="billiard-btn" onclick="billiardCue.power=Math.min(billiardCue.power+10,100);drawBilliard()">💪 加力</div>';
    h+='<div class="billiard-btn" onclick="billiardCue.power=Math.max(billiardCue.power-10,10);drawBilliard()">🔽 减力</div>';
    h+='</div>';
    body.innerHTML=h;
    resetBilliard();
    $("billiardOverlay").className="billiard-overlay show";
    setTimeout(initBilliardCanvas,100);
  }catch(e){console.error("openBilliardPanel:",e)}
}
function resetBilliard(){
  try{
    billiardBalls=[];
    billiardBalls.push({x:170,y:340,color:"#fff",vx:0,vy:0,isCue:true});
    var colors=["#fcb85c","#fc6b6b","#5cb4fc","#a78bfa","#fc5c8a","#5cfcfc","#888","#222"];
    for(var i=0;i<8;i++){
      var angle=Math.random()*Math.PI*2;
      var dist=15+Math.random()*20;
      billiardBalls.push({x:170+Math.cos(angle)*dist,y:50+Math.sin(angle)*dist,color:colors[i],vx:0,vy:0,isCue:false});
    }
    billiardScore=0;
    billiardCue={power:30,angle:-Math.PI/2};
    billiardAiming=true;
  }catch(e){}
}
function initBilliardCanvas(){
  try{
    var canvas=$("billiardCanvas");
    if(!canvas)return;
    billiardCtx=canvas.getContext("2d");
    drawBilliard();
    canvas.addEventListener("touchstart",function(e){
      e.preventDefault();
      var rect=canvas.getBoundingClientRect();
      var touch=e.touches[0];
      var x=(touch.clientX-rect.left)*(340/rect.width);
      var y=(touch.clientY-rect.top)*(380/rect.height);
      if(billiardAiming){
        var cue=billiardBalls[0];
        billiardCue.angle=Math.atan2(y-cue.y,x-cue.x);
        billiardDragging=true;
      }
    },{passive:false});
    canvas.addEventListener("touchmove",function(e){
      e.preventDefault();
      if(!billiardDragging)return;
      var rect=canvas.getBoundingClientRect();
      var touch=e.touches[0];
      var x=(touch.clientX-rect.left)*(340/rect.width);
      var y=(touch.clientY-rect.top)*(380/rect.height);
      var cue=billiardBalls[0];
      billiardCue.angle=Math.atan2(y-cue.y,x-cue.x);
      var dist=Math.sqrt((x-cue.x)*(x-cue.x)+(y-cue.y)*(y-cue.y));
      billiardCue.power=Math.min(dist/2,100);
      drawBilliard();
    },{passive:false});
    canvas.addEventListener("touchend",function(e){
      e.preventDefault();
      if(billiardDragging&&billiardAiming){
        billiardDragging=false;
        billiardAiming=false;
        billiardBalls[0].vx=Math.cos(billiardCue.angle)*billiardCue.power*0.3;
        billiardBalls[0].vy=Math.sin(billiardCue.angle)*billiardCue.power*0.3;
        startBilliardAnim();
      }
    },{passive:false});
  }catch(e){}
}
function drawBilliard(){
  try{
    if(!billiardCtx)return;
    billiardCtx.fillStyle="rgba(0,80,0,.3)";
    billiardCtx.fillRect(0,0,340,380);
    // Draw pockets
    var pockets=[[5,5],[170,5],[335,5],[5,375],[170,375],[335,375]];
    for(var i=0;i<pockets.length;i++){
      billiardCtx.beginPath();
      billiardCtx.arc(pockets[i][0],pockets[i][1],12,0,Math.PI*2);
      billiardCtx.fillStyle="rgba(0,0,0,.5)";
      billiardCtx.fill();
    }
    // Draw cue line
    if(billiardAiming&&billiardBalls.length>0){
      var cue=billiardBalls[0];
      billiardCtx.beginPath();
      billiardCtx.moveTo(cue.x,cue.y);
      billiardCtx.lineTo(cue.x+Math.cos(billiardCue.angle)*(20+billiardCue.power),cue.y+Math.sin(billiardCue.angle)*(20+billiardCue.power));
      billiardCtx.strokeStyle="rgba(255,255,255,.3)";
      billiardCtx.lineWidth=2;
      billiardCtx.stroke();
    }
    // Draw balls
    for(var i=0;i<billiardBalls.length;i++){
      var b=billiardBalls[i];
      billiardCtx.beginPath();
      billiardCtx.arc(b.x,b.y,BILLIARD_RADIUS,0,Math.PI*2);
      billiardCtx.fillStyle=b.color;
      billiardCtx.fill();
      billiardCtx.strokeStyle="rgba(0,0,0,.3)";
      billiardCtx.lineWidth=1;
      billiardCtx.stroke();
      if(b.isCue){
        billiardCtx.beginPath();
        billiardCtx.arc(b.x,b.y,BILLIARD_RADIUS+2,0,Math.PI*2);
        billiardCtx.strokeStyle="rgba(124,92,252,.4)";
        billiardCtx.lineWidth=1.5;
        billiardCtx.stroke();
      }
    }
    // Power bar
    if(billiardAiming){
      billiardCtx.fillStyle="rgba(0,0,0,.5)";
      billiardCtx.fillRect(10,10,100,8);
      billiardCtx.fillStyle="#fcb85c";
      billiardCtx.fillRect(10,10,billiardCue.power,8);
      billiardCtx.fillStyle="#fff";
      billiardCtx.font="9px Arial";
      billiardCtx.fillText("力:"+Math.floor(billiardCue.power),115,17);
    }
  }catch(e){}
}
function startBilliardAnim(){
  try{
    var running=true;
    function anim(){
      if(!running)return;
      var anyMoving=false;
      // Physics
      for(var i=0;i<billiardBalls.length;i++){
        var b=billiardBalls[i];
        b.x+=b.vx;
        b.y+=b.vy;
        b.vx*=0.98;
        b.vy*=0.98;
        if(Math.abs(b.vx)<0.1&&Math.abs(b.vy)<0.1){b.vx=0;b.vy=0}
        else anyMoving=true;
        // Walls
        if(b.x<10+BILLIARD_RADIUS){b.x=10+BILLIARD_RADIUS;b.vx*=-0.8}
        if(b.x>330-BILLIARD_RADIUS){b.x=330-BILLIARD_RADIUS;b.vx*=-0.8}
        if(b.y<10+BILLIARD_RADIUS){b.y=10+BILLIARD_RADIUS;b.vy*=-0.8}
        if(b.y>370-BILLIARD_RADIUS){b.y=370-BILLIARD_RADIUS;b.vy*=-0.8}
        // Pockets
        var pockets=[[5,5],[170,5],[335,5],[5,375],[170,375],[335,375]];
        for(var p=0;p<pockets.length;p++){
          var dx=b.x-pockets[p][0],dy=b.y-pockets[p][1];
          if(Math.sqrt(dx*dx+dy*dy)<12){
            if(b.isCue){
              b.x=170;b.y=340;b.vx=0;b.vy=0;
            }else{
              billiardBalls.splice(i,1);i--;
              billiardScore++;
              updateBillboardStats();
            }
            anyMoving=true;
            break;
          }
        }
      }
      // Collisions
      for(var i=0;i<billiardBalls.length;i++){
        for(var j=i+1;j<billiardBalls.length;j++){
          var a=billiardBalls[i],b=billiardBalls[j];
          var dx=b.x-a.x,dy=b.y-a.y;
          var dist=Math.sqrt(dx*dx+dy*dy);
          if(dist<BILLIARD_RADIUS*2&&dist>0){
            var nx=dx/dist,ny=dy/dist;
            var overlap=BILLIARD_RADIUS*2-dist;
            a.x-=nx*overlap/2;a.y-=ny*overlap/2;
            b.x+=nx*overlap/2;b.y+=ny*overlap/2;
            var relV=(a.vx-b.vx)*nx+(a.vy-b.vy)*ny;
            if(relV>0){
              a.vx-=relV*nx*0.8;a.vy-=relV*ny*0.8;
              b.vx+=relV*nx*0.8;b.vy+=relV*ny*0.8;
              anyMoving=true;
            }
          }
        }
      }
      drawBilliard();
      if(!anyMoving){
        running=false;
        billiardAiming=true;
        updateBillboardStats();
        if(billiardBalls.length<=1)showToast("🎉 全部进球！得分："+billiardScore);
      }else{
        requestAnimationFrame(anim);
      }
    }
    anim();
  }catch(e){}
}
function updateBillboardStats(){
  try{
    var s=$("billiardScore");if(s)s.textContent=billiardScore;
    var r=$("billiardRemain");if(r)r.textContent=Math.max(0,billiardBalls.length-1);
  }catch(e){}
}
function closeBilliardPanel(){try{var b=$("billiardOverlay");if(b)b.className="billiard-overlay"}catch(e){}}

// ==========================================================================
// ===== v3.24.0 对话音乐打碟 =====
// ==========================================================================
var djSpinning=false;
var djVolume=50;
var djBpm=120;
var djTimer=null;
var DJ_SOUNDS=["🎵","🎶","🎸","🎹","🥁","🎺","🎻","🎷"];
function openDjPanel(){
  try{
    var body=$("djBody");
    var h="";
    h+='<div class="dj-bpm">🎵 BPM: <span id="djBpmVal">'+djBpm+'</span></div>';
    h+='<div class="dj-turntable">';
    h+='<div class="dj-disc'+(djSpinning?" spinning":"")+'" id="djDisc">🎧</div>';
    h+='<div class="dj-center"></div>';
    h+='</div>';
    h+='<div class="dj-pads">';
    h+='<div class="dj-pad dj-pad-1" onclick="djPlaySound(0)">'+DJ_SOUNDS[0]+'</div>';
    h+='<div class="dj-pad dj-pad-2" onclick="djPlaySound(1)">'+DJ_SOUNDS[1]+'</div>';
    h+='<div class="dj-pad dj-pad-3" onclick="djPlaySound(2)">'+DJ_SOUNDS[2]+'</div>';
    h+='<div class="dj-pad dj-pad-4" onclick="djPlaySound(3)">'+DJ_SOUNDS[3]+'</div>';
    h+='</div>';
    h+='<div class="dj-controls">';
    h+='<div class="dj-btn'+(djSpinning?" active":"")+'" onclick="djToggleSpin()">'+(djSpinning?"⏸ 停止":"▶ 转碟")+'</div>';
    h+='<div class="dj-btn" onclick="djBpm=Math.max(60,djBpm-10);updateDjBpm()">⏪ 减速</div>';
    h+='<div class="dj-btn" onclick="djBpm=Math.min(200,djBpm+10);updateDjBpm()">⏩ 加速</div>';
    h+='</div>';
    body.innerHTML=h;
    $("djOverlay").className="dj-overlay show";
  }catch(e){console.error("openDjPanel:",e)}
}
function djPlaySound(idx){
  try{
    var disc=$("djDisc");
    if(disc){
      disc.style.transform="scale(1.1)";
      setTimeout(function(){if(disc)disc.style.transform="scale(1)"},100);
    }
    try{
      var ctx=window._musicCtx||new(window.AudioContext||window.webkitAudioContext)();
      window._musicCtx=ctx;
      var osc=ctx.createOscillator();
      var gain=ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      var freqs=[262,330,392,440,523,587,659,784];
      osc.frequency.value=freqs[idx+idx];
      osc.type="sine";
      gain.gain.setValueAtTime(0.2,ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+0.3);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime+0.3);
    }catch(e){}
    showToast("🎵 "+DJ_SOUNDS[idx]+" 打碟中！");
  }catch(e){}
}
function djToggleSpin(){
  djSpinning=!djSpinning;
  var disc=$("djDisc");
  if(disc){
    if(djSpinning){
      disc.className="dj-disc spinning";
      startDjBeat();
    }else{
      disc.className="dj-disc";
      stopDjBeat();
    }
  }
  openDjPanel();
}
function startDjBeat(){
  try{
    stopDjBeat();
    djTimer=setInterval(function(){
      try{
        var ctx=window._musicCtx||new(window.AudioContext||window.webkitAudioContext)();
        window._musicCtx=ctx;
        var osc=ctx.createOscillator();
        var gain=ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.frequency.value=80;
        osc.type="sine";
        gain.gain.setValueAtTime(0.15,ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+0.1);
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime+0.1);
      }catch(e){}
    },60000/djBpm);
  }catch(e){}
}
function stopDjBeat(){try{if(djTimer){clearInterval(djTimer);djTimer=null}}catch(e){}}
function updateDjBpm(){
  var v=$("djBpmVal");
  if(v)v.textContent=djBpm;
  if(djSpinning){stopDjBeat();startDjBeat()}
}
