var gemGrid=[];
var gemScore=0;
var gemSelected=null;
var GEM_TYPES=[{color:"#fc6b6b",emoji:"❤️"},{color:"#5cb4fc",emoji:"💎"},{color:"#5cfca8",emoji:"💚"},{color:"#fcb85c",emoji:"⭐"},{color:"#a78bfa",emoji:"🔮"},{color:"#fc5c8a",emoji:"🌸"}];
function openGemPanel(){
  try{
    gemScore=0;
    gemSelected=null;
    gemGrid=[];
    for(var r=0;r<8;r++){
      var row=[];
      for(var c=0;c<6;c++){
        row.push(Math.floor(Math.random()*GEM_TYPES.length));
      }
      gemGrid.push(row);
    }
    // Remove initial matches
    while(removeGemMatches()>0){}
    renderGem();
    $("gemOverlay").className="gem-overlay show";
  }catch(e){console.error("openGemPanel:",e)}
}
function renderGem(){
  try{
    var body=$("gemBody");
    if(!body)return;
    var h="";
    h+='<div class="gem-stats">';
    h+='<div class="gem-stat"><div class="gem-stat-num">'+gemScore+'</div><div class="gem-stat-label">分数</div></div>';
    h+='<div class="gem-stat"><div class="gem-stat-num" onclick="openGemPanel()">🔄</div><div class="gem-stat-label">重开</div></div>';
    h+='</div>';
    h+='<div class="gem-board-box">';
    h+='<div class="gem-board">';
    for(var r=0;r<gemGrid.length;r++){
      for(var c=0;c<gemGrid[r].length;c++){
        var val=gemGrid[r][c];
        if(val<0){
          h+='<div class="gem-cell empty"></div>';
        }else{
          var gt=GEM_TYPES[val];
          h+='<div class="gem-cell'+(gemSelected&&gemSelected.r===r&&gemSelected.c===c?" selected":"")+'" style="background:'+gt.color+'" onclick="clickGem('+r+','+c+')">'+gt.emoji+'</div>';
        }
      }
    }
    h+='</div>';
    h+='</div>';
    body.innerHTML=h;
  }catch(e){}
}
function clickGem(row,col){
  try{
    if(!gemSelected){
      gemSelected={r:row,c:col};
      renderGem();
      return;
    }
    var r1=gemSelected.r,c1=gemSelected.c;
    var dr=Math.abs(r1-row),dc=Math.abs(c1-col);
    if((dr===1&&dc===0)||(dr===0&&dc===1)){
      // Swap
      var temp=gemGrid[r1][c1];
      gemGrid[r1][c1]=gemGrid[row][col];
      gemGrid[row][col]=temp;
      gemSelected=null;
      var matched=removeGemMatches();
      if(matched===0){
        // Swap back
        temp=gemGrid[r1][c1];
        gemGrid[r1][c1]=gemGrid[row][col];
        gemGrid[row][col]=temp;
      }else{
        gemScore+=matched*10;
      }
      renderGem();
    }else{
      gemSelected={r:row,c:col};
      renderGem();
    }
  }catch(e){}
}
function removeGemMatches(){
  try{
    var matched={};
    // Horizontal
    for(var r=0;r<gemGrid.length;r++){
      for(var c=0;c<gemGrid[r].length-2;c++){
        if(gemGrid[r][c]>=0&&gemGrid[r][c]===gemGrid[r][c+1]&&gemGrid[r][c]===gemGrid[r][c+2]){
          matched[r+","+c]=true;matched[r+","+(c+1)]=true;matched[r+","+(c+2)]=true;
        }
      }
    }
    // Vertical
    for(var c=0;c<6;c++){
      for(var r=0;r<gemGrid.length-2;r++){
        if(gemGrid[r][c]>=0&&gemGrid[r][c]===gemGrid[r+1][c]&&gemGrid[r][c]===gemGrid[r+2][c]){
          matched[r+","+c]=true;matched[(r+1)+","+c]=true;matched[(r+2)+","+c]=true;
        }
      }
    }
    var keys=Object.keys(matched);
    if(keys.length===0)return 0;
    // Remove matched
    for(var i=0;i<keys.length;i++){
      var parts=keys[i].split(",");
      gemGrid[parseInt(parts[0])][parseInt(parts[1])]=-1;
    }
    // Drop gems down
    for(var c=0;c<6;c++){
      for(var r=gemGrid.length-1;r>=0;r--){
        if(gemGrid[r][c]<0){
          for(var r2=r-1;r2>=0;r2--){
            if(gemGrid[r2][c]>=0){
              gemGrid[r][c]=gemGrid[r2][c];
              gemGrid[r2][c]=-1;
              break;
            }
          }
        }
      }
      // Fill empty
      for(var r=0;r<gemGrid.length;r++){
        if(gemGrid[r][c]<0)gemGrid[r][c]=Math.floor(Math.random()*GEM_TYPES.length);
      }
    }
    var more=removeGemMatches();
    return keys.length+more;
  }catch(e){return 0}
}
function closeGemPanel(){try{var b=$("gemOverlay");if(b)b.className="gem-overlay"}catch(e){}}

