var circusScore=0;var circusRound=0;var circusPerformers=[];var circusSelected=-1;
var circusTricks=["🤹 抛球","🔥 火圈","🎪 空中飞人","🎠 驯兽","🤸 翻跟斗","🎈 气球编织"];
