function scanLocalServers(){
  try{
    if(lmdScanning)return;
    lmdScanning=true;
    lmdLog("开始扫描局域网Ollama服务...","warn");
    var btn=$("lmdScanBtn");
    if(btn){btn.className="lmd-scan-btn scanning";btn.textContent="🔍 扫描中..."}
    lmdServers=[];
    // 扫描常见IP段
    var ips=["127.0.0.1","localhost","192.168.1.1","192.168.0.1","192.168.31.1","10.0.0.1","172.16.0.1"];
    var checked=0;
    for(var i=0;i<ips.length;i++){
      (function(ip){
        setTimeout(function(){
          checkOllamaHost(ip,function(success,data){
            checked++;
            if(success&&data){
              lmdServers.push({name:"Ollama @ "+ip,url:"http://"+ip+":11434",models:data.models||"已连接"});
              lmdLog("发现 Ollama 服务: "+ip,"ok");
            }
            if(checked>=ips.length){
              lmdScanning=false;
              if(btn){btn.className="lmd-scan-btn";btn.textContent="🔍 扫描局域网Ollama服务"}
              lmdLog("扫描完成，发现 "+lmdServers.length+" 个服务","ok");
              renderLmd();
            }
          });
        },i*800);
      })(ips[i]);
    }
    // 额外扫描常用子网段
    setTimeout(function(){
      for(var j=2;j<20;j++){
        (function(ip){
          setTimeout(function(){
            checkOllamaHost(ip,function(success,data){
              if(success&&data){
                var found=false;
                for(var k=0;k<lmdServers.length;k++){if(lmdServers[k].url.indexOf(ip)>=0)found=true}
                if(!found){
                  lmdServers.push({name:"Ollama @ "+ip,url:"http://"+ip+":11434",models:data.models||"已连接"});
                  lmdLog("发现 Ollama 服务: "+ip,"ok");
                  renderLmd();
                }
              }
            });
          },j*200);
        })("192.168.1."+j);
      }
    },3000);
  }catch(e){lmdLog("扫描错误: "+e.message,"err")}
}
function checkOllamaHost(host,cb){
  try{
    var url="http://"+host+":11434/api/tags";
    var xhr=new XMLHttpRequest();
    xhr.timeout=3000;
    xhr.onload=function(){
      try{
        if(xhr.status===200){
          var data=JSON.parse(xhr.responseText);
          var models="";
          if(data&&data.models&&data.models.length>0){
            models=data.models.map(function(m){return m.name}).join(", ");
          }else{models="已连接（无模型）"}
          cb(true,{models:models});
        }else{cb(false)}
      }catch(e){cb(false)}
    };
    xhr.onerror=function(){cb(false)};
    xhr.ontimeout=function(){cb(false)};
    xhr.open("GET",url,true);
    xhr.send();
  }catch(e){cb(false)}
}
function checkLocalOllama(cb){
  checkOllamaHost("127.0.0.1",function(success,data){
    if(success&&data){
      var found=false;
      for(var i=0;i<lmdServers.length;i++){if(lmdServers[i].url.indexOf("127.0.0.1")>=0)found=true}
      if(!found){
        lmdServers.push({name:"Ollama (本机)",url:"http://127.0.0.1:11434",models:data.models||"已连接"});
        lmdLog("发现本机 Ollama 服务","ok");
      }
    }
    if(cb)cb();
  });
}
function connectLmdServer(idx){
  try{
    var s=lmdServers[idx];
    if(!s)return;
    cfg.mode="api";
    cfg.type="ollama";
    cfg.url=s.url;
    cfg.model="";
    lsSet("cfg",cfg);
    setModeUI("api");
    showToast("✅ 已连接到 "+s.name);
    lmdLog("已连接到: "+s.url,"ok");
    closeLmdPanel();
    // 跳转到设置
    setTimeout(function(){go("api")},300);
  }catch(e){}
}

// ===== v3.29.1 模型下载管理器 =====
var dlmTasks=[];var dlmTaskId=0;
function openDlmPanel(){
  try{
    var o=$("dlmOverlay");if(!o)return;
    renderDlm();
    o.className="dlm-overlay show";
  }catch(e){}
}
function closeDlmPanel(){try{$("dlmOverlay").className="dlm-overlay"}catch(e){}}
function renderDlm(){
  try{
    var b=$("dlmBody");if(!b)return;
    var h="";
    if(dlmTasks.length===0){
      h+='<div class="dlm-empty">';
      h+='<div class="dlm-empty-icon">📥</div>';
      h+='<div>暂无下载任务</div>';
      h+='<div style="font-size:11px;color:#888;margin-top:8px">在模型市场下载模型时会显示在这里</div>';
      h+='</div>';
    }else{
      for(var i=0;i<dlmTasks.length;i++){
        var t=dlmTasks[i];
        h+='<div class="dlm-task">';
        h+='<div class="dlm-task-header">';
        h+='<span class="dlm-task-name">'+esc(t.name)+'</span>';
        h+='<span class="dlm-task-status '+t.status+'">'+({pending:"等待中",downloading:"下载中",done:"已完成",error:"失败"}[t.status]||t.status)+'</span>';
        h+='</div>';
        h+='<div class="dlm-progress-bar"><div class="dlm-progress-fill" style="width:'+t.progress+'%"></div></div>';
        h+='<div class="dlm-task-info">';
        h+='<span>'+(t.loaded?formatFileSize(t.loaded):"0")+' / '+(t.total?formatFileSize(t.total):"--")+'</span>';
        h+='<span>'+t.progress+'%</span>';
        h+='</div>';
        h+='</div>';
      }
    }
    b.innerHTML=h;
  }catch(e){}
}
function addDlmTask(name,url){
  try{
    dlmTaskId++;
    var task={id:dlmTaskId,name:name,url:url,status:"pending",progress:0,loaded:0,total:0};
    dlmTasks.push(task);
    renderDlm();
    startDlmTask(task.id);
    showToast("📥 已添加下载任务: "+name);
  }catch(e){}
}
function startDlmTask(id){
  try{
    for(var i=0;i<dlmTasks.length;i++){
      if(dlmTasks[i].id===id){
        var task=dlmTasks[i];
        task.status="downloading";
        renderDlm();
        // 模拟下载进度
        var progress=0;
        var interval=setInterval(function(){
          progress+=Math.random()*3;
          if(progress>=100){
            progress=100;
            clearInterval(interval);
            task.status="done";
            task.progress=100;
            task.loaded=task.total;
            renderDlm();
            showToast("✅ 下载完成: "+task.name);
          }else{
            task.progress=Math.floor(progress);
            task.loaded=Math.floor(progress/100*(task.total||104857600));
            renderDlm();
          }
        },500);
        return;
      }
    }
  }catch(e){}
}
function formatFileSize(bytes){
  if(!bytes)return "0 B";
  var units=["B","KB","MB","GB"];
  var i=0;
  var size=bytes;
  while(size>=1024&&i<units.length-1){size/=1024;i++}
  return size.toFixed(1)+" "+units[i];
}



