// ===== v3.30.0 对话思维导图 =====
var mindmapNodes=[];var mindmapEdges=[];var mindmapNodeId=0;
var mindmapTopics=["AI技术","深度学习","自然语言","计算机视觉","强化学习","数据科学","云计算","物联网"];
function openMindmapPanel(){
  try{
    var o=$("mindmapOverlay");if(!o)return;
    mindmapNodes=[];mindmapEdges=[];
    // 初始节点
    mindmapNodes.push({id:++mindmapNodeId,text:"中心主题",x:170,y:40,color:"#5cfca8"});
    renderMindmap();
    o.className="mindmap-overlay show";
    setTimeout(drawMindmap,200);
  }catch(e){}
}
function closeMindmapPanel(){try{$("mindmapOverlay").className="mindmap-overlay"}catch(e){}}
function renderMindmap(){
  try{
    var b=$("mindmapBody");if(!b)return;
    var h="";
    h+='<div class="mindmap-stats">';
    h+='<div class="mindmap-stat"><div class="mindmap-stat-num">'+mindmapNodes.length+'</div><div class="mindmap-stat-label">节点数</div></div>';
    h+='<div class="mindmap-stat"><div class="mindmap-stat-num">'+mindmapEdges.length+'</div><div class="mindmap-stat-label">连接数</div></div>';
    h+='</div>';
    h+='<input class="mindmap-topic-input" id="mindmapTopicInput" placeholder="输入新节点名称..." onkeydown="if(event.key===\'Enter\')addMindmapNode()">';
    h+='<div class="mindmap-tools">';
    h+='<div class="mindmap-tool" onclick="addMindmapNode()">➕ 添加节点</div>';
    h+='<div class="mindmap-tool" onclick="clearMindmap()">🗑️ 清空</div>';
    h+='<div class="mindmap-tool" onclick="generateMindmap()">✨ 自动生成</div>';
    h+='</div>';
    h+='<div class="mindmap-canvas-wrap"><canvas class="mindmap-canvas" id="mindmapCanvas" width="340" height="360"></canvas></div>';
    b.innerHTML=h;
    setTimeout(drawMindmap,100);
  }catch(e){}
}
function addMindmapNode(){
  var inp=$("mindmapTopicInput");if(!inp)return;
  var text=inp.value.trim()||"新节点"+(mindmapNodes.length+1);
  inp.value="";
  var colors=["#5cfca8","#fcb85c","#5cb4fc","#a78bfa","#ff6b6b","#5cfcc8"];
  var color=colors[mindmapNodes.length%colors.length];
  var angle=Math.random()*Math.PI*2;
  var dist=60+Math.random()*80;
  var x=170+Math.cos(angle)*dist;
  var y=70+Math.sin(angle)*dist;
  x=Math.max(30,Math.min(310,x));
  y=Math.max(30,Math.min(330,y));
  mindmapNodes.push({id:++mindmapNodeId,text:text,x:x,y:y,color:color});
  if(mindmapNodes.length>1){
    mindmapEdges.push({from:mindmapNodes[0].id,to:mindmapNodeId});
  }
  drawMindmap();
}
function clearMindmap(){
  mindmapNodes=[{id:++mindmapNodeId,text:"中心主题",x:170,y:40,color:"#5cfca8"}];
  mindmapEdges=[];
  drawMindmap();
}
function generateMindmap(){
  // 快速生成示例思维导图
  clearMindmap();
  var topic=mindmapTopics[Math.floor(Math.random()*mindmapTopics.length)];
  mindmapNodes[0].text=topic;
  var subs=[topic+"的应用",topic+"的原理",topic+"的发展",topic+"的挑战",topic+"的未来"];
  for(var i=0;i<subs.length;i++){
    var colors=["#fcb85c","#5cb4fc","#a78bfa","#ff6b6b","#5cfcc8"];
    var angle=-Math.PI/2+(i/(subs.length-1))*Math.PI;
    var dist=80+Math.random()*20;
    var x=170+Math.cos(angle)*dist;
    var y=60+Math.sin(angle)*dist;
    x=Math.max(30,Math.min(310,x));
    y=Math.max(30,Math.min(330,y));
    mindmapNodes.push({id:++mindmapNodeId,text:subs[i],x:x,y:y,color:colors[i]});
    mindmapEdges.push({from:mindmapNodes[0].id,to:mindmapNodeId});
  }
  drawMindmap();
}
function drawMindmap(){
  var c=$("mindmapCanvas");if(!c)return;
  var ctx=c.getContext("2d");if(!ctx)return;
  ctx.clearRect(0,0,c.width,c.height);
  // 背景
  ctx.fillStyle="rgba(20,20,46,0.3)";ctx.fillRect(0,0,c.width,c.height);
  // 画连线
  for(var i=0;i<mindmapEdges.length;i++){
    var e=mindmapEdges[i];
    var fNode=mindmapNodes.find(function(n){return n.id===e.from});
    var tNode=mindmapNodes.find(function(n){return n.id===e.to});
    if(fNode&&tNode){
      ctx.strokeStyle="rgba(92,252,168,0.15)";ctx.lineWidth=1.5;
      ctx.beginPath();ctx.moveTo(fNode.x,fNode.y+12);
      ctx.lineTo(tNode.x,tNode.y-12);ctx.stroke();
      // 小圆点
      ctx.fillStyle="rgba(92,252,168,0.2)";
      ctx.beginPath();ctx.arc((fNode.x+tNode.x)/2,(fNode.y+tNode.y)/2,3,0,Math.PI*2);ctx.fill();
    }
  }
  // 画节点
  for(var i=0;i<mindmapNodes.length;i++){
    var n=mindmapNodes[i];
    var r=n.color||"#5cfca8";
    ctx.fillStyle=r;ctx.globalAlpha=0.15;
    ctx.beginPath();ctx.arc(n.x,n.y,22,0,Math.PI*2);ctx.fill();
    ctx.globalAlpha=1;
    ctx.strokeStyle=r;ctx.lineWidth=1.5;ctx.globalAlpha=0.3;
    ctx.beginPath();ctx.arc(n.x,n.y,22,0,Math.PI*2);ctx.stroke();
    ctx.globalAlpha=1;
    ctx.fillStyle="#e0d4ff";ctx.font="11px sans-serif";ctx.textAlign="center";ctx.textBaseline="middle";
    var txt=n.text.length>8?n.text.slice(0,7)+"...":n.text;
    ctx.fillText(txt,n.x,n.y);
  }
}

