    var sentimentColor=analyticsData.sentimentScore<40?"#5cfca8":analyticsData.sentimentScore<60?"#ffd700":"#ff69b4";
    h+='<div class="analytics-stat-row"><span class="analytics-label">情绪指数</span><span class="analytics-value" style="color:'+sentimentColor+'">'+analyticsData.sentimentScore+'% ('+sentimentLabel+')</span></div>';
    h+='<div style="height:8px;background:rgba(255,255,255,.05);border-radius:4px;margin:8px 0;overflow:hidden"><div style="height:100%;width:'+analyticsData.sentimentScore+'%;background:linear-gradient(90deg,#5cfca8,#ffd700,#ff69b4);border-radius:4px;transition:width .5s"></div></div>';
    h+='<div class="analytics-insight"><div class="analytics-insight-text">💡 根据对话分析，你的整体情绪状态'+(analyticsData.sentimentScore>50?"良好，保持了积极的心态。":"平稳，建议多进行一些轻松愉快的话题。")+'</div></div>';
    h+='</div>';
