    var maxVal=Math.max.apply(null,analyticsData.weeklyData)||1;
    for(var i=0;i<7;i++){
      var pct=analyticsData.weeklyData[i]/maxVal*100;
      h+='<div class="analytics-bar" style="left:'+(i*14.5+2)+'%;height:'+pct+'%;background:'+(i==6?'rgba(255,215,0,0.8)':'rgba(255,215,0,0.5)')+'"></div>';
      h+='<div class="analytics-weekday" style="left:'+(i*14.5+2)+'%">'+days[i]+'</div>';
    }
