var studySubjects=[];var studyTimerRunning=false;var studyTimerSeconds=0;var studyTimerInterval=null;
var studyDefaultSubjects=[
  {icon:"📖",name:"数学",progress:60,done:false},
  {icon:"🔬",name:"物理",progress:45,done:false},
  {icon:"💻",name:"编程",progress:80,done:false},
  {icon:"📝",name:"英语",progress:30,done:false}
];
function openStudyplannerPanel(){
  try{
    var o=$("studyplannerOverlay");if(!o)return;
    if(studySubjects.length===0)studySubjects=JSON.parse(JSON.stringify(studyDefaultSubjects));
    studyTimerSeconds=0;
    renderStudyplanner();
    o.className="studyplanner-overlay show";
  }catch(e){}
}
function closeStudyplannerPanel(){try{$("studyplannerOverlay").className="studyplanner-overlay"}catch(e){}}
function renderStudyplanner(){
  try{
    var b=$("studyplannerBody");if(!b)return;
    var doneCount=0;var totalProgress=0;
    for(var i=0;i<studySubjects.length;i++){if(studySubjects[i].done)doneCount++;totalProgress+=studySubjects[i].progress;}
    var avgProgress=studySubjects.length>0?Math.round(totalProgress/studySubjects.length):0;
    var h="";
    h+='<div class="studyplanner-summary">';
    h+='<div class="studyplanner-summary-item"><div class="studyplanner-summary-num">'+studySubjects.length+'</div><div class="studyplanner-summary-label">总科目</div></div>';
    h+='<div class="studyplanner-summary-item"><div class="studyplanner-summary-num">'+doneCount+'/'+studySubjects.length+'</div><div class="studyplanner-summary-label">已完成</div></div>';
    h+='<div class="studyplanner-summary-item"><div class="studyplanner-summary-num">'+avgProgress+'%</div><div class="studyplanner-summary-label">平均进度</div></div>';
    h+='</div>';
    // 计时器
    var mins=Math.floor(studyTimerSeconds/60);var secs=studyTimerSeconds%60;
    var timeStr=(mins<10?"0":"")+mins+":"+(secs<10?"0":"")+secs;
    h+='<div class="studyplanner-timer">';
    h+='<div class="studyplanner-timer-display">'+timeStr+'</div>';
    h+='<div>'+(studyTimerRunning?'<span class="studyplanner-timer-btn running" onclick="stopStudyTimer()">⏸ 暂停</span>':'<span class="studyplanner-timer-btn" onclick="startStudyTimer()">▶ 开始</span>')+'<span class="studyplanner-timer-btn" onclick="resetStudyTimer()">⏹ 重置</span></div>';
    h+='</div>';
    // 科目列表
    for(var i=0;i<studySubjects.length;i++){
      var s=studySubjects[i];
      h+='<div class="studyplanner-subject'+(s.done?' completed':'')+'">';
      h+='<div class="studyplanner-subj-icon">'+s.icon+'</div>';
      h+='<div class="studyplanner-subj-info"><div class="studyplanner-subj-name">'+esc(s.name)+'</div><div class="studyplanner-subj-progress">进度 '+s.progress+'%</div></div>';
      h+='<div class="studyplanner-subj-check'+(s.done?' done':'')+'" onclick="toggleStudyDone('+i+')">'+(s.done?'✓':'')+'</div>';
      h+='</div>';
    }
    // 添加新科目
    h+='<input class="studyplanner-input" id="studySubjectInput" placeholder="输入新科目名称..." onkeydown="if(event.key===\'Enter\')addStudySubject()">';
    h+='<div class="studyplanner-add" onclick="addStudySubject()">➕ 添加科目</div>';
    b.innerHTML=h;
  }catch(e){}
}
function addStudySubject(){
  var inp=$("studySubjectInput");if(!inp)return;
  var name=inp.value.trim();if(!name)return;
  inp.value="";
  var icons=["📐","🌍","🎨","🎵","🧪","📜","🧮","🔭","⚖️","🗺️"];
  var icon=icons[studySubjects.length%icons.length];
  studySubjects.push({icon:icon,name:name,progress:0,done:false});
  renderStudyplanner();
}
function toggleStudyDone(idx){
  studySubjects[idx].done=!studySubjects[idx].done;
  if(studySubjects[idx].done)studySubjects[idx].progress=100;
  renderStudyplanner();
}
function startStudyTimer(){
  if(studyTimerRunning)return;
  studyTimerRunning=true;
  if(studyTimerInterval)clearInterval(studyTimerInterval);
  studyTimerInterval=setInterval(function(){studyTimerSeconds++;renderStudyplanner()},1000);
}
function stopStudyTimer(){
  studyTimerRunning=false;
  if(studyTimerInterval){clearInterval(studyTimerInterval);studyTimerInterval=null}
  renderStudyplanner();
}
function resetStudyTimer(){
  stopStudyTimer();studyTimerSeconds=0;renderStudyplanner();
}

