var healthMetrics=[{icon:"🚶",value:0,unit:"步",label:"今日步数"},{icon:"💧",value:0,unit:"杯",label:"饮水"},{icon:"😴",value:0,unit:"小时",label:"睡眠"},{icon:"🔥",value:0,unit:"千卡",label:"消耗热量"}];
