var musicNotes=["C","D","E","F","G","A","B"];
var musicNoteNames=["Do","Re","Mi","Fa","Sol","La","Si"];
var musicMelody=[];
var musicRecording=false;
var musicFullScale=["C","D","E","F","G","A","B","C5","D5","E5","F5","G5","A5","B5"];
var musicBlackKeys=["C#","D#","F#","G#","A#"];
var musicFullScaleDisplay=["C","D","E","F","G","A","B","C","D","E","F","G","A","B"];
function openMusicPanel(){
  try{
    var o=$("musicOverlay");if(!o)return;
    musicMelody=[];
    renderMusic();
    o.className="music-overlay show";
  }catch(e){}
}
function closeMusicPanel(){try{$("musicOverlay").className="music-overlay"}catch(e){}}
function renderMusic(){
  try{
    var b=$("musicBody");if(!b)return;
    var h="";
    h+='<div class="music-stats">';
    h+='<div class="music-stat"><div class="music-stat-num">🎹</div><div class="music-stat-label">钢琴</div></div>';
    h+='<div class="music-stat"><div class="music-stat-num">'+musicMelody.length+'</div><div class="music-stat-label">音符数</div></div>';
    h+='<div class="music-stat"><div class="music-stat-num">'+(musicRecording?"🔴":"⏹")+'</div><div class="music-stat-label">'+(musicRecording?"录制中":"待机")+'</div></div>';
    h+='</div>';
    // 钢琴键盘
    h+='<div class="music-piano">';
    h+='<div class="music-keys">';
    for(var i=0;i<14;i++){
      var isBlack=false;
      for(var j=0;j<musicBlackKeys.length;j++){
        if(musicFullScaleDisplay[i]===musicBlackKeys[j]){isBlack=true;break;}
      }
      if(isBlack){
        h+='<div class="music-key black" onclick="playMusicNote('+i+',\''+musicFullScaleDisplay[i]+'\')" style="margin-left:-9px;margin-right:-9px">'+musicFullScaleDisplay[i]+'</div>';
      }else{
        h+='<div class="music-key" onclick="playMusicNote('+i+',\''+musicFullScaleDisplay[i]+'\')"><span style="margin-top:auto">'+musicFullScaleDisplay[i]+'</span></div>';
      }
    }
    h+='</div>';
    h+='</div>';
    // 预设旋律
    h+='<div class="music-patterns">';
    var patterns=["小星星","欢乐颂","两只老虎","生日快乐","卡农"];
    for(var i=0;i<patterns.length;i++){
      h+='<span class="music-pattern" onclick="playMusicPattern('+i+')">'+patterns[i]+'</span>';
    }
    h+='</div>';
    // 录制按钮
    h+='<div class="music-record">';
    h+='<div class="music-record-btn'+(musicRecording?' recording':'')+'" onclick="toggleMusicRecord()">'+(musicRecording?'⏹':'🔴')+'</div>';
    h+='<div class="music-btn" onclick="clearMusicMelody()">🗑️ 清空</div>';
    h+='</div>';
    // 旋律显示
    h+='<div class="music-melody"><div class="music-melody-text">'+(musicMelody.length>0?musicMelody.join(" "):"点击琴键或选择旋律开始创作")+'</div></div>';
    b.innerHTML=h;
  }catch(e){}
}
function playMusicNote(idx,note){
  musicMelody.push(note);
  if(musicRecording)renderMusic();
  else renderMusic();
  try{
    // 使用Web Audio API播放简单音调
    var ctx=new(window.AudioContext||window.webkitAudioContext)();
    var osc=ctx.createOscillator();
    var gain=ctx.createGain();
    osc.connect(gain);gain.connect(ctx.destination);
    var freqs={"C":262,"D":294,"E":330,"F":349,"G":392,"A":440,"B":494,"C5":523,"D5":587,"E5":659,"F5":698,"G5":784,"A5":880,"B5":988};
    var freq=freqs[note]||440;
    osc.frequency.value=freq;
    osc.type="sine";
    gain.gain.setValueAtTime(0.3,ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01,ctx.currentTime+0.5);
    osc.start(ctx.currentTime);osc.stop(ctx.currentTime+0.5);
  }catch(e){}
}
function playMusicPattern(idx){
  var patterns=[
    ["C","C","G","G","A","A","G"],
    ["E","E","F","G","G","F","E","D","C","C","D","E","E","D","D"],
    ["C","D","E","C","C","D","E","C","E","F","G","E","F","G"],
    ["G","G","A","G","C","B","G","G","A","G","D","C","G","G","G","E","C","B","A","F","F","E","C","D","C"],
    ["C","D","E","F","G","F","E","D","C","E","G","A","B","A","G","F","E","F","G","A","G","F","E","D","C"]
  ];
  if(idx>=patterns.length)return;
  musicMelody=patterns[idx].slice();
  renderMusic();
  // 逐个播放
  var freqs={"C":262,"D":294,"E":330,"F":349,"G":392,"A":440,"B":494};
  for(var i=0;i<musicMelody.length;i++){
    (function(note,delay){
      setTimeout(function(){
        try{
          var ctx=new(window.AudioContext||window.webkitAudioContext)();
          var osc=ctx.createOscillator();var gain=ctx.createGain();
          osc.connect(gain);gain.connect(ctx.destination);
          osc.frequency.value=freqs[note]||440;
          osc.type="sine";
          gain.gain.setValueAtTime(0.3,ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01,ctx.currentTime+0.3);
          osc.start(ctx.currentTime);osc.stop(ctx.currentTime+0.3);
        }catch(e){}
      },delay);
    })(musicMelody[i],i*300);
  }
}
function toggleMusicRecord(){musicRecording=!musicRecording;renderMusic()}
function clearMusicMelody(){musicMelody=[];renderMusic()}

