// ===== v3.34.0 Smart Life: 密文解密 (Cipher Decoder) =====
var cipherMethod="caesar";
var cipherShift=3;
function openCipherPanel(){
  $("cipherOverlay").style.display="flex";
}
function closeCipherPanel(){$("cipherOverlay").style.display="none"}
function setCipherMethod(method){
  cipherMethod=method;
  var ms=document.querySelectorAll(".cipher-method");
  for(var i=0;i<ms.length;i++){ms[i].classList.remove("active")}
  event.target.classList.add("active");
  var shiftDiv=$("cipherShiftDiv");
  if(shiftDiv)shiftDiv.style.display=(method==="caesar")?"flex":"none";
}
function cipherEncrypt(){
  var input=$("cipherInput");
  if(!input||!input.value.trim()){showToast("请输入文字");return}
  var text=input.value;
  var result="";
  if(cipherMethod==="caesar"){
    result=caesarShift(text,cipherShift);
  }else if(cipherMethod==="reverse"){
    result=text.split("").reverse().join("");
  }else if(cipherMethod==="atbash"){
    result=atbashShift(text);
  }else if(cipherMethod==="base64"){
    try{result=btoa(unescape(encodeURIComponent(text)))}catch(e){result="编码失败"}
  }
  var out=$("cipherOutput");
  if(out)out.textContent=result;
}
function cipherDecrypt(){
  var input=$("cipherInput");
  if(!input||!input.value.trim()){showToast("请输入文字");return}
  var text=input.value;
  var result="";
  if(cipherMethod==="caesar"){
    result=caesarShift(text,-cipherShift);
  }else if(cipherMethod==="reverse"){
    result=text.split("").reverse().join("");
  }else if(cipherMethod==="atbash"){
    result=atbashShift(text);
  }else if(cipherMethod==="base64"){
    try{result=decodeURIComponent(escape(atob(text)))}catch(e){result="解码失败"}
  }
  var out=$("cipherOutput");
  if(out)out.textContent=result;
}
function caesarShift(text,shift){
  var result="";
  for(var i=0;i<text.length;i++){
    var c=text.charCodeAt(i);
    if(c>=65&&c<=90){result+=String.fromCharCode((c-65+shift+26)%26+65)}
    else if(c>=97&&c<=122){result+=String.fromCharCode((c-97+shift+26)%26+97)}
    else{result+=text[i]}
  }
  return result;
}
function atbashShift(text){
  var result="";
  for(var i=0;i<text.length;i++){
    var c=text.charCodeAt(i);
    if(c>=65&&c<=90){result+=String.fromCharCode(90-(c-65))}
    else if(c>=97&&c<=122){result+=String.fromCharCode(122-(c-97))}
    else{result+=text[i]}
  }
  return result;
}
function changeCipherShift(delta){
  cipherShift=(cipherShift+delta+26)%26;
  if(cipherShift===0)cipherShift=26;
  var v=$("cipherShiftVal");
  if(v)v.textContent=cipherShift;
}
function copyCipherResult(){
  var out=$("cipherOutput");
  if(out&&out.textContent){
    try{
      var ta=document.createElement("textarea");
      ta.value=out.textContent;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      document.body.removeChild(ta);
      showToast("已复制到剪贴板");
    }catch(e){showToast("复制失败")}
  }
}

