var WORLD_SETTINGS_DATA=[];
var WORLD_SETTING_TEMPLATES=[
  {name:"奇幻大陆",icon:"🏰",desc:"一个充满魔法与传说的奇幻世界，龙与勇者的故事在此交织",tags:["魔法","中世纪","冒险"]},
  {name:"赛博都市",icon:"🌆",desc:"霓虹灯下的未来都市，科技与人性的碰撞",tags:["科幻","赛博朋克","未来"]},
  {name:"仙侠世界",icon:"⛰️",desc:"御剑飞行的修仙世界，灵脉与道法的修行之路",tags:["仙侠","古风","修行"]},
  {name:"末日废土",icon:"☢️",desc:"文明崩塌后的废墟世界，生存与希望的终极考验",tags:["末日","生存","废土"]},
  {name:"童话王国",icon:"🌸",desc:"梦幻般的童话世界，可爱生物与奇妙冒险的乐园",tags:["童话","治愈","幻想"]},
  {name:"星海征途",icon:"🚀",desc:"浩瀚星海中的星际文明，探索未知星域的太空史诗",tags:["科幻","太空","探索"]}
];
function openWorldSettingPanel(){
  var o=$("worldsettingOverlay");if(!o)return;
  o.style.display="flex";
  renderWorldSettings();
}
function closeWorldSettingPanel(){
  var o=$("worldsettingOverlay");if(o)o.style.display="none";
}
function renderWorldSettings(){
  var body=$("worldsettingBody");if(!body)return;
  var h='<div class="worldsetting-create-btn" onclick="showWorldGenDialog()">✨ AI生成新世界观</div>';
  // Show templates
  h+='<div style="font-size:13px;color:#888;margin-bottom:8px;font-weight:600">📋 预设模板</div>';
  for(var i=0;i<WORLD_SETTING_TEMPLATES.length;i++){
    var t=WORLD_SETTING_TEMPLATES[i];
    h+='<div class="worldsetting-world-card" onclick="useWorldTemplate('+i+')">';
    h+='<div class="worldsetting-world-icon">'+t.icon+'</div>';
    h+='<div class="worldsetting-world-name">'+esc(t.name)+'</div>';
    h+='<div class="worldsetting-world-desc">'+esc(t.desc)+'</div>';
    h+='<div class="worldsetting-world-tags">';
    for(var j=0;j<t.tags.length;j++){h+='<span class="worldsetting-world-tag">'+t.tags[j]+'</span>';}
    h+='</div></div>';
  }
  // Custom worlds
  if(WORLD_SETTINGS_DATA.length>0){
    h+='<div style="font-size:13px;color:#888;margin:12px 0 8px;font-weight:600">🌟 我的世界观</div>';
    for(var i=0;i<WORLD_SETTINGS_DATA.length;i++){
      var w=WORLD_SETTINGS_DATA[i];
      h+='<div class="worldsetting-world-card">';
      h+='<div class="worldsetting-world-icon">'+w.icon+'</div>';
      h+='<div class="worldsetting-world-name">'+esc(w.name)+'</div>';
      h+='<div class="worldsetting-world-desc">'+esc(w.desc)+'</div>';
      h+='<div class="worldsetting-world-tags">';
      if(w.tags){for(var j=0;j<w.tags.length;j++){h+='<span class="worldsetting-world-tag">'+w.tags[j]+'</span>';}}
      h+='</div></div>';
    }
  }
  body.innerHTML=h;
}
function useWorldTemplate(idx){
  if(idx<0||idx>=WORLD_SETTING_TEMPLATES.length)return;
  var t=WORLD_SETTING_TEMPLATES[idx];
  WORLD_SETTINGS_DATA.push({name:t.name,icon:t.icon,desc:t.desc,tags:t.tags.slice()});
  showToast("🌍 已添加世界观: "+t.name);
  renderWorldSettings();
}
function showWorldGenDialog(){
  var body=$("worldsettingBody");if(!body)return;
  var h='<div style="font-size:16px;font-weight:700;color:#e0d4ff;margin-bottom:12px">✨ AI生成世界观</div>';
  h+='<div style="font-size:12px;color:#888;margin-bottom:10px">描述你想创建的世界，AI将为你生成完整的世界观设定</div>';
  h+='<textarea class="worldsetting-gen-input" id="worldGenInput" placeholder="例如：一个漂浮在云层之上的天空之城，由古代魔法水晶驱动..."></textarea>';
  h+='<div class="worldsetting-params">';
  h+='<div class="worldsetting-param"><div class="worldsetting-param-label">🏰 风格</div><div class="worldsetting-param-val" style="font-size:13px;color:#e0d4ff">奇幻</div></div>';
  h+='<div class="worldsetting-param"><div class="worldsetting-param-label">📏 规模</div><div class="worldsetting-param-val" style="font-size:13px;color:#e0d4ff">大陆级</div></div>';
  h+='</div>';
  h+='<div style="display:flex;gap:8px">';
  h+='<div class="worldsetting-create-btn" style="flex:1;margin:0" onclick="generateWorldSetting()">🚀 生成</div>';
  h+='<div class="premium-btn secondary" style="flex:0;padding:14px 20px;margin:0" onclick="renderWorldSettings()">↩ 返回</div>';
  h+='</div>';
  body.innerHTML=h;
  setTimeout(function(){var inp=$("worldGenInput");if(inp)inp.focus()},300);
}
function generateWorldSetting(){
  var inp=$("worldGenInput");if(!inp)return;
  var text=inp.value.trim();
  if(!text){showToast("请描述你想创建的世界");return}
  var names=["星辉大陆","暗影深渊","翡翠仙境","琥珀之城","霜月之谷","黄金之海"];
  var icons=["🏰","🌋","🌸","🌆","❄️","🌊"];
  var descs=["一个由古老魔法能量维系的神秘大陆，天空中漂浮着发光的水晶岛","一个被永夜笼罩的深渊世界，地底深处隐藏着远古文明的秘密","一片被翡翠之光祝福的仙境，精灵与自然和谐共处的理想乡","一座由琥珀与黄金铸成的辉煌城市，多元种族在此交汇共生","一片被永恒月光照耀的冰封山谷，冰雪之下沉睡着史诗级的力量","一片无边无际的金色海洋，星舰与海兽在此展开壮丽的冒险"];
  var tagsList=[["奇幻","魔法","探索"],["暗黑","神秘","冒险"],["治愈","自然","精灵"],["城市","多元","繁荣"],["冰雪","史诗","神秘"],["科幻","海洋","冒险"]];
  var idx=Math.floor(Math.random()*names.length);
  var newWorld={name:names[idx],icon:icons[idx],desc:descs[idx],tags:tagsList[idx].slice()};
  WORLD_SETTINGS_DATA.push(newWorld);
  showToast("🌍 世界观生成成功！");
  renderWorldSettings();
}

