var VOICE_LINES_DATA=[
  {name:"早安问候",icon:"🌅",type:"日常",wave:true},
  {name:"战斗呐喊",icon:"⚔️",type:"战斗",wave:true},
  {name:"温柔安慰",icon:"🤗",type:"情感",wave:true},
  {name:"魔法咒语",icon:"🔮",type:"魔法",wave:true},
  {name:"欢快笑声",icon:"😄",type:"情感",wave:true},
  {name:"神秘低语",icon:"🤫",type:"神秘",wave:true}
];
var SFX_ITEMS=[{icon:"🌊",name:"海浪"},{icon:"🌧️",name:"雨声"},{icon:"🔥",name:"火焰"},{icon:"🍃",name:"风声"},{icon:"⚡",name:"雷电"},{icon:"🎵",name:"旋律"},{icon:"🎻",name:"弦乐"},{icon:"🥁",name:"鼓点"},{icon:"🔔",name:"钟声"}];
var CURRENT_PLAYING_VOICE=null;
function openVoiceWorkshopPanel(){
  var o=$("voiceworkshopOverlay");if(!o)return;
  o.style.display="flex";
  renderVoiceWorkshop();
}
function closeVoiceWorkshopPanel(){
  var o=$("voiceworkshopOverlay");if(o)o.style.display="none";
  CURRENT_PLAYING_VOICE=null;
}
function renderVoiceWorkshop(){
  var body=$("voiceworkshopBody");if(!body)return;
  var h='<div class="voiceworkshop-gen-btn" onclick="showToast("🎙️ 声音合成功能开发中")">🎙️ AI生成新语音</div>';
  h+='<div style="font-size:13px;color:#888;margin-bottom:8px;font-weight:600">🎤 角色语音</div>';
  for(var i=0;i<VOICE_LINES_DATA.length;i++){
    var v=VOICE_LINES_DATA[i];
    var isPlaying=CURRENT_PLAYING_VOICE===i;
    h+='<div class="voiceworkshop-voice-card">';
    h+='<div class="voiceworkshop-voice-header">';
    h+='<div class="voiceworkshop-voice-icon">'+v.icon+'</div>';
    h+='<div class="voiceworkshop-voice-info"><div class="voiceworkshop-voice-name">'+esc(v.name)+'</div><span class="voiceworkshop-voice-type">'+v.type+'</span></div>';
    h+='</div>';
    if(v.wave){
      h+='<div class="voiceworkshop-voice-wave">';
      for(var w=0;w<7;w++){h+='<div class="voiceworkshop-voice-wave-bar"></div>';}
      h+='</div>';
    }
    h+='<div class="voiceworkshop-voice-actions">';
    h+='<div class="voiceworkshop-voice-play'+(isPlaying?' playing':'')+'" onclick="toggleVoicePlay('+i+')">'+(isPlaying?'⏹ 停止':'▶ 播放')+'</div>';
    h+='<div class="voiceworkshop-voice-play" onclick="showToast("💾 语音已保存")">💾 保存</div>';
    h+='</div></div>';
  }
  h+='<div style="font-size:13px;color:#888;margin:12px 0 8px;font-weight:600">🔊 音效库</div>';
  h+='<div class="voiceworkshop-sfx-grid">';
  for(var i=0;i<SFX_ITEMS.length;i++){
    var s=SFX_ITEMS[i];
    h+='<div class="voiceworkshop-sfx-item" onclick="playSfx('+i+')">'+s.icon+'<span>'+s.name+'</span></div>';
  }
  h+='</div>';
  body.innerHTML=h;
}
function toggleVoicePlay(idx){
  if(CURRENT_PLAYING_VOICE===idx){CURRENT_PLAYING_VOICE=null}else{CURRENT_PLAYING_VOICE=idx}
  renderVoiceWorkshop();
  if(CURRENT_PLAYING_VOICE!==null){showToast("🎵 正在播放: "+VOICE_LINES_DATA[idx].name)}
}
function playSfx(idx){
  if(idx<0||idx>=SFX_ITEMS.length)return;
  showToast("🔊 音效: "+SFX_ITEMS[idx].name);
}

