var SCENE_BACKGROUNDS=["🌌","🌅","🌃","🌄","🌲","🏖️"];
var SCENE_ELEMENTS=[{icon:"🌙",label:"月亮"},{icon:"⭐",label:"星星"},{icon:"☁️",label:"云朵"},{icon:"🌈",label:"彩虹"},{icon:"🦋",label:"蝴蝶"},{icon:"🌺",label:"花朵"},{icon:"🏠",label:"小屋"},{icon:"🌳",label:"树木"},{icon:"🎑",label:"灯笼"},{icon:"🔥",label:"篝火"},{icon:"💧",label:"水滴"},{icon:"❄️",label:"雪花"}];
var CURRENT_SCENE={bg:0,elements:[]};
function openSceneEditorPanel(){
  var o=$("sceneeditorOverlay");if(!o)return;
  o.style.display="flex";
  renderSceneEditor();
}
function closeSceneEditorPanel(){
  var o=$("sceneeditorOverlay");if(o)o.style.display="none";
}
function renderSceneEditor(){
  var body=$("sceneeditorBody");if(!body)return;
  var h='<div class="sceneeditor-canvas" id="sceneCanvas">';
  h+='<div class="sceneeditor-canvas-bg" id="sceneCanvasBg">'+SCENE_BACKGROUNDS[CURRENT_SCENE.bg]+'</div>';
  h+='<div class="sceneeditor-canvas-elements" id="sceneCanvasElems">';
  for(var i=0;i<CURRENT_SCENE.elements.length;i++){
    var e=CURRENT_SCENE.elements[i];
    h+='<div class="sceneeditor-canvas-elem" style="left:'+e.x+'%;top:'+e.y+'%;animation-delay:'+(e.delay||0)+'s">'+e.icon+'</div>';
  }
  h+='</div></div>';
  h+='<div style="font-size:13px;color:#888;margin-bottom:6px;font-weight:600">🎨 选择背景</div>';
  h+='<div class="sceneeditor-bg-options">';
  for(var i=0;i<SCENE_BACKGROUNDS.length;i++){
    h+='<div class="sceneeditor-bg-opt'+(CURRENT_SCENE.bg===i?' selected':'')+'" onclick="selectSceneBg('+i+')">'+SCENE_BACKGROUNDS[i]+'</div>';
  }
  h+='</div>';
  h+='<div style="font-size:13px;color:#888;margin-bottom:6px;font-weight:600">✨ 添加元素</div>';
  h+='<div class="sceneeditor-palette">';
  for(var i=0;i<SCENE_ELEMENTS.length;i++){
    var e=SCENE_ELEMENTS[i];
    h+='<div class="sceneeditor-palette-item" onclick="addSceneElement('+i+')" title="'+e.label+'">'+e.icon+'</div>';
  }
  h+='</div>';
  h+='<div class="sceneeditor-save-btn" onclick="saveCurrentScene()">💾 保存场景</div>';
  body.innerHTML=h;
}
function selectSceneBg(idx){
  if(idx<0||idx>=SCENE_BACKGROUNDS.length)return;
  CURRENT_SCENE.bg=idx;
  renderSceneEditor();
}
function addSceneElement(idx){
  if(idx<0||idx>=SCENE_ELEMENTS.length)return;
  CURRENT_SCENE.elements.push({icon:SCENE_ELEMENTS[idx].icon,x:Math.random()*70+15,y:Math.random()*60+20,delay:Math.random()*2});
  renderSceneEditor();
  showToast("✨ 已添加: "+SCENE_ELEMENTS[idx].label);
}
function saveCurrentScene(){
  showToast("🖼️ 场景已保存！");
}

// ===== v3.36.0 Premium Feature: 角色关系网 (Character Network) =====
var CHAR_NETWORK_DATA=[];
var CHAR_NETWORK_RELATIONS=["挚友","宿敌","师徒","恋人","兄妹","盟友","对手","知己"];
var CHAR_NETWORK_DEFAULT_CHARS=[
  {name:"小晴",avatar:"🌻",color:"#ff6b9d"},
  {name:"墨羽",avatar:"🦅",color:"#4a9eff"},
  {name:"艾琳",avatar:"🧪",color:"#00d2d3"},
  {name:"星辰",avatar:"⭐",color:"#a29bfe"},
  {name:"兔兔",avatar:"🐰",color:"#ff7675"},
  {name:"Luna",avatar:"🌙",color:"#74b9ff"}
];
function openCharNetworkPanel(){
  var o=$("charnetworkOverlay");if(!o)return;
  o.style.display="flex";
  renderCharNetwork();
}
function closeCharNetworkPanel(){
  var o=$("charnetworkOverlay");if(o)o.style.display="none";
}
function renderCharNetwork(){
  var body=$("charnetworkBody");if(!body)return;
  var h='<div class="charnetwork-add-btn" onclick="showAddRelationDialog()">🕸️ 添加角色关系</div>';
  // Graph visualization
  h+='<div class="charnetwork-graph" id="charNetworkGraph">';
  var centerX=50,centerY=45;
  var chars=CHAR_NETWORK_DATA.length>0?CHAR_NETWORK_DATA:CHAR_NETWORK_DEFAULT_CHARS;
  for(var i=0;i<chars.length&&i<8;i++){
    var angle=(i/chars.length)*Math.PI*2-Math.PI/2;
    var radius=30;
    var x=centerX+Math.cos(angle)*radius;
    var y=centerY+Math.sin(angle)*radius;
    var isCenter=i===0;
    // Draw connection line from center to node
    if(i>0){
      h+='<div class="charnetwork-line" style="left:'+centerX+'%;top:'+centerY+'%;width:'+radius+'%;transform:rotate('+(angle*180/Math.PI)+'deg);background:linear-gradient(90deg,var(--line-c,'+chars[0].color+'),'+chars[i].color+');opacity:.3"></div>';
    }
    h+='<div class="charnetwork-node'+(isCenter?' center':' connected')+'" style="left:'+(x-3)+'%;top:'+(y-3)+'%;background:'+chars[i].color+'22;border-color:'+chars[i].color+'44" onclick="showCharRelation('+i+')"><span style="font-size:20px">'+chars[i].avatar+'</span></div>';
  }
  h+='</div>';
  // Legend
  h+='<div class="charnetwork-legend">';
  h+='<div class="charnetwork-legend-item"><span class="charnetwork-legend-dot" style="background:#ff6b9d"></span>中心角色</div>';
  h+='<div class="charnetwork-legend-item"><span class="charnetwork-legend-dot" style="background:rgba(162,155,254,.5)"></span>关联角色</div>';
  h+='<div class="charnetwork-legend-item"><span class="charnetwork-legend-dot" style="background:rgba(92,252,168,.5)"></span>友好关系</div>';
  h+='</div>';
  // Character list
  h+='<div class="charnetwork-char-list">';
  for(var i=0;i<chars.length;i++){
    var c=chars[i];
    var rel=CHAR_NETWORK_RELATIONS[Math.floor(Math.random()*CHAR_NETWORK_RELATIONS.length)];
    h+='<div class="charnetwork-char-item"><div class="charnetwork-char-av" style="background:'+c.color+'22">'+c.avatar+'</div><div class="charnetwork-char-info"><div class="charnetwork-char-name">'+esc(c.name)+'</div><div class="charnetwork-char-rel">💞 '+rel+'</div></div><div class="charnetwork-char-strength">好感度: '+(Math.floor(Math.random()*40+60))+'%</div></div>';
  }
  h+='</div>';
  body.innerHTML=h;
}
function showCharRelation(idx){
  showToast("🕸️ 查看角色关系详情");
}
function showAddRelationDialog(){
  var body=$("charnetworkBody");if(!body)return;
  var h='<div style="font-size:16px;font-weight:700;color:#e0d4ff;margin-bottom:12px">🕸️ 添加角色关系</div>';
  h+='<div style="font-size:12px;color:#888;margin-bottom:10px">输入角色名称和关系类型</div>';
  h+='<input class="worldsetting-gen-input" id="relCharName" placeholder="角色名称" style="min-height:44px;margin-bottom:8px">';
  h+='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">';
  for(var i=0;i<CHAR_NETWORK_RELATIONS.length;i++){
    h+='<span class="worldsetting-world-tag" onclick="selectRelationType('+i+')" id="relTag'+i+'" style="cursor:pointer;color:#a29bfe;border-color:rgba(162,155,254,.2)">'+CHAR_NETWORK_RELATIONS[i]+'</span>';
  }
  h+='</div>';
  h+='<div style="display:flex;gap:8px">';
  h+='<div class="charnetwork-add-btn" style="flex:1;margin:0" onclick="addCharRelation()">✅ 确认添加</div>';
  h+='<div class="premium-btn secondary" style="flex:0;padding:14px 20px;margin:0" onclick="renderCharNetwork()">↩ 返回</div>';
  h+='</div>';
  body.innerHTML=h;
}
var SELECTED_RELATION=0;
function selectRelationType(idx){
  SELECTED_RELATION=idx;
  for(var i=0;i<CHAR_NETWORK_RELATIONS.length;i++){
    var tag=$("relTag"+i);
    if(tag){tag.style.background=i===idx?"rgba(162,155,254,.2)":"rgba(0,200,150,.08)";tag.style.borderColor=i===idx?"rgba(162,155,254,.4)":"rgba(0,200,150,.1)";}
  }
}
function addCharRelation(){
  var inp=$("relCharName");if(!inp)return;
  var name=inp.value.trim();
  if(!name){showToast("请输入角色名称");return}
  var avatars=["🌻","🦅","🧪","⭐","🐰","🌙","🌸","🎭","🦋","🐱"];
  var colors=["#ff6b9d","#4a9eff","#00d2d3","#a29bfe","#ff7675","#74b9ff","#ff9ff3","#54a0ff","#5f27cd","#01a3a4"];
  var idx=CHAR_NETWORK_DATA.length%avatars.length;
  CHAR_NETWORK_DATA.push({name:name,avatar:avatars[idx],color:colors[idx]});
  showToast("🕸️ 已添加: "+name);
  renderCharNetwork();
}

